	// the block's own default, and one index's.
	assert(/openPDFEditor\(/.test(inspector), 'nothing opens the distribution editor');
	assert((inspector.match(/openPDFEditor\(/g) ?? []).length >= 2,
		'only one of the two routes to a distribution is left');

	// And a column that is neither a number nor a flag has to say how it
	// reads: the Information view showed `distribution [object Object]`.
	assert(/x\?\.describe \? x\.describe\(v\)/.test(info),
		'the Information view stringifies a distribution again');
	const ed2 = readFileSync(new URL('../src/domain/edit.js', import.meta.url), 'utf8');
	assert(/describe: describePDF,/.test(ed2), 'the column no longer says how it reads');

	// The proof it is needed: a spec put through `String` is the bug.
