section('compartment model assembly');

test('two-compartment transfer matches the analytic solution', () => {
	// dA/dt = -k A, dB/dt = k A  ->  B = A0 (1 - exp(-k t))
	const k = 0.03;
	const r = run({
		simulation: {
			start_time: 0, end_time: 100, output_points: 11, spacing: 'linear',
			solver: 'dp45', rtol: 1e-11, abstol: 1e-15,
		},
		parameters: [{ name: 'k', value: k }],
		compartments: [
			{ name: 'A', initial: '1' },
			{ name: 'B', initial: '0' },
		],
		transfers: [{ name: 'T', from: 'A', to: 'B', rate: 'k' }],
	});
	for (let i = 0; i < r.t.length; i++) {
		const t = r.t[i];
		close(r.y[i][0], Math.exp(-k * t), 1e-8, `A at t=${t}`);
		close(r.y[i][1], 1 - Math.exp(-k * t), 1e-8, `B at t=${t}`);
	}
});

test('a closed loop of transfers conserves mass', () => {
	const r = run({
		simulation: {
			start_time: 0, end_time: 500, output_points: 21, spacing: 'linear',
			solver: 'ros23', rtol: 1e-10, abstol: 1e-14,
		},
		parameters: [
			{ name: 'k1', value: 0.02 }, { name: 'k2', value: 0.005 },
			{ name: 'k3', value: 0.01 },
		],
		compartments: [
			{ name: 'A', initial: '100' }, { name: 'B', initial: '0' },
			{ name: 'C', initial: '0' },
		],
		transfers: [
			{ name: 'Tab', from: 'A', to: 'B', rate: 'k1' },
			{ name: 'Tbc', from: 'B', to: 'C', rate: 'k2' },
			{ name: 'Tca', from: 'C', to: 'A', rate: 'k3' },
		],
	});
	for (let i = 0; i < r.t.length; i++) {
		const total = r.y[i][0] + r.y[i][1] + r.y[i][2];
		close(total, 100, 1e-8, `total at t=${r.t[i]}`);
	}
});

