// =========================================================================
section('the analytic Jacobian');

/**
 * Two central differences an octave apart. Their disagreement is the finite
 * difference's own uncertainty, and on a compartment model that is enormous --
 * a 1e-3 coupling has to be read off a total of 1e10 -- so it is what the
 * analytic value must be judged against. A fixed tolerance would either pass
 * everything or fail the models that matter.
 */
/**
 * A Jacobian by central differences, twice, plus what the arithmetic itself
 * can be trusted to.
 *
 * `roundoff[i][j]` is the third return because comparing coarse against fine
 * is not enough on its own: two differences of the same badly cancelled
 * quantity can agree to several digits by luck and report no noise at all
 * while both are wrong. That is not hypothetical -- examples/recorders.json
 * has a release of 3.2e9 Bq/year passing through a compartment whose
 * derivative term is 0.043, so a central difference over h = 1e-3 is asking
 * for eleven digits of a sixteen-digit number, and the answer is mostly
 * rounding. The bound on that is `eps * |f| / h`, which is a number rather
 * than a guess, so it is computed and returned.
 */
function differenceJacobian(sys, t, y, floor) {
	const n = y.length;
	const coarse = Array.from({ length: n }, () => new Float64Array(n));
	const fine = Array.from({ length: n }, () => new Float64Array(n));
	const roundoff = Array.from({ length: n }, () => new Float64Array(n));
	const fp = new Float64Array(n), fm = new Float64Array(n);
	const z = Float64Array.from(y);
	const EPS = Number.EPSILON;
	for (let j = 0; j < n; j++) {
		const base = Math.max(Math.abs(y[j]), floor) * 1e-6;
		for (const [h, J] of [[base, coarse], [base / 2, fine]]) {
			z[j] = y[j] + h; sys.dydt(t, z, fp);
			z[j] = y[j] - h; sys.dydt(t, z, fm);
			for (let i = 0; i < n; i++) {
				J[i][j] = (fp[i] - fm[i]) / (2 * h);
				// The largest |f| either side, over the smallest step taken.
				const mag = Math.max(Math.abs(fp[i]), Math.abs(fm[i]));
				roundoff[i][j] = Math.max(roundoff[i][j], (EPS * mag) / h);
			}
		}
		z[j] = y[j];
	}
	return { coarse, fine, roundoff };
}

/** Checks a model's Jacobian at several states; returns the worst overshoot. */
function jacobianAgrees(model, { states = 3 } = {}) {
	const sys = buildSystem(new Project(model));
	const j = sys.jacobian;
	assert(j.available, `no analytic Jacobian: ${j.reason}`);
	assert(colouringIsValid(j.pattern, j.groups), 'two columns of one colour share a row');

	const n = sys.layout.nstate;
	const y0 = sys.initialState();
	let worst = 0, missing = 0;
	for (let p = 0; p < states; p++) {
		const y = Float64Array.from(y0);
		if (p === 1) for (let i = 0; i < n; i++) y[i] = Math.abs(y[i]) * 0.5 + 1 + i;
		if (p === 2) for (let i = 0; i < n; i++) y[i] = 1e3 * (1 + Math.sin(i * 1.7) ** 2);
		const t = p === 0 ? 0 : 10 ** p;

		const A = Array.from({ length: n }, () => new Float64Array(n));
		j.evaluateDense(t, y, A);
		let ymax = 0;
		for (let i = 0; i < n; i++) ymax = Math.max(ymax, Math.abs(y[i]));
		const { coarse, fine, roundoff } = differenceJacobian(sys, t, y, Math.max(1, ymax) * 1e-3);

		let scale = 0;
		for (let i = 0; i < n; i++) {
			for (let k = 0; k < n; k++) scale = Math.max(scale, Math.abs(fine[i][k]), Math.abs(A[i][k]));
		}
		scale = Math.max(scale, 1e-300);
		for (let i = 0; i < n; i++) {
			for (let k = 0; k < n; k++) {
				const noise = Math.abs(coarse[i][k] - fine[i][k]);
				// Three floors: what the two differences disagree by, a
				// fraction of the matrix's own size, and what the subtraction
				// could not have resolved in the first place.
				const tol = Math.max(8 * noise, 1e-7 * scale, 4 * roundoff[i][k]);
				worst = Math.max(worst, Math.abs(A[i][k] - fine[i][k]) / tol);
				// Anything the difference can see must be in the pattern: an
				// entry outside it is dropped, and dropped silently.
				if (Math.abs(fine[i][k]) > 1e-6 * scale && Math.abs(fine[i][k]) > 4 * noise
					&& Math.abs(fine[i][k]) > 4 * roundoff[i][k]) {
					let found = false;
					for (let q = j.pattern.colPtr[k]; q < j.pattern.colPtr[k + 1]; q++) {
						if (j.pattern.rowIdx[q] === i) { found = true; break; }
					}
					if (!found) missing++;
				}
			}
		}
	}
	assert(missing === 0, `${missing} entries outside the sparsity pattern`);
	return { worst, jacobian: j, system: sys };
}

const jacBase = (extra) => ({
	simulation: {
		start_time: 0, end_time: 10, output_points: 3, spacing: 'linear', solver: 'ndf',
	},
	parameters: [{ name: 'k', value: 0.03 }, { name: 'q', value: 2.5 }, { name: 'n', value: 1.7 }],
	compartments: [
		{ name: 'A', initial: '100' }, { name: 'B', initial: '10' }, { name: 'C', initial: '1' },
	],
	transfers: [], expressions: [],
	...extra,
});

test('the tangent of every operator and function matches a difference', () => {
	const VARS = { a: 0, b: 1, c: 2 };
	const PARS = { p: 0, q: 1 };
	const build = (src) => {
		const tape = makeTape('\t');
		const r = emitWithTangent(parse(src), (name) => (
			name in VARS
				? { value: `y[${VARS[name]}]`, tangent: `dy[${VARS[name]}]` }
				: { value: `P[${PARS[name]}]`, tangent: null }
		), tape);
		// The temporaries are slots in an array on the context, so the
		// function declares it first. See `tapePrelude`.
		const fn = buildFunction(['y', 'dy', 'P'],
			[tapePrelude('\t'), ...tape.lines,
				`\treturn [${r.value}, ${r.tangent ?? 0}];`].join('\n'));
		const ctx = { t: 0.25, startTime: 0, endTime: 10 };
		return {
			stmts: tape.count,
			at: (y, dy, P) => fn(FUNCTION_TABLE, ctx, y, dy, P),
		};
	};

	const cases = [
		'a + b*c', 'a*b*c', 'a/b', 'a/(b/c)', '(a+b)/(b-c)/(a*c)',
		'a^2', 'a^3.5', 'a^-2', 'a^0.5', 'a^p', 'a^b', 'power(a, b)',
		'sqrt(a)*exp(-b)', 'log(a) + log10(b) + log2(c)',
		'sin(a)*cos(b)+tan(c)', 'tanh(a)+sinh(b)+cosh(c)',
		'asin(a/4)+acos(b/4)+atan(c)', 'atan2(a, b)', 'hypot(a, b)',
		'erf(a) + erfc(b)', 'abs(a)*abs(-b)', 'asinh(a)+acosh(b)+atanh(c)',
		'min(a, b, c)', 'max(a*2, b, c)', 'sum(a, b, c)', 'prod(a, b, c)',
		'mean(a, b, c)', 'if(a > 1, a*b, c^2)', 'if(a > 5, a*b, c^2)',
		'if(a > 1, a*b)', 'p*a + q*b', 'exp(-a/(b+c))*sqrt(a*b)',
		'a*floor(b) + round(c)*a', 'mod(a, 2) + rem(b, 3)', 'ulp(a)*1e15',
		'a*time() + b*end_time()', '(a<b)*c + (a==b)*a',
		'sqrt(a^2 + b^2 + 1)/log(c+2)',
	];
	const P = Float64Array.from([1.7, 0.4]);
	const y = Float64Array.from([1.3, 2.1, 0.7]);
	let worst = 0;
	for (const src of cases) {
		const b = build(src);
		for (let j = 0; j < 3; j++) {
			const dy = new Float64Array(3); dy[j] = 1;
			const analytic = b.at(y, dy, P)[1];
			const h = Math.max(1e-5, 1e-5 * Math.abs(y[j]));
			const value = (d) => {
				const z = Float64Array.from(y); z[j] += d;
				return b.at(z, new Float64Array(3), P)[0];
			};
			const d1 = (value(h) - value(-h)) / (2 * h);
			const d2 = (value(h / 2) - value(-h / 2)) / h;
			const fd = (4 * d2 - d1) / 3;   // Richardson
			const err = Math.abs(analytic - fd) / Math.max(1, Math.abs(fd), Math.abs(analytic));
			assert(err < 2e-6, `${src} d/dy${j}: ${analytic} vs ${fd}`);
			worst = Math.max(worst, err);
		}
	}
	assert(worst < 2e-6, `worst ${worst}`);
});

test('the tangent stays linear in the size of the expression', () => {
	// Inlined, d(a/b) and d(a^b) duplicate their operands, so a nested chain
	// grows as fan-out^depth. Naming each node is what keeps it linear.
	const build = (src) => {
		const tape = makeTape('\t');
		emitWithTangent(parse(src), (name) => ({ value: `y[0]`, tangent: `dy[0]` }), tape);
		return tape.count;
	};
	const shallow = build('a/(b/c)');
	const deep = build('a/(b/(c/(a/(b/(c/(a/b))))))');
	assert(deep < shallow * 8, `${shallow} -> ${deep} statements`);
	assert(build('((((a^b)^c)^a)^b)^c') < 40, 'nested powers blew up');
});

test('a function with no derivative is refused, not guessed', () => {
	let caught = null;
	const tape = makeTape('\t');
	try {
		emitWithTangent(parse('factorial(a)'),
			() => ({ value: 'y[0]', tangent: 'dy[0]' }), tape);
	} catch (e) { caught = e; }
	assert(caught instanceof NoDerivative, `threw ${caught}`);
	assert(/factorial/.test(caught.message), caught.message);

	// ... but the same call on a parameter is a constant, and constants are fine.
	const ok = emitWithTangent(parse('factorial(p)'),
		() => ({ value: 'P[0]', tangent: null }), makeTape('\t'));
	assert(ok.tangent === null, 'a constant should have no tangent at all');
});

test('the model generates a Jacobian that matches finite differences', () => {
	for (const [label, model] of [
		['linear transfers', jacBase({
			transfers: [
				{ name: 'T1', from: 'A', to: 'B', rate: 'k' },
				{ name: 'T2', from: 'B', to: 'C', rate: 'q' },
				{ name: 'T3', from: 'C', to: null, rate: 'k' },
				{ name: 'T4', from: null, to: 'A', rate: '5', multiply_by_donor: false },
			],
		})],
		['a rate that reads the state', jacBase({
			transfers: [{ name: 'T1', from: 'A', to: 'B', rate: 'k*B' }],
		})],
		['expressions feeding rates', jacBase({
			expressions: [
				{ name: 'E1', equation: 'sqrt(A) + B^n' },
				{ name: 'E2', equation: 'E1/(1 + C/q)' },
			],
			transfers: [
				{ name: 'T1', from: 'A', to: 'B', rate: 'k*E2' },
				{ name: 'T2', from: 'B', to: 'C', rate: 'E1*1e-6', multiply_by_donor: false },
			],
		})],
		['branches, min and max', jacBase({
			expressions: [{ name: 'E', equation: 'if(A > 50, min(A, B*3), max(C, 1)*q)' }],
			transfers: [{ name: 'T1', from: 'A', to: 'C', rate: 'k*E*1e-4' }],
		})],
		['a source term from an expression', jacBase({
			expressions: [{ name: 'E', equation: 'A*B*1e-3' }],
			inflows: [{ name: 'S', to: 'C', rate: 'E' }],
			transfers: [{ name: 'T1', from: 'A', to: 'B', rate: 'k' }],
		})],
		['a rate that reads the clock', jacBase({
			transfers: [{ name: 'T1', from: 'A', to: 'B', rate: 'k*(1 + time()/10)' }],
		})],
	]) {
		const { worst } = jacobianAgrees(model);
		assert(worst < 1, `${label}: off by ${worst.toFixed(2)}x the difference's own noise`);
	}
});

test('a quantity that cannot move with the state carries no tangent', () => {
	// A flow driven by a staircase in time whose values come from a table
	// read at the clock -- the shape a landscape model's water balance has,
	// where `WF_out` is `interpolationUseEndValues(time, ..., WF_out_marine,
	// ...)`. Nothing in it follows a compartment, so the staircase's points
	// are not live and the rule that will not differentiate a moving table
	// has nothing to refuse. It used to be handed a symbolic `dX[i]` for the
	// table and decline the whole model, which cost a 2,757-state model its
	// sparse matrix and made every step a dense factorisation.
	const model = jacBase({
		lookups: [{ name: 'Marine', points: [[0, 2], [5, 6], [10, 11]] }],
		expressions: [{ name: 'WF', equation: 'interpolationUseEndValues(time(), 0, Marine, 6, q*2)' }],
		transfers: [
			{ name: 'T1', from: 'A', to: 'B', rate: 'k*WF*1e-3' },
			{ name: 'T2', from: 'B', to: 'C', rate: 'q*1e-3' },
		],
	});
	const { worst } = jacobianAgrees(model);
	assert(worst < 1, `off by ${worst.toFixed(2)}x the difference's own noise`);

	// A table whose points really do follow a compartment is still refused,
	// and the reason names the block -- without which a model that declines
	// says only which function it was, in a model of four thousand equations.
	const live = buildSystem(new Project(jacBase({
		expressions: [{ name: 'WF', equation: 'interpolationUseEndValues(time(), 0, A, 6, q*2)' }],
		transfers: [{ name: 'T1', from: 'A', to: 'B', rate: 'k*WF*1e-3' }],
	})));
	assert(live.jacobian.available === false, 'a table whose points move was differentiated anyway');
	assert(/table that depends on the state/.test(live.jacobian.reason), live.jacobian.reason);
	assert(/'WF'/.test(live.jacobian.reason), live.jacobian.reason);
});

test('decay, ingrowth and several dimensions differentiate correctly', () => {
	const model = {
		index_lists: [
			{ name: 'Radionuclides', for_contaminants: true, indices: ['Pu-241', 'Am-241', 'Np-237'] },
			{ name: 'Object', indices: ['Lake', 'Mire', 'Forest'] },
			{ name: 'Wetland', sub_set_of: 'Object', indices: ['Lake', 'Mire'] },
		],
		simulation: {
			start_time: 0, end_time: 100, output_points: 3, spacing: 'linear', solver: 'ndf',
		},
		parameters: [
			{ name: 'k', value: 0.02, index_lists: ['Object'] }, { name: 'q', value: 3 },
		],
		compartments: [
			{ name: 'Soil', index_lists: ['Radionuclides', 'Object'], initial: '10' },
			{ name: 'Water', index_lists: ['Radionuclides', 'Object'], initial: '1' },
		],
		expressions: [
			{ name: 'Load', index_lists: ['Radionuclides'], equation: 'Soil[Lake] + Water[Mire]' },
		],
		transfers: [
			{ name: 'Perc', from: 'Soil', to: 'Water', rate: 'k', index_lists: ['Radionuclides', 'Object'] },
			{ name: 'Wet', from: 'Water', to: 'Soil', rate: 'k*1e-3', index_lists: ['Radionuclides', 'Wetland'] },
			{ name: 'Nl', from: 'Soil', to: null, rate: 'Load*1e-6', index_lists: ['Radionuclides', 'Object'] },
		],
	};
	const { worst, jacobian } = jacobianAgrees(model);
	assert(worst < 1, `off by ${worst.toFixed(2)}x the difference's own noise`);
	assert(jacobian.nnz < 18 * 18, 'the pattern is no better than dense');

	// Turning decay off changes the pattern, and must still be right.
	const off = structuredClone(model);
	off.compartments[0].handle_decay = false;
	const second = jacobianAgrees(off);
	assert(second.worst < 1, `handle_decay false: ${second.worst}`);
	assert(second.jacobian.nnz < jacobian.nnz, 'dropping ingrowth should drop entries');
});

test('every bundled example gets a Jacobian that matches', async () => {
	const { readFileSync, readdirSync } = await import('node:fs');
	const dir = new URL('../examples/', import.meta.url);
	for (const f of readdirSync(dir).filter((x) => x.endsWith('.json'))) {
		const model = JSON.parse(readFileSync(new URL(f, dir), 'utf8'));
		// A model with no compartments is never differentiated: there is
		// nothing to integrate and so nothing to take df/dy of.
		if (!(model.compartments ?? []).length) {
			const built = buildSystem(new Project(model));
			assert(built.jacobian.available === false, f);
			assert(/no compartments/.test(built.jacobian.reason), built.jacobian.reason);
			continue;
		}
		const { worst, jacobian } = jacobianAgrees(model);
		assert(worst < 1, `${f}: off by ${worst.toFixed(2)}x the difference's own noise`);
		// Every example's rates are constants, so df/dy is too -- except the
		// ones whose rates follow a lookup table, which is what those are for,
		// and the ones with a block that remembers: a min/max switches between
		// its target and the extreme so far, and a running mean divides by a
		// time that grows.
		const moving = (model.lookups ?? []).length > 0
			|| ['min_maxes', 'running_means', 'snapshots', 'delays']
				.some((k) => (model[k] ?? []).length > 0)
			// ...and waste packages whose failure hazard reads the clock: a
			// window, a constant rate from a start, a Weibull. Never and
			// all-at-once have no hazard, so they leave the matrix constant.
			|| (model.waste_packages ?? []).some((w) => !['never', 'at'].includes(w.failure ?? 'never'));
		assert(jacobian.constant === !moving,
			`${f}: constant=${jacobian.constant} with ${moving ? 'a' : 'no'} moving block`);
	}
});

test('a constant Jacobian is recognised, and a varying one is not called constant', () => {
	const constant = buildSystem(new Project(jacBase({
		transfers: [{ name: 'T1', from: 'A', to: 'B', rate: 'k' }],
	}))).jacobian;
	assert(constant.constant, 'a rate that is a parameter gives a constant Jacobian');

	for (const rate of ['k*B', 'k*(1 + time())']) {
		const j = buildSystem(new Project(jacBase({
			transfers: [{ name: 'T1', from: 'A', to: 'B', rate }],
		}))).jacobian;
		assert(!j.constant, `'${rate}' cannot give a constant Jacobian`);
	}
});

test('a model the generator cannot differentiate still runs', () => {
	const model = jacBase({
		expressions: [{ name: 'E', equation: 'factorial(A)' }],
		transfers: [{ name: 'T1', from: 'A', to: 'B', rate: 'E*1e-9' }],
	});
	const sys = buildSystem(new Project(model));
	assert(!sys.jacobian.available, 'should have declined');
	assert(/factorial/.test(sys.jacobian.reason), sys.jacobian.reason);
	// and the run falls back to differencing rather than failing
	const r = run(model);
	assert(r.y.length > 1, 'it still solved');
});

test('mapped and sub-set dimensions differentiate through their tables', () => {
	// The offsets here go through MAPS[k][n0]; the tangent has to follow the
	// same table, and a pattern that missed an entry would drop it silently.
	const model = {
		index_lists: [
			{ name: 'Region', indices: ['North', 'South'] },
			{
				name: 'Object', indices: ['Lake', 'Mire', 'Forest'],
				mapping: {
					to: 'Region',
					pairs: [
						{ from: 'Lake', to: 'North' },
						{ from: 'Mire', to: 'North' },
						{ from: 'Forest', to: 'South' },
					],
				},
			},
			{ name: 'Wetland', sub_set_of: 'Object', indices: ['Lake', 'Mire'] },
		],
		simulation: {
			start_time: 0, end_time: 10, output_points: 3, spacing: 'linear', solver: 'ndf',
		},
		parameters: [{
			name: 'k', index_lists: ['Region'], value: 0.1,
			entries: [{ index: { Region: 'South' }, value: 0.4 }],
		}],
		compartments: [
			{ name: 'A', index_lists: ['Object'], initial: '1' },
			{ name: 'B', index_lists: ['Object'], initial: '0' },
		],
		expressions: [
			// state-dependent, so the tangent has to travel the mapping too
			{ name: 'E', index_lists: ['Object'], equation: 'k*(1 + A/100)' },
		],
		transfers: [
			{ name: 'T', from: 'A', to: 'B', index_lists: ['Object'], rate: 'E' },
			{ name: 'W', from: 'B', to: 'A', index_lists: ['Wetland'], rate: '0.05' },
		],
	};
	const { worst } = jacobianAgrees(model);
	assert(worst < 1, `off by ${worst.toFixed(2)}x the difference's own noise`);
});

test('the colouring costs a few passes, not one per state', () => {
	// A chain of compartments: every row has at most three entries, so three
	// or four seeds should cover the whole matrix however long the chain is.
	const n = 40;
	const model = {
		simulation: {
			start_time: 0, end_time: 10, output_points: 3, spacing: 'linear', solver: 'ndf',
		},
		parameters: [{ name: 'k', value: 0.1 }],
		compartments: Array.from({ length: n }, (_, i) => ({
			name: `C${i}`, initial: i === 0 ? '1' : '0',
		})),
		transfers: Array.from({ length: n - 1 }, (_, i) => ({
			name: `T${i}`, from: `C${i}`, to: `C${i + 1}`, rate: 'k',
		})),
		expressions: [],
	};
	const j = buildSystem(new Project(model)).jacobian;
	assert(j.colours <= 4, `${j.colours} colours for a chain of ${n}`);
	assert(colouringIsValid(j.pattern, j.groups), 'invalid colouring');
	assert(j.nnz === 2 * n - 1, `${j.nnz} entries, expected ${2 * n - 1}`);
});

test('a supplied Jacobian gives the same trajectory as a differenced one', () => {
	const model = {
		simulation: {
			start_time: 0, end_time: 200, output_points: 9, spacing: 'linear',
			solver: 'ndf', rtol: 1e-10, abstol: 1e-16,
		},
		parameters: [{ name: 'k', value: 0.05 }],
		compartments: [
			{ name: 'A', initial: '1' }, { name: 'B', initial: '0' }, { name: 'C', initial: '0' },
		],
		transfers: [
			{ name: 'T1', from: 'A', to: 'B', rate: 'k' },
			{ name: 'T2', from: 'B', to: 'C', rate: 'k*0.5' },
		],
		expressions: [],
	};
	const p = new Project(model);
	const sys = buildSystem(p);
	const grid = p.timeGrid();
	const y0 = sys.initialState();
	const opts = { rtol: 1e-10, abstol: 1e-16 };
	const dense = Array.from({ length: 3 }, () => new Float64Array(3));

	const differenced = variableOrder(sys.dydt, grid, y0, opts);
	const asFunction = variableOrder(sys.dydt, grid, y0, {
		...opts,
		jacobian: (t, y) => { sys.jacobian.evaluateDense(t, y, dense); return dense; },
	});
	const asMatrix = variableOrder(sys.dydt, grid, y0, {
		...opts,
		jacobian: sys.jacobian.evaluateDense(0, y0,
			Array.from({ length: 3 }, () => new Float64Array(3))),
	});
	const asSparse = variableOrder(sys.dydt, grid, y0, { ...opts, jacobian: sys.jacobian });

	// The closed-form solution of the chain, for all four.
	const k = 0.05, k2 = 0.025;
	for (const [label, r] of [['differenced', differenced], ['function', asFunction],
		['matrix', asMatrix], ['sparse', asSparse]]) {
		const t = grid[grid.length - 1];
		close(r.y[r.t.length - 1][0], Math.exp(-k * t), 1e-7, `${label}: A`);
		close(r.y[r.t.length - 1][1],
			(k / (k2 - k)) * (Math.exp(-k * t) - Math.exp(-k2 * t)), 1e-7, `${label}: B`);
	}
	// The matrix form is a constant Jacobian: built once.
	assert(asMatrix.stats.npds === 1, `constant Jacobian evaluated ${asMatrix.stats.npds} times`);
	assert(asSparse.stats.npds === 1, `sparse constant Jacobian evaluated ${asSparse.stats.npds} times`);
	// A differenced Jacobian costs a column of evaluations each time it is
	// refreshed. For variableOrder on a constant-coefficient model that is one
	// refresh, so the saving is small here and shows up in rosenbrock23 below.
	assert(differenced.stats.npds >= 1, 'the differenced run built one too');
});

test('the whole pipeline agrees with itself, Jacobian or no Jacobian', () => {
	// 60 states, so the sparse path is the one under test.
	const n = 30;
	const model = {
		index_lists: [{ name: 'Radionuclides', for_contaminants: true, indices: ['Cs-137', 'Sr-90'] }],
		simulation: {
			start_time: 0, end_time: 500, output_points: 7, spacing: 'linear',
			solver: 'ndf', rtol: 1e-9, abstol: 1e-14,
		},
		parameters: [{ name: 'k', value: 0.02 }],
		compartments: Array.from({ length: n }, (_, i) => ({
			name: `C${i}`, initial: i === 0 ? '1e6' : '0', index_lists: ['Radionuclides'],
		})),
		transfers: Array.from({ length: n - 1 }, (_, i) => ({
			name: `T${i}`, from: `C${i}`, to: `C${i + 1}`, rate: 'k', index_lists: ['Radionuclides'],
		})),
		expressions: [],
	};
	const p = new Project(model);
	const sys = buildSystem(p);
	const grid = p.timeGrid();
	const y0 = sys.initialState();
	const opts = { rtol: 1e-9, abstol: 1e-14 };

	const plain = variableOrder(sys.dydt, grid, y0, opts);
	const sparse = variableOrder(sys.dydt, grid, y0, { ...opts, jacobian: sys.jacobian });
	assert(sparse.stats.sparse, 'this size should take the sparse path');

	let worst = 0, scale = 0;
	for (let i = 0; i < plain.t.length; i++) {
		for (let j = 0; j < 2 * n; j++) {
			worst = Math.max(worst, Math.abs(plain.y[i][j] - sparse.y[i][j]));
			scale = Math.max(scale, Math.abs(plain.y[i][j]));
		}
	}
	assert(worst / scale < 1e-7, `trajectories differ by ${worst / scale}`);

	// rosenbrock23 re-forms its Jacobian at every step, so there the analytic one
	// removes n evaluations of the model per step rather than n once.
	const differenced = rosenbrock23(sys.dydt, grid, y0, opts);
	const analytic = rosenbrock23(sys.dydt, grid, y0, { ...opts, jacobian: sys.jacobian });
	assert(analytic.stats.nfevals * 10 < differenced.stats.nfevals,
		`${analytic.stats.nfevals} evaluations against ${differenced.stats.nfevals}`);
	assert(analytic.stats.npds === 1, `Jacobian built ${analytic.stats.npds} times`);
	let d23 = 0, s23 = 0;
	for (let i = 0; i < differenced.t.length; i++) {
		for (let j = 0; j < 2 * n; j++) {
			d23 = Math.max(d23, Math.abs(differenced.y[i][j] - analytic.y[i][j]));
			s23 = Math.max(s23, Math.abs(differenced.y[i][j]));
		}
	}
	assert(d23 / s23 < 1e-6, `rosenbrock23 trajectories differ by ${d23 / s23}`);
});

test('sparse LU agrees with the dense one, and finds a singular matrix', () => {
	let seed = 20240905;
	const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
	for (const [n, perRow] of [[10, 2], [60, 3], [200, 4]]) {
		const I = [], J = [], V = [];
		for (let i = 0; i < n; i++) {
			I.push(i); J.push(i); V.push(2 + rnd() * 3);
			for (let q = 0; q < perRow; q++) {
				const j = Math.floor(rnd() * n);
				if (j !== i) { I.push(i); J.push(j); V.push(rnd() * 2 - 1); }
			}
		}
		const A = cscFromTriplets(n, n, Int32Array.from(I), Int32Array.from(J), Float64Array.from(V));
		const b = Float64Array.from({ length: n }, () => rnd() * 2 - 1);
		const lu = new SparseLU(n).factorize(A);
		assert(!lu.singular, `n=${n} reported singular`);
		const x = lu.solve(b);

		const r = new Float64Array(n);
		cscMulVec(A, x, r);
		let res = 0, nb = 0;
		for (let i = 0; i < n; i++) {
			res = Math.max(res, Math.abs(r[i] - b[i]));
			nb = Math.max(nb, Math.abs(b[i]));
		}
		assert(res / nb < 1e-10, `n=${n} residual ${res / nb}`);

		const dense = new LU(n).factorize(cscToDense(A)).solve(b);
		let diff = 0, nx = 0;
		for (let i = 0; i < n; i++) {
			diff = Math.max(diff, Math.abs(x[i] - dense[i]));
			nx = Math.max(nx, Math.abs(dense[i]));
		}
		assert(diff / nx < 1e-8, `n=${n} differs from the dense solve by ${diff / nx}`);
	}

	// Two identical rows: no pivot exists, and saying so beats returning NaN.
	const singular = cscFromTriplets(2, 2,
		Int32Array.from([0, 0, 1, 1]), Int32Array.from([0, 1, 0, 1]),
		Float64Array.from([1, 2, 2, 4]));
	assert(new SparseLU(2).factorize(singular).singular, 'should be singular');
});

test('the iteration matrix is I - h*J, and renumbering cuts the fill', () => {
	const n = 5;
	const I = [], J = [], V = [];
	for (let i = 0; i < n; i++) {
		I.push(i); J.push(i); V.push(-1 - i);
		if (i + 1 < n) { I.push(i + 1); J.push(i); V.push(0.5); }
	}
	const Jm = cscFromTriplets(n, n, Int32Array.from(I), Int32Array.from(J), Float64Array.from(V));
	const builder = makeMiterBuilder(Jm);
	const M = cscToDense(builder.update(0.25, Jm.values));
	const dense = cscToDense(Jm);
	for (let i = 0; i < n; i++) {
		for (let j = 0; j < n; j++) {
			close(M[i][j], (i === j ? 1 : 0) - 0.25 * dense[i][j], 1e-15, `M[${i}][${j}]`);
		}
	}

	// A banded matrix whose rows were declared in a scattered order fills in
	// badly in that order and hardly at all once renumbered.
	let seed = 7;
	const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
	const m = 200;
	const perm = Array.from({ length: m }, (_, i) => i).sort(() => rnd() - 0.5);
	const bi = [], bj = [], bv = [];
	for (let i = 0; i < m; i++) {
		for (let d = -2; d <= 2; d++) {
			const j = i + d;
			if (j < 0 || j >= m) continue;
			bi.push(perm[i]); bj.push(perm[j]); bv.push(d === 0 ? 4 : -1);
		}
	}
	const band = cscFromTriplets(m, m, Int32Array.from(bi), Int32Array.from(bj), Float64Array.from(bv));
	const natural = new SparseLU(m).factorize(band);
	const renumbered = new SparseLU(m).factorize(band, { q: reverseCuthillMcKeeOrder(band) });
	assert(renumbered.lnz + renumbered.unz < 0.6 * (natural.lnz + natural.unz),
		`fill ${natural.lnz + natural.unz} -> ${renumbered.lnz + renumbered.unz}`);
});

