test('the Jacobian check finds a wrong matrix, a missing entry and a bad colouring', async () => {
	const { checkJacobian } = await import('../src/sim/jaccheck.js');
	const { buildSystem: build } = await import('../src/sim/builder.js');
	const { readFileSync } = await import('node:fs');

	// A check that cannot fail is decoration. Each of the three faults below is
	// planted in a real model's generated Jacobian and has to be reported --
	// and reported as the *right* fault, since the three want different fixes.
	const raw = JSON.parse(readFileSync(
		new URL('../examples/landscape.json', import.meta.url), 'utf8',
	));
	const fresh = () => build(new Project(structuredClone(raw)));

	// Untouched: it agrees, which is the claim the rest of the suite rests on
	// every time it believes a stiff run.
	const clean = checkJacobian(structuredClone(raw));
	assert(clean.available && clean.verdict === 'agrees',
		`landscape.json: ${clean.verdict} — ${JSON.stringify(clean.at?.[0]?.disagreements?.[0] ?? {})}`);
	assert(clean.at.some((c) => c.checked > 20), 'nothing was actually compared');
	// Every state is named, or the hover is useless on the model that needs it.
	assert(clean.labels.length === clean.n && clean.labels.every((l) => l && !/^state \d/.test(l)),
		'some states have no name');

	// 1. A wrong value. Scaling one entry moves it far outside the 0.1% the
	//    comparison allows, and the report has to name the two states.
	{
		// Planted in both readers of the generated tangent, which is what a real
		// fault in it would touch: `evaluate` fills the whole matrix and `jvp`
		// answers one direction, and the check reads values through both --
		// group by group through `jvp`, column by column through `evaluate`.
		const sys = fresh();
		const realEval = sys.jacobian.evaluate;
		const realJvp = sys.jacobian.jvp;
		sys.jacobian.evaluate = (t, y) => { const v = realEval(t, y); if (v) v[3] *= 1.5; return v; };
		sys.jacobian.jvp = (t, y, v, out) => {
			const o = realJvp(t, y, v, out);
			// The same entry: the row of the fourth non-zero, when its column
			// carries the seed.
			const j = [...sys.jacobian.pattern.colPtr].findIndex((c, k) => c > 3 && k > 0) - 1;
			if (v[j]) o[sys.jacobian.pattern.rowIdx[3]] *= 1.5;
			return o;
		};
		const r = checkJacobian(structuredClone(raw), { system: sys });
		assert(r.verdict === 'differs', `a 50% error read as ${r.verdict}`);
		const d = r.at.flatMap((c) => c.disagreements)[0];
		assert(d && d.rowLabel && d.colLabel && d.relative > 0.2,
			`the disagreement is not described: ${JSON.stringify(d)}`);
	}

	// 2. A missing entry: the pattern loses a column's off-diagonal rows while
	//    the model keeps them. This is the one a tolerance never recovers --
	//    the solver simply never evaluates an entry the pattern does not have --
	//    so it outranks a wrong value in the verdict.
	{
		const sys = fresh();
		const p = sys.jacobian.pattern;
		const drop = 4;
		const rows = [];
		const ptr = new Int32Array(p.n + 1);
		const keep = [];
		let at = 0;
		let flat = 0;
		for (let j = 0; j < p.n; j++) {
			ptr[j] = at;
			for (let k = p.colPtr[j]; k < p.colPtr[j + 1]; k++) {
				const i = p.rowIdx[k];
				if (!(j === drop && i !== j)) { rows.push(i); keep.push(flat); at++; }
				flat++;
			}
		}
		ptr[p.n] = at;
		const real = sys.jacobian.evaluate;
		sys.jacobian.pattern = { n: p.n, nnz: at, colPtr: ptr, rowIdx: Int32Array.from(rows) };
		sys.jacobian.evaluate = (t, y) => {
			const v = real(t, y);
			return v ? Float64Array.from(keep, (k) => v[k]) : v;
		};
		const r = checkJacobian(structuredClone(raw), { system: sys });
		assert(r.verdict === 'missing', `a hole in the pattern read as ${r.verdict}`);
		const o = r.at.flatMap((c) => c.outside)[0];
		assert(o && o.col === drop && Math.abs(o.numeric) > 0,
			`the missing entry is not described: ${JSON.stringify(o)}`);
	}

	// 3. A colouring that is not one. Two columns sharing a row in one group
	//    means the seeds collide and every value read back through it is a sum,
	//    which no comparison of *values* would catch -- the values are read
	//    column by column here. It is checked structurally instead.
	{
		const sys = fresh();
		sys.jacobian.groups = [Array.from({ length: sys.layout.nstate }, (_, j) => j)];
		const r = checkJacobian(structuredClone(raw), { system: sys });
		assert(r.verdict === 'colouring', `one group of everything read as ${r.verdict}`);
		assert(r.colouring.clashes.length > 0, 'no clash was reported');
	}
});

test('the Jacobian check says what it could not judge, and stays affordable', async () => {
	const { checkJacobian, MANY_COLUMNS } = await import('../src/sim/jaccheck.js');
	const { readFileSync } = await import('node:fs');
	const load = (name) => JSON.parse(readFileSync(
		new URL(`../examples/${name}.json`, import.meta.url), 'utf8',
	));

	// An entry whose effect on the derivative is below that derivative's own
	// rounding cannot be judged by a difference quotient. Counting those
	// separately is the difference between an honest report and one that either
	// buries real disagreements among noise or calls noise agreement.
	const bio = checkJacobian(load('biosphere'));
	assert(bio.verdict === 'agrees', bio.verdict);
	const unresolvable = bio.at.reduce((s, c) => s + c.unresolvable, 0);
	const checked = bio.at.reduce((s, c) => s + c.checked, 0);
	assert(checked > 0 && unresolvable > 0,
		`${checked} judged, ${unresolvable} unresolvable — both should happen`);
	// Both counts are of *pattern entries* now. The sweep goes group by group
	// rather than column by column, so it judges what the matrix declares
	// instead of scanning every cell of an n-by-n square, and the two numbers
	// add up to the entries of the groups it swept rather than to n squared.
	assert(checked + unresolvable < bio.n * bio.n,
		'the check is still scanning the whole square');

	// Several states, not one: at the model's own start most compartments are
	// empty, and an empty compartment's column moves nothing.
	assert(bio.at.length >= 3, `only ${bio.at.length} states checked`);
	assert(/initial state/.test(bio.at[0].label), bio.at[0].label);

	// A model too wide to difference whole bounds both passes and says so,
	// rather than taking minutes or quietly checking only the first block.
	const far = checkJacobian(load('farfield'));
	assert(far.available && far.n > MANY_COLUMNS, `farfield is ${far.n} states`);
	assert(far.sampled && far.at.every((c) => c.columns <= MANY_COLUMNS),
		'a 1,266-state model scanned every column for entries outside the pattern');
	assert(far.verdict === 'agrees', far.verdict);
	// And the colouring is what makes it affordable: one evaluation of the
	// model per *group* covers every entry of every column in it, so a
	// 1,266-state matrix is judged on tens of thousands of entries rather than
	// on the four hundred columns a per-column sweep could afford.
	const farChecked = far.at.reduce((s, c) => s + c.checked, 0);
	assert(farChecked > 5000, `only ${farChecked} entries judged on a 4,630-entry matrix`);
	// And its states are still named -- a far-field cell is not an ordinary
	// block entry, and labelling it used to throw.
	assert(far.labels.some((l) => /Rock \[.*\] [FM]/.test(l)),
		`far-field cells are unnamed: ${far.labels[8]}`);

	// A model with no analytic Jacobian is refused with the generator's own
	// reason rather than with an empty picture.
	const none = checkJacobian(load('post-processing'));
	assert(!none.available && /compartment/.test(none.reason), JSON.stringify(none));
});

section('the element dimension and index-list relations');

test('two lists are related through whatever root they share', () => {
	// Materials, the sub-set of it that decays, and an element list mapped
	// onto it -- the shape every biosphere assessment model has. Reading the element
	// list from a block indexed by the *sub-set* needs two steps, which is
	// what used to fail: only direct relations were understood.
	const space = new IndexSpace([
		{ name: 'Contaminants', indices: ['Cs-137', 'Cs-135', 'Sr-90', 'I-129'] },
		{ name: 'Radionuclides', sub_set_of: 'Contaminants', indices: ['Cs-137', 'Sr-90', 'I-129'] },
		{
			name: 'Elements',
			mapping: {
				to: 'Contaminants',
				pairs: [
					{ from: 'Cs', to: 'Cs-137' }, { from: 'Cs', to: 'Cs-135' },
					{ from: 'Sr', to: 'Sr-90' }, { from: 'I', to: 'I-129' },
				],
			},
			indices: ['Cs', 'Sr', 'I'],
		},
	]);
	const table = (a, b) => {
		const r = space.relate(a, b);
		return r == null ? null : r.kind === 'same' ? 'same' : [...r.table].join(',');
	};
	// Standing at each radionuclide, its element: Cs-137 -> Cs, Sr-90 -> Sr…
	assert(table('Elements', 'Radionuclides') === '0,1,2', table('Elements', 'Radionuclides'));
	// …and at each material, likewise -- two isotopes of caesium, one element.
	assert(table('Elements', 'Contaminants') === '0,0,1,2', table('Elements', 'Contaminants'));
	// The other way a mapping has to pick a representative, since an element
	// has many isotopes. The first the file names is taken.
	assert(table('Radionuclides', 'Elements') === '0,1,2', table('Radionuclides', 'Elements'));
	assert(table('Contaminants', 'Elements') === '0,2,3', table('Contaminants', 'Elements'));
	// Sub-set relations still work, and a missing one is still a hole.
	assert(table('Contaminants', 'Radionuclides') === '0,2,3');
	assert(space.relate('Radionuclides', 'Contaminants').partial === true);
	assert(table('Radionuclides', 'Contaminants') === '0,-1,1,2');
	assert(table('Elements', 'Elements') === 'same');
});

test('unrelated lists stay unrelated', () => {
	const space = new IndexSpace([
		{ name: 'Radionuclides', for_contaminants: true, indices: ['Cs-137'] },
		{ name: 'Object', indices: ['Lake', 'Mire'] },
	]);
	assert(space.relate('Object', 'Radionuclides') === null);
	assert(space.relate('Radionuclides', 'Object') === null);
});

test('a list defined in terms of itself is refused', () => {
	let caught = null;
	try {
		// eslint-disable-next-line no-new
		new IndexSpace([
			{ name: 'A', mapping: { to: 'B', pairs: [] }, indices: ['x'] },
			{ name: 'B', mapping: { to: 'A', pairs: [] }, indices: ['y'] },
		]);
	} catch (e) { caught = e; }
	assert(caught instanceof IndexError, String(caught));
	assert(/in terms of itself/.test(caught.message), caught.message);
});

test('an element list is derived from the nuclides', () => {
	const p = new Project({
		name: 'el',
		nuclides: ['Cs-137', 'Cs-135', 'Sr-90'],
		half_lives: { 'Cs-135': 2.3e6 },
		compartments: [{ name: 'A', initial: '1' }],
	});
	const el = p.index_lists.find((l) => l.for_elements);
	assert(el, p.index_lists.map((l) => l.name).join(','));
	assert(el.name === 'Elements', el.name);
	assert(el.indices.map((i) => i.name).join(',') === 'Cs,Sr', el.indices.map((i) => i.name).join(','));
	// Mapped onto the catalogue, which is where Ecolego maps it:
	// `allElements.createMapping(allMaterial)`. Its indices still come from
	// the radionuclides -- `materialAdded` gives a material an element only
	// when it is a nuclide -- so a material that does not decay groups under
	// nothing.
	assert(el.mapping.to === 'Contaminants', el.mapping.to);
	// Derived, so it is not written to the file -- the two could otherwise
	// drift apart, and the nuclide list is the one that decides.
	assert(!p.toJSON().index_lists.some((l) => l.name === 'Elements'),
		JSON.stringify(p.toJSON().index_lists.map((l) => l.name)));
	// A model with no nuclides has no elements either.
	const bare = new Project({ name: 'b', compartments: [{ name: 'A', initial: '1' }] });
	assert(!bare.index_lists.some((l) => l.for_elements));

	// A file whose one material list is already *called* the catalogue is one:
	// it keeps the name and the role, and gains the radionuclide sub-set empty.
	// Demoting it would put a second catalogue above a list named `Materials`,
	// which is two lists claiming the same name's job -- and the second would
	// have to be called something else.
	const lone = ed.migrateKeys({
		name: 'lone',
		index_lists: [{ name: 'Contaminants', for_contaminants: true, indices: ['I-129'] }],
		compartments: [{ name: 'A', initial: '1', index_lists: ['Contaminants'] }],
	});
	assert(lone.index_lists.map((l) => l.name).join() === 'Contaminants',
		JSON.stringify(lone.index_lists.map((l) => l.name)));
	const loneRaw = structuredClone(lone);
	ed.materialiseShorthand(loneRaw);
	assert(loneRaw.index_lists.map((l) => l.name).join() === 'Contaminants,Radionuclides',
		JSON.stringify(loneRaw.index_lists.map((l) => l.name)));
	// Its elements still follow the catalogue: an empty radionuclide list is
	// not an answer to which of the materials decay.
	const loneEl = ed.indexLists(loneRaw).find((l) => l.for_elements);
	assert(loneEl?.indices.map((i) => i.name).join() === 'I', JSON.stringify(loneEl?.indices));

	// Every material has an element, not only the ones that decay: a mapping
	// has to cover the list it groups, or a parameter indexed by the elements
	// has no cell to be read at from a block indexed by the materials -- which
	// the build refuses, naming the missing index. Stable C-12 is the same
	// element as C-14 and joins it under `C`; a name that is not a nuclide's
	// is its own element, since there is nothing else it could belong to.
	const mixed = new Project({
		name: 'mixed',
		index_lists: [
			{ name: 'Contaminants', for_contaminants: true, indices: ['C-14', 'C-12', 'water'] },
			{
				name: 'Radionuclides', for_nuclides: true, sub_set_of: 'Contaminants',
				indices: ['C-14'],
			},
		],
		compartments: [{ name: 'A', initial: '1' }],
	});
	const mel = mixed.index_lists.find((l) => l.for_elements);
	assert(mel.indices.map((i) => i.name).join() === 'C,water', JSON.stringify(mel.indices));
	assert(mel.mapping.pairs.map((p) => `${p.from}<-${p.to}`).join()
		=== 'C<-C-14,C<-C-12,water<-water', JSON.stringify(mel.mapping.pairs));
	// ...and that is a model that builds: chemistry written per element is
	// readable at every material, which is the whole point of covering them.
	const chem = run({
		name: 'chem',
		simulation: {
			start_time: 0, end_time: 1, output_points: 2, spacing: 'linear',
			solver: 'dp45', rtol: 1e-8, abstol: 1e-12, time_unit: 'year',
		},
		index_lists: [
			{ name: 'Contaminants', for_contaminants: true, indices: ['C-14', 'water'] },
			{ name: 'Radionuclides', for_nuclides: true, sub_set_of: 'Contaminants',
				indices: ['C-14'] },
		],
		parameters: [{ name: 'Kd', index_lists: ['Elements'], value: 1,
			entries: [{ index: { Elements: 'C' }, value: 7 }] }],
		expressions: [{ name: 'readKd', equation: 'Kd', index_lists: ['Contaminants'] }],
		compartments: [{ name: 'Pool', initial: '0', index_lists: ['Contaminants'] }],
	});
	const at = (n) => chem.series(chem.outputs().find((o) => o.label === `readKd [${n}]`))[0];
	close(at('C-14'), 7, 0, 'the element’s own value');
	close(at('water'), 1, 0, 'the material that is its own element');
});

test('a material added to a stored element list brings its element with it', () => {
	// A derived element list works itself out; a *stored* one -- which is what
	// every imported model has -- follows nothing. So the editor keeps it in
	// step, because a mapping has to cover the list it groups: a material no
	// element stands for is a material at which nothing indexed by the
	// elements can be read, and the build refuses the model rather than
	// guessing. That is the shape of an imported model, where `Elements` maps
	// onto `Materials` and is written down with its pairs.
	const model = () => ({
		name: 'imported-ish',
		index_lists: [
			{ name: 'Contaminants', for_contaminants: true, indices: ['C-14'] },
			{
				name: 'Radionuclides', for_nuclides: true, sub_set_of: 'Contaminants',
				indices: ['C-14'],
			},
			{
				name: 'Elements', for_elements: true, indices: ['C'],
				mapping: { to: 'Contaminants', pairs: [{ from: 'C', to: 'C-14' }] },
			},
		],
		parameters: [{ name: 'Kd', index_lists: ['Elements'], value: 1 }],
		compartments: [{ name: 'Pool', initial: '0', index_lists: ['Contaminants'] }],
	});
	const elementsOf = (m) => {
		const el = ed.findIndexList(m, 'Elements');
		return {
			indices: el.indices.map((i) => i.name).join(),
			pairs: (el.mapping.pairs ?? []).map((p) => `${p.from}<-${p.to}`).join(),
		};
	};

	// A material that is nobody's isotope is its own element.
	const m = model();
	ed.addIndex(m, 'Contaminants', 'water');
	assert(elementsOf(m).indices === 'C,water', JSON.stringify(elementsOf(m)));
	assert(elementsOf(m).pairs === 'C<-C-14,water<-water', JSON.stringify(elementsOf(m)));

	// One that is joins the element already there rather than starting a
	// second: C-12 and C-14 are one element and one sorption coefficient is
	// right for both.
	ed.addIndex(m, 'Contaminants', 'C-12');
	assert(elementsOf(m).indices === 'C,water', JSON.stringify(elementsOf(m)));
	assert(elementsOf(m).pairs === 'C<-C-14,water<-water,C<-C-12',
		JSON.stringify(elementsOf(m)));

	// A radionuclide is a material, so adding one there does it too -- which
	// is `materialAdded` giving a nuclide its element index.
	ed.addIndex(m, 'Radionuclides', 'I-129');
	assert(elementsOf(m).indices === 'C,water,I', JSON.stringify(elementsOf(m)));
	assert(/I<-I-129/.test(elementsOf(m).pairs), JSON.stringify(elementsOf(m)));

	// Removing the material takes the pair, and the element with it once
	// nothing is left under it -- `materialRenamed` removes the old element
	// index the same way. An element standing for nothing is a column in every
	// chemistry parameter that can never be read.
	ed.removeIndex(m, 'Contaminants', 'water');
	assert(elementsOf(m).indices === 'C,I', JSON.stringify(elementsOf(m)));
	assert(!/water/.test(elementsOf(m).pairs), JSON.stringify(elementsOf(m)));
	// ...but an element with another member still standing stays.
	ed.removeIndex(m, 'Radionuclides', 'C-14');
	assert(elementsOf(m).indices === 'C,I', `C went with C-14: ${JSON.stringify(elementsOf(m))}`);
	assert(elementsOf(m).pairs === 'C<-C-12,I<-I-129', JSON.stringify(elementsOf(m)));

	// And the model still builds at every material, which is what covering
	// them is for.
	const built = new Project(structuredClone(m));
	assert(built.index_lists.find((l) => l.name === 'Elements').indices.length === 2);

	// A model's own grouping of its materials is not guessed at: `Species` is
	// a classification, not a rule, so a new material is left out of it and
	// the build says so if anything reads it.
	const own = model();
	// Ahead of the element list, so that finding the element one is finding
	// *the element one* rather than whichever grouping comes first.
	own.index_lists.splice(2, 0, {
		name: 'Species', indices: ['aqueous'],
		mapping: { to: 'Contaminants', pairs: [{ from: 'aqueous', to: 'C-14' }] },
	});
	ed.addIndex(own, 'Contaminants', 'water');
	assert(ed.findIndexList(own, 'Species').indices.map((i) => i.name).join() === 'aqueous',
		JSON.stringify(ed.findIndexList(own, 'Species').indices));
	assert(!(ed.findIndexList(own, 'Species').mapping.pairs ?? [])
		.some((p) => p.to === 'water'), 'a species was guessed at');
	assert(ed.findIndexList(own, 'Elements').indices.map((i) => i.name).join() === 'C,water',
		JSON.stringify(ed.findIndexList(own, 'Elements').indices));
});

test('a model that declares its own element list keeps it', () => {
	const p = new Project({
		name: 'own',
		index_lists: [
			{ name: 'Radionuclides', for_contaminants: true, indices: ['C-14-org', 'C-14-inorg'] },
			{
				// Carbon kept apart by chemical form, which the derived list
				// cannot express -- so the model says it and this tool steps
				// aside rather than adding a second, coarser one.
				name: 'Elements', mapping: { to: 'Radionuclides', pairs: [
					{ from: 'C-org', to: 'C-14-org' }, { from: 'C-inorg', to: 'C-14-inorg' },
				] }, indices: ['C-org', 'C-inorg'],
			},
		],
		half_lives: { 'C-14-org': 5700, 'C-14-inorg': 5700 },
		compartments: [{ name: 'A', initial: '1' }],
	});
	const els = p.index_lists.filter((l) => l.name === 'Elements');
	close(els.length, 1, 0, 'no second element list was derived');
	assert(els[0].indices.map((i) => i.name).join(',') === 'C-org,C-inorg');
	// And being declared, it is saved.
	assert(p.toJSON().index_lists.some((l) => l.name === 'Elements'));
});

test('a per-element value is read from a per-nuclide block', () => {
	// The thing every real biosphere model does and this tool could not: a
	// sorption coefficient is a property of the element, and every isotope of
	// that element shares it.
	const model = {
		name: 'kd',
		simulation: { start_time: 0, end_time: 10, output_points: 3, spacing: 'linear' },
		nuclides: ['Cs-137', 'Cs-135', 'Sr-90'],
		half_lives: { 'Cs-135': 2.3e6 },
		parameters: [{
			name: 'Kd', index_lists: ['Elements'], value: 0,
			entries: [
				{ index: { Elements: 'Cs' }, value: 10 },
				{ index: { Elements: 'Sr' }, value: 3 },
			],
		}],
		compartments: [{ name: 'Soil', initial: '1', handle_decay: false }],
		expressions: [{ name: 'Retard', equation: '1 + Kd' }],
	};
	const r = run(model);
	const at = (nuc) => r.series(r.outputs().find(
		(o) => o.block === 'Retard' && o.index?.[0] === nuc))[0];
	close(at('Cs-137'), 11, 0, 'both caesium isotopes share the element value');
	close(at('Cs-135'), 11, 0);
	close(at('Sr-90'), 4, 0);
	// It compiles to a table lookup, not a branch.
	const b = buildSystem(new Project(model));
	assert(/P\[MAPS\[\d+\]\[n0\]\]/.test(b.source.algebraic), b.source.algebraic);
});

test('elementOf takes the symbol off every spelling the corpus uses', () => {
	const cases = [
		['Cs-137', 'Cs'], ['C-14', 'C'], ['I-129', 'I'], ['Nb-93m', 'Nb'],
		['Ag-108m', 'Ag'], ['C-14 organic', 'C'], ['C-14-inorg', 'C'],
		['H-3', 'H'], ['U', 'U'], ['se-79', 'Se'],
	];
	for (const [nuclide, symbol] of cases) {
		assert(elementOf(nuclide) === symbol, `${nuclide} -> ${elementOf(nuclide)}`);
	}
	assert(elementOf('137Cs') === null, 'a name that does not start with a symbol');
	assert(elementOf('') === null);
});

test('the derived list is offered to the editor but cannot be edited', () => {
	const p = {
		nuclides: ['Cs-137', 'Sr-90'],
		index_lists: [{
			name: 'Radionuclides', for_contaminants: true,
			indices: [{ name: 'Cs-137', enabled: true }, { name: 'Sr-90', enabled: true }],
		}],
	};
	assert(ed.indexLists(p).map((l) => l.name).join() === 'Radionuclides,Elements');
	assert(ed.isDerivedList(p, 'Elements'));
	assert(!ed.isDerivedList(p, 'Radionuclides'));
	for (const attempt of [
		() => ed.addIndex(p, 'Elements', 'Xx'),
		() => ed.removeIndex(p, 'Elements', 'Cs'),
		() => ed.setIndexEnabled(p, 'Elements', 'Cs', false),
		() => ed.renameIndexList(p, 'Elements', 'Els'),
		() => ed.deleteIndexList(p, 'Elements'),
	]) {
		let caught = null;
		try { attempt(); } catch (e) { caught = e; }
		assert(caught instanceof ed.EditError, String(caught));
		assert(/follows the nuclide list/.test(caught.message), caught.message);
	}
	// It follows the nuclides instead.
	ed.addIndex(p, 'Radionuclides', 'I-129');
	assert(ed.indexLists(p).find((l) => l.derived).indices.map((i) => i.name).join(',')
		=== 'Cs,Sr,I');
	// And nothing was written to the model itself.
	close(p.index_lists.length, 1, 0);
});

test('decay follows whichever nuclide list a compartment is indexed by', () => {
	// Real models keep two -- the catalogue and the sub-set that decays -- and
	// index compartments by either. Insisting on one made every compartment
	// indexed by the other skip decay silently, which is a wrong answer that
	// looks like a right one.
	const model = {
		name: 'both',
		simulation: {
			start_time: 0, end_time: 30, output_points: 3, spacing: 'linear',
			rtol: 1e-11, abstol: 1e-14,
		},
		half_lives: { 'Cs-137': 30.17, 'Sr-90': 28.79, 'I-129': 1.57e7 },
		index_lists: [
			{ name: 'Contaminants', indices: ['Cs-137', 'Sr-90', 'I-129'] },
			{
				name: 'Radionuclides', for_contaminants: true, sub_set_of: 'Contaminants',
				indices: ['Cs-137', 'Sr-90'],
			},
		],
		compartments: [
			{ name: 'Full', initial: '100', index_lists: ['Contaminants'] },
			{ name: 'Sub', initial: '100', index_lists: ['Radionuclides'] },
		],
	};
	const r = run(model);
	const last = r.t.length - 1;
	const at = (block, nuc) => r.series(r.outputs().find(
		(o) => o.block === block && o.index?.[0] === nuc))[last];
	const expected = (halfLife) => 100 * Math.exp((-Math.LN2 / halfLife) * 30);

	// Every cell of both blocks decays, each with its own constant.
	close(at('Full', 'Cs-137'), expected(30.17), 1e-8);
	close(at('Full', 'Sr-90'), expected(28.79), 1e-8);
	close(at('Full', 'I-129'), expected(1.57e7), 1e-8);
	close(at('Sub', 'Cs-137'), expected(30.17), 1e-8);
	close(at('Sub', 'Sr-90'), expected(28.79), 1e-8);
	// The two lists agree exactly: the same nuclide is the same nuclide.
	close(at('Full', 'Cs-137'), at('Sub', 'Cs-137'), 0);

	// The element dimension is related to the nuclides but is not one of them,
	// so nothing decays along it.
	const b = buildSystem(new Project({
		...model,
		compartments: [{ name: 'E', initial: '1', index_lists: ['Elements'] }],
	}));
	assert(!/decay and ingrowth/.test(b.source.dydt), b.source.dydt);
});

test('a second material list is not invented over one the model states', () => {
	// The `nuclides:` shorthand used to add a `Radionuclides` list beside an
	// imported model's own material list. No block was indexed by it, so it
	// looked harmless -- but it is the one decay was applied along, and every
	// imported model ran without any.
	const p = new Project({
		name: 'imported',
		nuclides: ['Cs-137'],
		index_lists: [{ name: 'Radionuclides', for_contaminants: true, indices: ['Cs-137'] }],
		compartments: [{ name: 'A', initial: '1', index_lists: ['Radionuclides'] }],
	});
	close(p.index_lists.filter((l) => l.for_contaminants).length, 1, 0,
		p.index_lists.map((l) => l.name).join(','));
	close(p.index_lists.filter((l) => l.for_nuclides).length, 1, 0, 'one nuclide list');
	// The stated list keeps the radionuclide role and gains a catalogue above
	// it; the block is still indexed by what it was indexed by, and still
	// decays. See splitMaterialRoles.
	assert(p.nuclideListName === 'Radionuclides', p.nuclideListName);
	assert(p.materialListName === 'Contaminants', p.materialListName);
	const b = buildSystem(p);
	assert(/decay and ingrowth/.test(b.source.dydt), 'the compartment decays');
});

section('two-dimensional index references');

// A matrix indexed by a copy of the nuclide list (rows) and the nuclide list
// itself (columns) -- Ecolego's own shape for an ingrowth matrix, with the `_`
// prefix that keeps the two lists' names apart.
const matrixModel = (expressions, lists = null) => ({
	name: '2d',
	simulation: { start_time: 0, end_time: 10, output_points: 3, spacing: 'linear' },
	index_lists: lists ?? [
		{ name: 'Radionuclides', for_contaminants: true, indices: ['Cs-137', 'Sr-90'] },
		{ name: 'Parent', indices: ['_Cs-137', '_Sr-90'] },
	],
	compartments: [{ name: 'A', initial: '1', handle_decay: false, per_nuclide: false }],
	parameters: [{
		name: 'M', index_lists: ['Parent', 'Radionuclides'], value: 0,
		entries: [
			{ index: { Parent: '_Cs-137', Radionuclides: 'Cs-137' }, value: 11 },
			{ index: { Parent: '_Cs-137', Radionuclides: 'Sr-90' }, value: 12 },
			{ index: { Parent: '_Sr-90', Radionuclides: 'Cs-137' }, value: 21 },
			{ index: { Parent: '_Sr-90', Radionuclides: 'Sr-90' }, value: 22 },
		],
	}],
	expressions,
});

const algValue = (model, name) => {
	const r = run(model);
	const o = r.outputs().find((x) => x.block === name);
	return r.series(o)[0];
};

test('a reference may pin one bracket per dimension', () => {
	close(algValue(matrixModel([
		{ name: 'E', equation: 'M[_Cs-137][Sr-90]', per_nuclide: false },
	]), 'E'), 12, 0);
	close(algValue(matrixModel([
		{ name: 'E', equation: 'M[_Sr-90][Cs-137]', per_nuclide: false },
	]), 'E'), 21, 0);
});

test('the brackets are read by name, not by position', () => {
	// The rule that matters. Ecolego resolves each bracket against whichever
	// of the target's index lists contains it (ParserUtil.resolveIndexNames),
	// so a real model writes them in whatever order it likes: of the 506
	// two-bracket references in the .eco files on this machine, 200 are in an
	// order a positional reading would resolve to the wrong cell -- or to no
	// cell at all.
	const lists = [
		{ name: 'Ecosystem', indices: ['Lake', 'Mire'] },
		{ name: 'Objects', indices: ['01', '02'] },
	];
	const model = {
		name: 'lo',
		simulation: { start_time: 0, end_time: 10, output_points: 3, spacing: 'linear' },
		index_lists: lists,
		compartments: [{ name: 'A', initial: '1', handle_decay: false }],
		parameters: [{
			name: 'Area', index_lists: ['Ecosystem', 'Objects'], value: 0,
			entries: [
				{ index: { Ecosystem: 'Lake', Objects: '01' }, value: 1 },
				{ index: { Ecosystem: 'Lake', Objects: '02' }, value: 2 },
				{ index: { Ecosystem: 'Mire', Objects: '01' }, value: 3 },
				{ index: { Ecosystem: 'Mire', Objects: '02' }, value: 4 },
			],
		}],
		// Declared Ecosystem x Objects, written [object][ecosystem] -- exactly
		// `Ecosystem_area_objects[11][Lake]` from a real model.
		expressions: [{ name: 'E', equation: 'Area[02][Mire]' }],
	};
	close(algValue(model, 'E'), 4, 0);
});

test('a bracket may be left empty, and the dimension comes from the caller', () => {
	// `M[][Cs-137]` inside a Parent-indexed expression: the column is pinned,
	// the row follows the expression's own position, which is how the format
	// writes a dimension it does not pin.
	const r = run(matrixModel([
		{ name: 'E', equation: 'M[][Cs-137]', index_lists: ['Parent'] },
	]));
	const at = (idx) => r.series(r.outputs().find(
		(o) => o.block === 'E' && o.index?.[0] === idx))[0];
	close(at('_Cs-137'), 11, 0);
	close(at('_Sr-90'), 21, 0);
});

test('fewer brackets than dimensions: the rest follow the caller', () => {
	const r = run(matrixModel([
		{ name: 'E', equation: 'M[_Sr-90]', index_lists: ['Radionuclides'] },
	]));
	const at = (idx) => r.series(r.outputs().find(
		(o) => o.block === 'E' && o.index?.[0] === idx))[0];
	close(at('Cs-137'), 21, 0);
	close(at('Sr-90'), 22, 0);
});

test('one index pinning two dimensions is the diagonal', () => {
	// Both lists contain the same names, so `M[b]` pins both -- which is what
	// the desktop tool does, and the only sensible reading of a matrix indexed twice
	// over the same set.
	const sym = [{ name: 'L1', indices: ['a', 'b'] }, { name: 'L2', indices: ['a', 'b'] }];
	const model = {
		name: 'diag',
		simulation: { start_time: 0, end_time: 10, output_points: 3, spacing: 'linear' },
		index_lists: sym,
		compartments: [{ name: 'A', initial: '1', handle_decay: false, per_nuclide: false }],
		parameters: [{
			name: 'M', index_lists: ['L1', 'L2'], value: 0,
			entries: [
				{ index: { L1: 'a', L2: 'a' }, value: 11 },
				{ index: { L1: 'a', L2: 'b' }, value: 12 },
				{ index: { L1: 'b', L2: 'a' }, value: 21 },
				{ index: { L1: 'b', L2: 'b' }, value: 22 },
			],
		}],
		expressions: [
			{ name: 'D', equation: 'M[b]', per_nuclide: false },
			// With two brackets each takes a dimension of its own, in the
			// order written.
			{ name: 'P', equation: 'M[a][b]', per_nuclide: false },
		],
	};
	close(algValue(model, 'D'), 22, 0);
	close(algValue(model, 'P'), 12, 0);
});

test('an index name is raw text, not something to tokenize', () => {
	// ValueIterator.parseIndex reads to the closing bracket and no further.
	// Real index names are not identifiers.
	const names = [
		'Cs-137', '_Ra-226', '01', 'F.18:00_51_FORSMARK', 'B.04:00_205_BARSEBÄCK',
		'S2_outer', 'Geosphere.Sink',
	];
	for (const n of names) {
		const ast = parse(`A[${n}]`);
		assert(ast.indices.length === 1 && ast.indices[0] === n, `${n} -> ${JSON.stringify(ast)}`);
	}
	// Two brackets, and an empty one.
	close(parse('M[a][b]').indices.length, 2, 0);
	assert(parse('M[][b]').indices[0] === null);
	assert(parse('M').indices.length === 0);
	// A missing bracket is still an error, with a position.
	let caught = null;
	try { parse('A[Cs'); } catch (e) { caught = e; }
	assert(caught instanceof ParseError, String(caught));
});

test('renaming a block does not touch an index that shares its name', () => {
	// `Cs` inside `A[Cs-137]` used to tokenize as an identifier, so renaming a
	// block called `Cs` rewrote part of a nuclide name.
	assert(ed.renameInEquation('A[Cs-137] + Cs', 'Cs', 'X') === 'A[Cs-137] + X',
		ed.renameInEquation('A[Cs-137] + Cs', 'Cs', 'X'));
	assert(ed.renameInEquation('M[_Ra-226][Pb-210] * M', 'M', 'Q')
		=== 'Q[_Ra-226][Pb-210] * Q');
});

test('a two-dimensional reference is differentiated like any other', () => {
	// The Jacobian reads the same offsets the derivative does, so a pinned
	// cell must reach the same slot in both.
	const model = {
		name: 'jac2d',
		simulation: { start_time: 0, end_time: 10, output_points: 3, spacing: 'linear' },
		index_lists: [
			{ name: 'Radionuclides', for_contaminants: true, indices: ['Cs-137', 'Sr-90'] },
			{ name: 'Parent', indices: ['_Cs-137', '_Sr-90'] },
		],
		compartments: [
			{ name: 'A', initial: '1', handle_decay: false, per_nuclide: false },
			{ name: 'B', initial: '0', handle_decay: false, per_nuclide: false },
		],
		parameters: [{
			name: 'M', index_lists: ['Parent', 'Radionuclides'], value: 0,
			entries: [{ index: { Parent: '_Sr-90', Radionuclides: 'Cs-137' }, value: 0.25 }],
		}],
		transfers: [{
			name: 'T', from: 'A', to: 'B', rate: 'M[_Sr-90][Cs-137]',
			multiply_by_donor: true, per_nuclide: false,
		}],
	};
	const b = buildSystem(new Project(model));
	assert(b.jacobian.available, b.jacobian.reason);
	const J = [new Float64Array(2), new Float64Array(2)];
	b.jacobian.evaluateDense(0, Float64Array.from([1, 0]), J);
	close(J[0][0], -0.25, 1e-12);
	close(J[1][0], 0.25, 1e-12);
});

test('what the brackets cannot mean is reported precisely', () => {
	const build = (equation, lists) => () => buildSystem(new Project(matrixModel(
		[{ name: 'E', equation, per_nuclide: false }], lists,
	)));
	expectError(build('M[_Cs-137][Sr-90][Cs-137]'),
		/pins 3 indices, but 'M' is indexed by only 2 lists/, 'too many brackets');
	expectError(build('A[Cs-137]'),
		/'A' is indexed by nothing, so it holds a single value/, 'a scalar target');
	expectError(build('M[_Cs-137][Pu-239]'),
		/'Pu-239' is not an index of any list/, 'an unknown index');
	expectError(build('M[_Cs-137][_Sr-90]'),
		/pins 'Parent' twice/, 'both brackets on one dimension');
	// A disabled index is a different mistake, and says so.
	expectError(build('M[_Cs-137][Sr-90]', [
		{ name: 'Radionuclides', for_contaminants: true, indices: ['Cs-137', { name: 'Sr-90', enabled: false }] },
		{ name: 'Parent', indices: ['_Cs-137', '_Sr-90'] },
	]), /'Sr-90' is disabled in 'Radionuclides'/, 'a disabled index');
});

test('initial conditions take two-dimensional references too', () => {
	const model = matrixModel([]);
	model.compartments = [{
		name: 'A', initial: 'M[_Sr-90][Cs-137]', handle_decay: false, per_nuclide: false,
	}];
	const b = buildSystem(new Project(model));
	close(b.initialState()[0], 21, 0);
});

section('index operations and aggregates');

// One compartment over two dimensions, with a known value in every cell, so
// each reduction has an arithmetic answer rather than a plausible one.
const reduceModel = (extra = {}) => ({
	name: 'reduce',
	simulation: { start_time: 0, end_time: 10, output_points: 3, spacing: 'linear' },
	half_lives: { N1: 'stable', N2: 'stable' },
	index_lists: [
		{ name: 'Radionuclides', for_contaminants: true, indices: ['N1', 'N2'] },
		{ name: 'Object', indices: ['Lake', 'Mire', 'Forest'] },
	],
	compartments: [{
		name: 'Soil', initial: '0', handle_decay: false, index_lists: ['Radionuclides', 'Object'],
		entries: [
			{ index: { Radionuclides: 'N1', Object: 'Lake' }, initial: '1' },
			{ index: { Radionuclides: 'N1', Object: 'Mire' }, initial: '2' },
			{ index: { Radionuclides: 'N1', Object: 'Forest' }, initial: '3' },
			{ index: { Radionuclides: 'N2', Object: 'Lake' }, initial: '10' },
			{ index: { Radionuclides: 'N2', Object: 'Mire' }, initial: '20' },
			{ index: { Radionuclides: 'N2', Object: 'Forest' }, initial: '30' },
		],
	}],
	...extra,
});

const reduced = (ops, name, index = null) => {
	const r = run(reduceModel(ops));
	const o = r.outputs().find(
		(x) => x.block === name && (index == null || x.index?.[0] === index));
	assert(o, `no output for ${name}${index ? `[${index}]` : ''}`);
	return r.series(o)[0];
};

test('an index operation reduces its target along the list it does not share', () => {
	// Indexed by Radionuclides, so it reduces over Object: 1+2+3 and 10+20+30.
	const ops = {
		index_reductions: [
			{ name: 'ByNuclide', target: 'Soil', operation: 'sum', index_lists: ['Radionuclides'] },
			{ name: 'ByObject', target: 'Soil', operation: 'sum', index_lists: ['Object'] },
		],
	};
	close(reduced(ops, 'ByNuclide', 'N1'), 6, 0);
	close(reduced(ops, 'ByNuclide', 'N2'), 60, 0);
	// The other way round: over the nuclides, 1+10, 2+20, 3+30.
	close(reduced(ops, 'ByObject', 'Lake'), 11, 0);
	close(reduced(ops, 'ByObject', 'Mire'), 22, 0);
	close(reduced(ops, 'ByObject', 'Forest'), 33, 0);
});

test('every reduction an index operation offers', () => {
	const each = (operation, extra = {}) => reduced({
		index_reductions: [{
			name: 'R', target: 'Soil', operation, index_lists: ['Radionuclides'], ...extra,
		}],
	}, 'R', 'N1');
	close(each('sum'), 6, 0);
	close(each('product'), 6, 0, '1*2*3');
	close(each('min'), 1, 0);
	close(each('max'), 3, 0);
	close(each('mean'), 2, 0);
	close(each('percentile', { percentile: 50 }), 2, 0, 'the median of 1, 2, 3');
	close(each('percentile', { percentile: 0 }), 1, 0);
	close(each('percentile', { percentile: 100 }), 3, 0);
});

test('an index operation with no dimension reduces the target’s first list', () => {
	// IndexOperation.getOperationTargetIndexList: with no list of its own it
	// takes the target's first, leaving a block that is still indexed by the
	// rest -- so this one is per-object, over the nuclides.
	const ops = {
		index_reductions: [
			{ name: 'Flat', target: 'Soil', operation: 'sum', per_nuclide: false, index_lists: [] },
		],
	};
	let caught = null;
	try { reduced(ops, 'Flat'); } catch (e) { caught = e; }
	// Soil is [Radionuclides, Object]; reducing only the nuclides leaves an Object
	// dimension the block does not have, which cannot be resolved.
	assert(caught instanceof BuildError, String(caught));

	// With a one-dimensional target it is the whole reduction.
	const ops2 = {
		index_reductions: [
			{ name: 'ByObject', target: 'Soil', operation: 'sum', index_lists: ['Object'] },
			{ name: 'Everything', target: 'ByObject', operation: 'sum', per_nuclide: false, index_lists: [] },
		],
	};
	close(reduced(ops2, 'Everything'), 66, 0, '11 + 22 + 33');
});

test('a reduction pins the list, not the index name', () => {
	// A target indexed by a list and a copy of it carries the same index names
	// twice. Pinning by name would give the diagonal; pinning the list gives
	// the row.
	const model = {
		name: 'copy',
		simulation: { start_time: 0, end_time: 10, output_points: 3, spacing: 'linear' },
		index_lists: [
			{ name: 'L1', indices: ['a', 'b'] },
			{ name: 'L2', indices: ['a', 'b'] },
		],
		compartments: [{ name: 'A', initial: '1', handle_decay: false, per_nuclide: false }],
		parameters: [{
			name: 'M', index_lists: ['L1', 'L2'], value: 0,
			entries: [
				{ index: { L1: 'a', L2: 'a' }, value: 1 },
				{ index: { L1: 'a', L2: 'b' }, value: 2 },
				{ index: { L1: 'b', L2: 'a' }, value: 4 },
				{ index: { L1: 'b', L2: 'b' }, value: 8 },
			],
		}],
		index_reductions: [
			{ name: 'RowSum', target: 'M', operation: 'sum', index_lists: ['L1'] },
		],
	};
	const r = run(model);
	const at = (i) => r.series(r.outputs().find(
		(o) => o.block === 'RowSum' && o.index?.[0] === i))[0];
	close(at('a'), 3, 0, 'M[a][a] + M[a][b]');
	close(at('b'), 12, 0, 'M[b][a] + M[b][b]');
});

test('an aggregate reduces several blocks, index by index', () => {
	const ops = {
		index_reductions: [
			{ name: 'ByNuclide', target: 'Soil', operation: 'sum', index_lists: ['Radionuclides'] },
			{ name: 'MaxObj', target: 'Soil', operation: 'max', index_lists: ['Radionuclides'] },
		],
		block_reductions: [
			{ name: 'Both', targets: ['ByNuclide', 'MaxObj'], operation: 'sum', index_lists: ['Radionuclides'] },
			{ name: 'MeanBoth', targets: 'ByNuclide+MaxObj', operation: 'mean', index_lists: ['Radionuclides'] },
			// A single target is that block.
			{ name: 'Just', targets: ['ByNuclide'], index_lists: ['Radionuclides'] },
		],
	};
	close(reduced(ops, 'Both', 'N1'), 9, 0, '6 + 3');
	close(reduced(ops, 'Both', 'N2'), 90, 0, '60 + 30');
	close(reduced(ops, 'MeanBoth', 'N1'), 4.5, 0);
	close(reduced(ops, 'Just', 'N1'), 6, 0);
});

test('an aggregate may reduce blocks of lower dimension than itself', () => {
	// A block indexed by fewer lists is read at every combination of the rest,
	// which is what makes an aggregate over a mixed set mean anything.
	const ops = {
		parameters: [
			{ name: 'PerNuclide', index_lists: ['Radionuclides'], value: 0,
				entries: [{ index: { Radionuclides: 'N1' }, value: 100 }, { index: { Radionuclides: 'N2' }, value: 200 }] },
			{ name: 'Scalar', per_nuclide: false, index_lists: [], value: 5 },
		],
		block_reductions: [{
			name: 'Mixed', targets: ['Soil', 'PerNuclide', 'Scalar'], operation: 'sum',
			index_lists: ['Radionuclides', 'Object'],
		}],
	};
	const r = run(reduceModel(ops));
	const at = (n, o) => r.series(r.outputs().find(
		(x) => x.block === 'Mixed' && x.index?.[0] === n && x.index?.[1] === o))[0];
	close(at('N1', 'Lake'), 106, 0, '1 + 100 + 5');
	close(at('N2', 'Forest'), 235, 0, '30 + 200 + 5');
});

test('a reduction is differentiated analytically', () => {
	// A rate that reads a sum over the objects couples every object to every
	// other, and the analytic Jacobian has to say so.
	const model = {
		name: 'jac',
		simulation: { start_time: 0, end_time: 10, output_points: 3, spacing: 'linear' },
		index_lists: [{ name: 'Object', indices: ['Lake', 'Mire', 'Forest'] }],
		compartments: [{
			name: 'C', initial: '1', handle_decay: false, index_lists: ['Object'],
			entries: [
				{ index: { Object: 'Lake' }, initial: '1' },
				{ index: { Object: 'Mire' }, initial: '2' },
				{ index: { Object: 'Forest' }, initial: '4' },
			],
		}],
		index_reductions: [{ name: 'Total', target: 'C', operation: 'sum', index_lists: [] }],
		transfers: [{
			name: 'T', from: 'C', to: null, rate: 'Total * 0.5',
			multiply_by_donor: false, index_lists: ['Object'],
		}],
	};
	const b = buildSystem(new Project(model));
	assert(b.jacobian.available, b.jacobian.reason);
	assert(b.jacobian.constant === false, 'the rate moves with the state');
	close(b.jacobian.nnz, 9, 0, 'the sum couples every object to every other');

	const n = 3;
	const y = Float64Array.from([1, 2, 4]);
	const J = Array.from({ length: n }, () => new Float64Array(n));
	b.jacobian.evaluateDense(0, y, J);
	for (let i = 0; i < n; i++) {
		for (let j = 0; j < n; j++) close(J[i][j], -0.5, 1e-12, `J[${i}][${j}]`);
	}

	// max picks one term, so only the largest object contributes.
	const m2 = structuredClone(model);
	m2.index_reductions[0].operation = 'max';
	const b2 = buildSystem(new Project(m2));
	const J2 = Array.from({ length: n }, () => new Float64Array(n));
	b2.jacobian.evaluateDense(0, y, J2);
	const colSum = (j) => J2.reduce((s, r) => s + r[j], 0);
	close(colSum(0), 0, 1e-12, 'Lake is not the largest');
	close(colSum(1), 0, 1e-12, 'nor is Mire');
	close(colSum(2), -1.5, 1e-12, 'Forest is');
});

test('the generated code is the loop written out, not an interpreter', () => {
	const b = buildSystem(new Project(reduceModel({
		index_reductions: [
			{ name: 'ByNuclide', target: 'Soil', operation: 'max', index_lists: ['Radionuclides'] },
		],
	})));
	assert(/Math\.max\(y\[[^)]*\], y\[[^)]*\], y\[[^)]*\]\)/.test(b.source.algebraic),
		b.source.algebraic);
});

test('a reduction takes part in the dependency order', () => {
	// An expression that reads a reduction of another expression has to be
	// evaluated after both, whatever order the file lists them in.
	const b = buildSystem(new Project(reduceModel({
		expressions: [
			{ name: 'Dose', equation: 'Total * 2', per_nuclide: false, index_lists: [] },
			{ name: 'Scaled', equation: 'Soil * 10', index_lists: ['Radionuclides', 'Object'] },
		],
		index_reductions: [
			{ name: 'Total', target: 'PerNuclide', operation: 'sum', per_nuclide: false, index_lists: [] },
			{ name: 'PerNuclide', target: 'Scaled', operation: 'sum', index_lists: ['Radionuclides'] },
		],
	})));
	const order = b.layout.algebraic.map((a) => a.name);
	assert(order.indexOf('Scaled') < order.indexOf('PerNuclide'), order.join(' -> '));
	assert(order.indexOf('PerNuclide') < order.indexOf('Total'), order.join(' -> '));
	assert(order.indexOf('Total') < order.indexOf('Dose'), order.join(' -> '));
	// 10 * (1+2+3+10+20+30) * 2
	close(b.evaluateAlgebraic(0, b.initialState())[
		b.layout.algebraic.find((a) => a.name === 'Dose').base], 1320, 1e-9);
});

test('what a reduction cannot mean is reported', () => {
	const build = (extra) => () => buildSystem(new Project(reduceModel(extra)));
	expectError(build({
		index_reductions: [{ name: 'R', target: 'Nope', index_lists: ['Radionuclides'] }],
	}), /'Nope' is not a block in this model/, 'an unknown target');
	expectError(build({
		parameters: [{ name: 'k', value: 1, per_nuclide: false, index_lists: [] }],
		index_reductions: [{ name: 'R', target: 'k', per_nuclide: false, index_lists: [] }],
	}), /holds a single value, so there is no index to reduce/, 'a scalar target');
	expectError(build({
		index_reductions: [{ name: 'R', target: 'Soil', index_lists: ['Radionuclides', 'Object'] }],
	}), /nothing left to reduce over/, 'the same dimensions as its target');
	expectError(build({
		block_reductions: [{ name: 'A', targets: ['Nope'], index_lists: ['Radionuclides'] }],
	}), /'Nope' is not a block in this model/, 'an unknown aggregate target');
});

test('a reduction is validated when the file loads', () => {
	expectError(() => new Project(reduceModel({
		index_reductions: [{ name: 'R', target: 'Soil', operation: 'sideways' }],
	})), /'sideways' is not a reduction/, 'an unknown operation');
	expectError(() => new Project(reduceModel({
		block_reductions: [{ name: 'A', targets: ['Soil'], operation: 'percentile' }],
	})), /not a reduction an aggregate can do/, 'percentile is index-operation only');
	expectError(() => new Project(reduceModel({
		index_reductions: [{ name: 'R', target: 'Soil', operation: 'percentile', percentile: 140 }],
	})), /between 0 and 100/, 'a percentile out of range');
	expectError(() => new Project(reduceModel({
		index_reductions: [{ name: 'R', operation: 'sum' }],
	})), /needs a block to reduce/, 'no target');
	expectError(() => new Project(reduceModel({
		block_reductions: [{ name: 'A', operation: 'sum' }],
	})), /needs at least one block to reduce/, 'no targets');
});

// --- scenarios ---------------------------------------------------------------

test('the scenario dimension is found through a sub-set and through a mapping', () => {
	const space = new IndexSpace([
		{ name: 'Climate', for_scenarios: true, indices: ['Present', 'Warm', 'Dry'] },
		// A sub-set: two of the three, by name.
		{ name: 'Extremes', sub_set_of: 'Climate', indices: ['Warm', 'Dry'] },
		// A mapping: several scenarios share one coarse class.
		{
			name: 'Wetness',
			mapping: {
				to: 'Climate',
				pairs: [
					{ from: 'Wet', to: 'Warm' },
					{ from: 'Dry', to: 'Dry' },
					{ from: 'Wet', to: 'Present' },
				],
			},
			indices: ['Wet', 'Dry'],
		},
		{ name: 'Object', indices: ['Lake', 'Mire'] },
	]);

	assert(space.scenarioRoot === 'Climate', space.scenarioRoot);
	assert(space.scenarios().join() === 'Present,Warm,Dry');
	// However a list reaches the scenario root, it is the scenario dimension.
	for (const n of ['Climate', 'Extremes', 'Wetness']) {
		assert(space.isScenarioDim(n), `${n} is not seen as a scenario`);
	}
	assert(!space.isScenarioDim('Object'));

	// Opening a model selects the first, as Ecolego does.
	assert(space.scenario === 'Present');
	assert(space.withoutScenarios(['Climate', 'Object', 'Extremes']).join() === 'Object');

	// `Present` is not one of the extremes, so a block indexed by that list
	// has no index for it -- which is a fact worth reporting rather than
	// guessing at.
	assert(space.scenarioIndexIn('Climate') === 'Present');
	assert(space.scenarioIndexIn('Extremes') === null);
	assert(space.scenarioIndexIn('Wetness') === 'Wet', space.scenarioIndexIn('Wetness'));

	space.setScenario('Dry');
	assert(space.scenarioIndexIn('Climate') === 'Dry');
	assert(space.scenarioIndexIn('Extremes') === 'Dry');
	assert(space.scenarioIndexIn('Wetness') === 'Dry');

	// The tuple a stored value is read at -- ScenarioIndexWrapper.wrap.
	const pinned = space.pinScenario(['Climate', 'Object'], { Object: 'Lake' });
	assert(pinned.Climate === 'Dry' && pinned.Object === 'Lake', JSON.stringify(pinned));
	// A block with no scenario dimension is left exactly as it was.
	const plain = { Object: 'Lake' };
	assert(space.pinScenario(['Object'], plain) === plain);

	// Anything that is not a scenario leaves none selected.
	assert(space.setScenario('Sideways') === null);
	assert(space.pinScenario(['Climate'], {}).Climate === undefined);
});

/** Two scenarios changing a rate and a volume, with one dose out the far end. */
function scenarioModel(scenario) {
	return {
		simulation: {
			start_time: 0, end_time: 50, output_points: 51, spacing: 'linear',
			solver: 'dp45', rtol: 1e-10, abstol: 1e-12, time_unit: 'year',
		},
		...(scenario ? { scenario } : {}),
		index_lists: [
			{ name: 'Climate', for_scenarios: true, indices: ['Wet', 'Dry'] },
			{ name: 'Object', indices: ['Lake', 'Mire'] },
		],
		parameters: [
			{
				name: 'Runoff', index_lists: ['Climate'], value: 0,
				entries: [
					{ index: { Climate: 'Wet' }, value: 0.1 },
					{ index: { Climate: 'Dry' }, value: 0.01 },
				],
			},
			{
				name: 'Area', index_lists: ['Climate', 'Object'], value: 0,
				entries: [
					{ index: { Climate: 'Wet', Object: 'Lake' }, value: 3 },
					{ index: { Climate: 'Wet', Object: 'Mire' }, value: 5 },
					{ index: { Climate: 'Dry', Object: 'Lake' }, value: 30 },
					{ index: { Climate: 'Dry', Object: 'Mire' }, value: 50 },
				],
			},
		],
		compartments: [{ name: 'Soil', initial: '100', handle_decay: false }],
		transfers: [{ name: 'Drain', from: 'Soil', to: null, rate: 'Runoff' }],
		// Not indexed by the scenarios, and reads a block that is: exactly the
		// reference that used to have nowhere to go.
		expressions: [
			{ name: 'Rate', equation: 'Runoff' },
			{ name: 'Total_area', index_lists: ['Object'], equation: 'Area' },
		],
	};
}

test('one scenario is live, and every block indexed by it is read at that one', () => {
	const wet = run(new Project(scenarioModel('Wet')));
	const dry = run(new Project(scenarioModel('Dry')));

	const at = (r, label) => r.series(r.outputs().find((o) => o.label === label))[0];
	close(at(wet, 'Rate'), 0.1, 0);
	close(at(dry, 'Rate'), 0.01, 0);

	// Soil drains at the scenario's rate.
	const last = (r) => r.series(r.outputs().find((o) => o.label === 'Soil'))[r.t.length - 1];
	close(last(wet), 100 * Math.exp(-0.1 * 50), 1e-6);
	close(last(dry), 100 * Math.exp(-0.01 * 50), 1e-6);

	// A two-dimensional block keeps the dimension that is a real axis and
	// loses the one that is not.
	close(at(wet, 'Total_area [Lake]'), 3, 0);
	close(at(wet, 'Total_area [Mire]'), 5, 0);
	close(at(dry, 'Total_area [Lake]'), 30, 0);
	close(at(dry, 'Total_area [Mire]'), 50, 0);

	// And nothing anywhere carries the scenario: the model was run once.
	for (const o of wet.outputs()) {
		assert(!(o.dims ?? []).includes('Climate'), `${o.label} still has the scenario`);
	}
});

test('a scenario-only block is a single value, and the state vector never sees one', () => {
	const m = scenarioModel('Dry');
	const sys = buildSystem(new Project(m));

	const runoff = sys.layout.parameters.find((p) => p.name === 'Runoff');
	assert(runoff.width === 1, `${runoff.width} slots for a scenario-only parameter`);
	assert(runoff.dims.length === 0, runoff.dims.join());

	const area = sys.layout.parameters.find((p) => p.name === 'Area');
	assert(area.dims.join() === 'Object', area.dims.join());
	assert(area.width === 2, `${area.width} slots`);

	// The value in the slot is the one for the live scenario.
	close(sys.parameterValues[runoff.base], 0.01, 0);

	// Opening the same model with no choice saved runs the first scenario.
	const first = new Project(scenarioModel(null));
	assert(first.scenario === 'Wet', first.scenario);
	// And a choice that no longer names a scenario falls back rather than
	// leaving the model with none.
	const stale = new Project(scenarioModel('Ice age'));
	assert(stale.scenario === 'Wet', stale.scenario);
});

test('choosing a scenario is an edit like any other', () => {
	const m = scenarioModel(null);
	assert(ed.scenarioNames(m).join() === 'Wet,Dry');
	assert(ed.scenarioList(m).name === 'Climate');
	assert(ed.activeScenario(m) === 'Wet', 'the first until one is chosen');

	ed.setScenario(m, 'Dry');
	assert(m.scenario === 'Dry');
	assert(ed.activeScenario(m) === 'Dry');

	let refused = null;
	try { ed.setScenario(m, 'Ice age'); } catch (e) { refused = e.message; }
	assert(refused && /not a scenario/.test(refused), String(refused));
	assert(m.scenario === 'Dry', 'and the model was left alone');

	ed.setScenario(m, null);
	assert(m.scenario === undefined, 'clearing it leaves nothing behind');

	// A model with no scenario list has nothing to choose.
	assert(ed.scenarioNames({}).length === 0);
	assert(ed.activeScenario({}) === null);

	// The dimension is still a dimension for editing: a value can be set per
	// scenario even though only one of them runs.
	const runoff = m.parameters.find((p) => p.name === 'Runoff');
	assert(ed.effectiveDims(m, runoff).join() === 'Climate', 'the editor still sees it');
	assert(ed.combinationCount(m, ['Climate']) === 2);
});

test('the bundled scenario example answers differently under each one', async () => {
	const { readFileSync } = await import('node:fs');
	const raw = JSON.parse(
		readFileSync(new URL('../examples/scenarios.json', import.meta.url), 'utf8'),
	);
	const names = ed.scenarioNames(raw);
	assert(names.length === 3, names.join());

	const peak = (scenario) => {
		const r = run(new Project({ ...raw, scenario }));
		const out = r.outputs().find((o) => o.label === 'Peak_dose');
		assert(out, 'no Peak_dose');
		return r.series(out)[r.t.length - 1];
	};
	const values = names.map(peak);
	for (const v of values) assert(v > 0 && Number.isFinite(v), String(v));
	assert(new Set(values).size === 3, `three scenarios gave ${new Set(values).size} answers`);
	// Wetter washes more through, so the dose is higher; drier, lower.
	assert(values[1] > values[0] && values[0] > values[2], values.join(' '));
});

test('a scenario dimension is left out of the reduction’s count', () => {
	// Ecolego counts a block's dimensions with getDimensionForScenario, which
	// leaves the scenario list out -- so a block indexed by [Scenarios, A, B]
	// reduced to [A] is reduced over B, not over the scenarios. Eight blocks
	// in the .eco files here are shaped exactly that way.
	const scen = (d) => d === 'Scenarios';
	assert(operatedList(['A'], ['Scenarios', 'A', 'B'], scen) === 'B',
		operatedList(['A'], ['Scenarios', 'A', 'B'], scen));
	// Without the marker it would take the scenarios, which is the bug.
	assert(operatedList(['A'], ['Scenarios', 'A', 'B']) === 'Scenarios');
	assert(operatedList([], ['Scenarios', 'A'], scen) === 'A', 'and never as the first');

	const model = {
		name: 'sc',
		simulation: { start_time: 0, end_time: 10, output_points: 3, spacing: 'linear' },
		index_lists: [
			{ name: 'Scenarios', for_scenarios: true, indices: ['Base', 'Alt'] },
			{ name: 'Object', indices: ['Lake', 'Mire'] },
		],
		compartments: [{ name: 'A', initial: '1', handle_decay: false, per_nuclide: false }],
		parameters: [{
			name: 'V', index_lists: ['Scenarios', 'Object'], value: 0,
			entries: [
				{ index: { Scenarios: 'Base', Object: 'Lake' }, value: 1 },
				{ index: { Scenarios: 'Base', Object: 'Mire' }, value: 2 },
				{ index: { Scenarios: 'Alt', Object: 'Lake' }, value: 10 },
				{ index: { Scenarios: 'Alt', Object: 'Mire' }, value: 20 },
			],
		}],
		// Indexed by the scenarios and nothing else, so what is left to reduce
		// over is the objects.
		index_reductions: [{ name: 'PerScenario', target: 'V', index_lists: ['Scenarios'] }],
	};

	// One scenario is live at a time, so the block holds one value -- the sum
	// over the objects at whichever scenario is selected.
	const total = (project) => {
		const r = run(project);
		const out = r.outputs().filter((o) => o.block === 'PerScenario');
		assert(out.length === 1, `${out.length} series for a scenario-indexed block`);
		return r.series(out[0])[0];
	};
	close(total(new Project(model)), 3, 0, '1 + 2 at the first scenario');
	close(total(new Project({ ...model, scenario: 'Alt' })), 30, 0, '10 + 20 at Alt');

	// The flag and the choice both survive a round trip, or the next load
	// reduces the wrong list, or runs the wrong scenario.
	const chosen = new Project({ ...model, scenario: 'Alt' });
	const back = new Project(JSON.parse(JSON.stringify(chosen.toJSON())));
	assert(back.index_lists[0].for_scenarios === true);
	assert(back.scenario === 'Alt', back.scenario);
});

test('percentile matches the standard definition', () => {
	// Sorted values at the midpoints (i - 0.5) / n,
	// with the extremes pinned to 0 and 100 and straight lines between.
	close(percentileOf(50, [1, 2, 3]), 2, 0);
	close(percentileOf(50, [1, 2, 3, 4]), 2.5, 0, 'even samples average the middle two');
	close(percentileOf(0, [1, 2, 3, 4]), 1, 0);
	close(percentileOf(100, [1, 2, 3, 4]), 4, 0);
	close(percentileOf(25, [1, 2, 3, 4]), 1.5, 0);
	close(percentileOf(75, [1, 2, 3, 4]), 3.5, 0);
	close(percentileOf(50, [7]), 7, 0, 'one value is every percentile of itself');
	assert(Number.isNaN(percentileOf(50, [])), 'an empty sample has no percentile');
	assert(Number.isNaN(percentileOf(101, [1, 2])), 'and 101 is not a percentage');
	// Unsorted input, and duplicates.
	close(percentileOf(50, [3, 1, 2]), 2, 0);
	close(percentileOf(50, [5, 5, 5]), 5, 0);
	// Through the equation language, which is how a block reaches it.
	close(evalExpr('percentile(50, 1, 2, 3, 4)'), 2.5, 0);
});

test('a reduction survives a round trip through the project file', () => {
	const p = new Project(reduceModel({
		index_reductions: [{
			name: 'R', target: 'Soil', operation: 'percentile', percentile: 90,
			index_lists: ['Radionuclides'], unit: 'Bq',
		}],
		block_reductions: [{ name: 'A', targets: ['Soil', 'R'], operation: 'max', index_lists: ['Radionuclides'] }],
	}));
	const back = new Project(JSON.parse(JSON.stringify(p.toJSON())));
	assert(back.index_reductions[0].operation === 'percentile');
	close(back.index_reductions[0].percentile, 90, 0);
	assert(back.index_reductions[0].target === 'Soil');
	assert(back.index_reductions[0].unit === 'Bq');
	assert(back.block_reductions[0].operation === 'max');
	close(back.block_reductions[0].targets.length, 2, 0);
});

test('reductions are blocks the editor can add, rename and delete', () => {
	const p = {
		name: 'ed',
		index_lists: [
			{ name: 'N', for_contaminants: true, indices: ['a'] },
			{ name: 'O', indices: ['x', 'y'] },
		],
		compartments: [{ name: 'Soil', index_lists: ['N', 'O'] }],
	};
	const io = ed.addIndexOperation(p, { name: 'Total', target: 'Soil' });
	// One dimension fewer than its target, which is what makes it a reduction.
	close(io.index_lists.length, 1, 0);
	assert(io.index_lists[0] === 'O', io.index_lists.join(','));

	const agg = ed.addAggregate(p, { name: 'Both', targets: ['Soil', 'Total'] });
	// Wide enough to reach every target.
	close(agg.index_lists.length, 2, 0);

	ed.renameBlock(p, 'Total', 'Sum_all');
	assert(p.block_reductions[0].targets.includes('Sum_all'), JSON.stringify(p.block_reductions[0].targets));
	assert(p.index_reductions[0].name === 'Sum_all');

	ed.renameBlock(p, 'Soil', 'Ground');
	assert(p.index_reductions[0].target === 'Ground', p.index_reductions[0].target);

	// Deleting a block a reduction reduces is refused, like any other
	// reference -- otherwise the model quietly stops building.
	let caught = null;
	try { ed.deleteBlock(p, 'Ground'); } catch (e) { caught = e; }
	assert(caught instanceof ed.EditError, String(caught));
	assert(/Sum_all/.test(caught.message), caught.message);

	p.block_reductions[0].targets = ['Ground'];
	const removed = ed.deleteBlock(p, 'Sum_all');
	assert(removed.includes('Sum_all'), removed.join(','));
	close(p.index_reductions.length, 0, 0);
});

section('error reporting');

function expectError(fn, pattern, what) {
	let caught = null;
	try { fn(); } catch (e) { caught = e; }
	assert(caught, `${what}: expected an error`);
	assert(pattern.test(caught.message), `${what}: got "${caught.message}"`);
}

test('circular expression references are rejected', () => {
	expectError(
		() => buildSystem(new Project({
			compartments: [{ name: 'A', initial: '0' }],
			expressions: [
				{ name: 'E1', equation: 'E2 + 1' },
				{ name: 'E2', equation: 'E1 + 1' },
			],
		})),
		/Circular reference/, 'cycle',
	);
});

test('unknown names are rejected with a helpful message', () => {
	expectError(
		() => buildSystem(new Project({
			compartments: [{ name: 'A', initial: '0' }],
			expressions: [{ name: 'E', equation: 'nosuchthing * 2' }],
		})),
		/Unknown name 'nosuchthing'/, 'unknown ref',
	);
});

test('a transfer to a missing compartment is rejected', () => {
	expectError(
		() => new Project({
			compartments: [{ name: 'A', initial: '0' }],
			transfers: [{ name: 'T', from: 'A', to: 'Nope', rate: '1' }],
		}),
		/Unknown target compartment 'Nope'/, 'bad target',
	);
});

test('duplicate block names are rejected', () => {
	expectError(
		() => new Project({
			compartments: [{ name: 'A', initial: '0' }],
			parameters: [{ name: 'A', value: 1 }],
		}),
		/Duplicate block name/, 'duplicate',
	);
});

test('a nuclide with no half-life is rejected', () => {
	expectError(
		() => new Project({
			nuclides: ['Bogusium-1'],
			compartments: [{ name: 'A', initial: '0' }],
		}),
		/No half-life/, 'unknown nuclide',
	);
});

test('a model with no compartments is evaluated rather than integrated', () => {
	// Ecolego has plenty of these: they read a released inventory or a
	// measured series and work out a dose. There is nothing to integrate, so
	// the algebraic blocks are evaluated straight onto the output grid.
	const model = {
		name: 'post',
		simulation: { start_time: 0, end_time: 10, output_points: 6, spacing: 'linear' },
		parameters: [{ name: 'DC', value: 2, per_nuclide: false, index_lists: [] }],
		lookups: [{
			name: 'Release', per_nuclide: false, index_lists: [],
			points: [[0, 0], [10, 100]],
		}],
		expressions: [{
			name: 'Dose', equation: 'Release * DC', per_nuclide: false, index_lists: [],
		}],
	};
	const b = buildSystem(new Project(model));
	close(b.layout.nstate, 0, 0);
	close(b.initialState().length, 0, 0);
	// Nothing to differentiate, and the interface is told why rather than
	// being left to report a Jacobian for a model that is never solved.
	assert(b.jacobian.available === false);
	assert(/no compartments/.test(b.jacobian.reason), b.jacobian.reason);

	const r = run(model);
	close(r.t.length, 6, 0);
	assert(r.stats.integrated === false, JSON.stringify(r.stats));
	assert(r.stats.solver == null, 'no solver ran');
	const at = (name) => r.series(r.outputs().find((o) => o.block === name));
	// The table is read at each output time, and the dose follows it.
	close(at('Release')[0], 0, 0);
	close(at('Release')[3], 60, 1e-12);
	close(at('Dose')[3], 120, 1e-12);
	close(at('Dose')[5], 200, 1e-12);
	// There are no state series at all, and the outputs say so.
	assert(!r.outputs().some((o) => o.kind === 'compartment'),
		r.outputs().map((o) => o.kind).join(','));
});

test('an evaluated model handles indices, lookups and reductions', () => {
	// Everything a solved model's algebraic side can do, a post-processing
	// model can do too -- it is the same generated function, called on a grid
	// instead of by a solver.
	const r = run({
		name: 'dose',
		simulation: { start_time: 0, end_time: 100, output_points: 3, spacing: 'linear' },
		nuclides: ['I-129', 'Ra-226'],
		parameters: [{
			name: 'DC', value: 2,
			entries: [{ index: { Radionuclides: 'Ra-226' }, value: 5 }],
		}],
		lookups: [{ name: 'Release', points: [[0, 0], [100, 10]] }],
		expressions: [{ name: 'Dose', equation: 'Release * DC' }],
		index_reductions: [{
			name: 'Total', target: 'Dose', operation: 'sum',
			per_nuclide: false, index_lists: [],
		}],
	});
	assert(r.stats.integrated === false);
	const at = (name, idx, i) => r.series(r.outputs().find(
		(o) => o.block === name && (idx == null || o.index?.[0] === idx)))[i];
	// Halfway: the table reads 5, so the doses are 10 and 25.
	close(at('Release', 'I-129', 1), 5, 1e-12);
	close(at('Dose', 'I-129', 1), 10, 1e-12);
	close(at('Dose', 'Ra-226', 1), 25, 1e-12);
	close(at('Total', null, 1), 35, 1e-12, 'the reduction adds them');
	close(at('Total', null, 2), 70, 1e-12);
});

test('a model with neither compartments nor equations runs anyway', () => {
	// This used to be a BuildError. It is not an error: it is what a model
	// looks like before anything has been added to it, and refusing to build
	// one meant that emptying a model reported a fault in the file where what
	// was wanted was an empty chart and somewhere to click.
	const bare = run({
		simulation: {
			start_time: 0, end_time: 100, output_points: 4, spacing: 'linear',
			solver: 'ndf', rtol: 1e-6, abstol: 1e-9, time_unit: 'year',
		},
	});
	assert(bare.t.length === 4, `${bare.t.length} output points for an empty model`);
	assert(bare.outputs().length === 0, 'an empty model has something to chart');
	assert(bare.stats.integrated === false, 'an empty model was integrated');
	// A CSV of an empty model is the clock and nothing else, which is what a
	// spreadsheet should get rather than a header with no rows.
	const rows = bare.toCSV().trim().split('\n');
	assert(rows[0] === 'time' && rows.length === 5, JSON.stringify(rows));

	// Its parameters are its outputs, each a flat line at its own value, and
	// an indexed one is one line per index like anything else.
	const consts = run({
		simulation: {
			start_time: 0, end_time: 100, output_points: 3, spacing: 'linear',
			solver: 'ndf', rtol: 1e-6, abstol: 1e-9, time_unit: 'year',
		},
		nuclides: ['Cs-137', 'Sr-90'],
		parameters: [
			// Not per nuclide: a dose limit is one number, and a block in a
			// model with a material list has to say so.
			{ name: 'limit', value: 0.014, unit: 'Sv/year', per_nuclide: false },
			{
				name: 'Kd',
				index_lists: ['Radionuclides'],
				unit: 'm3/kg',
				entries: [
					{ index: { Radionuclides: 'Cs-137' }, value: 10 },
					{ index: { Radionuclides: 'Sr-90' }, value: 20 },
				],
			},
		],
	});
	const outs = consts.outputs();
	assert(outs.map((o) => o.label).join(' | ') === 'limit | Kd [Cs-137] | Kd [Sr-90]',
		outs.map((o) => o.label).join(' | '));
	assert(outs.every((o) => o.kind === 'parameter' && o.source === 'P'),
		'a parameter output is not marked as a constant');
	const kd = consts.series(outs[2]);
	assert(kd.length === 3 && [...kd].every((v) => v === 20), [...kd].join());
	assert(consts.constantOf(outs[0]) === 0.014, String(consts.constantOf(outs[0])));
	assert(consts.constantOf(outs[2]) === 20, String(consts.constantOf(outs[2])));
	assert(consts.nuclides.join() === 'Cs-137,Sr-90', 'the nuclide list was lost');
});

test('a parameter is a line on the chart like any other block', () => {
	// The point of charting a constant: a rate beside the flux it scales, or a
	// limit beside the dose that has to stay under it.
	const r = run({
		simulation: {
			start_time: 0, end_time: 10, output_points: 3, spacing: 'linear',
			solver: 'ndf', rtol: 1e-6, abstol: 1e-9, time_unit: 'year',
		},
		parameters: [{ name: 'k', value: 0.1, unit: '1/year' }],
		compartments: [{ name: 'A', initial: '100', unit: 'Bq' }],
		transfers: [{ name: 'loss', from: 'A', to: null, rate: 'k', multiply_by_donor: true }],
	});
	const outs = r.outputs();
	// Parameters come last: they are the least interesting line on any chart
	// and the most numerous in a real model.
	assert(outs.map((o) => o.kind).join() === 'compartment,transfer,parameter',
		outs.map((o) => o.kind).join());
	const k = outs.find((o) => o.kind === 'parameter');
	assert(k.unit === '1/year', `unit ${k.unit}`);
	assert([...r.series(k)].every((v) => v === 0.1), 'k is not flat at 0.1');
	// Only a constant reports one: everything else varies, and saying it does
	// not would be a lie the chart would then draw.
	assert(r.constantOf(outs[0]) === null && r.constantOf(outs[1]) === null,
		'a varying output claims to be constant');
	assert(r.toCSV().split('\n')[0] === 'time,A,loss,k', r.toCSV().split('\n')[0]);
});

test('an evaluated model still orders its blocks and reads the clock', () => {
	// Dependency order and the simulation clock are the two things the solver
	// would otherwise have provided, so they are worth pinning down.
	const r = run({
		name: 'chain',
		simulation: { start_time: 100, end_time: 200, output_points: 3, spacing: 'linear' },
		parameters: [{ name: 'k', value: 3, per_nuclide: false, index_lists: [] }],
		expressions: [
			// Deliberately listed after the block it reads.
			{ name: 'Second', equation: 'First * 2', per_nuclide: false, index_lists: [] },
			{ name: 'First', equation: 'time() * k', per_nuclide: false, index_lists: [] },
		],
	});
	const at = (name) => r.series(r.outputs().find((o) => o.block === name));
	close(at('First')[0], 300, 1e-12, 'time() is the output time, not zero');
	close(at('First')[2], 600, 1e-12);
	close(at('Second')[2], 1200, 1e-12, 'and it was evaluated after First');
});

test('referencing an indexed block from a scalar block is rejected clearly', () => {
	// The message names the index list and suggests both ways out.
	expectError(
		() => buildSystem(new Project({
			nuclides: ['Cs-137', 'Sr-90'],
			compartments: [{ name: 'A', initial: '1' }],
			expressions: [{ name: 'S', equation: 'A', per_nuclide: false }],
		})),
		/indexed by 'Radionuclides'.*explicit index/s, 'ambiguous index',
	);
});

test('an initial condition may read anything that does not change over the run', () => {
	// It used to accept parameters and numbers and nothing else, which is
	// narrower than the model: an initial inventory is very often *derived* --
	// a concentration times a volume, an inventory per square metre times an
	// area -- and writing that as one expression and reading it here is the
	// natural way to say it. Ecolego puts no restriction on it at all; the
	// initial condition goes through the ordinary equation compiler.
	//
	// So the rule is the honest one: a block may be read when its value cannot
	// change over the run. What cannot be read is what has no value yet, or a
	// different one at every moment.
	const model = (initial, extra = {}) => ({
		name: 'ic',
		simulation: {
			start_time: 0, end_time: 1, output_points: 2, spacing: 'linear',
			solver: 'dp45', rtol: 1e-9, abstol: 1e-14, time_unit: 'year',
		},
		parameters: [
			{ name: 'Conc', value: 3, per_nuclide: false },
			{ name: 'Volume', value: 4, per_nuclide: false },
		],
		expressions: [
			{ name: 'Amount', equation: 'Conc * Volume', per_nuclide: false },
			// One built on another, so the chain has to be followed.
			{ name: 'Twice', equation: 'Amount * 2', per_nuclide: false },
			{ name: 'Clocked', equation: 'Conc * time', per_nuclide: false },
			{ name: 'Downstream', equation: 'Clocked + 1', per_nuclide: false },
			{ name: 'FromState', equation: 'Pool + 1', per_nuclide: false },
			...(extra.expressions ?? []),
		],
		lookups: [{
			name: 'Series', per_nuclide: false,
			points: [[0, 5], [1, 9]], interpolation: 'linear',
		}],
		compartments: [
			{ name: 'Pool', initial: '1', handle_decay: false, per_nuclide: false },
			{ name: 'A', initial, handle_decay: false, per_nuclide: false },
		],
		...extra.rest,
	});
	const startsAt = (initial, extra) => {
		const r = run(model(initial, extra));
		return r.series(r.outputs().find((o) => o.block === 'A'))[0];
	};

	// What was always allowed still is.
	close(startsAt('5'), 5, 0, 'a number');
	close(startsAt('Conc * 2'), 6, 0, 'a parameter');
	// ...and now an expression of them, however many steps deep.
	close(startsAt('Amount'), 12, 0, 'an expression of parameters');
	close(startsAt('Twice'), 24, 0, 'an expression of an expression');
	close(startsAt('Amount + Conc'), 15, 0, 'an expression beside a parameter');
	// `start_time` and `end_time` are constants of the run; only `time` moves.
	close(startsAt('Amount * (1 + start_time)'), 12, 0, 'start_time is a constant');

	// And what cannot be read says which of the reasons it is, because the way
	// out differs for each.
	expectError(() => run(model('Pool')),
		/'Pool': it is a compartment, and no compartment has a value until/,
		'a state has no value yet');
	expectError(() => run(model('Clocked')),
		/'Clocked': its value changes over the run/, 'it reads the clock');
	expectError(() => run(model('Downstream')),
		/'Downstream': its value changes over the run/,
		'it reads something that reads the clock');
	expectError(() => run(model('FromState')),
		/'FromState': its value changes over the run/, 'it reads the state');
	expectError(() => run(model('Series')),
		/'Series': its value changes over the run, being read from a table at the clock/,
		'a lookup is read at the clock');
	expectError(() => run(model('Missing')),
		/may only use parameters, numbers and expressions that do not change/,
		'a name that is nothing at all');

	// A block that remembers is a function of history, so it is never one of
	// these -- and neither is anything built on it.
	expectError(() => run(model('Peak', {
		rest: { min_maxes: [{ name: 'Peak', target: 'Pool', operation: 'max', per_nuclide: false }] },
	})), /its value changes over the run/, 'a recorder remembers');

	// An *indexed* expression lands per index, which is the case worth having:
	// an inventory per nuclide per object, written once.
	const r = run({
		name: 'per index',
		simulation: {
			start_time: 0, end_time: 1, output_points: 2, spacing: 'linear',
			solver: 'dp45', rtol: 1e-9, abstol: 1e-14, time_unit: 'year',
		},
		index_lists: [
			{ name: 'Radionuclides', for_nuclides: true, indices: ['I-129', 'Cs-137'] },
			{ name: 'Object', indices: ['Lake', 'Mire'] },
		],
		half_lives: { 'I-129': 1.57e7, 'Cs-137': 30.17 },
		parameters: [
			{ name: 'Conc', index_lists: ['Radionuclides'], value: 0, entries: [
				{ index: { Radionuclides: 'I-129' }, value: 3 },
				{ index: { Radionuclides: 'Cs-137' }, value: 5 }] },
			{ name: 'Vol', index_lists: ['Object'], value: 0, entries: [
				{ index: { Object: 'Lake' }, value: 10 },
				{ index: { Object: 'Mire' }, value: 100 }] },
		],
		expressions: [{
			name: 'Inventory', index_lists: ['Radionuclides', 'Object'],
			equation: 'Conc * Vol',
		}],
		compartments: [{
			name: 'Pool', initial: 'Inventory', handle_decay: false,
			index_lists: ['Radionuclides', 'Object'],
		}],
	});
	const at = (label) => r.series(r.outputs().find((o) => o.label === label))[0];
	close(at('Pool [I-129, Lake]'), 30, 0, '3 x 10');
	close(at('Pool [I-129, Mire]'), 300, 0, '3 x 100');
	close(at('Pool [Cs-137, Lake]'), 50, 0, '5 x 10');
	close(at('Pool [Cs-137, Mire]'), 500, 0, '5 x 100');
});

test('end time before start time is rejected', () => {
	expectError(
		() => new Project({
			simulation: { start_time: 10, end_time: 1 },
			compartments: [{ name: 'A', initial: '0' }],
		}),
		/End time must be greater/, 'bad time span',
	);
});

