test('autoLayout ranks compartments by flow depth', () => {
	const m = {
		compartments: [{ name: 'A' }, { name: 'B' }, { name: 'C' }],
		transfers: [
			{ name: 't1', from: 'A', to: 'B' },
			{ name: 't2', from: 'B', to: 'C' },
		],
	};
	ed.autoLayout(m);
	assert(m.layout.A.x < m.layout.B.x, 'A left of B');
	assert(m.layout.B.x < m.layout.C.x, 'B left of C');
});

test('autoLayout terminates on a cycle and keeps user positions', () => {
	const m = {
		compartments: [{ name: 'A' }, { name: 'B' }],
		transfers: [
			{ name: 't1', from: 'A', to: 'B' },
			{ name: 't2', from: 'B', to: 'A' },
		],
		layout: { A: { x: 5, y: 5 } },
	};
	ed.autoLayout(m);
	close(m.layout.A.x, 5, 0, 'existing position kept');
	assert(m.layout.B, 'B got a position');
});

test('acyclic breaks a cycle by dropping one edge, and only one', () => {
	const ids = ['A', 'B', 'C'];
	const edges = [
		{ from: 'A', to: 'B' }, { from: 'B', to: 'C' }, { from: 'C', to: 'A' },
	];
	const dag = acyclic(ids, edges);
	assert(dag.length === 2, `kept ${dag.length} of 3 edges`);

	// What is left has to be a DAG, or the ranking never terminates.
	const seen = new Set();
	const stack = new Set();
	const out = new Map(ids.map((i) => [i, dag.filter((e) => e.from === i).map((e) => e.to)]));
	const walk = (id) => {
		if (stack.has(id)) throw new Error('still cyclic');
		if (seen.has(id)) return;
		seen.add(id); stack.add(id);
		for (const v of out.get(id)) walk(v);
		stack.delete(id);
	};
	for (const id of ids) walk(id);

	// A self loop is a cycle of one, and goes the same way.
	assert(acyclic(['A'], [{ from: 'A', to: 'A' }]).length === 0, 'self loop dropped');
});

test('rankNodes takes the longest path, and pulls a source up to what it feeds', () => {
	// A -> B -> C, and A -> C directly: C is two columns along, not one.
	const rank = rankNodes(['A', 'B', 'C'], [
		{ from: 'A', to: 'B' }, { from: 'B', to: 'C' }, { from: 'A', to: 'C' },
	]);
	assert(rank.get('A') === 0 && rank.get('B') === 1 && rank.get('C') === 2,
		`ranks ${[...rank].map(([k, v]) => `${k}=${v}`).join(' ')}`);

	// S feeds only C, three columns along. Left where the longest path puts it
	// it would sit alone at the far left with one very long line; it belongs
	// beside what it feeds.
	const pulled = rankNodes(['A', 'B', 'C', 'S'], [
		{ from: 'A', to: 'B' }, { from: 'B', to: 'C' }, { from: 'S', to: 'C' },
	]);
	assert(pulled.get('S') === 1, `source pulled to ${pulled.get('S')}, wanted 1`);
	assert(pulled.get('A') === 0, 'and the chain still starts at 0');
});

test('packLine keeps boxes apart and on target where there is room', () => {
	// Far apart: everyone gets exactly what they asked for.
	const roomy = packLine([50, 50, 50], [0, 200, 400], 10);
	close(roomy[0], 0, 0); close(roomy[1], 200, 0); close(roomy[2], 400, 0);

	// All wanting the same place: they queue, in order, never overlapping.
	const tight = packLine([50, 50, 50], [100, 100, 100], 10);
	for (let i = 1; i < tight.length; i++) {
		assert(tight[i] >= tight[i - 1] + 50 + 10, `box ${i} overlaps its neighbour`);
	}

	// The backward pass: one box shoved along at the start must not drag the
	// rest of the line with it.
	const relieved = packLine([50, 50, 50], [0, 0, 400], 10);
	close(relieved[2], 400, 0, 'the last box keeps its target');
});

test('layerFlow lays a flow out in columns without overlapping anything', () => {
	const nodes = ['A', 'B', 'C', 'D'].map((id) => ({ id, w: 100, h: 40 }));
	const edges = [
		{ from: 'A', to: 'B' }, { from: 'A', to: 'C' },
		{ from: 'B', to: 'D' }, { from: 'C', to: 'D' },
	];
	const { at } = layerFlow(nodes, edges, { gapX: 60, gapY: 30 });
	assert(at.get('A').x < at.get('B').x, 'A left of B');
	assert(at.get('B').x < at.get('D').x, 'B left of D');
	close(at.get('B').x, at.get('C').x, 0, 'the two middle nodes share a column');
	assert(Math.abs(at.get('B').y - at.get('C').y) >= 40 + 30, 'and do not overlap');

	// The diamond is symmetric, so the two ends should sit between its sides.
	const mid = (at.get('B').y + at.get('C').y) / 2;
	close(at.get('A').y, mid, 1, 'A centred on what it feeds');
	close(at.get('D').y, mid, 1, 'D centred on what feeds it');
});

test('layerFlow keeps a lane open for a line that skips a column', () => {
	// A -> B -> C with A -> C as well. The long line passes through B's
	// column, so the ordering has to know it is there; it does, because the
	// line is split into a chain through a placeholder in that column, and the
	// placeholder takes up room B cannot.
	const nodes = ['A', 'B', 'C'].map((id) => ({ id, w: 100, h: 40 }));
	const plain = layerFlow(nodes, [
		{ from: 'A', to: 'B' }, { from: 'B', to: 'C' },
	], { gapX: 60, gapY: 30 });
	const bypassed = layerFlow(nodes, [
		{ from: 'A', to: 'B' }, { from: 'B', to: 'C' }, { from: 'A', to: 'C' },
	], { gapX: 60, gapY: 30 });

	// A plain chain is a straight line, and the bypass is what bends it.
	const spread = (r) => {
		const ys = [...r.at.values()].map((p) => p.y);
		return Math.max(...ys) - Math.min(...ys);
	};
	close(spread(plain), 0, 0, 'a chain lies flat');
	assert(spread(bypassed) > 0, 'the bypass moves the ends off B');
	// The placeholder is not a node: it must not appear in the result or the
	// diagram would try to draw a box for it.
	assert(bypassed.at.size === 3, `${bypassed.at.size} positions for 3 nodes`);
});

test('a flow in two pieces is packed, not stacked in one column', () => {
	// Two chains that share nothing: laid out one under the other they would
	// be a column twice as tall as it needs to be.
	const nodes = ['A', 'B', 'X', 'Y'].map((id) => ({ id, w: 100, h: 40 }));
	const { at, w, h } = layoutFlow(nodes, [
		{ from: 'A', to: 'B' }, { from: 'X', to: 'Y' },
	], { gapX: 60, gapY: 30 });
	assert(components(nodes.map((n) => n.id), [
		{ from: 'A', to: 'B' }, { from: 'X', to: 'Y' },
	]).length === 2, 'two pieces');
	for (const id of ['A', 'B', 'X', 'Y']) assert(at.has(id), `${id} placed`);
	assert(w > 0 && h > 0);
	const boxes = [...at.values()];
	for (let i = 0; i < boxes.length; i++) {
		for (let j = i + 1; j < boxes.length; j++) {
			const p = boxes[i]; const q = boxes[j];
			assert(!(p.x < q.x + 100 && q.x < p.x + 100 && p.y < q.y + 40 && q.y < p.y + 40),
				'two boxes overlap');
		}
	}
});

test('hangRows puts a block under what reads it', () => {
	const reader = { x: 500, y: 0 };
	const { at } = hangRows(
		[{ id: 'p', w: 100, h: 40 }],
		[{ from: 'p', to: 'R' }],
		new Map([['R', reader]]),
		{ top: 100 },
	);
	close(at.get('p').x + 50, 500, 1, 'centred on its reader');
	assert(at.get('p').y >= 100, 'and below the flow');
});

test('hangRows stacks blocks that want the same place instead of spreading them', () => {
	// Forty parameters all feeding one transfer. In a single row they would be
	// nearly ten thousand units across, and every one of them further from
	// what reads it than the last.
	const nodes = Array.from({ length: 40 }, (_, i) => ({ id: `p${i}`, w: 120, h: 44 }));
	const links = nodes.map((n) => ({ from: n.id, to: 'R' }));
	const { at } = hangRows(nodes, links, new Map([['R', { x: 600, y: 0 }]]), { top: 0 });
	const xs = [...at.values()].map((p) => p.x);
	const ys = [...at.values()].map((p) => p.y);
	const width = Math.max(...xs) + 120 - Math.min(...xs);
	assert(width < 3000, `spread over ${Math.round(width)} units`);
	assert(new Set(ys).size > 1, 'they did not stack');

	// And none of them landed on top of another.
	const boxes = [...at.values()];
	for (let i = 0; i < boxes.length; i++) {
		for (let j = i + 1; j < boxes.length; j++) {
			const p = boxes[i]; const q = boxes[j];
			assert(!(p.x < q.x + 120 && q.x < p.x + 120 && p.y < q.y + 44 && q.y < p.y + 44),
				'two parameters overlap');
		}
	}
});

test('hangRows places a block whose neighbours are all further from the flow', () => {
	// D reads C reads B reads A, and only A touches the flow. On the way down
	// D has nothing placed to go on; the sweep back up is what finds it.
	const nodes = ['A', 'B', 'C', 'D'].map((id) => ({ id, w: 100, h: 40 }));
	const links = [
		{ from: 'A', to: 'B' }, { from: 'B', to: 'C' }, { from: 'C', to: 'D' },
		{ from: 'F', to: 'A' },
	];
	const { at } = hangRows(nodes, links, new Map([['F', { x: 800, y: 0 }]]), { top: 0 });
	for (const id of ['A', 'B', 'C', 'D']) {
		close(at.get(id).x + 50, 800, 60, `${id} under the flow it supplies`);
	}
	// A is read by D through the chain, so D is the row nearest the flow.
	assert(at.get('D').y < at.get('C').y, 'D above C');
	assert(at.get('C').y < at.get('B').y, 'C above B');
	assert(at.get('B').y < at.get('A').y, 'B above A');
});

test('autoLayout puts a rate parameter between the compartments it moves between', () => {
	const m = {
		compartments: [{ name: 'A' }, { name: 'B' }],
		transfers: [{ name: 'T', from: 'A', to: 'B', rate: 'k' }],
		parameters: [{ name: 'k', value: 1 }],
	};
	ed.autoLayout(m);
	const mid = (n) => m.layout[n].x + ed.blockSize(m, n, 'compartment').w / 2;
	const k = m.layout.k.x + ed.blockSize(m, 'k', 'parameter').w / 2;
	close(k, (mid('A') + mid('B')) / 2, 2, 'under the middle of the transfer');
	assert(m.layout.k.y > m.layout.A.y, 'and below the flow');
});

test('autoLayout keeps an influence-only model in dependency order', () => {
	// No compartments at all: a post-processing model is nothing but blocks
	// reading blocks, and it still has a shape.
	const m = {
		compartments: [],
		expressions: [{ name: 'Out', equation: 'Mid * 2' }, { name: 'Mid', equation: 'In + 1' }],
		parameters: [{ name: 'In', value: 1 }],
	};
	ed.autoLayout(m);
	assert(m.layout.Out.y < m.layout.Mid.y, 'the output is above what it reads');
	assert(m.layout.Mid.y < m.layout.In.y, 'and that above what it reads');
});

test('autoLayout leaves no two blocks on top of each other, in any example', async () => {
	const { readFileSync, readdirSync } = await import('node:fs');
	const dir = new URL('../examples/', import.meta.url);
	const KIND = {
		compartments: 'compartment', expressions: 'expression', parameters: 'parameter',
		lookups: 'lookup', index_reductions: 'index_reduction', block_reductions: 'block_reduction',
	};
	for (const f of readdirSync(dir).filter((x) => x.endsWith('.json'))) {
		const m = JSON.parse(readFileSync(new URL(f, dir), 'utf8'));
		// The examples ship with positions of their own; this is about what
		// the layout does when there are none.
		delete m.layout;
		ed.autoLayout(m);

		const boxes = [];
		for (const [coll, kind] of Object.entries(KIND)) {
			for (const b of m[coll] ?? []) {
				const name = sys.qualifiedName(b);
				const at = m.layout[name];
				assert(at, `${f}: ${name} got no position`);
				boxes.push({ name, ...at, ...ed.blockSize(m, name, kind) });
			}
		}
		// Within one canvas. `autoLayout` lays each sub-system out in its own
		// coordinates -- that is how the diagram draws them, one at a time --
		// so two blocks in different sub-systems share coordinates without
		// ever being drawn together, and comparing them is comparing the
		// positions of two different drawings. Only held before because no
		// example had a sub-system.
		const perCanvas = new Map();
		for (const b of boxes) {
			const canvas = sys.parentOf(b.name);
			if (!perCanvas.has(canvas)) perCanvas.set(canvas, []);
			perCanvas.get(canvas).push(b);
		}
		for (const [canvas, here] of perCanvas) {
			for (let i = 0; i < here.length; i++) {
				for (let j = i + 1; j < here.length; j++) {
					const p = here[i]; const q = here[j];
					const hit = p.x < q.x + q.w && q.x < p.x + p.w
						&& p.y < q.y + q.h && q.y < p.y + p.h;
					assert(!hit, `${f}: ${p.name} overlaps ${q.name}`
						+ ` on ${canvas || 'the top level'}`);
				}
			}
		}
	}
});

test('placeLoose puts a new block by what reads it, and moves nothing', () => {
	const m = {
		compartments: [{ name: 'A' }, { name: 'B' }],
		transfers: [{ name: 'T', from: 'A', to: 'B', rate: '1' }],
		parameters: [],
	};
	ed.autoLayout(m);
	const before = JSON.parse(JSON.stringify(m.layout));

	// A parameter added from the block list arrives with no geometry, and the
	// transfer is edited to read it.
	ed.addParameter(m, { name: 'k', value: 1 });
	ed.updateBlock(m, 'T', { rate: 'k' });
	assert(!m.layout.k, 'the new parameter has no position yet');
	ed.placeLoose(m);

	for (const [name, at] of Object.entries(before)) {
		close(m.layout[name].x, at.x, 0, `${name} did not move`);
		close(m.layout[name].y, at.y, 0, `${name} did not move`);
	}
	const mid = (m.layout.A.x + m.layout.B.x + ed.blockSize(m, 'A', 'compartment').w) / 2;
	close(m.layout.k.x + ed.blockSize(m, 'k', 'parameter').w / 2, mid, 40,
		'the new parameter is near the transfer that reads it');
	assert(m.layout.k.y > m.layout.A.y, 'and below the flow');
});

// --- lining a selection up by hand -----------------------------------------

/** Three boxes of three different sizes, scattered. */
const SCATTERED = () => [
	{ x: 0, y: 0, w: 100, h: 40 },
	{ x: 20, y: 70, w: 60, h: 40 },
	{ x: 200, y: 10, w: 40, h: 80 },
];

test('the six lines are drawn through the extent of the selection', () => {
	const boxes = SCATTERED();
	// Left edge 0, right edge 240, top 0, bottom 110 -- the bounds of the
	// three together, since there is no page to align to.
	const left = alignBoxes(boxes, 'left');
	assert(left.every((p) => p.x === 0), 'every left edge on the leftmost');
	const right = alignBoxes(boxes, 'right');
	right.forEach((p, i) => close(p.x + boxes[i].w, 240, 0, 'right edges level'));
	const centre = alignBoxes(boxes, 'centre');
	centre.forEach((p, i) => close(p.x + boxes[i].w / 2, 120, 0, 'centres level'));

	const top = alignBoxes(boxes, 'top');
	assert(top.every((p) => p.y === 0), 'every top edge on the topmost');
	const bottom = alignBoxes(boxes, 'bottom');
	bottom.forEach((p, i) => close(p.y + boxes[i].h, 110, 0, 'bottom edges level'));
	const middle = alignBoxes(boxes, 'middle');
	middle.forEach((p, i) => close(p.y + boxes[i].h / 2, 55, 0, 'middles level'));

	// One axis at a time: aligning left must not shuffle anything vertically.
	left.forEach((p, i) => close(p.y, boxes[i].y, 0, 'y untouched'));
	top.forEach((p, i) => close(p.x, boxes[i].x, 0, 'x untouched'));
});

test('distributing equalises the gaps, not the centres', () => {
	// Widths 100, 60, 40 across a span of 240: 40 units of air for two gaps.
	const boxes = SCATTERED();
	const at = alignBoxes(boxes, 'across');
	const laid = at.map((p, i) => ({ x: p.x, w: boxes[i].w })).sort((a, b) => a.x - b.x);
	close(laid[1].x - (laid[0].x + laid[0].w), 20, 0, 'first gap');
	close(laid[2].x - (laid[1].x + laid[1].w), 20, 0, 'second gap');
	// Equal centres would have been 0, 90, 200 -- which is not this.
	assert(at[1].x !== 90, 'the middle box is not spaced by its centre');
	// The span is what was divided, so its ends are where they were.
	close(laid[0].x, 0, 0, 'left end stays');
	close(laid[2].x + laid[2].w, 240, 0, 'right end stays');

	const down = alignBoxes(boxes, 'down');
	const rows = down.map((p, i) => ({ y: p.y, h: boxes[i].h })).sort((a, b) => a.y - b.y);
	close(rows[1].y - (rows[0].y + rows[0].h), rows[2].y - (rows[1].y + rows[1].h), 0,
		'equal gaps down as well');
	down.forEach((p, i) => close(p.x, boxes[i].x, 0, 'x untouched'));
});

test('distributing keeps the order it found, and the span, even when they do not fit', () => {
	// Three boxes 100 wide in a span of 150: the gaps are negative, so they
	// overlap -- evenly, and still between the same two edges. Refusing would
	// leave the selection as it was, which is the one thing it is not.
	//
	// Given out of order, too: what is spread is what is on the diagram, and
	// the order blocks happen to sit in the file is not that.
	const boxes = [
		{ x: 50, y: 0, w: 100, h: 20 },
		{ x: 0, y: 0, w: 100, h: 20 },
		{ x: 30, y: 0, w: 100, h: 20 },
	];
	const at = alignBoxes(boxes, 'across');
	assert(at[1].x < at[2].x && at[2].x < at[0].x, 'left to right as they were seen');
	close(at[1].x, 0, 0, 'left end stays');
	close(at[0].x + 100, 150, 0, 'right end stays');
	close((at[2].x - (at[1].x + 100)) - (at[0].x - (at[2].x + 100)), 0, 0,
		'the overlap is shared equally');
});

test('an arrangement of one or two does what it can, and no more', () => {
	const one = [{ x: 7, y: 9, w: 10, h: 10 }];
	for (const how of ARRANGEMENTS) {
		const at = alignBoxes(one, how);
		close(at[0].x, 7, 0, `${how} left one box alone`);
		close(at[0].y, 9, 0, `${how} left one box alone`);
	}
	// Two can be lined up but not spread: they are both ends of the span.
	const two = [{ x: 0, y: 0, w: 10, h: 10 }, { x: 40, y: 0, w: 10, h: 10 }];
	close(alignBoxes(two, 'across')[1].x, 40, 0, 'nothing to spread between two');
	close(alignBoxes(two, 'left')[1].x, 0, 0, 'but two do line up');
	let threw = false;
	try { alignBoxes(two, 'sideways'); } catch { threw = true; }
	assert(threw, 'an arrangement nobody offers is refused');
});

test('aligning blocks uses the sizes the diagram draws, sub-systems included', () => {
	const m = {
		compartments: [{ name: 'A' }, { name: 'B' }, { name: 'Inner', system: 'S' }],
		parameters: [{ name: 'k' }],
		transfers: [{ name: 'T', from: 'A', to: 'B', rate: 'k' }],
		layout: {
			A: { x: 0, y: 0 },
			B: { x: 40, y: 200, w: 300 },
			k: { x: 500, y: 90 },
			S: { x: 90, y: 400 },
		},
	};
	const wide = ed.blockSize(m, 'B', 'compartment').w;
	assert(wide === 300, 'B carries an explicit width');

	// Right edges: B is the widest and reaches furthest, so it is the one the
	// others move to -- which a rule that only looked at x would miss.
	const right = Math.max(
		ed.blockSize(m, 'k', 'parameter').w + 500,
		40 + wide,
	);
	assert(ed.alignBlocks(m, ['A', 'B', 'k', 'S'], 'right') > 0);
	for (const [name, kind] of [['A', 'compartment'], ['B', 'compartment'],
		['k', 'parameter'], ['S', 'system']]) {
		close(m.layout[name].x + ed.blockSize(m, name, kind).w, right, 0,
			`${name} right edge`);
	}
	// A sub-system is a node on the diagram, so it moved with the rest.
	assert(m.layout.S.x !== 90, 'the sub-system was lined up too');
	// And nothing was resized on the way.
	close(m.layout.B.w, 300, 0, 'B kept its width');

	// Nothing left to do: the second time it says so rather than recording an
	// edit, which is what lets the diagram report it instead of an undo step.
	assert(ed.alignBlocks(m, ['A', 'B', 'k', 'S'], 'right') === 0, 'already lined up');
});

test('what is drawn as a line has no box to line up', () => {
	const m = {
		compartments: [{ name: 'A' }, { name: 'B' }],
		transfers: [{ name: 'T', from: 'A', to: 'B', rate: '1' }],
		layout: { A: { x: 0, y: 0 }, B: { x: 100, y: 100 } },
	};
	for (const bad of ['T', 'Nope']) {
		let threw = false;
		try { ed.alignBlocks(m, ['A', bad], 'left'); } catch { threw = true; }
		assert(threw, `${bad} refused`);
	}
	// Refused before anything moved.
	close(m.layout.B.x, 100, 0, 'B stayed where it was');
	let threw = false;
	try { ed.alignBlocks(m, ['A', 'B'], 'nowhere'); } catch { threw = true; }
	assert(threw, 'an arrangement nobody offers is refused');
});

test('a shape is lined up by the box it occupies, keeping which way it points', () => {
	const m = {
		shapes: [
			{ id: 'sh1', figure: 'rect', x: 0, y: 0, w: 100, h: 50 },
			// An arrow drawn up and to the left: its width and height are its
			// direction, so they are negative and its box is elsewhere.
			{ id: 'sh2', figure: 'arrow', x: 300, y: 200, w: -80, h: -40 },
		],
	};
	assert(ed.alignShapes(m, ['sh1', 'sh2'], 'left') === 1, 'one of the two moved');
	const arrow = m.shapes[1];
	close(Math.min(arrow.x, arrow.x + arrow.w), 0, 0, 'its box is on the leftmost edge');
	close(arrow.w, -80, 0, 'and it still points the way it did');
	close(arrow.h, -40, 0, 'and it still points the way it did');
	close(m.shapes[0].x, 0, 0, 'the rectangle was already there');

	let threw = false;
	try { ed.alignShapes(m, ['sh1', 'nope'], 'left'); } catch { threw = true; }
	assert(threw, 'an id that names nothing is refused');
});

// --- the blocks that remember ----------------------------------------------

/**
 * A model exercising all five at once, against values that can be worked out
 * by hand: over 0..10 the target `time` has mean 5, `time*(10-time)` peaks at
 * 25, and `time` delayed by 2 is `t - 2`.
 */
function rememberingModel(solver = 'dp45', extra = {}) {
	return {
		simulation: {
			start_time: 0, end_time: 10, output_points: 101, spacing: 'linear',
			solver, rtol: 1e-9, abstol: 1e-11, time_unit: 'year',
		},
		compartments: [{ name: 'A', initial: '1' }],
		expressions: [
			{ name: 'Ramp', equation: 'time' },
			{ name: 'Hump', equation: 'time * (10 - time)' },
		],
		min_maxes: [{ name: 'PeakHump', target: 'Hump', operation: 'max' }],
		running_means: [{ name: 'MeanRamp', target: 'Ramp' }],
		delays: [{ name: 'Lagged', target: 'Ramp', delay: '2' }],
		triggers: [
			{ name: 'Halfway', first: 'time', second: '5', direction: 'rising' },
		],
		snapshots: [
			{ name: 'AtHalfway', target: 'Ramp', event: 'Halfway', initial: '-1' },
		],
		...extra,
	};
}

/** The value of one output at (or just before) a time. */
function valueAtTime(results, label, t) {
	const out = results.outputs().find((o) => o.label === label);
	assert(out, `no output called '${label}'`);
	const s = results.series(out);
	let best = 0;
	for (let i = 0; i < results.t.length; i++) if (results.t[i] <= t + 1e-9) best = i;
	return s[best];
}

test('a history is read back as a staircase, and a delay between its points', () => {
	const h = new History();
	for (const [t, v] of [[0, 1], [1, 4], [3, 9]]) h.add(t, v);

	// hold: EcoMath.useInputBelow -- the last value at or before the time,
	// flat outside the range at both ends.
	close(h.hold(-5), 1, 0); close(h.hold(0), 1, 0);
	close(h.hold(0.9), 1, 0); close(h.hold(1), 4, 0);
	close(h.hold(2.9), 4, 0); close(h.hold(3), 9, 0); close(h.hold(99), 9, 0);

	// lerp: ScalarBatchRecorder.get -- straight between the points, flat outside.
	close(h.lerp(-5), 1, 0); close(h.lerp(0.5), 2.5, 0);
	close(h.lerp(2), 6.5, 0); close(h.lerp(99), 9, 0);

	// Reads arrive in whatever order the solver's stages ask for, so the same
	// answers have to come back however they are approached.
	close(h.hold(2.9), 4, 0, 'after a read further on');
	close(h.lerp(0.5), 2.5, 0);

	// A restart lands on the time already recorded; that replaces the point
	// rather than leaving two at one instant.
	h.add(3, 11);
	assert(h.size === 3, `${h.size} points`);
	close(h.hold(3), 11, 0);
	close(h.lastTime, 3, 0);

	// Nothing recorded reads as zero rather than as NaN.
	const empty = new History();
	close(empty.hold(1), 0, 0);
	close(empty.lerp(1), 0, 0);
});

test('the five remembering blocks each compute what they say they do', () => {
	for (const solver of ['dp45', 'ros23', 'ndf']) {
		const r = run(new Project(rememberingModel(solver)));
		const at = (n, t) => valueAtTime(r, n, t);

		// The largest `time * (10 - time)` has been: 25, at t = 5, which is
		// where the event puts a step. Between steps the block reports the
		// extreme at the last one -- a staircase, which is what Ecolego
		// reports too: its history is written on accepted steps and read back
		// with `useInputBelow`.
		close(at('PeakHump', 10), 25, 1e-6, `${solver}: peak`);
		const peaks = r.series(r.outputs().find((o) => o.label === 'PeakHump'));
		for (let i = 1; i < peaks.length; i++) {
			assert(peaks[i] >= peaks[i - 1] - 1e-12, `${solver}: a maximum went down`);
			assert(peaks[i] <= 25 + 1e-9, `${solver}: a maximum above the real one`);
		}

		// The mean of `time` over 0..10. Between steps it is the same
		// staircase as the maximum, and it can never run ahead of the true
		// mean so far, which for this target is t/2.
		close(at('MeanRamp', 10), 5, 1e-6, `${solver}: mean`);
		const means = r.series(r.outputs().find((o) => o.label === 'MeanRamp'));
		for (let i = 1; i < means.length; i++) {
			assert(means[i] >= means[i - 1] - 1e-12, `${solver}: a mean went down`);
			// The bound is the true mean plus the solver's own error: the
			// integral underneath is integrated, not summed.
			assert(means[i] <= (r.t[i] / 2) * (1 + 1e-6) + 1e-9,
				`${solver}: a mean ran ahead of itself at t=${r.t[i]}`);
		}

		// `time` as it was two years ago, and the first value it ever had
		// before that.
		close(at('Lagged', 10), 8, 1e-6, `${solver}: delay`);
		close(at('Lagged', 3), 1, 1e-6, `${solver}: delay`);
		close(at('Lagged', 1), 0, 1e-9, `${solver}: before the history starts`);

		// The snapshot holds its initial value until the event fires, then
		// what its target was at the crossing -- which is exactly 5.
		close(at('AtHalfway', 4), -1, 0, `${solver}: before the event`);
		close(at('AtHalfway', 6), 5, 1e-7, `${solver}: at the event`);

		// A discrete event's own value is the gap between its two expressions.
		close(at('Halfway', 10), 5, 1e-9, `${solver}: the event function`);

		// One crossing, located once. Without the guard against a crossing at
		// the instant a restart begins, this fires again on every segment.
		assert(r.stats.events === 1, `${solver}: ${r.stats.events} events`);
	}
});

test('a discrete event stops the solver at the crossing, not at the next step', () => {
	// Ten output points over ten years: the crossing at t = 5 falls between
	// two of them, so a solver that only looked at output times would put the
	// snapshot at 5.55 or at 4.44.
	const m = rememberingModel('dp45');
	m.simulation.output_points = 10;
	const r = run(new Project(m));
	close(valueAtTime(r, 'AtHalfway', 10), 5, 1e-7);
	assert(r.stats.restarts === 1, `${r.stats.restarts} restarts`);
});

test('firstCrossing finds a root in the direction asked for, and only then', () => {
	// g(t) = t - 3 over [0, 10], sampled exactly.
	const g = (t) => Float64Array.from([t - 3]);
	const hit = firstCrossing(g, 0, g(0), 10, g(10), Int8Array.from([1]));
	assert(hit, 'no crossing found');
	close(hit.t, 3, 1e-9);
	assert(hit.which.join() === '0');

	// The same crossing, the wrong way round: it rises, so a falling event
	// must not see it.
	assert(firstCrossing(g, 0, g(0), 10, g(10), Int8Array.from([-1])) === null);
	// And either way counts for 0.
	assert(firstCrossing(g, 0, g(0), 10, g(10), Int8Array.from([0])) !== null);

	// The earliest of several, which is the only one that matters when every
	// event is terminal.
	const two = (t) => Float64Array.from([t - 7, t - 2]);
	const both = firstCrossing(two, 0, two(0), 10, two(10), Int8Array.from([1, 1]));
	close(both.t, 2, 1e-9);
	assert(both.which.join() === '1', both.which.join());
});

test('an event resets a min/max and starts and stops a running mean', () => {
	const m = {
		simulation: {
			start_time: 0, end_time: 10, output_points: 201, spacing: 'linear',
			solver: 'ros23', rtol: 1e-10, abstol: 1e-12, time_unit: 'year',
		},
		compartments: [{ name: 'A', initial: '1' }],
		expressions: [
			{ name: 'Down', equation: '10 - time' },
			{ name: 'Ramp', equation: 'time' },
		],
		triggers: [
			{ name: 'At5', first: 'time', second: '5', direction: 'rising' },
			{ name: 'At8', first: 'time', second: '8', direction: 'rising' },
		],
		min_maxes: [
			{ name: 'Peak', target: 'Down', operation: 'max' },
			{ name: 'PeakAfter5', target: 'Down', operation: 'max', reset_trigger: 'At5' },
			{ name: 'Lowest', target: 'Down', operation: 'min' },
		],
		running_means: [
			{ name: 'MeanAll', target: 'Ramp' },
			{ name: 'MeanFrom5', target: 'Ramp', start_trigger: 'At5' },
			{ name: 'Mean5to8', target: 'Ramp', start_trigger: 'At5', stop_trigger: 'At8' },
		],
	};
	const r = run(new Project(m));
	const at = (n, t) => valueAtTime(r, n, t);

	// `10 - time` starts at its largest, so an unreset maximum never moves;
	// resetting at t = 5 starts it again from 5.
	close(at('Peak', 10), 10, 1e-7);
	close(at('PeakAfter5', 10), 5, 1e-5);
	close(at('Lowest', 10), 0, 1e-6, 'the smallest it reaches');

	// The mean of `time`: over 0..10 it is 5, over 5..10 it is 7.5, over 5..8
	// it is 6.5 and stays there once the recording stops.
	close(at('MeanAll', 10), 5, 1e-6);
	close(at('MeanFrom5', 10), 7.5, 1e-5);
	close(at('Mean5to8', 10), 6.5, 1e-5);
	close(at('Mean5to8', 9), 6.5, 1e-5, 'unchanged after it stops');

	assert(r.stats.events === 2, `${r.stats.events} events`);
});

test('a running mean is a state, and its analytic Jacobian is right', () => {
	const m = {
		simulation: {
			start_time: 0, end_time: 20, output_points: 21, spacing: 'linear',
			solver: 'ndf', rtol: 1e-8, abstol: 1e-10, time_unit: 'year',
		},
		parameters: [{ name: 'k', value: 0.1 }],
		compartments: [
			{ name: 'A', initial: '10' },
			{ name: 'B', initial: '0' },
		],
		transfers: [{ name: 'T', from: 'A', to: 'B', rate: 'k' }],
		// A + B is conserved, so the mean of it is that constant exactly --
		// which is the point: it isolates the integral from the arithmetic.
		expressions: [{ name: 'Both', equation: 'A + B' }],
		running_means: [{ name: 'MeanBoth', target: 'Both' }],
	};

	const sys = buildSystem(new Project(m));
	// Two compartments and the mean's integral, in that order: a compartment
	// is addressed by name, the integral never is.
	const kinds = sys.layout.states.map((s) => `${s.name}:${s.kind}`);
	assert(kinds.join(' ') === 'A:compartment B:compartment MeanBoth:running_mean',
		kinds.join(' '));

	const { worst } = jacobianAgrees(m, { states: 2 });
	assert(worst < 1, `off by ${worst.toFixed(2)}x the difference's own noise`);
	// The matrix moves: a mean divides by a time that grows, so it cannot be
	// factorised once and reused.
	assert(sys.jacobian.constant === false, 'reported constant');

	// The mean of a constant is that constant.
	const r = run(new Project(m));
	close(valueAtTime(r, 'MeanBoth', 20), 10, 1e-6);
});

test('a model that remembers gives the same answer twice', () => {
	// The histories are cleared at the start of each run; if they were not,
	// a second run would start with the first one's maximum already in place.
	const m = rememberingModel('ros23');
	const first = run(new Project(m));
	const second = run(new Project(m));
	for (const label of ['PeakHump', 'MeanRamp', 'Lagged', 'AtHalfway']) {
		close(valueAtTime(second, label, 10), valueAtTime(first, label, 10), 1e-12, label);
	}

	// And the same system, run twice, must not accumulate either.
	const sys = buildSystem(new Project(m));
	const before = sys.memory[0].history.size;
	sys.primeRecorders(0, sys.initialState());
	assert(sys.memory[0].history.size <= before + 1, 'the history was not cleared');
});

test('the blocks that remember round-trip through the project format', () => {
	const m = rememberingModel();
	const round = new Project(JSON.parse(JSON.stringify(new Project(m).toJSON())));
	assert(round.min_maxes[0].target === 'Hump');
	assert(round.min_maxes[0].operation === 'max');
	assert(round.running_means[0].target === 'Ramp');
	assert(round.snapshots[0].trigger === 'Halfway');
	assert(round.snapshots[0].initial === '-1');
	assert(round.delays[0].delay === '2');
	assert(round.triggers[0].direction === 'rising');

	// Ecolego's own spellings are accepted on the way in and normalised.
	const eco = new Project({
		...m,
		min_maxes: [{ name: 'PeakHump', target: 'Hump', operation: 'MIN' }],
		triggers: [
			{ name: 'Halfway', first: 'time', second: '5', direction: 'LEFT' },
		],
	});
	assert(eco.min_maxes[0].operation === 'min', eco.min_maxes[0].operation);
	assert(eco.triggers[0].direction === 'falling', eco.triggers[0].direction);
});

test('adding a recorder takes its target’s dimensions, and renames follow it', () => {
	const m = {
		index_lists: [
			{ name: 'Radionuclides', for_contaminants: true, indices: ['Cs-137', 'I-129'] },
		],
		compartments: [{ name: 'Soil', index_lists: ['Radionuclides'], initial: '1' }],
		expressions: [{ name: 'Dose', index_lists: ['Radionuclides'], equation: 'Soil' }],
	};
	const event = ed.addRecorder(m, 'trigger', { first: 'Dose', second: '0' });
	const peak = ed.addRecorder(m, 'min_max', { target: 'Dose' });
	const snap = ed.addRecorder(m, 'snapshot', { target: 'Dose', trigger: event.name });
	assert(peak.index_lists.join() === 'Radionuclides', peak.index_lists.join());
	assert(event.index_lists.join() === 'Radionuclides');

	// The target is a reference like any other, and so is the event.
	ed.renameBlock(m, 'Dose', 'DoseRate');
	assert(peak.target === 'DoseRate', peak.target);
	assert(m.triggers[0].first === 'DoseRate');
	ed.renameBlock(m, event.name, 'Crossed');
	assert(snap.trigger === 'Crossed', snap.trigger);

	// And a block something is watching cannot be deleted out from under it.
	let refused = null;
	try { ed.deleteBlock(m, 'DoseRate'); } catch (e) { refused = e.message; }
	assert(refused && /DoseRate/.test(refused), String(refused));
	assert(/Peak|Crossed|Snapshot/.test(refused), refused);
});

test('variableOrder integrates a model with events, whatever its state count', async () => {
	// ndf.js rebuilds its interpolation data when an event cuts a step short.
	// The scratch array holds k+1-m columns of neq rows, and was allocated by
	// neq -- so with the order ahead of the state count, which is every small
	// model with an event, the later columns were undefined and the solver
	// threw "Cannot set properties of undefined" instead of integrating.
	const { readFileSync } = await import('node:fs');
	const raw = JSON.parse(
		readFileSync(new URL('../examples/recorders.json', import.meta.url), 'utf8'),
	);
	const results = {};
	for (const solver of ['ndf', 'ros23', 'dp45']) {
		results[solver] = run({ ...raw, simulation: { ...raw.simulation, solver } });
		assert(results[solver].t.length > 100, `${solver} returned too few points`);
		assert(results[solver].stats.events >= 1, `${solver} located no event`);
	}
	// The state itself has to agree; the blocks that sample accepted steps --
	// min/max, running mean, delay -- legitimately do not, because no two
	// solvers step alike.
	const base = results.ros23;
	for (const id of ['ndf', 'dp45']) {
		let worst = 0;
		for (const o of base.outputs()) {
			if (o.kind !== 'compartment' && o.kind !== 'expression') continue;
			const a = base.series(o);
			const b = results[id].series(o);
			let scale = 0;
			for (let i = 0; i < a.length; i++) scale = Math.max(scale, Math.abs(a[i]));
			if (!(scale > 0)) continue;
			for (let i = 0; i < a.length; i++) {
				if (Math.abs(a[i]) < scale * 1e-6) continue;
				worst = Math.max(worst, Math.abs(a[i] - b[i]) / Math.abs(a[i]));
			}
		}
		assert(worst < 1e-3, `${id} disagrees with rosenbrock23 by ${worst.toExponential(1)}`);
	}
});

test('the bundled recorder example computes what it claims', async () => {
	const { readFileSync } = await import('node:fs');
	const raw = JSON.parse(readFileSync(new URL('../examples/recorders.json', import.meta.url), 'utf8'));
	const r = run(new Project(raw));

	const dose = r.outputs().find((o) => o.block === 'Dose');
	const series = r.series(dose);
	let peak = -Infinity;
	for (const v of series) peak = Math.max(peak, v);

	// The recorded peak is the continuous one, so it is at least the largest
	// value any output point happened to catch.
	const recorded = valueAtTime(r, 'Peak_dose [Cs-137]', raw.simulation.end_time);
	assert(recorded >= peak, `${recorded} < ${peak}`);
	close(recorded, peak, 1e-3, 'and no more than a whisker above it');

	// The event fires when the dose falls back through the limit, and the
	// snapshot holds that year.
	const year = valueAtTime(r, 'Year_below_limit [Cs-137]', raw.simulation.end_time);
	assert(year > 0 && year < raw.simulation.end_time, `crossed at ${year}`);
	const limit = raw.parameters.find((p) => p.name === 'Limit').value;
	close(valueAtTime(r, 'Dose [Cs-137]', year), limit, 1e-2, 'the dose at the crossing');

	// The delay reports the dose a century earlier, which is a value the same
	// run already has.
	const end = raw.simulation.end_time;
	const lagged = valueAtTime(r, 'Dose_a_century_ago [Cs-137]', end);
	close(lagged, valueAtTime(r, 'Dose [Cs-137]', end - 100), 5e-2, 'a century back');
});

test('an edited model still builds and runs', () => {
	const m = baseModel();
	delete m.layout;
	ed.addCompartment(m, { name: 'C' });
	ed.addTransfer(m, 'B', 'C', { rate: 'k' });
	ed.renameBlock(m, 'k', 'rate');
	m.simulation = {
		start_time: 0, end_time: 50, output_points: 3, spacing: 'linear',
		solver: 'dp45', rtol: 1e-10, abstol: 1e-14,
	};
	const r = run(m);
	// A -> B -> C with equal rates: mass is conserved across the three.
	for (let i = 0; i < r.t.length; i++) {
		close(r.y[i][0] + r.y[i][1] + r.y[i][2], 1, 1e-9, `mass at t=${r.t[i]}`);
	}
	assert(m.transfers[0].rate === 'rate', 'rename reached the transfer');
});

test('layout survives a Project round-trip', () => {
	const m = baseModel();
	m.simulation = { start_time: 0, end_time: 1, output_points: 2, spacing: 'linear' };
	const round = new Project(JSON.parse(JSON.stringify(new Project(m).toJSON())));
	close(round.layout.A.x, 10, 0);
	close(round.layout.B.x, 200, 0);
});

