test('a lookup is a block the editor can add, rename, move and delete', () => {
	const p = {
		name: 'ed',
		simulation: { start_time: 0, end_time: 100, output_points: 3, spacing: 'linear' },
		systems: ['NF'],
		compartments: [{ name: 'A', initial: '0' }],
		expressions: [{ name: 'E', equation: 'Q * 2' }],
	};
	const block = ed.addLookup(p, { name: 'Q' });
	close(block.points.length, 2, 0, 'a new table spans the simulation');
	close(block.points[1][0], 100, 0);
	assert(ed.findBlock(p, 'Q'), 'findable by name');
	assert(ed.blockNames(p).includes('Q'));

	// Renaming follows through the equation that reads it.
	ed.renameBlock(p, 'Q', 'Flow');
	assert(p.expressions[0].equation === 'Flow * 2', p.expressions[0].equation);

	// And into a sub-system, where the reference has to become qualified.
	const to = ed.moveBlock(p, 'Flow', 'NF');
	assert(to === 'NF.Flow', to);
	assert(p.expressions[0].equation === 'NF.Flow * 2', p.expressions[0].equation);

	// Deleting one that is still read is refused, as for any other block.
	let caught = null;
	try { ed.deleteBlock(p, 'NF.Flow'); } catch (e) { caught = e; }
	assert(caught instanceof ed.EditError, String(caught));
	p.expressions[0].equation = '0';
	const removed = ed.deleteBlock(p, 'NF.Flow');
	assert(removed.includes('NF.Flow'), removed.join(','));
	close(p.lookups.length, 0, 0);
});

test('a lookup takes a shape, a colour and a size like any other node', () => {
	assert(ed.NODE_KINDS.includes('lookup'), ed.NODE_KINDS.join(','));
	const p = { name: 'ap', compartments: [{ name: 'A' }] };
	ed.addLookup(p, { name: 'Q' });
	close(ed.blockSize(p, 'Q', 'lookup').w, ed.DEFAULT_SIZE.lookup.w, 0);
	ed.setBlockColor(p, 'Q', '#ff0000');
	assert(p.lookups[0].color === '#ff0000');
	ed.setBlockShape(p, 'Q', 'ellipse');
	assert(ed.blockShape(p, 'Q') === 'ellipse');
});

test('a new lookup is not indexed by the nuclide list', () => {
	// A measured series is a property of the place, not of the nuclide in it,
	// which is the same exception parameters get.
	const p = {
		name: 'nd', nuclides: ['Cs-137'],
		index_lists: [{ name: 'Radionuclides', for_contaminants: true, indices: ['Cs-137'] }],
		compartments: [{ name: 'A' }],
	};
	close(ed.addLookup(p, { name: 'Q' }).index_lists.length, 0, 0);
	close(ed.addCompartment(p, { name: 'B' }).index_lists.length, 1, 0);
});

section('completing an equation');

test('the chart\'s search box offers the names its outputs are made of', () => {
	// SimpleSilo reports 9,885 lines; nobody scrolls that. What there is to
	// find is the blocks and the indices the labels are built from, each once,
	// with how many lines it reaches -- a block before an index, the model's
	// own order within each, and the usual ranking of what was typed.
	const outs = [
		{ kind: 'compartment', block: 'Soil', label: 'Soil [Cs-137, Lake]', unit: 'Bq', dims: ['Radionuclides', 'Object'], index: ['Cs-137', 'Lake'] },
		{ kind: 'compartment', block: 'Soil', label: 'Soil [Cs-137, Mire]', unit: 'Bq', dims: ['Radionuclides', 'Object'], index: ['Cs-137', 'Mire'] },
		{ kind: 'compartment', block: 'Soil', label: 'Soil [I-129, Lake]', unit: 'Bq', dims: ['Radionuclides', 'Object'], index: ['I-129', 'Lake'] },
		{ kind: 'expression', block: 'Dose', label: 'Dose [Lake]', unit: 'Sv/year', dims: ['Object'], index: ['Lake'] },
		{ kind: 'parameter', block: 'k', label: 'k', unit: '1/year', dims: [], index: null },
	];
	const items = cmp.searchCandidates(outs);
	const names = items.map((i) => `${i.what}:${i.label}`);
	assert(names.join() === 'block:Soil,block:Dose,block:k,index:Cs-137,index:Lake,index:Mire,index:I-129',
		names.join());
	const soil = items.find((i) => i.label === 'Soil');
	assert(soil.count === 3 && soil.detail === '3 lines' && soil.kind === 'compartment'
		&& /compartment/.test(soil.say) && /Bq/.test(soil.say), JSON.stringify(soil));
	const lake = items.find((i) => i.label === 'Lake');
	assert(lake.count === 3 && lake.list === 'Object' && lake.detail === 'Object', JSON.stringify(lake));
	// Ranked as everything else is: what the word starts beats what merely
	// contains it, and the whole box is the word.
	const ranked = cmp.rankCompletions('la', items, 10).items.map((i) => i.label);
	assert(ranked[0] === 'Lake', ranked.join());
	const ranked2 = cmp.rankCompletions('s', items, 10).items.map((i) => i.label);
	assert(ranked2[0] === 'Soil' && ranked2.includes('Cs-137') && ranked2.indexOf('Soil') < ranked2.indexOf('Cs-137'),
		ranked2.join());
	// Nothing at all for a block-less run; every name for an empty box -- in
	// the model's order, not shortest first.
	assert(cmp.searchCandidates([]).length === 0, 'candidates from nothing');
	const all = cmp.rankCompletions('', items, 100).items.map((i) => i.label);
	assert(all.join() === 'Soil,Dose,k,Cs-137,Lake,Mire,I-129', all.join());
	// A name in two lists is offered once, naming both; a name that is also a
	// block's is the block's row and nothing more.
	const twice = cmp.searchCandidates([
		{ kind: 'compartment', block: 'Lake', label: 'Lake [Cs-137]', dims: ['Contaminants'], index: ['Cs-137'] },
		{ kind: 'expression', block: 'Dose', label: 'Dose [Cs-137]', dims: ['Radionuclides'], index: ['Cs-137'] },
		{ kind: 'parameter', block: 'Area', label: 'Area [Lake]', dims: ['Compartments'], index: ['Lake'] },
	]);
	const cs = twice.filter((i) => i.label === 'Cs-137');
	assert(cs.length === 1 && cs[0].detail === 'Contaminants, Radionuclides' && cs[0].count === 2,
		JSON.stringify(cs));
	assert(twice.filter((i) => i.label === 'Lake').length === 1
		&& twice.find((i) => i.label === 'Lake').what === 'block', 'Lake offered as the block alone');
});

test('the word under the caret is the word that gets replaced', () => {
	const w = (text, caret) => {
		const at = cmp.wordAt(text, caret);
		return at ? `${at.kind}:${at.start},${at.end}:${at.word}` : 'none';
	};

	// The span runs both ways from the caret, so finishing a word you went
	// back into replaces the whole word rather than splitting it.
	assert(w('1 + Kd * 2', 6) === 'name:4,6:Kd');
	assert(w('1 + Kd * 2', 5) === 'name:4,6:K');
	assert(w('', 0) === 'name:0,0:');
	assert(w('1 + ', 4) === 'name:4,4:');

	// A dotted path is one word: `NearField.Wa` is a partly-typed reference
	// into a sub-system, not `Wa` after a full stop.
	assert(w('NearField.Wa', 12) === 'name:0,12:NearField.Wa');
	assert(w('a + NearField.', 14) === 'name:4,14:NearField.');

	// Numbers are not words. `2.5e3` looked like a dotted path to a scanner
	// that only knew the character class.
	assert(w('2.5e3', 3) === 'none');
	assert(w('1e-5 * A', 2) === 'none');
	assert(w('x2', 2) === 'name:0,2:x2');

	// Inside brackets it is an index name being typed, which is not an
	// identifier at all -- real models index by `F.18:00_51_FORSMARK` and
	// `_Ra-226` -- so the span runs to the bracket.
	assert(w('Soil[Cs-1', 9) === 'index:5,9:Cs-1');
	assert(w('Soil[Cs-137]', 9) === 'index:5,11:Cs-1');
	assert(cmp.wordAt('Soil[Cs-1', 9).owner === 'Soil');
	assert(cmp.wordAt('Soil[Cs-1', 9).slot === 0);
	// One bracket per dimension, so the second one is the second dimension.
	assert(cmp.wordAt('M[Cs-137][La', 12).slot === 1);
	assert(cmp.wordAt('M[Cs-137][La', 12).owner === 'M');
	assert(cmp.wordAt('M[][La', 6).slot === 1);
	assert(cmp.wordAt('Sub.M[La', 8).owner === 'Sub.M');
	// A bracket after nothing nameable is nothing to complete.
	assert(w('(a + b)[x', 9) === 'none');
});

test('what may be written is what would resolve to the block it names', () => {
	const m = {
		compartments: [
			{ name: 'Water' },
			{ name: 'Water', system: 'NearField' },
			{ name: 'Rock', system: 'NearField' },
		],
		parameters: [{ name: 'Volume', unit: 'm3' }],
		expressions: [], transfers: [],
	};
	const from = (system) => cmp.blockCandidates(m, { system })
		.map((c) => c.insert).sort().join(' ');

	// From the root: local names for the root's own blocks, full paths for
	// what is inside a sub-system.
	assert(from('') === 'NearField.Rock NearField.Water Volume Water', from(''));

	// From inside: its own two blocks by their local names, and the root's
	// `Volume` -- but *not* the root's `Water`. Ecolego writes both as
	// `Water`, and the nearer one wins when it is read back, so offering it
	// here would insert a reference to the wrong compartment.
	assert(from('NearField') === 'Rock Volume Water', from('NearField'));
	const water = cmp.blockCandidates(m, { system: 'NearField' })
		.find((c) => c.insert === 'Water');
	assert(water.name === 'NearField.Water', water.name);

	// A block never offers itself: an equation that names itself is a cycle,
	// and the editor already reports it as one.
	assert(!cmp.blockCandidates(m, { system: 'NearField', exclude: 'NearField.Rock' })
		.some((c) => c.insert === 'Rock'));
});

test('candidates are ranked by how well the word matches, blocks first', () => {
	const items = (word, list) => cmp.rankCompletions(word, list.map((match) => ({
		match, type: match === match.toLowerCase() && !match.includes('.')
			? 'function' : 'block',
	}))).items.map((c) => c.match).join(' ');

	// Same spelling beats different case beats the last part of a path beats
	// anywhere at all.
	assert(items('Wa', ['NearField.Water', 'Water', 'washout', 'Downwash'])
		=== 'Water NearField.Water washout Downwash');
	// The shorter of two equally good matches first, and -- because names in
	// this domain are capitalised and functions are not -- a lower-case word
	// finds the function before the block, without that being a rule about
	// functions.
	assert(items('mi', ['min', 'minimum', 'Mixing']) === 'min minimum Mixing');
	assert(items('Mi', ['min', 'minimum', 'Mixing']) === 'Mixing min minimum');
	// Nothing matches nothing.
	assert(items('zz', ['min', 'Water']) === '');
	// Asking with an empty word asks for everything.
	assert(cmp.rankCompletions('', [{ match: 'a', type: 'block' },
		{ match: 'b', type: 'block' }]).total === 2);
	// The cap is on what is returned, not on what was counted, so a caller can
	// say how much it is not showing.
	const many = Array.from({ length: 50 }, (_, i) => ({ match: `A${i}`, type: 'block' }));
	const cut = cmp.rankCompletions('A', many, 10);
	assert(cut.items.length === 10 && cut.total === 50);
});

test('taking a completion writes the text and leaves the caret where the next thing goes', () => {
	const m = {
		compartments: [{ name: 'Soil', index_lists: ['Radionuclides'] }],
		parameters: [{ name: 'Kd', unit: 'm3/kg' }],
		lookups: [
			{ name: 'Flow', points: [[0, 1]] },
			{ name: 'Curve', points: [[0, 1]], argument: 'X' },
		],
		expressions: [], transfers: [],
		index_lists: [{ name: 'Radionuclides', indices: [{ name: 'I-129' }, { name: 'Tc-99' }] }],
	};
	const take = (text, caret, pick) => {
		const r = cmp.completionsAt(m, { text, caret });
		const item = r.items.find((i) => i.insert.startsWith(pick)) ?? r.items[0];
		const done = cmp.applyCompletion(text, r, item);
		return `${done.text.slice(0, done.caret)}|${done.text.slice(done.caret)}`;
	};

	// A block is finished and the caret follows it.
	assert(take('2 * K', 5, 'Kd') === '2 * Kd|');
	// A function arrives with its parentheses and the caret between them,
	// because the next thing to type is always an argument.
	assert(take('sq', 2, 'sqrt') === 'sqrt(|)');
	// Unless there is already a bracket there to use.
	assert(take('sq(Kd)', 2, 'sqrt') === 'sqrt|(Kd)');
	// A function that takes nothing is written bare, as the parser accepts it.
	assert(take('ti', 2, 'time') === 'time|');

	// An index closes its own bracket, and does not double one that is there.
	assert(take('Soil[I', 6, 'I-129') === 'Soil[I-129]|');
	assert(take('Soil[I]', 6, 'I-129') === 'Soil[I-129|]');

	// A lookup table read at an argument has no value of its own -- it is
	// called, not referred to -- so it is offered as the call it has to be.
	assert(take('Cur', 3, 'Curve') === 'Curve(|)');
	assert(take('Flo', 3, 'Flow') === 'Flow|');
});

test('the list offers the indices of the block whose bracket it is in', () => {
	const m = {
		compartments: [{ name: 'M', index_lists: ['Radionuclides', 'Object'] }],
		parameters: [{ name: 'plain' }],
		expressions: [], transfers: [],
		index_lists: [
			{ name: 'Radionuclides', indices: [{ name: 'I-129' }, { name: 'Tc-99' }] },
			{ name: 'Object', indices: [{ name: 'Lake' }, { name: 'Mire', enabled: false }] },
		],
	};
	const at = (text) => {
		const r = cmp.completionsAt(m, { text, caret: text.length });
		return r ? r.items.map((c) => c.insert).join(' ') : 'none';
	};

	// Every dimension's indices, not only the one this bracket sits in:
	// Ecolego resolves a bracket by name and not by position, and two
	// two-bracket references in five in the real files here are written in the
	// order the other dimension would suggest. The bracket's own dimension
	// comes first because that is the order Ecolego writes them in, and each
	// index keeps the order its list declares -- `Lake` does not climb above
	// `I-129` for being shorter.
	assert(at('M[') === 'I-129] Tc-99] Lake]', at('M['));
	assert(at('M[I-129][') === 'Lake] I-129] Tc-99]', at('M[I-129]['));
	// A disabled index is not a value the block holds, so it is not offered.
	assert(!at('M[').includes('Mire'));
	// Past the last dimension, and on a block that has none, there is nothing
	// to say -- which is different from saying nothing useful.
	assert(at('M[I-129][Lake][') === 'none');
	assert(at('plain[') === 'none');
	assert(at('nosuch[') === 'none');
	// Which list an index came from travels with it, since with every
	// dimension on offer the name alone no longer says.
	const lists = cmp.completionsAt(m, { text: 'M[', caret: 2 })
		.items.map((c) => `${c.insert}:${c.list}`).join(' ');
	assert(lists === 'I-129]:Radionuclides Tc-99]:Radionuclides Lake]:Object', lists);
});

test('completion follows the sub-system the equation is written in', () => {
	const m = {
		compartments: [{ name: 'Water', system: 'NearField' }],
		parameters: [
			{ name: 'Kd', system: 'NearField', unit: 'm3/kg' },
			{ name: 'Kd', unit: 'm3/kg' },
			{ name: 'rho' },
		],
		expressions: [], transfers: [],
	};
	const inside = cmp.completionsAt(m, {
		text: 'K', caret: 1, system: 'NearField', owner: 'NearField.Water',
	});
	// The one it means from in there is its own, written short.
	const kd = inside.items.filter((c) => c.type === 'block');
	assert(kd.length === 1 && kd[0].insert === 'Kd' && kd[0].name === 'NearField.Kd',
		JSON.stringify(kd.map((c) => [c.insert, c.name])));

	// From the root the same word means the root's, and the sub-system's is
	// reachable by its path.
	const outside = cmp.completionsAt(m, { text: 'K', caret: 1 });
	assert(outside.items.filter((c) => c.type === 'block')
		.map((c) => c.insert).sort().join(' ') === 'Kd NearField.Kd');

	// Whatever is inserted resolves back to the block that was shown. This is
	// the property the whole thing rests on, so it is checked over every
	// candidate rather than over the two above.
	const known = new Set(['NearField.Water', 'NearField.Kd', 'Kd', 'rho']);
	for (const system of ['', 'NearField']) {
		for (const c of cmp.blockCandidates(m, { system })) {
			assert(sys.resolveReference(c.insert, system, (n) => known.has(n)) === c.name,
				`${c.insert} from '${system}' is not ${c.name}`);
		}
	}
});

test('every function the parser accepts can be completed, with its signature', () => {
	const names = cmp.functionCandidates().map((c) => c.insert);
	// Every name the parser will accept, the aliases included: an .eco file
	// that says `ln` should find `ln`.
	for (const n of [...Object.keys(FUNCTIONS), 'ln', 'pow', 'fabs', 'sgn', 'product']) {
		assert(names.includes(n), `${n} is not offered`);
	}
	assert(new Set(names).size === names.length, 'no name is offered twice');

	// The signature is read off the arity the parser checks against, so it
	// cannot drift from what the function actually takes.
	const sig = (n) => cmp.functionCandidates().find((c) => c.insert === n).label;
	assert(sig('power') === 'power(a, b)');
	assert(sig('min') === 'min(a, …)');
	assert(sig('if') === 'if(logical_test, value_if_true[, value_if_false])');
	assert(sig('pi') === 'pi', sig('pi'));
	assert(sig('ln') === 'ln(a)', sig('ln'));
	assert(sig('interpolationUseEndValues') === 'interpolationUseEndValues(xi, x, y, …)');

	// And every one of them says what it is for.
	for (const c of cmp.functionCandidates()) {
		assert(c.help.summary && c.help.summary.length > 3, `${c.insert} has no summary`);
		assert(FUNCTION_CATEGORIES.includes(c.help.category), `${c.insert}: ${c.help.category}`);
	}

	// An alias says which function it is, rather than silently offering it.
	assert(cmp.functionCandidates().find((c) => c.insert === 'ln').help.alias === 'log');
	assert(cmp.functionCandidates().find((c) => c.insert === 'log').help.alias === null);
});

test('a field that holds block names rather than an expression is not offered functions', () => {
	const m = {
		compartments: [{ name: 'Soil' }], parameters: [], expressions: [], transfers: [],
	};
	const with_ = cmp.completionsAt(m, { text: 's', caret: 1 });
	const without = cmp.completionsAt(m, { text: 's', caret: 1, functions: false });
	assert(with_.items.some((c) => c.type === 'function'));
	assert(without.items.every((c) => c.type === 'block'));
	assert(without.items.length === 1);
});

test('a lookup table called at an argument is a usable equation, not an unknown function', () => {
	// The builder tells the parser which names are callable
	// (sim/builder.js `callTarget`); the editor has to agree, or every model
	// that drives something from a table shows a red field while running.
	const m = {
		lookups: [{ name: 'Q_gw', points: [[0, 1], [10, 2]], argument: 'X' }],
		compartments: [{ name: 'Lake' }],
		parameters: [], expressions: [], transfers: [],
	};
	assert(validateEquation(m, 'Q_gw(time)', 'Lake') === null,
		validateEquation(m, 'Q_gw(time)', 'Lake'));
	assert(validateEquation(m, 'Q_gw(2)', 'Lake') === null);
	// Something that is not a table still is not callable.
	assert(/Unknown function/.test(validateEquation(m, 'Lake(1)', 'Q_gw') ?? ''));
	// And inside a sub-system it is found the way any other name is.
	const n = {
		lookups: [{ name: 'Q', system: 'Sub', points: [[0, 1]], argument: 'X' }],
		compartments: [{ name: 'C', system: 'Sub' }],
		parameters: [], expressions: [], transfers: [],
	};
	assert(validateEquation(n, 'Q(2)', 'Sub.C') === null, validateEquation(n, 'Q(2)', 'Sub.C'));
	assert(validateEquation(n, 'Sub.Q(2)', 'C') === null);
});

section('XML parsing');

test('elements, attributes, text and nesting', () => {
	const root = parseXML('<a x="1" y=\'two\'><b>hi</b><b>there</b></a>');
	assert(root.name === 'a');
	assert(root.attrs.x === '1' && root.attrs.y === 'two');
	close(children(root, 'b').length, 2, 0);
	assert(childText(root, 'b') === 'hi');
});

test('CDATA is taken verbatim', () => {
	const root = parseXML('<a><eq><![CDATA[x < 1 && y > 2 & z]]></eq></a>');
	assert(childText(root, 'eq') === 'x < 1 && y > 2 & z', childText(root, 'eq'));
});

test('entities are decoded outside CDATA', () => {
	const root = parseXML('<a><t>&lt;tag&gt; &amp; &quot;q&quot; &#65;&#x42;</t></a>');
	assert(childText(root, 't') === '<tag> & "q" AB', childText(root, 't'));
});

test('self-closing tags, comments and the XML declaration', () => {
	const root = parseXML(
		'<?xml version="1.0"?><!-- note --><a><b/><c k="v"/></a>',
	);
	assert(root.name === 'a');
	close(root.children.length, 2, 0);
	assert(child(root, 'c').attrs.k === 'v');
});

test('malformed XML is rejected with a position', () => {
	let caught = null;
	try { parseXML('<a><b></a>'); } catch (e) { caught = e; }
	assert(caught instanceof XMLError, 'expected an XMLError');
	assert(/does not match/.test(caught.message), caught.message);

	caught = null;
	try { parseXML('<a><b>'); } catch (e) { caught = e; }
	assert(caught && /Unclosed/.test(caught.message), caught?.message);
});

