section('ZIP reading');

await (async () => {
	const zipStored = await makeZip([
		{ name: 'p/model/model.xml', text: '<data-model/>' },
		{ name: 'p/views.xml', text: VIEWS_XML },
	]);
	const zipDeflated = await makeZip([
		{ name: 'p/model/model.xml', text: MODEL_XML, deflate: true },
	]);

	test('stored entries round-trip', async () => {
		const entries = await unzip(zipStored);
		assert(entries.has('p/model/model.xml'), [...entries.keys()].join(','));
		assert(entryText(entries.get('p/views.xml')) === VIEWS_XML);
	});

	test('deflated entries round-trip', async () => {
		const entries = await unzip(zipDeflated);
		assert(entryText(entries.get('p/model/model.xml')) === MODEL_XML,
			'inflated text matches');
	});

	test('a non-ZIP is refused with an explanation', async () => {
		let caught = null;
		try { await unzip(new TextEncoder().encode('not a zip at all')); }
		catch (e) { caught = e; }
		assert(caught instanceof ZipError, 'expected a ZipError');
		assert(/does not look like a ZIP/.test(caught.message), caught?.message);
	});
})();

