test('a transfer with one open end keeps it open', () => {
	const t = imported.project.transfers.find((x) => x.name === 'Outflow');
	assert(t.from === 'Deep_soil' && t.to == null, `${t.from} -> ${t.to}`);
});

test('unsupported block types are skipped and reported, not dropped silently', () => {
	// `transport-begin` is one of the ~20 block types this tool still has no
	// equivalent for. It used to be `delay`, which is now imported.
	const skipped = imported.report.skipped.find((s) => s.type === 'transport-begin');
	assert(skipped, JSON.stringify(imported.report.skipped));
	assert(skipped.name === 'Depth');
	assert(!imported.report.ok, 'the report knows it is incomplete');
});

test('invalid names are rewritten and equations follow', () => {
	const renamed = new Map(imported.report.renamed.map((r) => [r.from, r.to]));
	assert(renamed.get('Deep soil') === 'Deep_soil', JSON.stringify([...renamed]));
	assert(renamed.get('k leach') === 'k_leach');
	const total = imported.project.expressions.find((e) => e.name === 'Total');
	assert(total.equation.includes('Deep_soil'), total.equation);
	assert(!total.equation.includes('Deep soil'), total.equation);
});

test('an imported project validates and runs', () => {
	const p = new Project(imported.project);
	// 2 nuclides x 2 enabled objects, twice over.
	close(p.indexSpace.width(p.compartments[0].index_lists), 4, 0);
	const r = run(imported.project);
	assert(r.t.length > 2, 'produced results');
	// Mass leaves Soil for Deep_soil, so Soil can only fall.
	const soilCsLake = r.outputs().find(
		(o) => o.block === 'Soil' && o.index[0] === 'Cs-137' && o.index[1] === 'Lake');
	const v = r.series(soilCsLake);
	assert(v[0] > v[v.length - 1], 'Soil drains');
	close(v[0], 1e10, 1e-9, 'initial inventory');
});

