const shapes = importModelXML(REAL_SHAPES_XML);

test('index ids are scoped to their list, not global', () => {
	// Both Elements and Species have an index with id "Nb"; the parameter is
	// indexed by Elements, so its entry must resolve to Elements/Nb.
	const k = shapes.project.parameters.find((p) => p.name === 'k');
	assert(k.index_lists.join(',') === 'Elements', k.index_lists.join(','));
	close(k.entries.length, 1, 0);
	assert(k.entries[0].index.Elements === 'Nb',
		JSON.stringify(k.entries[0].index));
	assert(!('Species' in k.entries[0].index), 'not resolved against the wrong list');
});

test('source and sink components become open transfer ends', () => {
	const feed = shapes.project.transfers.find((t) => t.name === 'Feed');
	const leak = shapes.project.transfers.find((t) => t.name === 'Leak');
	assert(feed.from == null, `Feed.from = ${feed.from}`);
	// Endpoints are qualified: this Water is the one in the NF sub-system.
	assert(feed.to === 'NF.Water', feed.to);
	assert(leak.to == null, `Leak.to = ${leak.to}`);
	// They are represented, not lost, so they must not be reported as skipped.
	assert(!shapes.report.skipped.some((s) => s.type === 'inflow' || s.type === 'sink'),
		JSON.stringify(shapes.report.skipped));
});

test('transfer and transfer-coefficient have opposite donor defaults', () => {
	// From BlockXMLHandler: `transfer` is created with multiplyWithDonor
	// false (an absolute flux), `transfer-coefficient` with true.
	const move = shapes.project.transfers.find((t) => t.name === 'Move');
	const leak = shapes.project.transfers.find((t) => t.name === 'Leak');
	assert(move.multiply_by_donor === true, 'transfer-coefficient multiplies by donor');
	assert(leak.multiply_by_donor === false, 'plain transfer is an absolute flux');
	// And a transfer with no donor can never multiply by one.
	const feed = shapes.project.transfers.find((t) => t.name === 'Feed');
	assert(feed.multiply_by_donor === false, 'no donor to multiply by');
});

test('blocks sharing a name in different sub-systems keep it', () => {
	// Ecolego scopes names by sub-system and so does this tool now: the two
	// Waters are different compartments and both stay `Water`. The importer
	// used to number the second one and warn that equations referring to it
	// could not be disambiguated.
	const waters = shapes.project.compartments.filter((c) => c.name === 'Water');
	close(waters.length, 2, 0, 'both kept the name');
	assert(waters[0].system === 'NF' && waters[1].system === 'FF',
		waters.map((w) => w.system).join(','));
	assert(JSON.stringify(shapes.project.systems) === '["NF","FF"]',
		JSON.stringify(shapes.project.systems));
	assert(!shapes.report.warnings.some((w) => /more than one block|spelled differently/.test(w)),
		`nothing to warn about: ${shapes.report.warnings.join(' | ')}`);
});

test('influence connections are noted as inert, not counted as losses', () => {
	assert(shapes.report.notes.some((n) => n.type === 'influence'),
		JSON.stringify(shapes.report.notes));
	assert(!shapes.report.skipped.some((n) => n.type === 'influence'));
});

test('a model with these shapes builds and runs', () => {
	const r = run(shapes.project);
	// Both compartments are called Water; the sub-system is what tells them
	// apart, so results are addressed by the qualified name.
	const [nfName, ffName] = shapes.project.compartments
		.map((c) => (c.system ? `${c.system}.${c.name}` : c.name));
	assert(nfName === 'NF.Water' && ffName === 'FF.Water', `${nfName}, ${ffName}`);
	const nf = r.outputs().filter((o) => o.block === nfName);
	close(nf.length, 2, 0, 'one cell per element');

	// The far-field box starts at 1000 and loses an absolute 3/yr through the
	// plain transfer, while gaining k*NF from the coefficient transfer.
	const ffH = r.series(r.outputs().find(
		(o) => o.block === ffName && o.index[0] === 'H'));
	assert(ffH[0] === 1000, `starts at ${ffH[0]}`);
	assert(ffH[ffH.length - 1] < 1000, 'net loss over ten years');
	assert(ffH[ffH.length - 1] > 950, `but only a little: ${ffH[ffH.length - 1]}`);
});

