test('a function is drawn on the canvas, and can be made there', async () => {
	// It is a node like any other algebraic block: a shape, a size, a place in
	// the layout. What it has not got is a port -- nothing flows through one.
	assert(ed.NODE_KINDS.includes('function'), 'a function is not a node kind');
	assert(ed.defaultShapeFor('function') === 'rounded', ed.defaultShapeFor('function'));
	assert(ed.DEFAULT_SIZE.function.w > ed.DEFAULT_SIZE.expression.w,
		'a signature needs more room than an equation');
	assert(ed.view({}).show_functions === true, 'functions are hidden by default');
	assert(ed.view({ view: { show_functions: false } }).show_functions === false,
		'the toggle does not stick');

	const { readFileSync } = await import('node:fs');
	const graph = readFileSync(new URL('../src/ui/graph.js', import.meta.url), 'utf8');
	assert(/if \(v\.show_functions\) for \(const f of p\.functions \?\? \[\]\) push\(f, 'function'\)/.test(graph),
		'the diagram does not draw them');
	assert(/toggle\('show_functions', 'functions'\)/.test(graph), 'Show has no entry for them');
	assert(/const HAS_PORT = new Set\(\['compartment', 'farfield', 'waste_package'\]\)/.test(graph),
		'a function grew a connect handle');
	// Made from the canvas menu, where every other block that is not a
	// compartment is made.
	assert(/label: 'Function',[\s\S]{0,200}onPick: \(\) => this\._addNodeAt\('function', at\)/.test(graph),
		'the canvas menu cannot make one');
	assert(/function: \(\) => ed\.addFunction\(this\.project, \{ system \}\)/.test(graph),
		'the menu entry is not wired to the editor');
	// Added while its kind is switched off in Show, it is nowhere to be seen.
	// That is said, with the switch named: a click that appears to do nothing
	// reads as a click that did not take.
	// Said when the block is *made*, not when it is selected: selecting a
	// parameter from the tree while reading the chart used to explain a
	// diagram nobody was looking at.
	assert(!/reveal && sel\?\.name && sel\.name !== was\) this\._?sayIfNotDrawn/.test(graph),
		'it is still said on every selection');
	assert(/this\.hooks\.onSelect\?\.\(\{ kind, name \}\);[\s\S]{0,400}this\.sayIfNotDrawn\(name\);/.test(graph),
		'adding a hidden kind says nothing');

	// And a new one lands where it was asked for, in the sub-system shown.
	const project = { systems: ['NF'], functions: [], expressions: [] };
	const made = ed.addFunction(project, { system: 'NF' });
	ed.setPosition(project, ed.qualifiedName(made), { x: 40, y: 60 });
	assert(made.system === 'NF' && made.name === 'Func', JSON.stringify(made));
	assert(project.layout['NF.Func'].x === 40, JSON.stringify(project.layout));
	// Its body is empty on purpose: a guess would be worse than the strip
	// asking for the real one.
	assert(made.equation === '', JSON.stringify(made));
	assert(ed.allEquationProblems(project).some((p) => /has no body yet/.test(p.message)),
		JSON.stringify(ed.allEquationProblems(project)));
});

test('the settings dialog and the Information view know what a function is', async () => {
	const { readFileSync } = await import('node:fs');
	const inspector = readFileSync(new URL('../src/ui/inspector.js', import.meta.url), 'utf8');
	const panel = /if \(kind === 'function'\) \{[\s\S]*?\n\t\}/.exec(inspector)?.[0] ?? '';
	assert(/ed\.setFunctionParameters\(/.test(panel), 'the parameters box does not go through the domain');
	assert(/locals: new Set\(params\(\)\)/.test(panel), 'the body is not checked in its own scope');
	assert(/complete: equationLook\(/.test(panel), 'the body has no completion of its own');
	// No Enabled switch and no dimensions: a function has no value to leave
	// out of a run, and the index it is worked out at is the caller's.
	assert(/if \(kind !== 'function'\) host\.append\(enabledRow\(\)\)/.test(inspector),
		'a function is offered an Enabled switch');
	assert(/if \(offered\.length && kind !== 'function' && kind !== 'event'\)/.test(inspector),
		'a function is offered index lists');
	const info = readFileSync(new URL('../src/ui/info.js', import.meta.url), 'utf8');
	assert(/'Called as'/.test(info), 'the Information view does not show the signature');
	assert(/function: \['equation', 'Body'\]/.test(info), 'the body is not the defining field');
	// ...and no "at the start" row: a function has no value at any instant,
	// only an answer for what it is called with.
	assert(/hooks\.atStart && kind !== 'function'/.test(info),
		'a function is given a start value');
});

test('a number can carry its unit: 0.01[m] is a length, and runs as 0.01', async () => {
	const { parse } = await import('../src/parser/parser.js');
	const { parseUnit, equationUnit } = await import('../src/domain/unitcheck.js');
	const year = parseUnit('year');
	const metres = () => parseUnit('m');

	// The parser: the unit rides on the number node and nowhere else.
	const ast = parse('0.01[m] * Depth');
	assert(ast.type === 'binary' && ast.left.type === 'num', JSON.stringify(ast));
	assert(ast.left.value === 0.01 && ast.left.unit === 'm', JSON.stringify(ast.left));
	assert(parse('3').unit === undefined, 'a bare number grew a unit');
	assert(parse('1e3[Bq/m3]').unit === 'Bq/m3', 'a compound unit did not survive the bracket');

	// The compiler reads the value and nothing else: the run is the bare number's.
	const code = emit(parse('0.01[m] * 2'), null, null);
	assert(!/m/.test(code), `the unit leaked into the code: ${code}`);
	assert(new Function(`return ${code};`)() === 0.02, code);

	// The checker: a bare number is absorbed, a literal with a unit is a quantity.
	const of = (text) => equationUnit(parse(text), metres, year);
	assert(String(of('0.01 * Depth').dim) === 'm', 'a bare number is not absorbed');
	assert(String(of('0.01[m] * Depth').dim) === 'm^2', `a length times a length: ${of('0.01[m] * Depth').dim}`);
	assert(String(of('Depth / 2[year]').dim) === 'm/year');
	assert(of('Depth + 0.5').clash === null, 'adding a plain number is fine');
	assert(/m and year/.test(of('Depth + 2[year]').clash ?? ''),
		`adding a time to a length is not reported: ${of('Depth + 2[year]').clash}`);
	// Unconverted -- `equationUnit` judges the tree it is given, and it is
	// `scaleLiterals` that converts one before it gets here.
	assert(of('Depth + 5[cm]').clash, 'adding centimetres to metres is not reported');
	// A unit the reader cannot make out is an unknown, and an unknown is silence.
	assert(of('3[((] * Depth').dim === null && of('3[((] * Depth').clash === null);
});

test('an SI prefix is a scale on the base unit, and the checker hands over the factor', async () => {
	const { parseUnit, sameUnit, scaleText } = await import('../src/domain/unitcheck.js');
	const near = (a, b) => Math.abs(a / b - 1) < 1e-9;

	const kBq = parseUnit('kBq/m^3');
	const Bq = parseUnit('Bq/m^3');
	assert(!kBq.equals(Bq), 'a kilobecquerel became a becquerel');
	assert(kBq.sameKind(Bq) && near(kBq.factor(Bq), 1000), `${kBq.factor(Bq)}`);
	assert(String(kBq) === '1000 Bq/m^3', String(kBq));
	// Prefixes ride through products, quotients and powers.
	assert(String(parseUnit('cm3')) === '1e-6 m^3', String(parseUnit('cm3')));
	assert(parseUnit('cm3').sameKind(parseUnit('m^3')));
	assert(String(parseUnit('mSv/year')) === '0.001 Sv/year');
	assert(sameUnit('mSv/year', 'mSv/y') && sameUnit('mL', 'ml') && sameUnit('µg', 'ug'));
	assert(!sameUnit('mSv', 'Sv') && !sameUnit('m', 'cm') && !sameUnit('kg', 'g'));
	assert(String(parseUnit('kBq/Bq')) === '×1000', String(parseUnit('kBq/Bq')));
	assert(String(parseUnit('MBq/kBq')) === '×1000');
	// The kilogram is the base of mass: messages keep saying kg.
	assert(String(parseUnit('kg')) === 'kg' && String(parseUnit('kilogram')) === 'kg');
	assert(String(parseUnit('g')) === '0.001 kg' && String(parseUnit('mg')) === '1e-6 kg');
	assert(near(parseUnit('kg').factor(parseUnit('g')), 1000));
	assert(String(parseUnit('kg/(m^2*year)')) === 'kg/(m^2*year)', 'the unit every file writes stopped printing as itself');
	// Symbols whose remainder is not a base are never split.
	for (const [text, as] of [['mol', 'mol'], ['min', 'min'], ['Gy', 'Gy'], ['Pa', 'Pa'],
		['ha', 'ha'], ['kgC', 'kgC'], ['Ma', 'Ma'], ['My', 'My'], ['kd', 'kd'], ['pH', 'pH']]) {
		assert(String(parseUnit(text)) === as, `${text} read as ${parseUnit(text)}`);
	}
	assert(String(parseUnit('ms')) === '0.001 s');
	assert(scaleText(1000) === '1000' && scaleText(0.01) === '0.01' && scaleText(1e-6) === '1e-6'
		&& scaleText(1e12) === '1e+12', 'the scale is not written the way a reader would');

	// The warning: the same quantity a prefix apart says so, with the factor.
	const p = {
		simulation: { time_unit: 'year' },
		compartments: [{ name: 'Lake', initial: '0', unit: 'Bq' }],
		parameters: [{ name: 'Volume', value: 2e6, unit: 'm3' }, { name: 'Depth', value: 2, unit: 'm' }],
		expressions: [], transfers: [], inflows: [],
	};
	const say = (block) => ed.unitProblems(p, block, 'expression').map((w) => w.detail).join(' | ');
	assert(say({ name: 'C', equation: 'Lake / Volume', unit: 'kBq/m^3' })
		=== 'works out as Bq/m^3, but this block says 1000 Bq/m^3 — the same quantity, '
		+ '1000 times smaller; nothing here converts, so the factor is yours to write in',
		say({ name: 'C', equation: 'Lake / Volume', unit: 'kBq/m^3' }));
	assert(say({ name: 'D', equation: 'Depth * 100', unit: 'cm' })
		=== 'works out as m, but this block says 0.01 m — the same quantity, 100 times larger; '
		+ 'nothing here converts, so the factor is yours to write in',
		say({ name: 'D', equation: 'Depth * 100', unit: 'cm' }));
	// A different quantity altogether gets no factor.
	assert(say({ name: 'X', equation: 'Lake / Volume', unit: 'Sv' })
		=== 'works out as Bq/m^3, but this block says Sv');
	// A literal written directly against something whose unit is known is
	// converted to that unit, so there is nothing left to report.
	assert(say({ name: 'A', equation: 'Depth + 1000[mm]', unit: 'm' }) === '',
		say({ name: 'A', equation: 'Depth + 1000[mm]', unit: 'm' }));
	assert(say({ name: 'B', equation: '1000[mm] + Depth', unit: 'm' }) === '');
	assert(say({ name: 'C2', equation: 'Lake / Volume + 5[kBq/m3]', unit: 'Bq/m^3' }) === '');
	assert(say({ name: 'D2', equation: 'if(Depth > 500[mm], Depth, 0)', unit: 'm' }) === '');
	// A different quantity is still a clash, and is offered no factor.
	assert(say({ name: 'E2', equation: 'Depth + 2[year]', unit: 'm' }) === 'm and year cannot be added');
	// A literal with no target -- buried in a product, where there is no one
	// unit to scale it to -- is not converted, and the clash says the factor.
	assert(say({ name: 'F2', equation: 'Depth + (2 * 1000[mm])', unit: 'm' })
		=== 'm and 0.001 m cannot be added — the same quantity, a factor of 1000 apart; '
		+ 'only a literal written directly against the other side is converted, so the '
		+ 'factor is yours to write in here',
		say({ name: 'F2', equation: 'Depth + (2 * 1000[mm])', unit: 'm' }));
	// ...and one written against a block with no unit at all is reported, since
	// the same equation would convert the moment a unit was typed on that block.
	assert(say({ name: 'G2', equation: 'plain + 1000[mm]', unit: 'm' })
		=== '1000[mm] is not converted: nothing it is written against says what unit it is in',
		say({ name: 'G2', equation: 'plain + 1000[mm]', unit: 'm' }));
	// And a right answer in a prefixed unit is a right answer.
	assert(say({ name: 'Z', equation: 'Depth * 100[cm/m]', unit: 'cm' }) === '',
		say({ name: 'Z', equation: 'Depth * 100[cm/m]', unit: 'cm' }));
});

test('a version report says what changed between two models, block by block', async () => {
	const V = await import('../src/domain/versions.js');
	const before = {
		name: 'Well', description: 'January',
		simulation: { time_unit: 'year', end_time: 1000, solver: 'ndf' },
		nuclides: [{ name: 'Cs-137', half_life: 30.17 }, { name: 'Sr-90', half_life: 28.8 }],
		index_lists: [{ name: 'RN', for_contaminants: true, indices: [{ name: 'Cs-137' }, { name: 'Sr-90' }] }],
		compartments: [
			{ name: 'Soil', initial: '0', unit: 'Bq', x: 10, y: 10 },
			{ name: 'Well', initial: '0', unit: 'Bq', x: 30, y: 10 },
		],
		parameters: [
			{ name: 'k_old', value: 0.1, unit: '1/year' },
			{ name: 'Kd', value: 1, entries: [{ index: 'Cs-137', value: 100 }, { index: 'Sr-90', value: 10 }] },
			{ name: 'Depth', value: 2, unit: 'm', comment: 'measured' },
		],
		transfers: [{ name: 'Leach', from: 'Soil', to: 'Well', rate: 'k_old' }],
		expressions: [], inflows: [], lookups: [],
	};
	const after = JSON.parse(JSON.stringify(before));
	after.name = 'Well, revised';
	after.simulation.end_time = 10000;
	after.simulation.non_negative = true;
	after.nuclides.push({ name: 'Ra-226', half_life: 1600 });
	after.nuclides[0].half_life = 30.05;
	after.index_lists[0].indices.push({ name: 'Ra-226' });
	after.compartments[0].x = 200;                         // moved on the canvas: not a change
	// Not `Well` under a new name: a block gone under one name and back under
	// another with nothing else different is reported as renamed, so Lake
	// starts with something in it.
	after.compartments.push({ name: 'Lake', initial: '5', unit: 'Bq' });
	after.compartments = after.compartments.filter((c) => c.name !== 'Well');
	after.parameters[0].name = 'k';                        // renamed, otherwise the same
	after.parameters[1].entries[0].value = 200;            // one entry changed
	after.parameters[1].entries.push({ index: 'Ra-226', value: 500 });
	after.parameters[2].comment = 'assumed';               // a comment is a change
	after.transfers[0].rate = 'k';
	after.transfers[0].description = 'leaching';

	const diff = V.compareModels(before, after);
	assert(!diff.same);
	assert(diff.name.before === 'Well' && diff.name.after === 'Well, revised');
	assert(diff.description === null, 'the description did not change');
	const names = (xs) => xs.map((x) => `${x.kind}:${x.name}`).sort().join(' ');
	assert(names(diff.blocks.added) === 'compartments:Lake', names(diff.blocks.added));
	assert(names(diff.blocks.removed) === 'compartments:Well', names(diff.blocks.removed));
	assert(diff.blocks.renamed.length === 1 && diff.blocks.renamed[0].from === 'k_old'
		&& diff.blocks.renamed[0].to === 'k', JSON.stringify(diff.blocks.renamed));
	// Soil only moved on the canvas, so it is not among the changed.
	assert(names(diff.blocks.changed) === 'parameters:Depth parameters:Kd transfers:Leach', names(diff.blocks.changed));
	const kd = diff.blocks.changed.find((c) => c.name === 'Kd');
	assert(kd.fields.map((f) => f.field).join(' ') === 'entries[Cs-137].value entries[Ra-226]',
		kd.fields.map((f) => f.field).join(' '));
	assert(kd.fields[0].before === 100 && kd.fields[0].after === 200);
	const leach = diff.blocks.changed.find((c) => c.name === 'Leach');
	assert(leach.fields.map((f) => `${f.field}:${f.before}>${f.after}`).join(' ')
		=== 'description:undefined>leaching rate:k_old>k');
	assert(diff.blocks.counted.before === 6 && diff.blocks.counted.after === 6, JSON.stringify(diff.blocks.counted));
	// Lists and nuclides.
	assert(diff.lists.length === 1 && diff.lists[0].added.join() === 'Ra-226' && !diff.lists[0].removed.length);
	assert(diff.nuclides.added.join() === 'Ra-226' && diff.nuclides.changed[0].name === 'Cs-137');
	assert(diff.nuclides.changed[0].fields[0].field === 'half_life');
	// Settings.
	assert(diff.settings.map((f) => f.field).join(' ') === 'end_time non_negative', JSON.stringify(diff.settings));

	// The text.
	const lines = V.reportLines(diff, { before: 'well-jan.json', after: 'well-mar.json' });
	const text = lines.join('\n');
	assert(lines[0] === 'Version report: well-mar.json against well-jan.json');
	assert(/^Blocks: 6 before, 6 after — 1 added, 1 removed, 3 changed, 1 renamed, 3 in the lists and nuclides, 2 settings, the name or description$/m.test(text), lines[1]);
	assert(/^\+ compartment Lake$/m.test(text) && /^- compartment Well$/m.test(text));
	assert(/^↔ parameter k_old → k \(renamed\)$/m.test(text));
	assert(/^~ parameter Kd\n    entries\[Cs-137\]\.value: 100 → 200\n    entries\[Ra-226\]: \(absent\) → \{"index":"Ra-226","value":500\}$/m.test(text), text);
	assert(/^~ parameter Depth\n    comment: measured → assumed$/m.test(text));
	assert(/^Index lists\n~ RN: \+ Ra-226$/m.test(text));
	assert(/^Nuclides\n\+ Ra-226\n~ Cs-137\n    half_life: 30.17 → 30.05$/m.test(text));
	assert(/^Simulation settings\nend_time: 1000 → 10000\nnon_negative: \(absent\) → true$/m.test(text));
	assert(/^Name: Well → Well, revised$/m.test(text));
	assert(V.summary(diff).startsWith('1 added, 1 removed, 3 changed, 1 renamed'));

	// Nothing changed: one line saying so, and `same`.
	const none = V.compareModels(before, JSON.parse(JSON.stringify(before)));
	assert(none.same && V.summary(none) === 'no differences');
	assert(V.reportLines(none).join('\n') === 'Version report: this model against the earlier version\n\nNo differences.');
	// Key order and layout are not differences.
	const shuffled = { ...before, compartments: before.compartments.map((c) => ({ y: 99, unit: c.unit, initial: c.initial, name: c.name })) };
	assert(V.compareModels(before, shuffled).same, 'key order or layout counted as a change');
	// Long values are cut short in the text, not in the data.
	assert(V.shown('x'.repeat(200)).length === 200, 'a string is shown whole');
	assert(V.shown({ a: 'x'.repeat(200) }).length === 72 && V.shown({ a: 'x'.repeat(200) }).endsWith('…'));
});

test('the sidebar offers a version report against the file as opened or another file', async () => {
	const { readFileSync } = await import('node:fs');
	const app = readFileSync(new URL('../src/ui/app.js', import.meta.url), 'utf8');
	// The model as opened is kept as one string beside the undo stack, and it
	// is taken after the tidying that opening does, so that tidying is not a
	// difference.
	assert(/undoStack\.reset\(state\.raw, viewNow\(\)\);\n(?:\s*\/\/.*\n)*\s*state\.opened = \{\n\s*text: JSON\.stringify\(state\.raw\),\n\s*label: modelSource\?\.example \? `the example \$\{modelSource\.example\}` : \(modelSource\?\.label \?\? UNTITLED\),/.test(app),
		'the model as opened is not remembered at setModel');
	assert(/className: 'ghost sb-action sb-compare'/.test(app), 'no Compare with button');
	assert(/label: 'The model as it was opened'/.test(app) && /label: 'Another file(?:…|\\u2026)'/.test(app));
	assert(/function openVersionReport\(/.test(app));
	// The other file is read the way Open reads one, so .eco and .eas compare too.
	const fn = /function compareWithFile\(\) \{[\s\S]*?\n\}/.exec(app)?.[0] ?? '';
	assert(/pickFile\(/.test(fn) && /readModelFile\(/.test(fn), 'the other file is not read through readModelFile');
	assert(/compareModels\(/.test(fn));
	// The report is a modal with Copy and Save, like the run log.
	const rep = /function openVersionReport\([\s\S]*?\n\}/.exec(app)?.[0] ?? '';
	assert(/reportLines\(/.test(rep) && /'Copy'/.test(rep) && /'Save as text(?:…|\\u2026)'/.test(rep), rep.slice(0, 300));
});

test('the mass-balance audit closes on what the equations moved, and opens on a hold', async () => {
	const { audit, describeAudit, TERMS, budgetIndex, closedBelow } = await import('../src/domain/massbalance.js');
	const { buildJacobian } = await import('../src/sim/jacobian.js');
	const { integrationFingerprint } = await import('../src/domain/fingerprint.js');
	const sim = (solver, on = true) => ({
		time_unit: 'year', start_time: 0, end_time: 200, output_points: 40, spacing: 'linear',
		solver, rtol: 1e-6, abstol: 1e-9, mass_balance: on,
	});
	// Decay down Sr-90 → Y-90, a source, an outflow to outside, an explicit
	// dy/dt term, and a transfer between per-nuclide compartments.
	const model = (solver, on = true) => ({
		name: 'audit', simulation: sim(solver, on),
		nuclides: ['Sr-90', 'Y-90', 'Cs-137'],
		index_lists: [{ name: 'RN', for_contaminants: true, indices: [{ name: 'Sr-90' }, { name: 'Y-90' }, { name: 'Cs-137' }] }],
		compartments: [
			{ name: 'Soil', index_lists: ['RN'], initial: '0', entries: [{ index: 'Sr-90', initial: '1000' }, { index: 'Cs-137', initial: '500' }] },
			{ name: 'Water', index_lists: ['RN'], initial: '0', dydt: '2' },
			{ name: 'Sink', index_lists: ['RN'], initial: '0' },
		],
		parameters: [{ name: 'k', value: 0.05 }, { name: 'q', value: 10 }],
		transfers: [
			{ name: 'Leach', from: 'Soil', to: 'Water', rate: 'k' },
			{ name: 'Out', from: 'Water', to: null, rate: 'k / 2' },
			{ name: 'Collect', from: 'Water', to: 'Sink', rate: '0.01' },
		],
		inflows: [{ name: 'Rain', to: 'Soil', rate: 'q', index_lists: ['RN'] }],
		expressions: [], lookups: [],
	});

	// The layout: six budgets per family, one family per nuclide plus one, last
	// in the vector, hidden, and not a name anything can read.
	const r = run(model('dp45'));
	const L = r.system.layout;
	assert(L.budget && L.budget.nfam === 4 && L.budget.families.join() === 'Sr-90,Y-90,Cs-137,not by nuclide', JSON.stringify(L.budget?.families));
	assert(L.budget.base === 9 && L.nstate === 9 + TERMS.length * 4, `${L.budget.base} ${L.nstate}`);
	const b = L.states.find((s) => s.kind === 'budget');
	assert(b && b.hidden && b.base === 9 && b.width === 24 && b.block === null);
	assert(L.budget.members.map((m) => m.name).join() === 'Soil,Water,Sink');
	assert(Array.from(L.budget.members[0].famOf).join() === '0,1,2', 'the family of each offset is the nuclide');
	assert(budgetIndex(L.budget, 'decay', 2) === 9 + 2 * 4 + 2);
	// The audit closes to round-off under an explicit solver...
	const a = r.massBalance();
	assert(a.closed && a.worst < 1e-12, `dormandPrince closes to ${a.worst}`);
	// ...and every family's line adds up to what it holds.
	for (const f of a.families.slice(0, 3)) {
		const x = f.final;
		assert(Math.abs(x.inventory - (x.start + x.in - x.out - x.decay + x.ingrowth + x.explicit + x.between)) < 1e-9 * f.scale, f.name);
		assert(x.in > 0 && x.out > 0 && x.explicit > 0, `${f.name}: ${JSON.stringify(x)}`);
	}
	const sr = a.families[0].final;
	const y90 = a.families[1].final;
	assert(sr.decay > 2000 && sr.ingrowth === 0, 'Sr-90 decays and grows in from nothing');
	assert(y90.ingrowth > 1e6 && Math.abs(y90.ingrowth - y90.decay) < 0.01 * y90.decay, 'Y-90 is in secular equilibrium');
	assert(a.families[3].idle, 'no compartment is outside the nuclide dimension here');
	// Every term the equations moved is accounted for at every time, not only at the end.
	for (let i = 0; i < r.t.length; i++) {
		let inv = 0;
		for (const m of L.budget.members) for (let off = 0; off < m.width; off++) if (m.famOf[off] === 0) inv += r.y[i][m.base + off];
		const term = (name) => r.y[i][budgetIndex(L.budget, name, 0)];
		const expected = sr.start + term('in') - term('out') - term('decay') + term('ingrowth') + term('explicit') + term('between');
		assert(Math.abs(inv - expected) < 1e-9 * a.families[0].scale, `t=${r.t[i]}: ${inv} vs ${expected}`);
	}

	// The implicit solvers: exact where the stages are linear solves, to the
	// Newton tolerance where they are not -- and closed either way.
	assert(run(model('ros23')).massBalance().worst < 1e-10, 'ros23');
	const stiff = run(model('ndf')).massBalance();
	assert(stiff.closed && stiff.worst < closedBelow(1e-6) && stiff.worst < 1e-6, `variableOrder ${stiff.worst}`);
	const about = (a, b) => Math.abs(a / b - 1) < 1e-12;
	assert(about(closedBelow(1e-6), 2e-5) && about(closedBelow(undefined), 2e-5) && closedBelow(1e-12) === 1e-10);

	// The trajectories are those of the run without the audit -- to within the
	// tolerance, not to the bit: the budgets take part in the step-size
	// control, so the steps land elsewhere (1.3e-8 relative here, under dormandPrince
	// at rtol 1e-6).
	const plain = run(model('dp45', false));
	assert(plain.massBalance() === null && plain.system.layout.budget === null && plain.system.layout.nstate === 9);
	const soil = plain.system.layout.states.find((s) => s.name === 'Soil');
	for (let i = 0; i < r.t.length; i++) {
		for (let off = 0; off < 3; off++) {
			const p = plain.y[i][soil.base + off];
			const q = r.y[i][soil.base + off];
			assert(Math.abs(p - q) <= 1e-6 * Math.max(1, Math.abs(p)), `Soil moved: ${p} vs ${q}`);
		}
	}
	// It declines the analytic Jacobian, and it is in the fingerprint.
	assert(r.jacobian.available === false && /mass-balance audit/.test(r.jacobian.reason), JSON.stringify(r.jacobian));
	assert(plain.jacobian.available === true, 'the plain run lost its Jacobian');
	assert(integrationFingerprint(model('dp45', true)) !== integrationFingerprint(model('dp45', false)));

	// The report.
	const lines = describeAudit(a, { timeUnit: 'year' });
	assert(/^mass balance: closes — worst relative residual \d\.\de-\d+ \(.* at t = .* year\)$/.test(lines[0]), lines[0]);
	assert(/^  Sr-90: holds [\d.]+ at the end = start 1000 \+ in 2000 − out [\d.]+ − decay [\d.e+]+ \+ ingrowth 0 \+ explicit 400; residual .* \(.* relative, worst at t = .* year\)$/.test(lines[1]), lines[1]);
	assert(lines[4] === '  not by nuclide: nothing held or moved', lines[4]);

	// A model with no nuclides at all has the one family.
	const flat = run({
		name: 'plain', simulation: sim('dp45'), index_lists: [], parameters: [], expressions: [], lookups: [],
		compartments: [{ name: 'A', initial: '10' }, { name: 'B', initial: '0' }],
		inflows: [{ name: 'Feed', to: 'A', rate: '1' }],
		transfers: [{ name: 'AB', from: 'A', to: 'B', rate: '0.1' }, { name: 'Bout', from: 'B', to: null, rate: '0.05' }],
	});
	const fa = flat.massBalance();
	assert(fa.families.length === 1 && fa.families[0].name === 'not by nuclide' && fa.closed, JSON.stringify(fa.families.map((f) => f.name)));
	assert(Math.abs(fa.families[0].final.in - 200) < 1e-6 && fa.families[0].final.out > 0);

	// A hold: an absolute flux of 0.5 a year drains a compartment that has 1
	// in it, for 200 years. "Cannot go negative" holds it at zero after the
	// first two while the recipient goes on filling to 100, and the audit shows
	// the 99 the projection created -- the held-at-zero count only says that
	// it happened.
	const held = run({
		name: 'held', simulation: sim('ndf'), index_lists: [], parameters: [], expressions: [], lookups: [], inflows: [],
		compartments: [{ name: 'A', initial: '1' }, { name: 'B', initial: '0' }],
		transfers: [{ name: 'Drain', from: 'A', to: 'B', rate: '0.5', multiply_by_donor: false }],
	});
	const ha = held.massBalance();
	assert(held.heldAtZero().length === 1, 'A was not held');
	assert(!ha.closed && ha.worst > 0.9, `the hold did not open the balance: ${ha.worst}`);
	const hb = ha.families[0].final;
	assert(Math.abs(hb.inventory - 100) < 1e-6 && Math.abs(hb.residual - 99) < 1e-6, JSON.stringify(hb));
	assert(/^mass balance: DOES NOT CLOSE — relative residual 9\.\d+e-1 in not by nuclide at t = 200 year; a state held at zero/.test(describeAudit(ha, { timeUnit: 'year' })[0]));

	// Between families: a per-nuclide compartment summed into one that is not
	// indexed (which the builder allows only with "sum extra indices"). The
	// nuclides lose it, the un-indexed family gains it, and both sides close.
	const across = run({
		name: 'between', simulation: sim('dp45'),
		nuclides: ['Sr-90', 'Cs-137'],
		index_lists: [{ name: 'RN', for_contaminants: true, indices: [{ name: 'Sr-90' }, { name: 'Cs-137' }] }],
		compartments: [{ name: 'Water', index_lists: ['RN'], initial: '100' }, { name: 'Sink', index_lists: [], initial: '0', handle_decay: false }],
		parameters: [], expressions: [], lookups: [], inflows: [],
		transfers: [{ name: 'Collect', from: 'Water', to: 'Sink', rate: '0.02', sum_extra_indices: true }],
	});
	const xa = across.massBalance();
	assert(xa.closed && xa.worst < 1e-12, `between: ${xa.worst}`);
	const [xs, xc, xu] = xa.families.map((f) => f.final);
	assert(xs.between < -40 && xc.between < -40 && Math.abs(xu.between - (-xs.between - xc.between)) < 1e-9, JSON.stringify([xs.between, xc.between, xu.between]));
	assert(Math.abs(xu.inventory - xu.between) < 1e-9 && xu.decay === 0, 'the sink holds exactly what came across');
	assert(/out\[\d+ \+ BMAP0\[n0\]\] -= f0;\n\t\tout\[\d+ \+ 2\] \+= f0;/.test(across.system.source.dydt), 'the between terms are not emitted on both sides');

	// What carries it: the worker's payloads, the run log, the switch, the status line.
	const { readFileSync } = await import('node:fs');
	const worker = readFileSync(new URL('../src/worker/sim-worker.js', import.meta.url), 'utf8');
	assert((worker.match(/massBalance: results\.massBalance\(\),/g) ?? []).length === 2, 'both payloads carry the audit');
	const app = readFileSync(new URL('../src/ui/app.js', import.meta.url), 'utf8');
	assert(/boolField\('mass_balance', \{/.test(app), 'no switch under SIMULATION');
	assert(/parts\.push\(\['mass balance', p\.massBalance\.closed/.test(app) && /className: 'stat-balance'|classList\.add\('stat-balance'\)/.test(app));
	const { runLogLines } = await import('../src/domain/runlog.js');
	const log = runLogLines({ project: held.project?.raw ?? { name: 'held', simulation: sim('ndf') }, payload: { stats: held.stats, timing: held.timing, t: held.t, outputs: [], heldAtZero: held.heldAtZero(), massBalance: ha }, build: 'test', at: new Date(0) }).join('\n');
	assert(/mass-balance audit: on/.test(log) && /DOES NOT CLOSE/.test(log), log);
});

test('waste packages: the failure hazards match their closed forms, and the block is refused when it cannot fail', async () => {
	const W = await import('../src/domain/wastepackage.js');
	// h = F'/(1 - F): difference F numerically and compare with the hazard.
	const check = (kind, p, t) => {
		const dt = 1e-4;
		const F = (x) => W.failedFraction(kind, x, p);
		const numeric = (F(t + dt) - F(t - dt)) / (2 * dt) / (1 - F(t));
		const h = W.hazard(kind, t, p);
		assert(Math.abs(numeric - h) < 1e-4 * Math.max(1, Math.abs(h)), `${kind} at ${t}: ${numeric} vs ${h}`);
	};
	check('exponential', { start: 100, rate: 0.01 }, 250);
	check('weibull', { start: 0, scale: 1000, shape: 2.5 }, 700);
	check('weibull', { start: 50, scale: 200, shape: 0.7 }, 120);
	check('uniform', { from: 100, to: 1100 }, 600);
	// Before the start nothing fails; the hazard is 0 and so is the fraction.
	assert(W.hazard('exponential', 50, { start: 100, rate: 0.01 }) === 0 && W.failedFraction('exponential', 50, { start: 100, rate: 0.01 }) === 0);
	assert(W.hazard('never', 5, {}) === 0 && W.hazard('at', 5, { at: 3 }) === 0, 'a jump has no hazard');
	assert(W.failedFraction('at', 3, { at: 3 }) === 1 && W.failedFraction('at', 2.9, { at: 3 }) === 0);
	// The uniform hazard is capped at the end of the window rather than infinite.
	const cap = W.hazard('uniform', 1100, { from: 100, to: 1100 });
	assert(Number.isFinite(cap) && Math.abs(cap - 1 / (W.WINDOW_TAIL * 1000)) < 1e-9, `${cap}`);
	// The code and the number agree, since one is made from the other.
	const code = W.hazardCode('weibull', { t: 't', start: '0', scale: '1000', shape: '2.5' });
	assert(new Function('t', `return ${code};`)(700) === W.hazard('weibull', 700, { start: 0, scale: 1000, shape: 2.5 }));
	assert(W.failureTimeKeys('uniform').join() === 'fail_from,fail_to' && W.failureTimeKeys('never').length === 0);
	assert(W.describeWaste({ packages: 4500, failure: 'uniform', fail_from: '1000', fail_to: '10000' }) === '4,500 packages, fail 1000 – 10000');
	assert(W.describeWaste({ failure: 'never' }) === 'never fail');

	// What is wrong, before the run.
	const problems = (b) => W.wasteProblems({ waste_packages: [{ name: 'W', ...b }] }).map((p) => `${p.field}: ${p.message}`);
	assert(problems({ failure: 'never' }).length === 0);
	assert(/failure: 'sometimes' is not a way/.test(problems({ failure: 'sometimes' })[0]));
	assert(/fail_at: Packages that fail all at one time need fail at/.test(problems({ failure: 'at' })[0]), problems({ failure: 'at' })[0]);
	assert(/fail_to: The failures end \(100\) before they begin \(200\)/.test(problems({ failure: 'uniform', fail_from: '200', fail_to: '100' })[0]));
	assert(problems({ failure: 'uniform', fail_from: 't0', fail_to: 't1' }).length === 0, 'equations are not judged before the run');
	assert(/shape has to be above 0/.test(problems({ failure: 'weibull', fail_start: '0', fail_scale: '10', fail_shape: '0' })[0]));
	assert(/packages: '2.5' is not a number of packages/.test(problems({ failure: 'never', packages: 2.5 })[0]));
	assert(/irf: The instant release fraction is between 0 and 1/.test(problems({ failure: 'never', irf: '1.5' })[0]));
});

test('waste packages are a block kind: normalised by the project, added and connected by the editor', async () => {
	const { COLLECTIONS } = await import('../src/domain/systems.js');
	const { SINGULAR } = await import('../src/domain/blocks.js');
	const { switchTimes } = await import('../src/domain/switchtimes.js');
	const { integrationFingerprint } = await import('../src/domain/fingerprint.js');
	assert(COLLECTIONS.includes('waste_packages') && SINGULAR.waste_packages === 'waste_package');
	assert(ed.KIND_LABEL.waste_package === 'Waste packages' && ed.entryKeys('waste_package').join() === 'inventory,irf');

	const raw = {
		simulation: { ...DEFAULT_SIMULATION, end_time: 10000, output_points: 5, spacing: 'linear', time_unit: 'year' },
		nuclides: ['Cs-137', 'Sr-90'],
		index_lists: [{ name: 'RN', for_contaminants: true, indices: [{ name: 'Cs-137' }, { name: 'Sr-90' }] }],
		compartments: [{ name: 'NearField', index_lists: ['RN'], initial: '0' }],
		parameters: [{ name: 't_fail', value: 1000 }],
		waste_packages: [{
			name: 'Canisters', index_lists: ['RN'], packages: '4500.2', failure: 'uniform',
			fail_from: 't_fail', fail_to: '5000', inventory: '1e12', irf: '0.05', degradation_rate: '1e-5',
			handle_decay: 'false', to: 'NearField',
			entries: [{ index: { RN: 'Sr-90' }, inventory: '2e12', irf: '0.1', degradation_rate: '9' }],
		}],
		transfers: [], expressions: [], inflows: [],
	};
	const p = new Project(JSON.parse(JSON.stringify(raw)));
	const w = p.waste_packages[0];
	assert(w.kind === 'waste_package' && w.packages === 4500 && w.failure === 'uniform' && w.handle_decay === false, JSON.stringify(w));
	assert(!('to' in w), 'the release is a transfer, not a field');
	assert(w.unit === 'Bq/year', w.unit);
	assert(w.fail_shape === '1' && w.fail_start === '0', 'defaults are filled in');
	// Per-nuclide entries keep only what is per nuclide: a degradation rate is the waste form's.
	assert(JSON.stringify(w.entries[0]) === '{"index":{"RN":"Sr-90"},"inventory":"2e12","irf":"0.1"}', JSON.stringify(w.entries[0]));
	assert(p.toJSON().waste_packages.length === 1 && !('waste_packages' in new Project({ simulation: DEFAULT_SIMULATION }).toJSON()));
	// The failure times are corners the solver lands on: the parameter, by
	// name, and the number. Asked of the model as the editor holds it.
	assert(switchTimes(raw).join() === '1000,5000', switchTimes(raw).join());
	// A bad way of failing is refused by the project.
	let threw = null;
	try { new Project({ ...JSON.parse(JSON.stringify(raw)), waste_packages: [{ ...raw.waste_packages[0], failure: 'at' }] }); } catch (e) { threw = e; }
	assert(threw && /need fail at/.test(threw.message), threw?.message);
	// And the fingerprint moves with a setting.
	const other = JSON.parse(JSON.stringify(raw)); other.waste_packages[0].degradation_rate = '2e-5';
	assert(integrationFingerprint(raw) !== integrationFingerprint(other));
	other.waste_packages[0].degradation_rate = '1e-5'; other.waste_packages[0].failure = 'exponential'; other.waste_packages[0].fail_rate = '1e-3';
	assert(integrationFingerprint(raw) !== integrationFingerprint(other), 'the way of failing is not in the fingerprint');

	// The editor: add, connect the release, refuse a second.
	const model = { simulation: { ...DEFAULT_SIMULATION, time_unit: 'year' }, nuclides: ['Cs-137'],
		index_lists: [{ name: 'RN', for_contaminants: true, indices: [{ name: 'Cs-137' }] }],
		compartments: [{ name: 'NearField', index_lists: ['RN'], initial: '0' }], transfers: [] };
	const added = ed.addWastePackage(model, { at: { x: 10, y: 20 } });
	assert(added.name === 'Packages' && added.index_lists.join() === 'RN' && added.unit === 'Bq/year' && added.failure === 'never', JSON.stringify(added));
	assert(ed.wasteStates(model, added).states === 2);
	const rel = ed.addTransfer(model, 'Packages', 'NearField');
	assert(rel.rate === 'Packages' && rel.multiply_by_donor === false, JSON.stringify(rel));
	assert(ed.isReleaseTransfer(model, rel) && ed.releaseTransfers(model, 'Packages').length === 1);
	let second = null;
	try { ed.addTransfer(model, 'Packages', 'NearField'); } catch (e) { second = e; }
	assert(second && /already delivers its release/.test(second.message), second?.message);
	assert(ed.endpointProblem(model, 'Packages', 'from') === null);
	assert(/nothing flows into them/.test(ed.endpointProblem(model, 'Packages', 'to')));
	// A model with no radionuclides gets packages indexed by nothing.
	const plain = { simulation: { ...DEFAULT_SIMULATION }, compartments: [{ name: 'A' }] };
	assert(ed.addWastePackage(plain).index_lists.length === 0);
	// The strip carries the problems.
	added.failure = 'weibull'; added.fail_scale = '100'; added.fail_shape = '-1';
	const strip = ed.modelWarnings(model).map((w) => w.message);
	assert(strip.some((m) => /Weibull shape has to be above 0/.test(m)), strip.join(' | '));
});

test('waste packages integrate: failure, exposure and release match their closed forms, and a failure time is a jump', async () => {
	const { budgetIndex } = await import('../src/domain/massbalance.js');
	const sim = (extra = {}) => ({
		time_unit: 'year', start_time: 0, end_time: 2000, output_points: 41, spacing: 'linear',
		solver: 'dp45', rtol: 1e-8, abstol: 1e-6, mass_balance: true, ...extra,
	});
	const model = (waste, extra = {}) => ({
		name: 'wp', simulation: sim(extra),
		nuclides: ['Cs-137', 'I-129'],
		index_lists: [{ name: 'RN', for_contaminants: true, indices: [{ name: 'Cs-137' }, { name: 'I-129' }] }],
		compartments: [{ name: 'NearField', index_lists: ['RN'], initial: '0', handle_decay: false }],
		parameters: [{ name: 'lambda_f', value: 1e-3, index_lists: [] }, { name: 't0', value: 500, index_lists: [] }],
		waste_packages: [{
			name: 'Canisters', index_lists: ['RN'], inventory: '1e12', irf: '0.1', degradation_rate: '2e-3',
			handle_decay: false, ...waste,
		}],
		transfers: [{ name: 'Release', from: 'Canisters', to: 'NearField', rate: 'Canisters', multiply_by_donor: false }],
		expressions: [], inflows: [], lookups: [],
	});
	const states = (r) => {
		const L = r.system.layout;
		return {
			P: L.states.find((s) => s.name === 'Canisters intact'),
			M: L.states.find((s) => s.name === 'Canisters exposed'),
			NF: L.states.find((s) => s.name === 'NearField'),
		};
	};
	const near = (a, b, tol) => Math.abs(a / b - 1) < tol;

	// The layout: two hidden inventories per index, after the compartments,
	// in the inventory unit; the block's own slot is the release.
	const r = run(model({ failure: 'exponential', fail_start: 't0', fail_rate: 'lambda_f' }));
	const { P, M, NF } = states(r);
	assert(P && M && P.kind === 'waste_package' && P.hidden && P.role === 'intact' && M.role === 'exposed', JSON.stringify([P, M]));
	assert(P.base === 2 && M.base === 4 && P.width === 2 && r.system.layout.nstate === 6 + 6 * 3, `${P.base} ${M.base} ${r.system.layout.nstate}`);
	assert(P.unit === 'Bq' && P.block.unit === 'Bq/year', 'the inventories are in the inventory unit, the release per unit time');
	const w = r.system.layout.wastes[0];
	assert(w.name === 'Canisters' && w.intact === 2 && w.exposed === 4 && w.failure === 'exponential', JSON.stringify(w));
	// Settings the way of failing does not read get no slot.
	const slots = r.system.layout.algebraic.map((a) => a.name);
	assert(slots.includes('Canisters#fail_rate') && slots.includes('Canisters#hazard') && slots.includes('Canisters') && !slots.includes('Canisters#fail_scale'), slots.join());
	// The series: the two inventories and the release, labelled and in their units.
	const outs = r.outputs().filter((o) => /Canisters/.test(o.label));
	assert(outs.map((o) => `${o.label}|${o.unit}|${o.kind}`).join(' ') === 'Canisters intact [Cs-137]|Bq|waste_inventory Canisters intact [I-129]|Bq|waste_inventory Canisters exposed [Cs-137]|Bq|waste_inventory Canisters exposed [I-129]|Bq|waste_inventory Canisters [Cs-137]|Bq/year|waste_package Canisters [I-129]|Bq/year|waste_package', outs.map((o) => `${o.label}|${o.unit}|${o.kind}`).join(' '));
	// The audit declines the analytic Jacobian; without it the block has one,
	// and it agrees with finite differences.
	assert(r.jacobian.available === false && /mass-balance audit/.test(r.jacobian.reason), JSON.stringify(r.jacobian));
	{
		const plainModel = model({ failure: 'weibull', fail_start: '100', fail_scale: '800', fail_shape: '3' }, { mass_balance: false });
		const { worst, jacobian } = jacobianAgrees(plainModel);
		assert(jacobian.available !== false && worst < 1, `the waste Jacobian is off by ${worst}x the difference's noise`);
		assert(jacobian.constant === false, 'a Weibull hazard reads the clock, so the matrix moves');
		const still = jacobianAgrees(model({ failure: 'at', fail_at: 't0' }, { mass_balance: false })).jacobian;
		assert(still.constant === true, 'with no hazard the matrix is constant');
	}

	// The closed forms, with no decay: P = P0 e^{-λτ}, M = λ(1-irf)P0 (e^{-λτ} - e^{-dτ})/(d-λ).
	const n = r.t.length - 1;
	const tau = r.t[n] - 500; const lam = 1e-3, d = 2e-3, irf = 0.1, P0 = 1e12;
	const Pexact = P0 * Math.exp(-lam * tau);
	const Mexact = lam * (1 - irf) * P0 * (Math.exp(-lam * tau) - Math.exp(-d * tau)) / (d - lam);
	assert(near(r.y[n][P.base], Pexact, 1e-8), `intact ${r.y[n][P.base]} vs ${Pexact}`);
	assert(near(r.y[n][M.base], Mexact, 1e-7), `exposed ${r.y[n][M.base]} vs ${Mexact}`);
	// Nothing left the model: intact + exposed + near field is the inventory.
	assert(near(r.y[n][P.base] + r.y[n][M.base] + r.y[n][NF.base], P0, 1e-9), 'mass was lost');
	// Before the start nothing has failed, at every output time.
	for (let i = 0; i < r.t.length && r.t[i] < 500; i++) assert(r.y[i][P.base] === P0 && r.y[i][M.base] === 0, `failed early at ${r.t[i]}`);
	// The start is a corner the solver landed on.
	assert(r.t.includes(500) && r.stats.breaks === 1, `breaks ${r.stats.breaks}`);
	// The release slot is h P irf + d M, read off the same instant.
	const rel = r.outputs().find((o) => o.label === 'Canisters [Cs-137]');
	const relValue = r.series(rel)[n];
	assert(near(relValue, lam * r.y[n][P.base] * irf + d * r.y[n][M.base], 1e-9), `release ${relValue}`);
	// The audit closes: the release into the near field is a move, not an arrival.
	const audit = r.massBalance();
	assert(audit.closed && audit.worst < 1e-12, `audit ${audit.worst}`);
	assert(audit.families[0].final.in === 0 && audit.families[0].final.out === 0, JSON.stringify(audit.families[0].final));
	// Both nuclides move alike here, since nothing distinguishes them.
	assert(r.y[n][P.base] === r.y[n][P.base + 1] && r.y[n][M.base] === r.y[n][M.base + 1]);

	// All at one time: a jump. The row at the corner is the state before it;
	// the next row has the whole intact inventory exposed, less the instant
	// release, which is in the near field.
	const j = run(model({ failure: 'at', fail_at: 't0' }));
	const S = states(j);
	const at = j.t.indexOf(500); const after = at + 1;
	assert(at > 0 && j.y[at][S.P.base] === P0 && j.y[at][S.M.base] === 0 && j.y[at][S.NF.base] === 0, 'the corner row is not the state before the jump');
	assert(j.y[after][S.P.base] === 0, 'the packages did not fail');
	const dt = j.t[after] - 500;
	const Mafter = (1 - irf) * P0 * Math.exp(-d * dt);
	assert(near(j.y[after][S.M.base], Mafter, 1e-8), `exposed after the jump ${j.y[after][S.M.base]} vs ${Mafter}`);
	assert(near(j.y[after][S.P.base] + j.y[after][S.M.base] + j.y[after][S.NF.base], P0, 1e-9), 'the jump lost mass');
	assert(j.y[after][S.NF.base] > irf * P0, 'the instant release did not reach the near field');
	assert(j.massBalance().closed && j.massBalance().worst < 1e-12, 'the jump opened the balance');
	assert(j.system.jumps.length === 1 && j.system.jumps[0].name === 'Canisters' && j.system.slotValue(j.system.jumps[0].slot) === 500);
	// A time that does not come to a number is refused before the run.
	let refused = null;
	try { run(model({ failure: 'at', fail_at: 'time() + 1' })); } catch (e) { refused = e; }
	assert(refused && /has to come to a number before the run/.test(refused.message), refused?.message);

	// A window, with decay on: everything fails between 500 and 1500, and the
	// decay chain runs in both inventories -- Cs-137 at 30 years is nearly
	// gone by 2000 while I-129 is not.
	const u = run(model({ failure: 'uniform', fail_from: '500', fail_to: '1500', handle_decay: true }));
	const U = states(u);
	const m = u.t.length - 1;
	assert(u.y[m][U.P.base + 1] < 1e-6 * P0, `I-129 still intact after the window: ${u.y[m][U.P.base + 1]}`);
	assert(u.y[m][U.P.base] < u.y[m][U.P.base + 1] || u.y[m][U.P.base] < 1e-9 * P0, 'Cs-137 did not decay inside the packages');
	assert(u.stats.breaks === 2 && u.t.includes(500) && u.t.includes(1500));
	assert(u.massBalance().closed, 'decay inside the packages is not in the budget');
	const half = u.t.indexOf(1000);
	// Halfway through the window half the I-129 has failed, give or take the cap.
	assert(near(u.y[half][U.P.base + 1], 0.5 * P0, 1e-3), `${u.y[half][U.P.base + 1]}`);

	// Never: a store that only decays.
	const s0 = run(model({ failure: 'never', handle_decay: true }));
	const S0 = states(s0);
	assert(s0.y[s0.t.length - 1][S0.M.base] === 0 && s0.y[s0.t.length - 1][S0.NF.base] === 0);
	assert(near(s0.y[s0.t.length - 1][S0.P.base + 1], P0 * Math.exp(-Math.LN2 * 2000 / 1.57e7), 1e-4), 'I-129 in a store');

	// Weibull, and the release read only -- nothing drawn out of the block:
	// what leaves has left the model, and the audit says so as `out`.
	const wb = model({ failure: 'weibull', fail_start: '100', fail_scale: '800', fail_shape: '3' });
	wb.transfers = [];
	const v = run(wb);
	const V = states(v);
	const k = v.t.length - 1;
	const F = 1 - Math.exp(-(((v.t[k] - 100) / 800) ** 3));
	assert(near(v.y[k][V.P.base], P0 * (1 - F), 1e-7), `weibull intact ${v.y[k][V.P.base]} vs ${P0 * (1 - F)}`);
	const va = v.massBalance();
	assert(va.closed && va.families[0].final.out > 0.5 * P0, `read-only release is not counted out: ${JSON.stringify(va.families[0].final)}`);
	assert(v.y[k][V.NF.base] === 0);
	// The budget state for `out` holds exactly what left.
	const outState = budgetIndex(v.system.layout.budget, 'out', 0);
	assert(near(v.y[k][outState], P0 - v.y[k][V.P.base] - v.y[k][V.M.base], 1e-9));
});

test('waste packages are drawn, edited and described like the block they are, and the example runs', async () => {
	const { readFileSync } = await import('node:fs');
	const read = (f) => readFileSync(new URL(f, import.meta.url), 'utf8');
	const graph = read('../src/ui/graph.js');
	assert(/HAS_PORT = new Set\(\['compartment', 'farfield', 'waste_package'\]\)/.test(graph), 'no port to draw the release from');
	assert(/for \(const w of p\.waste_packages \?\? \[\]\) push\(w, 'waste_package'\);/.test(graph), 'not drawn');
	assert(/label: 'Waste packages',[\s\S]*?onPick: \(\) => this\._addNodeAt\('waste_package', at\)/.test(graph), 'not in the canvas menu');
	assert(/waste_package: \(\) => ed\.addWastePackage\(this\.project, \{ at, system \}\)/.test(graph));
	assert(/ed\.RELEASING\.has\(ed\.findBlock\(this\.project, from\)\?\.kind\)/.test(graph), 'the one-release rule is not shared');
	assert(/nothing flows into them, `\n\s*\+ `their release comes out\./.test(graph), 'a drop onto the block is not refused with a reason');
	assert(/return truncate\(ed\.describeWaste\(n\.block\), 24\)/.test(graph), 'no subtitle');
	const inspector = read('../src/ui/inspector.js');
	assert(/'lookup', 'index_reduction', 'block_reduction', 'farfield', 'waste_package', 'event', 'parameter',/.test(inspector));
	const panel = /if \(kind === 'waste_package'\) \{[\s\S]*?\n\t\}\n\n\tif \(kind === 'farfield'\)/.exec(inspector)?.[0] ?? '';
	assert(panel, 'no panel');
	for (const need of ["derivedField('States'", "selectField('Release'", "numberField('Packages'", 'withEntries(equationField(', "field: 'irf'", "selectField('Packages fail'", 'ed.FAILURE_KEYS[failure]', "field: 'degradation_rate'", "checkField('Handle decay and ingrowth'"]) {
		assert(panel.includes(need), `the panel lacks ${need}`);
	}
	assert(/const fromNames = \[\.\.\.endpointNames, \.\.\.wasteNames\];/.test(inspector) && /\.\.\.fromNames\.map\(\(n\) => \[n, n\]\)/.test(inspector), 'packages are not offered as a donor');
	const info = read('../src/ui/info.js');
	assert(/if \(kind === 'waste_package'\) \{[\s\S]*?ed\.wasteStates\(project, block\)[\s\S]*?ed\.releaseTransfers\(project, qname\)/.test(info), 'no Information section');
	const icons = read('../src/ui/icons.js');
	assert(/waste_package: \{ shape: 'rect', tone: 'waste', mark: 'canister' \}/.test(icons) && /canister: 'M 4\.4 2\.4 H 9\.6/.test(icons));
	const css = read('../css/app.css');
	assert((css.match(/--node-fill-waste:/g) ?? []).length === 3, 'a theme lacks the fill');
	assert(/\.gnode-waste_package \.gnode-body \{\n\tfill: var\(--node-fill-waste\);/.test(css) && /\.bicon-waste \.bicon-body/.test(css));
	const app = read('../src/ui/app.js');
	assert(/file: 'waste-packages\.json', title: 'Canisters failing: a source term with barriers'/.test(app), 'the example is not listed');

	// The example: it is a Project, it builds, it runs, and the books close.
	const raw = JSON.parse(read('../examples/waste-packages.json'));
	const p = new Project(raw);
	assert(p.waste_packages.length === 1 && p.waste_packages[0].failure === 'weibull' && p.waste_packages[0].packages === 4500);
	const r = run(raw);
	assert(r.system.layout.nstate === 22, `${r.system.layout.nstate} states`); // + two event counts
	assert(r.stats.breaks === 2 && r.t.includes(1000) && r.t.includes(100000), 'the first failure and the glaciation are not corners');
	assert(r.stats.jumps === 1, 'the glaciation did not jump');
	assert(r.stats.solver === 'ndf', `a segmented run lost its solver name: ${r.stats.solver}`);
	// With the audit on -- 50 states then -- the books close.
	const audited = run({ ...raw, simulation: { ...raw.simulation, mass_balance: true } });
	assert(audited.system.layout.nstate === 52 && audited.massBalance().closed, `the example does not close: ${audited.massBalance().worst}`);
	assert(ed.stateCount(raw) === 22 && ed.stateCount({ ...raw, simulation: { ...raw.simulation, mass_balance: true } }) === 52, 'the model card miscounts');
	const labels = r.outputs().map((o) => o.label);
	assert(labels.includes('Canisters intact [Cs-137]') && labels.includes('Canisters exposed [Cl-36]') && labels.includes('Canisters [Se-79]'), labels.filter((l) => /Canisters/.test(l)).join());
	// Cl-36 is long-lived and 8% instantly released: by a million years it has all left the canisters and some has reached the biosphere.
	const L = r.system.layout; const n = r.t.length - 1;
	const P = L.states.find((s) => s.name === 'Canisters intact'); const B = L.states.find((s) => s.name === 'Biosphere');
	assert(r.y[n][P.base + 2] < 1e-3 && r.y[n][B.base + 2] > 1e5, `${r.y[n][P.base + 2]} ${r.y[n][B.base + 2]}`);
	// And the strip has nothing to say about it.
	assert(ed.modelWarnings(raw).filter((w) => /Canisters/.test(w.name ?? '')).length === 0, JSON.stringify(ed.modelWarnings(raw)));
});

test('disruptive events: the vocabulary, the problems, and a reproducible draw', async () => {
	const D = await import('../src/domain/disruption.js');
	const { streamFor } = await import('../src/domain/sample.js');
	assert(D.TIMINGS.join() === 'at,poisson' && D.ACTIONS.join() === 'fail,move');
	assert(JSON.stringify(D.normaliseActions([{ kind: 'fail', block: 'C', fraction: 0.1 }, { kind: 'move', from: 'A', to: '', fraction: 'f' }, null, 'x']))
		=== '[{"kind":"fail","fraction":"0.1","block":"C"},{"kind":"move","fraction":"f","from":"A","to":null}]');
	assert(D.describeDisruption({ timing: 'poisson', rate: '1e-5', actions: [{ kind: 'fail', block: 'Canisters', fraction: '0.1' }] }) === 'Poisson 1e-5 · fails 10% of Canisters');
	assert(D.describeDisruption({ timing: 'at', at: 't_glacial', actions: [{ kind: 'move', from: 'Soil', to: null, fraction: '0.8' }] }) === 'at t_glacial · moves 80% of Soil out');
	assert(D.describeDisruption({ timing: 'poisson', rate: 'r', from: '500', actions: [] }) === 'Poisson r in 500 – end · does nothing but count');
	// The draw: exponential gaps from the stream, inside the window, reproducible.
	const a = D.sampleOccurrences(1e-3, 0, 100000, streamFor(7, 'Quake#occurrences#2'));
	const b = D.sampleOccurrences(1e-3, 0, 100000, streamFor(7, 'Quake#occurrences#2'));
	assert(a.length > 50 && a.length < 150 && JSON.stringify(a) === JSON.stringify(b), `${a.length}`);
	assert(a.every((t, i) => t > 0 && t < 100000 && (i === 0 || t > a[i - 1])), 'not ascending inside the window');
	const c = D.sampleOccurrences(1e-3, 0, 100000, streamFor(7, 'Quake#occurrences#3'));
	assert(JSON.stringify(a) !== JSON.stringify(c), 'two realisations drew the same');
	assert(D.sampleOccurrences(0, 0, 100, streamFor(1, 'x')).length === 0 && D.sampleOccurrences(1, 5, 5, streamFor(1, 'x')).length === 0);
	assert(D.sampleOccurrences(1e6, 0, 1, streamFor(1, 'x'), 50).length === 50, 'the cap did not hold');
	// A long run at a small rate: the mean over many streams is the rate times the window.
	let total = 0;
	for (let i = 0; i < 400; i++) total += D.sampleOccurrences(2e-5, 0, 1e6, streamFor(11, `Q#${i}`)).length;
	assert(Math.abs(total / 400 - 20) < 1.5, `mean ${total / 400} against 20`);

	// The problems.
	const problems = (b, extra = {}) => D.disruptionProblems({
		waste_packages: [{ name: 'Canisters' }], compartments: [{ name: 'Soil' }, { name: 'Lake' }], events: [{ name: 'E', ...b }], ...extra,
	}).map((p) => `${p.field}: ${p.message}`);
	assert(problems({ timing: 'at', at: '500', actions: [{ kind: 'fail', block: 'Canisters', fraction: '0.1' }] }).length === 0);
	assert(/timing: 'sometimes' is not a way/.test(problems({ timing: 'sometimes' })[0]));
	assert(/at: An event at a time needs the time/.test(problems({ timing: 'at' })[0]));
	assert(/rate: A random event needs its rate/.test(problems({ timing: 'poisson' })[0]));
	assert(/until: The window ends \(100\) before it opens \(500\)/.test(problems({ timing: 'poisson', rate: '1', from: '500', until: '100' })[0]));
	assert(problems({ timing: 'poisson', rate: '1', from: '', until: '' }).length === 0, 'a blank window end is the run’s');
	assert(/actions\[0\]: 'Soil' is not a set of waste packages/.test(problems({ timing: 'at', at: '1', actions: [{ kind: 'fail', block: 'Soil', fraction: '0.1' }] })[0]));
	assert(/actions\[0\]: 'Canisters' is not a compartment, so there is nothing to move/.test(problems({ timing: 'at', at: '1', actions: [{ kind: 'move', from: 'Canisters', fraction: '0.1' }] })[0]));
	assert(/actions\[0\]: Moving Soil into itself/.test(problems({ timing: 'at', at: '1', actions: [{ kind: 'move', from: 'Soil', to: 'Soil', fraction: '0.1' }] })[0]));
	assert(/actions\[1\]: A share is between 0 and 1; 1.5 is not/.test(problems({ timing: 'at', at: '1', actions: [{ kind: 'move', from: 'Soil', to: 'Lake', fraction: '0.5' }, { kind: 'fail', block: 'Canisters', fraction: '1.5' }] })[0]));
	assert(/actions\[0\]: 'burn' is not something an event can do/.test(problems({ timing: 'at', at: '1', actions: [{ kind: 'burn' }] })[0]));
});

test('disruptive events are a block kind: normalised, edited, renamed with their targets, and corners for the solver', async () => {
	const { COLLECTIONS } = await import('../src/domain/systems.js');
	const { switchTimes } = await import('../src/domain/switchtimes.js');
	const { integrationFingerprint } = await import('../src/domain/fingerprint.js');
	assert(COLLECTIONS.includes('events') && ed.KIND_LABEL.event === 'Events');
	const raw = {
		simulation: { ...DEFAULT_SIMULATION, end_time: 10000, output_points: 5, spacing: 'linear', time_unit: 'year' },
		nuclides: ['Cs-137'],
		index_lists: [{ name: 'RN', for_contaminants: true, indices: [{ name: 'Cs-137' }] }],
		compartments: [{ name: 'Soil', index_lists: ['RN'], initial: '1' }, { name: 'Lake', index_lists: ['RN'], initial: '0' }],
		parameters: [{ name: 't_glacial', value: 5000, index_lists: [] }],
		waste_packages: [{ name: 'Canisters', index_lists: ['RN'], inventory: '1e12' }],
		events: [
			{ name: 'Glaciation', timing: 'at', at: 't_glacial', sampled: 'false', index_lists: ['RN'],
				actions: [{ kind: 'move', from: 'Soil', to: 'Lake', fraction: 0.8 }, { kind: 'fail', block: 'Canisters', fraction: '0.05' }] },
			{ name: 'Quake', timing: 'poisson', rate: '1e-5', from: '1000', until: '', actions: [] },
		],
		transfers: [], expressions: [], inflows: [],
	};
	const p = new Project(JSON.parse(JSON.stringify(raw)));
	const g = p.events[0];
	assert(g.kind === 'event' && g.timing === 'at' && g.sampled === false && g.index_lists.length === 0, JSON.stringify(g));
	assert(JSON.stringify(g.actions) === '[{"kind":"move","fraction":"0.8","from":"Soil","to":"Lake"},{"kind":"fail","fraction":"0.05","block":"Canisters"}]', JSON.stringify(g.actions));
	assert(p.events[1].sampled === true && p.events[1].unit === '');
	assert(p.toJSON().events.length === 2);
	// Corners: the time, and the window's open end.
	assert(switchTimes(raw).join() === '1000,5000', switchTimes(raw).join());
	// A bad action is refused by the project.
	let threw = null;
	try { new Project({ ...JSON.parse(JSON.stringify(raw)), events: [{ name: 'X', timing: 'at', at: '1', actions: [{ kind: 'fail', block: 'Soil', fraction: '1' }] }] }); } catch (e) { threw = e; }
	assert(threw && /not a set of waste packages/.test(threw.message), threw?.message);
	// The fingerprint moves with the share and with the target.
	const other = JSON.parse(JSON.stringify(raw)); other.events[0].actions[0].fraction = '0.9';
	assert(integrationFingerprint(raw) !== integrationFingerprint(other));
	other.events[0].actions[0].fraction = '0.8'; other.events[0].actions[0].to = null;
	assert(integrationFingerprint(raw) !== integrationFingerprint(other), 'the target is not in the fingerprint');

	// The editor: add, rename a target, and the strip.
	const model = JSON.parse(JSON.stringify(raw));
	const added = ed.addDisruption(model, { at: { x: 1, y: 2 } });
	assert(added.name === 'Event' && added.timing === 'at' && added.index_lists.length === 0 && Array.isArray(added.actions), JSON.stringify(added));
	ed.renameBlock(model, 'Soil', 'Topsoil');
	assert(model.events[0].actions[0].from === 'Topsoil', 'the rename did not follow the action');
	ed.renameBlock(model, 'Canisters', 'Drums');
	assert(model.events[0].actions[1].block === 'Drums');
	// A reference walker sees the time and the share: `t_glacial` is used.
	const users = ed.referencesTo ? ed.referencesTo(model, 't_glacial') : null;
	if (users) assert(users.some((u) => /Glaciation/.test(String(u.name ?? u))), JSON.stringify(users));
	model.events[1].rate = '';
	const strip = ed.modelWarnings(model).map((w) => w.message);
	assert(strip.some((m) => /A random event needs its rate/.test(m)), strip.join(' | '));
});

test('disruptive events integrate: expected-value form, a timed jump, a window, and sampled realisations that replay', async () => {
	const { runProbabilistic, runRealization } = await import('../src/sim/probabilistic.js');
	const sim = (extra = {}) => ({
		time_unit: 'year', start_time: 0, end_time: 2000, output_points: 41, spacing: 'linear',
		solver: 'dp45', rtol: 1e-8, abstol: 1e-6, ...extra,
	});
	const model = (dis, extra = {}) => ({
		name: 'dis', simulation: sim(extra),
		nuclides: ['Cs-137', 'I-129'],
		index_lists: [{ name: 'RN', for_contaminants: true, indices: [{ name: 'Cs-137' }, { name: 'I-129' }] }],
		compartments: [
			{ name: 'NearField', index_lists: ['RN'], initial: '0', handle_decay: false },
			{ name: 'Sink', index_lists: ['RN'], initial: '0', handle_decay: false },
		],
		parameters: [{ name: 'q_rate', value: 1e-3, index_lists: [], pdf: { kind: 'unif', params: { min: 5e-4, max: 2e-3 } } }],
		waste_packages: [{ name: 'Canisters', index_lists: ['RN'], inventory: '1e12', irf: '0.1', degradation_rate: '2e-3', handle_decay: false, failure: 'never' }],
		transfers: [{ name: 'Release', from: 'Canisters', to: 'NearField', rate: 'Canisters', multiply_by_donor: false }],
		events: dis, expressions: [], inflows: [], lookups: [],
	});
	const st = (r, name) => r.system.layout.states.find((s) => s.name === name);
	const near = (a, b, tol) => Math.abs(a / b - 1) < tol;
	const quake = { name: 'Quake', timing: 'poisson', rate: 'q_rate', actions: [{ kind: 'fail', block: 'Canisters', fraction: '0.1' }] };

	// Expected-value form: a hazard of share x rate on the intact packages, and
	// the count grows at the rate.
	const r = run(model([quake]));
	const n = r.t.length - 1;
	const P = st(r, 'Canisters intact'); const N = st(r, 'Quake');
	assert(N && N.kind === 'event' && N.width === 1 && !N.hidden && P.base === 4 && N.base === 8, JSON.stringify([P?.base, N?.base]));
	assert(near(r.y[n][P.base], 1e12 * Math.exp(-1e-4 * 2000), 1e-8), `intact ${r.y[n][P.base]}`);
	assert(near(r.y[n][N.base], 2, 1e-7), `count ${r.y[n][N.base]}`);
	assert(r.outputs().some((o) => o.label === 'Quake' && o.kind === 'event' && o.unit === ''), 'the count is not a series');
	assert(r.jacobian.available === true && r.jacobian.constant === true, JSON.stringify(r.jacobian));
	const agree = jacobianAgrees(model([quake]));
	assert(agree.worst < 1, `the event Jacobian is off by ${agree.worst}x`);
	// With the audit on, the books close: the hazard's share moves mass inside the audited set.
	assert(run(model([quake], { mass_balance: true })).massBalance().closed);

	// A timed event: move half the near field to the sink and fail a fifth of
	// the packages at 800, as a jump; the count steps to 1.
	const g = { name: 'Glacier', timing: 'at', at: '800', actions: [
		{ kind: 'move', from: 'NearField', to: 'Sink', fraction: '0.5' },
		{ kind: 'fail', block: 'Canisters', fraction: '0.2' },
	] };
	const primed = model([g]); primed.compartments[0].initial = '4e10';
	const j = run(primed);
	const at = j.t.indexOf(800);
	const NF = st(j, 'NearField'); const S = st(j, 'Sink'); const Pj = st(j, 'Canisters intact'); const Nj = st(j, 'Glacier');
	assert(at > 0 && j.y[at][Nj.base] === 0 && j.y[at + 1][Nj.base] === 1, 'the count did not step at the corner');
	assert(j.y[at][S.base] === 0 && near(j.y[at + 1][S.base], 0.5 * j.y[at][NF.base], 1e-9), `sink ${j.y[at + 1][S.base]} vs half of ${j.y[at][NF.base]}`);
	assert(near(j.y[at][Pj.base], 1e12, 1e-12) && near(j.y[at + 1][Pj.base], 0.8e12, 1e-9), `intact ${j.y[at + 1][Pj.base]}`);
	const total = (row) => row[NF.base] + row[S.base] + row[Pj.base] + row[st(j, 'Canisters exposed').base];
	assert(near(total(j.y[at + 1]), total(j.y[at]), 1e-9), 'the jump lost mass');
	assert(j.stats.jumps === 1 && j.jacobian.constant === true, `${j.stats.jumps} ${j.jacobian.constant}`);
	assert(run(model([g], { mass_balance: true })).massBalance().closed, 'a move opened the balance');
	// ...and moving out of the model is counted out.
	const outModel = model([{ ...g, actions: [{ kind: 'move', from: 'NearField', to: null, fraction: '1' }] }], { mass_balance: true });
	outModel.compartments[0].initial = '4e10';
	const out = run(outModel);
	assert(out.massBalance().closed && near(out.massBalance().families[0].final.out, 4e10, 1e-9), JSON.stringify(out.massBalance().families[0].final));

	// A window: the expected count is the rate over it, and the matrix moves
	// with the clock while the window switches.
	const w = run(model([{ ...quake, rate: '1e-3', from: '500', until: '1500' }]));
	assert(near(w.y[w.t.length - 1][st(w, 'Quake').base], 1, 1e-7) && w.stats.breaks === 2 && w.jacobian.constant === false);

	// Sampled realisations: integer counts, a replay that matches, and the
	// expected-value form switched off while the dice are in play.
	const pm = model([quake]);
	const pr = runProbabilistic(pm, { iterations: 6, seed: 7, keep: (name) => /Quake|Canisters intact/.test(name) });
	const oQ = pr.outputs.findIndex((o) => o.label === 'Quake'); const oP = pr.outputs.findIndex((o) => o.label === 'Canisters intact [Cs-137]');
	const T = pr.t.length;
	const counts = []; const intact = [];
	for (let i = 0; i < 6; i++) { counts.push(pr.values[oQ][i * T + T - 1]); intact.push(pr.values[oP][i * T + T - 1]); }
	assert(counts.every(Number.isInteger) && counts.some((c) => c > 0), JSON.stringify(counts));
	// Each realisation's intact inventory is exactly 0.9^count of the start: nothing else takes from it.
	for (let i = 0; i < 6; i++) assert(near(intact[i], 1e12 * 0.9 ** counts[i], 1e-9), `realisation ${i}: ${intact[i]} vs ${1e12 * 0.9 ** counts[i]}`);
	const rep = runRealization(pm, { iterations: 6, seed: 7 }, 2);
	const m = rep.results.t.length - 1;
	assert(rep.results.y[m][st(rep.results, 'Quake').base] === counts[2] && rep.results.stats.jumps === counts[2], 'the replay drew differently');
	// Not sampled: every realisation keeps the expected-value form.
	const ev = runProbabilistic(model([{ ...quake, sampled: false }]), { iterations: 3, seed: 7, keep: (name) => /Quake/.test(name) });
	const oE = ev.outputs.findIndex((o) => o.label === 'Quake');
	for (let i = 0; i < 3; i++) assert(!Number.isInteger(ev.values[oE][i * T + T - 1]) && ev.values[oE][i * T + T - 1] > 0.5, 'the expected form was not kept');
	// A model whose only dice are the events still runs probabilistically.
	const onlyDice = model([quake]); onlyDice.parameters = []; onlyDice.events[0].rate = '1e-3';
	const od = runProbabilistic(onlyDice, { iterations: 4, seed: 3, keep: (name) => /Quake/.test(name) });
	assert(od.iterations === 4 && od.values[0].some((v) => v > 0), 'no realisations without a distributed parameter');
});

test('disruptive events are drawn, edited and described like the block they are', async () => {
	const { readFileSync } = await import('node:fs');
	const read = (f) => readFileSync(new URL(f, import.meta.url), 'utf8');
	const graph = read('../src/ui/graph.js');
	assert(/for \(const d of p\.events \?\? \[\]\) push\(d, 'event'\);/.test(graph));
	assert(/label: 'Event',[\s\S]*?onPick: \(\) => this\._addNodeAt\('event', at\)/.test(graph));
	assert(/event: \(\) => ed\.addDisruption\(this\.project, \{ at, system \}\)/.test(graph));
	assert(/return truncate\(ed\.describeDisruption\(n\.block\), 26\)/.test(graph));
	const inspector = read('../src/ui/inspector.js');
	const panel = /if \(kind === 'event'\) \{[\s\S]*?\n\t\}\n\n\tif \(kind === 'waste_package'\)/.exec(inspector)?.[0] ?? '';
	for (const need of ["selectField('Happens'", 'ed.TIMING_KEYS[timing]', "checkField('Draw the occurrences", "className: 'dis-action'", 'ed.ACTION_LABEL[kd]', "'+ Action'", "row('Does', list"]) {
		assert(panel.includes(need), `the panel lacks ${need}`);
	}
	const info = read('../src/ui/info.js');
	assert(/if \(kind === 'event'\) \{[\s\S]*?line\('Happens'[\s\S]*?line\('Does'/.test(info));
	const icons = read('../src/ui/icons.js');
	assert(/event: \{ shape: 'diamond', tone: 'event', mark: 'bolt' \}/.test(icons));
	const css = read('../css/app.css');
	assert(/\.dis-action \{/.test(css) && /\.dis-share \{/.test(css));
	const runlog = read('../src/domain/runlog.js');
	assert(/jumps/.test(runlog), 'the log says nothing about jumps');
});

test('a unit literal is converted to the unit of what it is written against', async () => {
	const { parse } = await import('../src/parser/parser.js');
	const { parseUnit, scaleLiterals } = await import('../src/domain/unitcheck.js');
	const year = parseUnit('year');
	const unitOf = (n) => ({ p1: parseUnit('m'), q: parseUnit('cm'), C: parseUnit('Bq/m3') }[n] ?? null);
	const scaled = (text) => {
		const ast = parse(text);
		const report = scaleLiterals(ast, unitOf, year);
		// `emit` wants the code that reads a name, which for this test is a slot of `P`.
		return { code: emit(ast, (n) => `P[${['p1', 'q', 'C', 'plain'].indexOf(n)}]`, null), ...report };
	};
	const value = (text, P) => new Function('P', `return ${scaled(text).code};`)(P);

	// The case this is all for: 1 m + 1000 mm is 2 m, not 1001.
	assert(value('p1 + 1000[mm]', [1]) === 2, `${value('p1 + 1000[mm]', [1])}`);
	assert(value('p1 - 2[km]', [1]) === -1999);
	// The target is the *sibling*, never a canonical unit -- which is what
	// makes it sound in a model whose lengths are in centimetres. 100 cm plus
	// 500 mm is 150 cm, and would be 1.5 if this scaled to metres instead.
	assert(value('q + 500[mm]', [0, 100]) === 150, `${value('q + 500[mm]', [0, 100])}`);
	// Every place two units have to agree, and nowhere else.
	assert(value('min(p1, 1000[mm])', [1]) === 1);
	assert(value('if(p1 > 500[mm], 10, 20)', [1]) === 10, 'a comparison does not convert');
	assert(value('if(p1 > 0, p1, 1000[mm])', [1]) === 1, 'the two results of an if do not agree');
	// A product has no unit to convert to, so the literal means what it says.
	assert(value('p1 * 5[cm]', [1]) === 5 && scaled('p1 * 5[cm]').converted.length === 0);
	// Bottom-up: an inner sum settles its unit before an outer one reads it.
	assert(value('(p1 + 1000[mm]) + 3000[mm]', [1]) === 5, `${value('(p1 + 1000[mm]) + 3000[mm]', [1])}`);
	// A dimensionless side is absorbed, not converted; a different quantity is
	// never converted; a literal already in the right unit is left alone.
	assert(value('1 + 1000[mm]', []) === 1001 && value('p1 + 2[year]', [1]) === 3 && value('p1 + 1[m]', [1]) === 2);
	// What it did, for the caller that reports it.
	const r = scaled('p1 + 1000[mm]');
	assert(r.converted.length === 1 && r.converted[0].from === '0.001 m' && r.converted[0].to === 'm' && r.converted[0].now === 1, JSON.stringify(r.converted));
	assert(scaled('plain + 1000[mm]').unconverted.length === 1, 'a literal with no target is not reported');
	assert(scaled('p1 + 1[m]').converted.length === 0 && scaled('p1 + 2').converted.length === 0);

	// The run and the checker agree on the same model: the equations the
	// checker is silent about are exactly the ones the run converted.
	const model = (eq, unit) => ({
		name: 'lit',
		simulation: { ...DEFAULT_SIMULATION, time_unit: 'year', start_time: 0, end_time: 1, output_points: 2, spacing: 'linear' },
		parameters: [
			{ name: 'p1', value: 1, unit: 'm', index_lists: [] },
			{ name: 'q', value: 100, unit: 'cm', index_lists: [] },
			{ name: 'plain', value: 1, index_lists: [] },
		],
		expressions: [{ name: 'E', equation: eq, unit, index_lists: [] }],
		compartments: [], transfers: [], inflows: [], index_lists: [],
	});
	const ran = (eq, unit) => {
		const m = model(eq, unit);
		const r = run(m);
		return {
			value: r.series(r.outputs().find((o) => o.label === 'E'))[0],
			warnings: ed.unitProblems(m, m.expressions[0], 'expression').map((w) => w.detail),
		};
	};
	for (const [eq, unit, want] of [
		['p1 + 1000[mm]', 'm', 2],
		['q + 500[mm]', 'cm', 150],
		['p1 - 2[km]', 'm', -1999],
		['min(p1, 1000[mm])', 'm', 1],
	]) {
		const got = ran(eq, unit);
		assert(got.value === want && got.warnings.length === 0, `${eq}: ${got.value} ${JSON.stringify(got.warnings)}`);
	}
	// And where it does not convert, the run says what was written and the
	// checker says why -- never one without the other.
	const nested = ran('p1 + (2 * 1000[mm])', 'm');
	assert(nested.value === 2001 && /a factor of 1000 apart/.test(nested.warnings[0] ?? ''), JSON.stringify(nested));
	const orphan = ran('plain + 1000[mm]', 'm');
	assert(orphan.value === 1001 && /is not converted/.test(orphan.warnings[0] ?? ''), JSON.stringify(orphan));

	// A conversion reaches the tangent too, since the Jacobian compiles the
	// same tree: a compartment leaking `k` per year, plus a literal flux.
	const flux = {
		name: 'flux',
		simulation: { ...DEFAULT_SIMULATION, time_unit: 'year', start_time: 0, end_time: 1, output_points: 2, spacing: 'linear', solver: 'ndf' },
		parameters: [{ name: 'base', value: 1, unit: 'Bq/year', index_lists: [] }],
		compartments: [{ name: 'A', initial: '0', unit: 'Bq', index_lists: [] }],
		inflows: [{ name: 'In', to: 'A', rate: 'base + 2000[mBq/year]', index_lists: [] }],
		transfers: [], expressions: [], index_lists: [],
	};
	const fr = run(flux);
	assert(fr.jacobian.available === true, JSON.stringify(fr.jacobian));
	// 1 Bq/year + 2000 mBq/year = 3 Bq/year for one year.
	const held = fr.series(fr.outputs().find((o) => o.label === 'A'));
	assert(Math.abs(held[held.length - 1] - 3) < 1e-6, `${held[held.length - 1]}`);
	assert(ed.modelWarnings(flux).filter((w) => /Units:/.test(w.message)).length === 0, JSON.stringify(ed.modelWarnings(flux)));
});

test('dy/dp is integrated to a tolerance that fits a sensitivity, not an inventory', async () => {
	const { runSensitivity } = await import('../src/sim/localsens.js');
	// dy/dt = -k*y with y(0) = 1e10 and k = 1e-5, which has a closed form:
	// y = y0 e^{-kt} and dy/dk = -t*y. The point of these numbers is the gap
	// between them -- dy/dk reaches -3.7e14 while the model's abstol is 1e-9 --
	// which is the shape that used to send the augmented solve to the
	// million-step ceiling: `abstol` is absolute, so the tolerance that suits
	// an inventory is wrong for its derivative by a factor of the parameter.
	const y0 = 1e10;
	const k = 1e-5;
	const model = {
		name: 'decaying', simulation: {
			...DEFAULT_SIMULATION, time_unit: 'year', start_time: 0, end_time: 2e5,
			output_points: 40, spacing: 'linear', solver: 'ndf', rtol: 1e-6, abstol: 1e-9,
		},
		index_lists: [], expressions: [], inflows: [],
		parameters: [
			{ name: 'k', value: k, unit: '1/year', index_lists: [] },
			// A parameter that is zero has no scale to read off; it must not
			// give an infinite or NaN tolerance.
			{ name: 'extra', value: 0, unit: '1/year', index_lists: [] },
		],
		compartments: [{ name: 'A', initial: String(y0), unit: 'Bq', index_lists: [] }],
		transfers: [{ name: 'Out', from: 'A', to: null, rate: 'k + extra', index_lists: [] }],
	};
	const r = runSensitivity(model, { parameters: ['k', 'extra'] });

	// It finishes, and in a sane number of steps: this took 830,031 and hit
	// the ceiling before the tolerances were scaled.
	assert(r.stats.nsteps < 5000, `${r.stats.nsteps} steps`);
	// And it is right, against the closed form, at every output time.
	let worst = 0;
	for (let j = 0; j < r.t.length; j++) {
		const t = r.t[j];
		const y = y0 * Math.exp(-k * t);
		assert(Math.abs(r.y[0][j] / y - 1) < 1e-5, `y at ${t}: ${r.y[0][j]} vs ${y}`);
		const want = -t * y;
		if (want === 0) continue;
		// Both parameters enter the rate as `k + extra`, so both derivatives
		// are the same number -- which also checks that a parameter of zero
		// was handled rather than skipped.
		for (const s of [r.sens[0][0][j], r.sens[1][0][j]]) {
			worst = Math.max(worst, Math.abs(s / want - 1));
		}
	}
	assert(worst < 1e-4, `dy/dk is off by ${worst} relative at worst`);

	// The tolerance really is per component: the state block keeps the model's
	// own, and each sensitivity block is that over the size of its parameter.
	const { readFileSync } = await import('node:fs');
	const src = readFileSync(new URL('../src/sim/localsens.js', import.meta.url), 'utf8');
	assert(/const scale = Math\.abs\(P\[wanted\[j\]\.slot\]\) \|\| 1;/.test(src), 'the parameter scale is not read from the run');
	assert(/atol\[n \* \(j \+ 1\) \+ i\] = atolAt\(i\) \/ scale;/.test(src), 'the sensitivity block is not scaled');
	assert(/abstol: atol,/.test(src) && !/abstol: project\.simulation\.abstol,/.test(src),
		'the solve is still given the bare setting');
	// The state block takes the run's own per-compartment tolerances, so the
	// states here are integrated to what the plain run integrates them to.
	assert(/const baseAtol = absoluteTolerance\(project, system\.layout\);/.test(src));
});

test('the blocks renamed keep their old files: every legacy key and the contaminant list migrate', async () => {
	const { migrateKeys } = await import('../src/domain/keys.js');
	const { COLLECTIONS } = await import('../src/domain/systems.js');
	// A model written before the blocks were renamed -- every collection under
	// its old key, the catalogue under Ecolego's name, the recorder fields
	// naming an event rather than a trigger.
	const old = {
		index_lists: [
			{ name: 'Materials', for_materials: true, indices: [{ name: 'Cs-137' }] },
			{ name: 'Radionuclides', for_nuclides: true, sub_set_of: 'Materials', indices: [{ name: 'Cs-137' }] },
		],
		compartments: [{ name: 'Soil', index_lists: ['Materials'], initial: '1',
			entries: [{ index: { Materials: 'Cs-137' }, initial: '5' }] }],
		sources: [{ name: 'Fallout', to: 'Soil', rate: '1' }],
		discrete_events: [{ name: 'Half_way', first: 'time()', second: '50' }],
		snapshots: [{ name: 'Kept', target: 'Soil', event: 'Half_way', initial: '-1' }],
		min_maxes: [{ name: 'Peak', target: 'Soil', reset_event: 'Half_way', start_event: 'Half_way', stop_event: 'Half_way' }],
		running_means: [{ name: 'Mean', target: 'Soil', start_event: 'Half_way' }],
		index_operations: [{ name: 'Total', target: 'Soil', operation: 'sum' }],
		aggregates: [{ name: 'Both', targets: ['Soil'], operation: 'max' }],
		disruptions: [{ name: 'Quake', timing: 'at', at: '10' }],
	};
	const m = migrateKeys(structuredClone(old));

	// Every collection is under the name the interface now uses, and none is
	// left behind under the old one.
	for (const [was, now] of [['sources', 'inflows'], ['discrete_events', 'triggers'],
		['disruptions', 'events'], ['index_operations', 'index_reductions'],
		['aggregates', 'block_reductions']]) {
		assert(Array.isArray(m[now]) && m[now].length === 1, `${was} did not become ${now}`);
		assert(m[was] === undefined, `${was} is still there`);
		assert(COLLECTIONS.includes(now), `${now} is not a collection`);
	}
	// The catalogue is renamed, and so is every reference to it -- the list's
	// own name, the sub-set's parent, a block's dimensions, an entry's index.
	assert(m.index_lists[0].name === 'Contaminants' && m.index_lists[0].for_contaminants === true, JSON.stringify(m.index_lists[0]));
	assert(m.index_lists[0].for_materials === undefined, 'the old flag is still there');
	assert(m.index_lists[1].sub_set_of === 'Contaminants');
	assert(m.compartments[0].index_lists.join() === 'Contaminants');
	assert(Object.keys(m.compartments[0].entries[0].index).join() === 'Contaminants');
	// A discrete event is a trigger, and the fields that name one say so.
	assert(m.snapshots[0].trigger === 'Half_way' && m.snapshots[0].event === undefined, JSON.stringify(m.snapshots[0]));
	assert(m.min_maxes[0].reset_trigger === 'Half_way' && m.min_maxes[0].stop_trigger === 'Half_way');
	assert(m.running_means[0].start_trigger === 'Half_way' && m.running_means[0].start_event === undefined);

	// ...and the whole thing still builds and runs, which is the point.
	const p = new Project({
		...m,
		simulation: { ...DEFAULT_SIMULATION, end_time: 20, output_points: 3, spacing: 'linear' },
		nuclides: ['Cs-137'],
	});
	assert(p.inflows.length === 1 && p.triggers.length === 1 && p.events.length === 1);
	assert(p.materialListName === 'Contaminants', p.materialListName);
	// And it is written back under the new names, not the ones it arrived in.
	const json = p.toJSON();
	assert(json.inflows && !json.sources && json.triggers && !json.discrete_events, Object.keys(json).join());
});

test('a flux says which of the two things its rate is, and in what unit', async () => {
	const { readFileSync } = await import('node:fs');
	const inspector = readFileSync(new URL('../src/ui/inspector.js', import.meta.url), 'utf8');
	// The tick called "Multiply by donor compartment" named the mechanism and
	// hid the consequence: it changes the unit of the equation box above it.
	assert(!/checkField\('Multiply by donor/.test(inspector), 'the checkbox is still there');
	assert(/selectField\('The rate is',/.test(inspector), 'no two-way choice');
	assert(/\['coefficient', `a rate coefficient, in \$\{perTime\}`\]/.test(inspector));
	assert(/\['absolute', `an absolute flux, in \$\{fluxUnit\}`\]/.test(inspector));
	// Both units come from the model's own derivation, so the choice cannot
	// disagree with the unit the flux is actually labelled with.
	assert(/const unitOf = \(byDonorThen\) => ed\.derivedUnit\(/.test(inspector));
	const p = {
		simulation: { time_unit: 'year' }, index_lists: [],
		compartments: [{ name: 'A', unit: 'Bq', index_lists: [] }, { name: 'B', unit: 'Bq', index_lists: [] }],
		transfers: [{ name: 'T', from: 'A', to: 'B', rate: 'k' }],
		parameters: [], expressions: [], inflows: [],
	};
	const t = p.transfers[0];
	assert(ed.derivedUnit(p, { ...t, multiply_by_donor: true }, 'transfer') === '1/year');
	assert(ed.derivedUnit(p, { ...t, multiply_by_donor: false }, 'transfer') === 'Bq/year');
	// A donor whose own unit is a quotient is bracketed, so the flux reads.
	p.compartments[0].unit = 'Bq/m3';
	assert(ed.derivedUnit(p, { ...t, multiply_by_donor: false }, 'transfer') === '(Bq/m3)/year');
});

test('the absolute tolerance can follow the solution, and the Newton test does not follow it', async () => {
	const { variableOrder } = await import('../src/ode/variable-order.js');
	const { readFileSync } = await import('node:fs');
	// A decay chain is the shape this is for: a daughter grows in over orders
	// of magnitude, so a floor fixed before the run holds it to a tolerance
	// that made sense for nothing it ever was.
	const raw = JSON.parse(readFileSync(new URL('../examples/decay-chain.json', import.meta.url), 'utf8'));
	const p = new Project(structuredClone(raw));
	const sys = buildSystem(p);
	const grid = p.timeGrid();
	const y0 = sys.initialState();
	const jac = sys.jacobian.available ? sys.jacobian : null;
	const at = (opts) => variableOrder(sys.dydt, grid, y0, { rtol: p.simulation.rtol, abstol: p.simulation.abstol, jacobian: jac, ...opts });
	const ref = variableOrder(sys.dydt, grid, y0, { rtol: 1e-11, abstol: 1e-14, jacobian: jac });
	const worstAgainstRef = (s2) => {
		const a = s2.y[s2.y.length - 1];
		const b = ref.y[ref.y.length - 1];
		const peak = Math.max(...Array.from(b, Math.abs));
		let w = 0;
		for (let i = 0; i < a.length; i++) {
			if (Math.abs(b[i]) < 1e-12 * peak) continue;
			w = Math.max(w, Math.abs(a[i] - b[i]) / Math.abs(b[i]));
		}
		return w;
	};
	const off = at({ autoUpdateAbsTol: false });
	const on = at({ autoUpdateAbsTol: true });
	// Much cheaper, for the same answer: 1,973 steps against 512 when measured.
	assert(on.stats.nsteps < off.stats.nsteps * 0.5, `${on.stats.nsteps} against ${off.stats.nsteps}`);
	assert(worstAgainstRef(on) < 1e-6 && worstAgainstRef(off) < 1e-6,
		`${worstAgainstRef(on)} vs ${worstAgainstRef(off)}`);

	// What it costs, on a model where a nuclide peaks and then decays away:
	// its tolerance floated up with its own history and its tail is no longer
	// controlled. This is the reason the switch is off by default, and the
	// number in its tooltip -- so it is checked rather than remembered.
	const bio = new Project(JSON.parse(readFileSync(new URL('../examples/biosphere.json', import.meta.url), 'utf8')));
	const bsys = buildSystem(bio);
	const bgrid = bio.timeGrid();
	const by0 = bsys.initialState();
	const bjac = bsys.jacobian.available ? bsys.jacobian : null;
	const bref = variableOrder(bsys.dydt, bgrid, by0, { rtol: 1e-11, abstol: 1e-14, jacobian: bjac });
	const bon = variableOrder(bsys.dydt, bgrid, by0, { rtol: 1e-6, abstol: 1e-9, jacobian: bjac, autoUpdateAbsTol: true });
	const repo = bsys.layout.states.find((x) => x.name === 'Repository');
	const want = bref.y[bref.y.length - 1][repo.base + 1];
	const got = bon.y[bon.y.length - 1][repo.base + 1];
	assert(Math.abs(got / want - 1) > 0.5,
		`the documented loss of the decayed tail is gone: ${got} against ${want}`);

	// The Newton iteration keeps the tolerance the run started with: the error
	// test asks whether a component is accurate enough, where its history is a
	// fair measure, and the Newton test asks how well a stage has been solved,
	// where it is not. Off, the two share one array and nothing is copied.
	const ndf = readFileSync(new URL('../src/ode/solvers/ndf.js', import.meta.url), 'utf8');
	assert(/const newtonThreshold = o\.autoAbstol \? threshold\.slice\(\) : threshold;/.test(ndf));
	assert(/const newtonWeight = o\.autoAbstol \? new Weighting\(neq, newtonThreshold, o\.normControl, rms\) : errorWeight;/.test(ndf));
	assert(/const size = newtonWeight\.of\(delta\);/.test(ndf), 'the Newton test still reads the floating weights');
	assert(/const roundoff = 100 \* EPS \* newtonWeight\.of\(ynew\);/.test(ndf));

	// And it is a setting of the model: normalised, carried to the solver,
	// part of what the trajectory is a function of, and written into the log.
	assert(new Project({ simulation: { ...DEFAULT_SIMULATION, auto_abstol: 'true' } }).simulation.auto_abstol === true);
	assert(new Project({ simulation: { ...DEFAULT_SIMULATION } }).simulation.auto_abstol === false);
	const runner = readFileSync(new URL('../src/sim/runner.js', import.meta.url), 'utf8');
	assert(/autoUpdateAbsTol: project\.simulation\.auto_abstol === true,/.test(runner));
	const { integrationFingerprint } = await import('../src/domain/fingerprint.js');
	const base = { simulation: { ...DEFAULT_SIMULATION }, compartments: [{ name: 'A', initial: '1' }] };
	assert(integrationFingerprint(base)
		!== integrationFingerprint({ ...base, simulation: { ...base.simulation, auto_abstol: true } }),
	'a run with it is the same run without it');
});

section('the ported DifferentialEquations.jl solvers');

test('every ported method integrates a closed-form problem to the tolerance asked', async () => {
	const { julia } = await import('../src/ode/julia-solvers.js');
	const ids = ['fbdf', 'qndf', 'rodas5p', 'radau5', 'kencarp4', 'trbdf2'];
	// A stiff pair with a known solution: y1' = -1000(y1 - cos t) - sin t and
	// y2' = -y2, so y1 -> cos t after a transient of 1/1000 and y2 = e^-t.
	const f = (t, y, out) => {
		out[0] = -1000 * (y[0] - Math.cos(t)) - Math.sin(t);
		out[1] = -y[1];
		return out;
	};
	const grid = Float64Array.from({ length: 21 }, (_, i) => i * 0.5);
	const y0 = Float64Array.from([1, 1]);
	for (const id of ids) {
		const s = julia(id)(f, grid, y0, { rtol: 1e-8, abstol: 1e-10 });
		assert(s.t.length === grid.length, `${id}: ${s.t.length} rows for ${grid.length} points`);
		assert(Math.abs(s.t[s.t.length - 1] - 10) < 1e-12, `${id}: ends at ${s.t[s.t.length - 1]}`);
		const last = s.y[s.y.length - 1];
		// TRBDF2 is second order and says so in its blurb; it is held to less.
		const tol = id === 'trbdf2' ? 2e-4 : 1e-6;
		assert(Math.abs(last[0] - Math.cos(10)) < tol, `${id}: y1 ${last[0]} against ${Math.cos(10)}`);
		assert(Math.abs(last[1] / Math.exp(-10) - 1) < tol, `${id}: y2 off by ${last[1] / Math.exp(-10) - 1}`);
		assert(s.stats.nsteps > 0 && s.stats.solver === id && s.stats.nfevals > 0, JSON.stringify(s.stats));
	}
});

test('a ported method takes this tool’s analytic Jacobian, and may decline a point', async () => {
	const { julia } = await import('../src/ode/julia-solvers.js');
	const raw = {
		name: 'j', simulation: { ...DEFAULT_SIMULATION, time_unit: 'year', start_time: 0,
			end_time: 100, output_points: 6, spacing: 'linear', rtol: 1e-8, abstol: 1e-10 },
		index_lists: [], expressions: [], inflows: [],
		parameters: [{ name: 'k', value: 0.05, index_lists: [] }],
		compartments: [{ name: 'A', initial: '10', index_lists: [] }, { name: 'B', initial: '0', index_lists: [] }],
		transfers: [{ name: 'T', from: 'A', to: 'B', rate: 'k', index_lists: [] }],
	};
	const p = new Project(raw);
	const sys = buildSystem(p);
	const grid = p.timeGrid();
	const y0 = sys.initialState();
	assert(sys.jacobian.available, 'the model has no analytic Jacobian to hand over');

	// With it and without it, the same answer: A = 10 e^{-kt}.
	for (const jacobian of [sys.jacobian, null]) {
		const s = julia('radau5')(sys.dydt, grid, y0, { rtol: 1e-8, abstol: 1e-10, jacobian });
		const a = s.y[s.y.length - 1][0];
		assert(Math.abs(a / (10 * Math.exp(-0.05 * 100)) - 1) < 1e-6, `${a}`);
	}
	// A Jacobian that declines a point answers `false`, and the package
	// differences that one call rather than taking a matrix it was not given.
	let declined = 0;
	const fickle = {
		pattern: sys.jacobian.pattern,
		evaluate: (t, y) => (t > 50 ? (declined++, null) : sys.jacobian.evaluate(t, y)),
	};
	const s = julia('radau5')(sys.dydt, grid, y0, { rtol: 1e-8, abstol: 1e-10, jacobian: fickle });
	assert(declined > 0, 'the fickle Jacobian was never asked after t = 50');
	assert(Math.abs(s.y[s.y.length - 1][0] / (10 * Math.exp(-5)) - 1) < 1e-6,
		`declining a point changed the answer: ${s.y[s.y.length - 1][0]}`);
});

test('every ported method says where it has got to, and stops when told to', async () => {
	// The `onStep` this tool hands a solver -- `(fraction, nsteps, t)`,
	// answering false to stop -- reached none of the ported six: the wrapper
	// read `onProgress` and `signal`, which are the names the *runner's* caller
	// uses and are not among the options a solver is given. So the bar never
	// moved and Stop did nothing, on every model, for all six. It showed up on
	// a model of 55 000 states where a run is an hour: a page saying "Solving…"
	// with no way out of it. Tested through `run`, because the mismatch was
	// between two layers and a unit test of either would have passed.
	const ids = ['fbdf', 'qndf', 'rodas5p', 'radau5', 'kencarp4', 'trbdf2'];
	const raw = {
		name: 'p', simulation: { ...DEFAULT_SIMULATION, time_unit: 'year', start_time: 0,
			end_time: 200, output_points: 21, spacing: 'linear', rtol: 1e-8, abstol: 1e-10 },
		index_lists: [], expressions: [], inflows: [],
		parameters: [{ name: 'k', value: 0.05, index_lists: [] }],
		compartments: [{ name: 'A', initial: '10', index_lists: [] }, { name: 'B', initial: '0', index_lists: [] }],
		transfers: [{ name: 'T', from: 'A', to: 'B', rate: 'k', index_lists: [] }],
	};
	for (const id of ids) {
		const model = structuredClone(raw);
		model.simulation.solver = id;

		let calls = 0;
		let far = 0;
		run(model, { onProgress: (f) => { calls++; far = Math.max(far, f); } });
		assert(calls > 0, `${id} never said where it had got to`);
		assert(far > 0.5, `${id} reported at most ${far} of the way through`);

		// And the answer to it is obeyed: a caller that aborts gets the abort
		// every other solver here throws, not a truncated run handed back as
		// though it were a result.
		const ac = new AbortController();
		let stopped = 0;
		let error = null;
		try {
			run(model, { signal: ac.signal, onProgress: () => { if (++stopped === 3) ac.abort(); } });
		} catch (e) { error = e; }
		assert(error && /aborted/i.test(error.message), `${id} ran on: ${error?.message ?? 'no error'}`);
		assert(stopped < calls, `${id} stopped no earlier than a whole run`);
	}
});

test('the ported methods agree with variableOrder on the bundled models, events and all', async () => {
	const { readFileSync } = await import('node:fs');
	const ids = ['rodas5p', 'radau5', 'fbdf', 'qndf', 'kencarp4'];
	for (const file of ['biosphere.json', 'decay-chain.json', 'recorders.json']) {
		const raw = JSON.parse(readFileSync(new URL(`../examples/${file}`, import.meta.url), 'utf8'));
		const base = run(structuredClone(raw));
		const outputs = base.outputs();
		// One series worth comparing: the largest thing the model reports.
		const pick = outputs.reduce((best, o) => {
			const v = Math.abs(base.series(o)[base.t.length - 1] ?? 0);
			return v > (best?.v ?? -1) ? { o, v } : best;
		}, null);
		assert(pick && pick.v > 0, `${file}: nothing to compare`);
		const want = base.series(pick.o)[base.t.length - 1];
		for (const id of ids) {
			const m = structuredClone(raw);
			m.simulation.solver = id;
			const r = run(m);
			assert(r.t.length === base.t.length, `${file} ${id}: ${r.t.length} rows against ${base.t.length}`);
			const got = r.series(r.outputs().find((o) => o.label === pick.o.label))[r.t.length - 1];
			assert(Math.abs(got / want - 1) < 1e-3,
				`${file} ${id}: ${pick.o.label} is ${got}, variableOrder says ${want}`);
			assert(r.stats.solver === id, `${file} ${id}: reported ${r.stats.solver}`);
		}
		// A model with discrete events stops at them whatever the solver.
		if (file === 'recorders.json') {
			for (const id of ids) {
				const m = structuredClone(raw);
				m.simulation.solver = id;
				assert(run(m).stats.events >= 1, `${id} missed the event`);
			}
		}
	}
});

test('the adapter passes only the options it was given', async () => {
	const { readFileSync } = await import('node:fs');
	const src = readFileSync(new URL('../src/ode/julia-solvers.js', import.meta.url), 'utf8');
	// The package merges what it is handed over its own defaults, so a key
	// present and `undefined` replaces the default rather than leaving it --
	// `dtmax: undefined` made every step size a NaN and the run never left t0.
	assert(/if \(opts\.hmax > 0\) settings\.dtmax = opts\.hmax;/.test(src), 'dtmax is set unconditionally again');
	assert(/if \(opts\.h0 > 0\) settings\.dt = opts\.h0;/.test(src));
	assert(!/dtmax: opts\.hmax > 0 \? opts\.hmax : undefined/.test(src));
	// And the solvers are in the catalogue, all local, with the ids the runner knows.
	const { SOLVER_INFO, LOCAL_SOLVER_IDS } = await import('../src/ode/solvers.js');
	for (const id of ['fbdf', 'qndf', 'rodas5p', 'radau5', 'kencarp4', 'trbdf2']) {
		assert(SOLVER_INFO[id] && SOLVER_INFO[id].label && SOLVER_INFO[id].blurb, `${id} is not in the catalogue`);
		assert(!SOLVER_INFO[id].remote && LOCAL_SOLVER_IDS.includes(id), `${id} is not local`);
	}
	const runner = readFileSync(new URL('../src/sim/runner.js', import.meta.url), 'utf8');
	for (const id of ['fbdf', 'qndf', 'rodas5p', 'radau5', 'kencarp4', 'trbdf2']) {
		assert(new RegExp(`${id}: julia\\('${id}'\\)`).test(runner), `${id} is not wired to the runner`);
	}
});

test('the NDF reads facsimile\'s error norm, iteration matrix and steps at the floor', async () => {
	const { readFileSync } = await import('node:fs');
	const { ndf } = await import('../src/ode/solvers/ndf.js');
	const { solverOptions } = await import('../src/ode/solvers.js');
	for (const key of ['error_norm', 'matrix', 'below_tol_run']) {
		assert(solverOptions('ndf').includes(key), `the NDF does not read ${key}`);
	}
	const last = (r) => { const o = r.outputs(); const v = r.series(o[o.length - 1]); return v[v.length - 1]; };
	const far = JSON.parse(readFileSync(new URL('../examples/farfield.json', import.meta.url), 'utf8'));
	far.simulation.solver = 'ndf';
	const at = (patch) => { const m = structuredClone(far); Object.assign(m.simulation, patch); return run(m); };
	const auto = at({});
	// The root mean square is the looser of the two norms: fewer steps, the same answer.
	const rms = at({ error_norm: 'rms' });
	assert(rms.stats.nsteps < auto.stats.nsteps, `rms took ${rms.stats.nsteps} steps against ${auto.stats.nsteps}`);
	close(last(rms), last(auto), 1e-6, 'the rms run');
	// Dense where auto is sparse, and the same numbers.
	const dense = at({ matrix: 'dense' });
	assert(auto.stats.sparse && !dense.stats.sparse, 'dense LU was asked for and not given');
	close(last(dense), last(auto), 1e-6, 'the dense run');
	// ...and sparse where auto would not be, on a model too small to be worth it.
	const chain = JSON.parse(readFileSync(new URL('../examples/decay-chain.json', import.meta.url), 'utf8'));
	chain.simulation.solver = 'ndf';
	const alone = run(chain);
	assert(!alone.stats.sparse, 'the decay chain is sparse on its own now; pick a smaller model');
	chain.simulation.matrix = 'sparse';
	const asked = run(chain);
	assert(asked.stats.sparse, 'sparse LU was asked for and not given');
	close(last(asked), last(alone), 1e-9, 'the sparse run');

	// Steps at the floor. At t = 1e15 the smallest step is about a fifth of a
	// unit of time, and an oscillation a thousand times faster fails the error
	// test at every size -- so each step is one at the floor.
	const floorSteps = (belowTolRun) => {
		let n = 0;
		try {
			ndf((t, y) => [Math.sin(1e3 * t)], [1e15, 1e15 + 1000], [0], {
				rtol: 1e-6, abstol: 1e-9, onAccepted: () => { n++; },
				...(belowTolRun === undefined ? {} : { belowTolRun }),
			});
		} catch (e) {
			assert(e.code === 'tolerance', `${e.code}: ${e.message}`);
			return n;
		}
		return Infinity;
	};
	// Unset is the NDF's own rule, which every run before the setting had:
	// twenty failed error tests at the floor, then stop.
	assert(floorSteps(undefined) === 20, `the NDF's own rule took ${floorSteps(undefined)}`);
	// Set, it is facsimile's: that many in a row, and 0 for none.
	for (const n of [0, 1, 3]) assert(floorSteps(n) === n, `below_tol_run ${n} took ${floorSteps(n)}`);
	// And the setting reaches the NDF from a model.
	const vo = readFileSync(new URL('../src/ode/variable-order.js', import.meta.url), 'utf8');
	for (const key of ['errorNorm', 'matrix', 'belowTolRun']) {
		assert(new RegExp(`\\.\\.\\.\\(opts\\.${key}`).test(vo), `variableOrder does not pass ${key}`);
	}
});

test('a switch shows the setting it controls, whichever way the setting defaults', async () => {
	const { readFileSync } = await import('node:fs');
	const app = readFileSync(new URL('../src/ui/app.js', import.meta.url), 'utf8');
	// `sim[key] !== false` is right only for a switch that is on when a model
	// says nothing. The two opt-in ones are off then, and reading them that way
	// drew them ticked while the run had them off.
	assert(/const checked = on \? sim\[key\] !== false : sim\[key\] === true;/.test(app),
		'the switch is read one way for both kinds again');
	// ...and it is only offered where it does something: the floating tolerance
	// is an NDF idea, and rosenbrock23 and dormandPrince have no equivalent. A switch that
	// silently does nothing on the solver you happen to have chosen is worse
	// than no switch -- on the bundled biosphere, whose solver is rosenbrock23, it
	// changed nothing at all and said nothing about why.
	const { solverFloatsAbsTol } = await import('../src/ode/solvers.js');
	assert(solverFloatsAbsTol('ndf') && solverFloatsAbsTol('rodas5p') && solverFloatsAbsTol('fbdf'));
	assert(!solverFloatsAbsTol('ros23') && !solverFloatsAbsTol('dp45') && !solverFloatsAbsTol('scipy_bdf'));
	// The switch is not drawn at all for a solver that cannot do it -- the
	// panel builds its rows from `solverOptions(id)` -- and the line under
	// them names what was left out, so it is missing rather than silently dead.
	const { solverOptions, solverIgnores, SOLVER_OPTION_INFO } = await import('../src/ode/solvers.js');
	assert(solverOptions('ndf').includes('auto_abstol'));
	assert(!solverOptions('ros23').includes('auto_abstol'));
	assert(solverIgnores('ros23').includes('letting the absolute tolerance follow the solution'));
	assert(/const keys = solverOptions\(id\);/.test(app), 'the panel no longer asks which settings apply');
	assert(/does not read \$\{list\}/.test(app), 'the dropped settings are not named');
	// And the claim it is greyed out for is true: the solvers that honour it
	// take fewer steps with it on, and the ones that do not are unmoved.
	const { readFileSync: read2 } = await import('node:fs');
	const chain = JSON.parse(read2(new URL('../examples/decay-chain.json', import.meta.url), 'utf8'));
	const steps = (solver, auto) => {
		const m = structuredClone(chain);
		m.simulation.solver = solver;
		m.simulation.auto_abstol = auto;
		return run(m).stats.nsteps;
	};
	for (const solver of ['ndf', 'rodas5p']) {
		assert(steps(solver, true) < steps(solver, false) * 0.6, `${solver} was not helped`);
	}
	assert(steps('ros23', true) === steps('ros23', false), 'rosenbrock23 moved, so it does honour it');

	// The two written into the panel by hand say which way they default...
	for (const [key, absentIsOn] of [['non_negative', true], ['mass_balance', false]]) {
		const decl = new RegExp(`boolField\\('${key}', \\{([\\s\\S]{0,60})`).exec(app);
		assert(decl, `${key} has no switch`);
		assert(/on: false/.test(decl[1]) === !absentIsOn, `${key}: the switch and the setting disagree`);
	}
	// ...and a solver setting says it in the one table that describes it.
	assert(SOLVER_OPTION_INFO.auto_abstol.kind === 'switch' && SOLVER_OPTION_INFO.auto_abstol.on === false,
		JSON.stringify(SOLVER_OPTION_INFO.auto_abstol));
	assert(/box\.append\(boolField\(key, \{ on: info\.on, title \}\)\);/.test(app),
		'the dynamic block no longer takes the default from the table');
	// What each switch claims is what a Project actually does.
	for (const [key, absentIsOn] of [['non_negative', true], ['mass_balance', false], ['auto_abstol', false]]) {
		const p = new Project({ simulation: { ...DEFAULT_SIMULATION } });
		assert((p.simulation[key] !== false) === absentIsOn, `${key}: the model default moved`);
	}
});

test('the plain BDFs are the NDF with its switch on, and QBDF is QNDF with it', async () => {
	const { readFileSync } = await import('node:fs');
	const { SOLVER_INFO, SOLVER_OPTION_INFO, solverOptions, solverFloatsAbsTol, SOLVER_IDS: ids } =
		await import('../src/ode/solvers.js');
	// One entry in the list, and a switch under Advanced settings -- off,
	// since the NDFs are the better formulas -- on the two methods that have
	// the choice.
	assert(!SOLVER_INFO.bdf && !ids.includes('bdf'), 'bdf is still offered as a solver of its own');
	assert(SOLVER_OPTION_INFO.bdf?.kind === 'switch' && SOLVER_OPTION_INFO.bdf.on === false,
		'the BDF switch is not a switch, off');
	assert(solverOptions('ndf').includes('bdf') && solverOptions('qndf').includes('bdf'),
		'the BDF switch is not offered on the NDF and QNDF');
	for (const id of ['fbdf', 'ros23', 'dp45', 'rodas5p', 'radau5', 'kencarp4', 'trbdf2']) {
		assert(!solverOptions(id).includes('bdf'), `the BDF switch is offered on ${id}, which has none`);
	}
	// It is the same code: the switch sets the kappa terms to zero, which is
	// exactly what makes an NDF a BDF, and is what odeset('BDF','on') does.
	const ndf = readFileSync(new URL('../src/ode/solvers/ndf.js', import.meta.url), 'utf8');
	assert(/const kappa = o\.bdf \? 0 : KAPPA\[k - 1\];/.test(ndf), 'the BDF flag no longer zeroes kappa');
	// The same error test, so the tolerance floats either way.
	assert(solverFloatsAbsTol('ndf'));

	// Same answer, and the kappa terms are worth a few steps -- which is why
	// the switch is there: running with and without it says what they buy.
	const raw = JSON.parse(readFileSync(new URL('../examples/biosphere.json', import.meta.url), 'utf8'));
	const at = (solver, bdf) => {
		const m = structuredClone(raw);
		m.simulation.solver = solver;
		m.simulation.bdf = bdf;
		const r = run(m);
		const o = r.outputs().find((x) => x.label === 'Well [I-129]');
		assert(o, 'the model stopped reporting the series this test reads');
		return { steps: r.stats.nsteps, solver: r.stats.solver, end: r.series(o)[r.t.length - 1] };
	};
	const a = at('ndf', false);
	const b = at('ndf', true);
	// Each reports the formulas it ran, not the entry it was chosen under.
	assert(a.solver === 'ndf' && b.solver === 'bdf', `${a.solver} / ${b.solver}`);
	assert(a.end > 0 && Math.abs(b.end / a.end - 1) < 1e-4, `${b.end} against ${a.end}`);
	assert(b.steps > a.steps, `the NDF terms bought nothing: ${a.steps} against ${b.steps}`);
	const q = at('qndf', false);
	const qb = at('qndf', true);
	assert(q.solver === 'qndf' && qb.solver === 'qbdf', `${q.solver} / ${qb.solver}`);
	assert(Math.abs(qb.end / q.end - 1) < 1e-3 && qb.steps !== q.steps,
		`QBDF is not QNDF with kappa off: ${qb.end} in ${qb.steps} steps against ${q.end} in ${q.steps}`);

	// A file that names the old solver runs what it asked for: the NDF
	// integrator with every kappa zero, which is the same code bit for bit.
	const old = structuredClone(raw);
	old.simulation.solver = 'bdf';
	const p = new Project(old);
	assert(p.simulation.solver === 'ndf' && p.simulation.bdf === true,
		`solver 'bdf' opened as ${p.simulation.solver}, bdf ${p.simulation.bdf}`);
	const older = structuredClone(raw);
	older.simulation.solver = 'ode15s_bdf';
	assert(new Project(older).simulation.bdf === true, 'the oldest name of the BDF solver lost its switch');
	const r = run(old);
	const o = r.outputs().find((x) => x.label === 'Well [I-129]');
	assert(r.series(o)[r.t.length - 1] === b.end && r.stats.nsteps === b.steps,
		'a file naming bdf does not run what the switch runs');
	// Off unless a file says so, as a boolean however it is spelt.
	assert(new Project(structuredClone(raw)).simulation.bdf === false);
	const spelt = structuredClone(raw);
	spelt.simulation.bdf = 'true';
	assert(new Project(spelt).simulation.bdf === true);

	// And it is part of what the trajectory is a function of.
	const { integrationFingerprint } = await import('../src/domain/fingerprint.js');
	const base = { simulation: { ...DEFAULT_SIMULATION }, compartments: [{ name: 'A', initial: '1' }] };
	assert(integrationFingerprint(new Project(base))
		!== integrationFingerprint(new Project({ ...base, simulation: { ...base.simulation, bdf: true } })),
	'a run with the BDF formulas is the same run without them');
});

test('a solver’s own settings are offered where they are read, and reach it', async () => {
	const { SOLVER_OPTION_INFO, SOLVER_OPTIONS, solverOptions, solverIgnores, SOLVER_IDS: ids } =
		await import('../src/ode/solvers.js');
	const { readFileSync } = await import('node:fs');

	// Every setting a solver is said to read is one the table describes, and
	// every solver in the catalogue has an entry -- or none, which the SciPy
	// ones have, since they are configured over the wire.
	for (const [id, keys] of Object.entries(SOLVER_OPTIONS)) {
		assert(ids.includes(id), `${id} is not a solver`);
		for (const k of keys) assert(SOLVER_OPTION_INFO[k], `${id} reads '${k}', which nothing describes`);
	}
	for (const [key, info] of Object.entries(SOLVER_OPTION_INFO)) {
		assert(info.label && info.blurb && ['number', 'choice', 'switch'].includes(info.kind), key);
		assert(info.kind !== 'choice' || Array.isArray(info.choices), `${key} is a choice with no choices`);
		// ...and nothing is described that no solver reads.
		assert(Object.values(SOLVER_OPTIONS).some((keys) => keys.includes(key)),
			`'${key}' is described but no solver reads it`);
	}
	// The families differ, which is the whole point of asking per solver.
	assert(!solverOptions('rodas5p').includes('newton_kappa'), 'a Rosenbrock has no Newton to tune');
	assert(!solverOptions('rodas5p').includes('max_jac_age'), 'a Rosenbrock re-forms df/dy every step');
	assert(!solverOptions('radau5').includes('error_norm'), 'Radau uses its own norm');
	assert(!solverOptions('dp45').includes('matrix'), 'a non-stiff solver factorises nothing');
	assert(solverOptions('fbdf').includes('min_order') && !solverOptions('ndf').includes('min_order'));
	/*
	  Taking a stalled Newton correction belongs to the NDF corrector and to
	  nothing else: the ported methods have their own, and the explicit
	  solvers have no corrector at all.

	  What the setting DOES cannot be checked here, and saying so is better
	  than a test that passes whatever it is set to. It only bites where the
	  right-hand side cancels so heavily that a correction cannot shrink any
	  further, and no small system reproduces that -- a linear chain converges
	  in one iteration, a three-species fast equilibrium converges in two, and
	  a scalar equation with a deliberately quantised f converges anyway. It
	  was found, and is demonstrated, on a 35-species spent-fuel dissolution
	  set with constants to 1e16: with the setting at 0 this solver reaches its
	  step budget partway through and stops; at 0.5 the same run finishes in
	  under a second and agrees with the reference code. See the note at the
	  stagnation test in ../src/ode/solvers/ndf.js.
	*/
	assert(solverOptions('ndf').includes('stagnation_tol'), 'the NDF corrector cannot be told to take a stalled correction');
	assert(!solverOptions('dp45').includes('stagnation_tol')
		&& !solverOptions('fbdf').includes('stagnation_tol'), 'offered to a solver that does not read it');
	assert(solverIgnores('dp45').includes('the Newton tolerance'));
	assert(solverOptions('scipy_bdf').length === 0 && solverIgnores('scipy_bdf').length > 0);

	// Each one is normalised by the model, refused when it is nonsense...
	const bad = (patch, why) => {
		let caught = null;
		try { new Project({ simulation: { ...DEFAULT_SIMULATION, ...patch } }); } catch (e) { caught = e; }
		assert(caught, `${JSON.stringify(patch)} was accepted`);
		assert(new RegExp(why).test(caught.message), `${caught.message} (wanted ${why})`);
	};
	bad({ max_order: 9 }, 'max order');
	bad({ max_steps: 0 }, 'max steps');
	bad({ newton_kappa: 2 }, 'newton kappa');
	bad({ stagnation_tol: 2 }, 'stagnation tol');
	bad({ matrix: 'banded' }, 'not a matrix');
	bad({ error_norm: 'l2' }, 'not a error norm');
	bad({ min_order: 4, max_order: 2 }, 'lowest order .* is above the highest');
	assert(new Project({ simulation: { ...DEFAULT_SIMULATION, max_order: '3' } }).simulation.max_order === 3,
		'a number written as a string was not read');
	assert(new Project({ simulation: { ...DEFAULT_SIMULATION, max_step: '' } }).simulation.max_step === undefined,
		'an empty setting was kept');

	// ...and reaches the solver, which is what `max_step` never did: it was a
	// setting of the model, in the fingerprint, and read by nothing.
	const raw = JSON.parse(readFileSync(new URL('../examples/biosphere.json', import.meta.url), 'utf8'));
	const steps = (patch) => {
		const m = structuredClone(raw);
		Object.assign(m.simulation, patch);
		return run(m).stats.nsteps;
	};
	const plain = steps({ solver: 'ndf' });
	assert(steps({ solver: 'ndf', max_step: 1000 }) > plain * 2, 'the largest step reached no solver');
	assert(steps({ solver: 'ndf', max_order: 2 }) > plain * 2, 'the order cap reached no solver');
	assert(steps({ solver: 'fbdf', max_order: 2 }) > steps({ solver: 'fbdf' }) * 2, 'the ported methods ignore the order cap');
	let budget = null;
	try { steps({ solver: 'ndf', max_steps: 50 }); } catch (e) { budget = e; }
	assert(budget && /50 steps/.test(budget.message), `the step budget reached no solver: ${budget?.message}`);

	// And they are part of what the trajectory is a function of.
	const { integrationFingerprint } = await import('../src/domain/fingerprint.js');
	const base = { simulation: { ...DEFAULT_SIMULATION }, compartments: [{ name: 'A', initial: '1' }] };
	for (const patch of [{ max_step: 10 }, { max_order: 3 }, { newton_kappa: 1e-4 }, { matrix: 'dense' },
		{ stagnation_tol: 0.5 }]) {
		assert(integrationFingerprint(base)
			!== integrationFingerprint({ ...base, simulation: { ...base.simulation, ...patch } }),
		`${JSON.stringify(patch)} does not change the run`);
	}
});

test('a setting that is not a parameter can still carry a spread, and the spread reaches the sampler', async () => {
	const U = await import('../src/domain/uncertainty.js');
	const { runProbabilistic } = await import('../src/sim/probabilistic.js');

	// Three hundred years, not twenty thousand: over twenty thousand a 30-year
	// nuclide is below the absolute tolerance at every output time, and what
	// the spread was then measured on was the solvers' round-off.
	const model = () => ({
		simulation: {
			...DEFAULT_SIMULATION, end_time: 300, output_points: 9,
			spacing: 'linear', time_unit: 'year',
		},
		nuclides: ['Cs-137'],
		index_lists: [{ name: 'RN', for_contaminants: true, indices: [{ name: 'Cs-137' }] }],
		compartments: [{ name: 'Rock', index_lists: ['RN'], initial: '0' }],
		// What leaves the packages: the rate is the block itself.
		transfers: [{
			name: 'Release', from: 'Canisters', to: 'Rock', rate: 'Canisters',
			multiply_by_donor: false, index_lists: ['RN'],
		}],
		// One number however many nuclides the packages hold, so it carries no
		// index list: the model's default would be the radionuclide one.
		parameters: [{ name: 'canister_life', value: 20000, index_lists: [] }],
		waste_packages: [{
			name: 'Canisters', index_lists: ['RN'], packages: 100,
			failure: 'weibull', fail_start: '0', fail_scale: 'canister_life',
			fail_shape: '2', inventory: '1e12', irf: '0.05',
			degradation_rate: '1e-4',
		}],
	});

	// A literal becomes a parameter carrying the value it had, and the setting
	// is left pointing at it by name.
	{
		const raw = model();
		const W = raw.waste_packages[0];
		const p = U.makeUncertain(raw, W, 'fail_shape', { unit: '' });
		assert(p.name === 'Canisters_fail_shape', p.name);
		assert(String(p.value) === '2', `the value did not travel: ${p.value}`);
		assert(W.fail_shape === 'Canisters_fail_shape', W.fail_shape);
		// One number however many nuclides the packages hold.
		assert((p.index_lists ?? []).length === 0, 'the parameter was given the nuclide list');
		// Asking twice finds the one already there rather than making a second.
		assert(U.makeUncertain(raw, W, 'fail_shape', {}) === p, 'a second parameter was made');
		assert(raw.parameters.filter((x) => x.name === 'Canisters_fail_shape').length === 1);
	}

	// A setting already pointing at a parameter is that parameter's, and the
	// control edits its distribution rather than wrapping it in another.
	{
		const raw = model();
		const W = raw.waste_packages[0];
		const st = U.uncertaintyOf(raw, W, 'fail_scale');
		assert(st.can && st.parameter?.name === 'canister_life', JSON.stringify(st.parameter?.name));
		assert(U.makeUncertain(raw, W, 'fail_scale', {}) === st.parameter);
		assert(raw.parameters.length === 1, 'a parameter was made for a setting that had one');
	}

	// An equation has no one value to give a spread to, and is refused with a
	// reason rather than having its arithmetic replaced.
	{
		const raw = model();
		const W = raw.waste_packages[0];
		W.fail_scale = '2 * canister_life';
		const st = U.uncertaintyOf(raw, W, 'fail_scale');
		assert(!st.can && /equation rather than a number/.test(st.why), st.why);
		let refused = null;
		try { U.makeUncertain(raw, W, 'fail_scale', {}); } catch (e) { refused = e; }
		assert(refused, 'an equation was turned into a parameter');
		assert(W.fail_scale === '2 * canister_life', 'the arithmetic was deleted');
	}

	// A bare name inside a sub-system means the nearer block of that name.
	{
		const raw = model();
		raw.parameters.push({ name: 'canister_life', system: 'Near', value: 500, index_lists: [] });
		raw.waste_packages[0].system = 'Near';
		const found = U.parameterBehind(raw, raw.waste_packages[0], 'canister_life');
		assert(found && String(found.value) === '500', `the root's was taken: ${found?.value}`);
	}

	// The whole point: after this the setting is sampled, ranked and reported
	// exactly as any other parameter is -- nothing downstream knows it came
	// from a waste package.
	{
		const raw = model();
		const W = raw.waste_packages[0];
		U.makeUncertain(raw, W, 'fail_scale', {}).pdf = {
			kind: 'unif', params: { min: 2000, max: 9000 },
		};
		U.makeUncertain(raw, W, 'fail_shape', {}).pdf = {
			kind: 'unif', params: { min: 1.1, max: 4 },
		};
		const out = runProbabilistic(raw, { iterations: 24, seed: 7 });
		const names = out.plan.map((x) => x.name).sort();
		assert(names.join() === 'Canisters_fail_shape,canister_life', names.join());
		for (const col of out.samples) {
			assert(Math.max(...col) - Math.min(...col) > 0, 'a sampled input did not vary');
		}
		// And it moved the answer: a shorter canister life is an earlier
		// release, so what is in the rock is not one number. Checked over the
		// whole grid rather than at the end, where a 30-year nuclide has
		// decayed to nothing in every realisation alike.
		const k = out.outputs.findIndex((o) => o.label === 'Rock [Cs-137]');
		const times = out.t.length;
		const at = (j) => Array.from({ length: out.iterations }, (_, i) => out.values[k][i * times + j]);
		const spread = Array.from({ length: times }, (_, j) => at(j))
			.map((col) => Math.max(...col) / Math.max(Math.min(...col), 1e-300));
		assert(Math.max(...spread) > 1.05,
			`the spread on the packages did not reach the results: ${Math.max(...spread)}`);
		// The packages themselves are reportable, which is the other half of
		// being able to analyse them.
		assert(out.outputs.some((o) => o.kind === 'waste_inventory'),
			'the packages have nothing to plot');
	}

	// Taking it off leaves the value behind, and leaves a parameter somebody
	// else reads alone.
	{
		const raw = model();
		const W = raw.waste_packages[0];
		U.makeUncertain(raw, W, 'fail_shape', {}).pdf = { kind: 'unif', params: { min: 1, max: 3 } };
		U.clearUncertainty(raw, W, 'fail_shape', { referencesTo: ed.referencesTo });
		assert(W.fail_shape === '2', `the value did not come back: ${W.fail_shape}`);
		assert(!raw.parameters.some((x) => x.name === 'Canisters_fail_shape'),
			'a parameter made for one setting outlived it');

		// `canister_life` was written by hand and is read elsewhere too, so
		// clearing its spread clears the spread and nothing else.
		raw.compartments[0].initial = 'canister_life';
		raw.parameters[0].pdf = { kind: 'unif', params: { min: 1, max: 3 } };
		U.clearUncertainty(raw, W, 'fail_scale', { referencesTo: ed.referencesTo });
		assert(!raw.parameters[0].pdf && raw.parameters[0].name === 'canister_life',
			'a hand-written parameter was removed');
		assert(W.fail_scale === 'canister_life', W.fail_scale);
	}

	// The mode selectors are not settings: they are already distributions.
	assert(U.UNCERTAIN_EXCLUDES.has('failure') && U.UNCERTAIN_EXCLUDES.has('timing'));
});

test('a warning is amber in both themes, and every palette defines the same colours', async () => {
	const { readFileSync } = await import('node:fs');
	const css = readFileSync(new URL('../css/app.css', import.meta.url), 'utf8');

	// Three palettes: the light one, the dark one the system asks for, and the
	// dark one chosen on the button. A token missing from the third is invisible
	// until somebody on a light system picks Dark -- which is how `--warn` came
	// to be the light amber there, so a warning badge was the error red.
	const blockAfter = (head) => {
		const at = css.indexOf(head);
		assert(at >= 0, `no ${head}`);
		const from = css.indexOf('{', at) + 1;
		let depth = 1;
		let i = from;
		for (; i < css.length && depth; i++) {
			if (css[i] === '{') depth++;
			else if (css[i] === '}') depth--;
		}
		return css.slice(from, i);
	};
	const names = (text) => new Set((text.match(/^\t*(--[\w-]+):/gm) ?? [])
		.map((l) => l.trim().replace(':', '')));
	const light = names(blockAfter('\n:root {'));
	const systemDark = names(blockAfter('@media (prefers-color-scheme: dark)'));
	const chosenDark = names(blockAfter('\n:root[data-theme="dark"] {'));
	for (const n of systemDark) {
		assert(chosenDark.has(n),
			`${n} is set when the system is dark and not when Dark is chosen`);
	}
	for (const n of chosenDark) {
		assert(systemDark.has(n), `${n} is set only when Dark is chosen`);
	}
	for (const n of systemDark) {
		assert(light.has(n), `${n} is overridden for dark but never defined for light`);
	}

	// Every `--warn*` is defined in all three, since the whole point of the
	// split is that one of them is a fill and one is ink on it.
	for (const n of ['--warn', '--warn-fill', '--warn-glyph', '--warn-bg']) {
		assert(light.has(n) && systemDark.has(n) && chosenDark.has(n), `${n} is not in all three`);
	}

	// And nothing reaches for a `--warn` that does not exist: a fallback literal
	// is a second palette nobody maintains, and the one that was there
	// (`#b45309`) is exactly the colour this is fixing.
	assert(!/var\(--warn[\w-]*,/.test(css),
		'a --warn token is used with a fallback, which is a second palette');

	// A filled warning mark is the fill colour with dark ink on it, not the ink
	// colour with white on it: at thirteen pixels a dark amber circle reads as
	// the red of an error, which is the one thing a warning must not look like.
	const rule = (selector) => {
		const at = css.indexOf(`\n${selector} {`);
		if (at < 0) return null;
		const from = css.indexOf('{', at) + 1;
		return css.slice(from, css.indexOf('\n}', from));
	};
	const tmark = rule('.trow .tmark.is-warning');
	assert(tmark && /background:\s*var\(--warn-fill\)/.test(tmark)
		&& /color:\s*var\(--warn-glyph\)/.test(tmark),
	`the tree's warning dot is not the fill with its own ink: ${tmark}`);
	assert(/\.gnode-problem\.is-warning \.gnode-problem-dot \{ fill: var\(--warn-fill\); \}/.test(css),
		'the diagram badge is not the fill colour');
	assert(/\.gnode-problem\.is-warning \.gnode-problem-mark \{ fill: var\(--warn-glyph\); \}/.test(css),
		'the diagram badge keeps the white glyph an error has');

	// The strip's wash comes from the fill amber. A tenth of the ink amber on a
	// white page is a warm grey-pink, which is what made the warning strip read
	// as a paler error strip.
	const strip = rule('.error.is-warning');
	assert(strip && /background:\s*var\(--warn-bg\)/.test(strip), `the strip wash: ${strip}`);

	// The light amber is yellow rather than orange-red. Hue, because that is
	// what the eye reads at this size: red is near 0 and amber near 40.
	const hueOf = (hex) => {
		const [r, g, b] = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255);
		const max = Math.max(r, g, b);
		const min = Math.min(r, g, b);
		if (max === min) return 0;
		const d = max - min;
		const h = max === r ? ((g - b) / d) % 6 : max === g ? (b - r) / d + 2 : (r - g) / d + 4;
		return ((h * 60) + 360) % 360;
	};
	const valueIn = (text, name) => new RegExp(`${name}:\\s*(#[0-9a-f]{6})`).exec(text)?.[1];
	const lightBlock = blockAfter('\n:root {');
	const warn = valueIn(lightBlock, '--warn');
	const fill = valueIn(lightBlock, '--warn-fill');
	const danger = valueIn(lightBlock, '--danger');
	assert(warn && fill && danger, `${warn} ${fill} ${danger}`);
	assert(hueOf(warn) >= 30 && hueOf(warn) <= 60,
		`--warn is at hue ${hueOf(warn).toFixed(0)}, which is not amber`);
	assert(hueOf(fill) >= 30 && hueOf(fill) <= 55,
		`--warn-fill is at hue ${hueOf(fill).toFixed(0)}, which is not amber`);
	assert(hueOf(warn) - hueOf(danger) > 20,
		`--warn is only ${(hueOf(warn) - hueOf(danger)).toFixed(0)} degrees off --danger`);

	// White has to stay legible on the error mark, and the glyph on the warning
	// one: both carry a character.
	const lum = (hex) => {
		const c = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255)
			.map((v) => (v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4));
		return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
	};
	const ratio = (a, b) => {
		const [hi, lo] = [lum(a), lum(b)].sort((x, y) => y - x);
		return (hi + 0.05) / (lo + 0.05);
	};
	const glyph = valueIn(lightBlock, '--warn-glyph');
	assert(ratio(danger, '#ffffff') >= 4.5, `white on --danger is ${ratio(danger, '#ffffff').toFixed(2)}:1`);
	assert(ratio(fill, glyph) >= 4.5, `--warn-glyph on --warn-fill is ${ratio(fill, glyph).toFixed(2)}:1`);
	assert(ratio(warn, '#ffffff') >= 4.5, `--warn as ink on white is ${ratio(warn, '#ffffff').toFixed(2)}:1`);
});

test('the documents are written in the same symbol notation the blocks are', async () => {
	const md = await import('../src/ui/markdown.js');
	const { readFileSync } = await import('node:fs');

	// A reference table that says T<sub>w</sub> has to *draw* T with a
	// subscript. Printing its own tags is what a reader sees when the renderer
	// does not know the notation the documents are written in.
	const runs = (t) => md.inlineRuns(t);
	assert(JSON.stringify(runs('T<sub>w</sub>'))
		=== JSON.stringify([{ text: 'T' }, { text: 'w', sub: true }]),
	JSON.stringify(runs('T<sub>w</sub>')));
	assert(JSON.stringify(runs('<sup>14</sup>C'))
		=== JSON.stringify([{ text: '14', sup: true }, { text: 'C' }]));

	// The four tags a block's symbol may use, and only those four.
	const flagged = (t, flag) => runs(t).some((r) => r[flag]);
	assert(flagged('<b>x</b>', 'strong') && flagged('<i>x</i>', 'em'));
	assert(runs('<time-unit>constructor</time-unit>').length === 1,
		'an XML element name in prose is being read as markup');

	// Emphasis and a subscript compose, either way round.
	const both = runs('**K<sub>d,f</sub>**');
	assert(both.length === 2 && both[1].sub && both[1].strong, JSON.stringify(both));

	// A code span wins, because the line of the guide that documents the
	// notation writes it in backticks and has to show it rather than draw it.
	assert(JSON.stringify(runs('`k<sub>d</sub>`'))
		=== JSON.stringify([{ text: 'k<sub>d</sub>', code: true }]),
	JSON.stringify(runs('`k<sub>d</sub>`')));

	// An opening tag with no partner is the text it is, not a swallowed rest
	// of the line.
	assert(runs('an unclosed <sub> stays').length === 1);
	// And the partner is the one that closes *this* tag.
	const deep = runs('<sub>a<sub>b</sub>c</sub>d');
	assert(deep[deep.length - 1].text === 'd' && !deep[deep.length - 1].sub,
		JSON.stringify(deep));

	// Nothing in the documents writes a subscript by breaking a code span
	// around it -- `F/T`<sub>`w`</sub> drew as two code spans with the second
	// one raised, which is not what a symbol looks like. Asserted on what the
	// renderer makes of the text rather than on the text: `<sup>14</sup>C`
	// *inside* a code span is the line that documents the notation, and is
	// exactly right.
	const inlines = (block) => {
		if (block.type === 'list') return block.items;
		if (block.type === 'table') return [...block.head, ...block.rows.flat()];
		if (block.type === 'code') return [];
		return [block.text ?? ''];
	};
	for (const file of ['GUIDE.md', 'INTERNALS.md']) {
		const text = readFileSync(new URL(`../${file}`, import.meta.url), 'utf8');
		for (const block of md.parseMarkdown(text)) {
			for (const line of inlines(block)) {
				const bad = runs(line).find((r) => r.code && (r.sub || r.sup));
				assert(!bad, `${file}: a code span inside a subscript — ${line.slice(0, 90)}`);
			}
		}
	}

	// The help pane styles them the way every other panel does: a subscript
	// inside a table row must not push the row's line height around.
	const css = readFileSync(new URL('../css/app.css', import.meta.url), 'utf8');
	const rule = /\n([^\n]*\.help-doc sup, \.help-doc sub[^{]*)\{([^}]*)\}/.exec(css);
	assert(rule && /line-height:\s*0/.test(rule[2]), 'the help pane does not style its subscripts');
});

test('the second skin is tokens only, and defines the same ones in both modes', async () => {
	const { readFileSync } = await import('node:fs');
	const root = new URL('..', import.meta.url);
	const skin = readFileSync(new URL('css/theme-kvotab.css', root), 'utf8');
	const app = readFileSync(new URL('css/app.css', root), 'utf8');

	// The whole point of a second skin is that it is a palette, not a second
	// stylesheet: a rule about a component here is one that has to be kept in
	// step with app.css by hand, and will not be. The two exceptions are the
	// page-chrome inset, which is a layout fact about being embedded and not a
	// colour at all.
	const bare = skin.replace(/\/\*[\s\S]*?\*\//g, '');
	const selectors = [...bare.matchAll(/(^|\n)\s*([^\s@}][^{}\n]*?)\s*\{/g)].map((m) => m[2].trim());
	assert(selectors.length >= 4, `only ${selectors.length} rules: ${selectors}`);
	for (const sel of selectors) {
		// Every rule is behind the attribute, so a page that does not ask for
		// the skin cannot be changed by loading it.
		assert(/\[data-(brand|chrome)="/.test(sel), `${sel} applies without being asked for`);
		// And a palette rule targets the root and nothing else: a rule about a
		// component is one that has to be kept in step with app.css by hand,
		// and will not be. The exception is the page-chrome inset, which is a
		// layout fact about being embedded rather than a colour.
		const palette = /^:root\[data-brand="[a-z]+"\](:not\(\[data-theme="light"\]\)|\[data-theme="dark"\])?$/;
		assert(palette.test(sel) || /data-chrome/.test(sel),
			`a skin rule that is neither a palette nor the chrome inset: ${sel}`);
	}

	// The three palettes again -- light, the system's dark, and the chosen one
	// -- have to define the same tokens, for the reason app.css's do.
	const blockAfter = (head) => {
		const at = skin.indexOf(head);
		assert(at >= 0, `no ${head}`);
		const from = skin.indexOf('{', at) + 1;
		let depth = 1;
		let i = from;
		for (; i < skin.length && depth; i++) {
			if (skin[i] === '{') depth++;
			else if (skin[i] === '}') depth--;
		}
		return skin.slice(from, i);
	};
	const names = (text) => new Set((text.match(/^\t*(--[\w-]+):/gm) ?? [])
		.map((l) => l.trim().replace(':', '')));
	const light = names(blockAfter(':root[data-brand="kvotab"] {'));
	const systemDark = names(blockAfter('@media (prefers-color-scheme: dark)'));
	const chosenDark = names(blockAfter(':root[data-brand="kvotab"][data-theme="dark"] {'));
	assert(light.size > 15, `${light.size} tokens in the light skin`);
	for (const n of systemDark) assert(chosenDark.has(n), `${n} is missing when Dark is chosen`);
	for (const n of chosenDark) assert(systemDark.has(n), `${n} is set only when Dark is chosen`);
	for (const n of light) assert(systemDark.has(n), `${n} is re-tinted for light and not for dark`);

	// Every token it overrides is one app.css defines: a name invented here
	// styles nothing, and a typo would be invisible.
	const known = new Set((app.match(/^\t(--[\w-]+):/gm) ?? [])
		.map((l) => l.trim().replace(':', '')));
	for (const n of light) assert(known.has(n), `${n} is not a token app.css has`);

	// The colours that carry meaning are not re-tinted. Red is a model that
	// will not run; the series colours were chosen to be told apart.
	for (const n of ['--danger', '--warn', '--warn-fill', '--warn-glyph', '--caution',
		'--series-1', '--series-2', '--series-3', '--series-4']) {
		assert(!light.has(n), `${n} means something and the skin changed it`);
	}

	// The accent must not be mistakable for the danger colour: a ring around a
	// selected block sits beside the ring around a broken one.
	const valueIn = (text, name) => new RegExp(`${name}:\\s*(#[0-9a-f]{6})`).exec(text)?.[1];
	const hueOf = (hex) => {
		const [r, g, b] = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255);
		const max = Math.max(r, g, b);
		const min = Math.min(r, g, b);
		if (max === min) return 0;
		const d = max - min;
		const h = max === r ? ((g - b) / d) % 6 : max === g ? (b - r) / d + 2 : (r - g) / d + 4;
		return ((h * 60) + 360) % 360;
	};
	const lum = (hex) => {
		const c = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255)
			.map((v) => (v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4));
		return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
	};
	const ratio = (a, b) => {
		const [hi, lo] = [lum(a), lum(b)].sort((x, y) => y - x);
		return (hi + 0.05) / (lo + 0.05);
	};
	const appLight = /\n:root \{([\s\S]*?)\n\}/.exec(app)[1];
	for (const [label, block] of [
		['light', blockAfter(':root[data-brand="kvotab"] {')],
		['dark', blockAfter(':root[data-brand="kvotab"][data-theme="dark"] {')],
	]) {
		// A filled control carries a label, so its own ink has to be readable
		// on it. The brand's `#bb6c5d` is 3.88:1 against white, which is why
		// the accent here is one step down from it.
		const accent = valueIn(block, '--accent');
		const on = valueIn(block, '--accent-ink');
		assert(accent && on, `${label}: ${accent} ${on}`);
		assert(ratio(accent, on) >= 4.5,
			`${label}: the accent's own ink is ${ratio(accent, on).toFixed(2)}:1 on it`);
		// The ring around a *selected* block is read against the ring around a
		// *broken* one, on the same canvas at the same moment -- so that one,
		// and not the accent, is the colour that has to be clear of the danger
		// red. The accent itself is the brand's terracotta and is meant to be
		// near it.
		const select = valueIn(block, '--select');
		const danger = valueIn(label === 'light' ? appLight : app, '--danger');
		assert(select, `${label}: no --select`);
		const apart = Math.abs(hueOf(select) - hueOf(danger));
		assert(Math.min(apart, 360 - apart) > 45,
			`${label}: the selection ring is ${apart.toFixed(0)} degrees from --danger`);
	}

	// And `--select` exists in app.css, defaulting to the accent, so every
	// other palette is unchanged by the split.
	assert(/--select: var\(--accent\);/.test(app), 'the selection colour has no default');
	assert(/\.gnode-halo \{[^}]*stroke: var\(--select\)/.test(app),
		'the selection ring does not use it');

	// And the switch is read before the first paint, or the page flashes the
	// default palette on the way in.
	const start = readFileSync(new URL('src/ui/start.js', root), 'utf8');
	assert(/data-brand/.test(start) && /data-chrome/.test(start),
		'the skin is not turned on in the boot script');
	const html = readFileSync(new URL('index.html', root), 'utf8');
	assert(/theme-kvotab\.css/.test(html), 'the skin is not linked');
});

test('a copy reaches the other tabs, and the newer copy is the one that pastes', async () => {
	const clip = await import('../src/ui/clipboard.js');

	// A stand-in for `localStorage`, which is the only thing two tabs of one
	// origin both see. Written against the same interface the real one has, so
	// the module needs no seam of its own.
	const make = (cap = Infinity) => {
		const map = new Map();
		return {
			map,
			getItem: (k) => (map.has(k) ? map.get(k) : null),
			setItem: (k, v) => {
				if (v.length > cap) { const e = new Error('quota'); e.name = 'QuotaExceededError'; throw e; }
				map.set(k, v);
			},
			removeItem: (k) => map.delete(k),
		};
	};
	const payload = {
		kind: 'blocks',
		parts: [],
		blocks: [{ part: -1, name: 'Geosphere', block: { name: 'Geosphere', initial: '0' } }],
		system: '',
		stranded: [],
	};

	const store = make();
	assert(clip.available(store));
	assert(clip.get(store) === null, 'an empty store is not an empty clipboard');

	const out = clip.put(payload, { model: 'Repository to well' }, store);
	assert(out.ok && out.bytes > 0 && Number.isFinite(out.at), JSON.stringify(out));
	const back = clip.get(store);
	assert(back.meta.model === 'Repository to well', JSON.stringify(back.meta));
	assert(back.payload.blocks[0].block.name === 'Geosphere');
	assert(back.at === out.at, 'the record does not carry when it was taken');

	// A deep copy, not the object: the tab that pasted must not be able to
	// edit what the tab that copied still holds.
	back.payload.blocks[0].block.initial = '999';
	assert(payload.blocks[0].block.initial === '0', 'the payload came back by reference');

	// Anything unreadable is nothing rather than a throw three calls later.
	for (const bad of ['', 'not json', '{}', '{"at":1}', '{"at":1,"payload":{}}',
		'{"at":1,"payload":{"blocks":[],"parts":[]}}', '{"at":"soon","payload":{"blocks":[1],"parts":[]}}',
		// A string has a length too, and `pasteBlocks` walks these as arrays.
		'{"at":1,"payload":{"blocks":"xx","parts":[]}}']) {
		store.map.set('boxflow.clipboard.v1', bad);
		assert(clip.get(store) === null, `${bad} came back as a clipboard`);
	}

	// Too large to share: refused, and what was shared before goes with it, so
	// a stale copy is never offered as though it were this one.
	clip.put(payload, {}, store);
	assert(clip.get(store), 'nothing to make stale');
	const big = { ...payload, blocks: [{ part: -1, name: 'X', block: { note: 'x'.repeat(clip.MOST) } }] };
	const refused = clip.put(big, {}, store);
	assert(!refused.ok && /too large/.test(refused.why), JSON.stringify(refused));
	assert(clip.get(store) === null, 'the previous copy survived a refusal');

	// A browser that holds nothing at all turns the feature off, not the editor.
	const dead = {
		getItem: () => { throw new Error('blocked'); },
		setItem: () => { throw new Error('blocked'); },
		removeItem: () => { throw new Error('blocked'); },
	};
	assert(!clip.available(dead));
	assert(clip.get(dead) === null);
	assert(clip.put(payload, {}, dead).ok === false);
	clip.forget(dead);

	// The rule app.js applies: the last thing copied anywhere is the thing
	// that pastes, and this tab's own wins a tie -- it is the copy that is
	// certainly intact, where the shared one is a round-trip through JSON.
	const newerWins = (mineAt, theirsAt) => (mineAt >= theirsAt ? 'mine' : 'theirs');
	assert(newerWins(5, 3) === 'mine');
	assert(newerWins(3, 5) === 'theirs');
	assert(newerWins(4, 4) === 'mine');

	// And that rule is the one in app.js, not a second copy of it here.
	const { readFileSync } = await import('node:fs');
	const app = readFileSync(new URL('../src/ui/app.js', import.meta.url), 'utf8');
	const fn = /function clipboardNow\(\) \{([\s\S]*?)\n\}/.exec(app)?.[1];
	assert(fn, 'there is no one place the two clipboards are compared');
	assert(/mine\.at >= rec\.at/.test(fn), `the tie does not go to this tab: ${fn}`);
	// The menus ask the same question, so a copy in another tab enables Paste.
	assert(/const now = clipboardNow\(\);/.test(app),
		'clipboardInfo does not read the shared copy, so Paste stays greyed out');
	// And a copy is shared as well as kept, not instead of.
	const copy = /function copySelection\(names\) \{([\s\S]*?)\n\}/.exec(app)?.[1] ?? '';
	assert(/state\.clipboard = payload;/.test(copy) && /shared\.put\(payload/.test(copy),
		'the copy is not both kept and shared');
});

test('a specialised block wears its own glyph, and every control takes the theme', async () => {
	const { readFileSync } = await import('node:fs');
	const root = new URL('..', import.meta.url);
	const icons = readFileSync(new URL('src/ui/icons.js', root), 'utf8');
	const graph = readFileSync(new URL('src/ui/graph.js', root), 'utf8');
	const css = readFileSync(new URL('css/app.css', root), 'utf8');

	// The tree and the canvas draw one vocabulary, not two: the glyph is
	// exported from the module that already had it rather than redrawn, so a
	// mark learned in the tree is the mark on the node.
	assert(/export function markPath\(kind\)/.test(icons), 'the marks are not shared');
	assert(/import \{ markPath, MARK_W, MARK_H \} from '\.\/icons\.js';/.test(graph),
		'the diagram does not use the tree’s marks');
	assert(!/const MARKS = \{/.test(graph), 'the diagram has a second copy of the marks');

	// The kinds whose *shape* does not say which block they are: a far-field
	// pathway, a waste package and the three that remember are all rectangles,
	// and a transport is the same folder an ordinary sub-system gets.
	const set = /const GLYPH_KINDS = new Set\(\[([\s\S]*?)\]\)/.exec(graph)?.[1] ?? '';
	for (const kind of ['farfield', 'waste_package', 'min_max', 'running_mean',
		'snapshot', 'transport']) {
		assert(set.includes(`'${kind}'`), `${kind} has no glyph on the canvas`);
	}
	// And not the ones that say it another way: a lookup table draws its own
	// curve, and a glyph on top of that is two pictures in one box.
	assert(!set.includes("'lookup'"), 'a lookup table has a glyph over its sparkline');

	// Every one of those kinds has a mark to draw.
	const { KIND_ICON } = await import('../src/ui/icons.js');
	for (const kind of ['farfield', 'waste_package', 'min_max', 'running_mean',
		'snapshot', 'transport']) {
		assert(KIND_ICON[kind]?.mark, `${kind} is asked for a glyph it has none of`);
	}

	// A transport is a sub-system whose kind is `system`, so it is asked for by
	// the flag rather than by the kind -- which is the one case that would
	// silently draw nothing.
	assert(/n\.kind === 'system' && n\.transport \? 'transport' : n\.kind/.test(graph),
		'a transport would be asked for under the wrong kind');

	// The glyph is dim and does not take clicks: it says what the block is and
	// the name says which one.
	const rule = /\n\.gnode-glyph \{([^}]*)\}/.exec(css)?.[1] ?? '';
	assert(/fill: none/.test(rule) && /stroke: var\(--node-ink-dim\)/.test(rule)
		&& /pointer-events: none/.test(rule), `the glyph rule: ${rule}`);

	// --- and the controls --------------------------------------------------
	//
	// `accent-color` is what paints the tick in a checkbox, the dot in a radio
	// and the bar of a progress element, and it inherits -- so it belongs on
	// the root, once. Set on one rule in the left panel, every other control in
	// the application wore the operating system's blue, which is wrong under any
	// palette and very wrong under one with no blue in it.
	const root_ = /\n:root \{([^}]*accent-color[^}]*)\}/.exec(css)?.[1];
	assert(root_ && /accent-color:\s*var\(--accent\)/.test(root_),
		'the accent is not set for every control at the root');
	const others = [...css.matchAll(/\n([^\n{]*)\{[^}]*accent-color[^}]*\}/g)]
		.map((m) => m[1].trim())
		.filter((sel) => sel !== ':root');
	assert(!others.length, `accent-color is set again on ${others.join(', ')}`);
});

test('Save means save: the file is remembered, and the button says whether there is anything to write', async () => {
	const { readFileSync } = await import('node:fs');
	const root = new URL('..', import.meta.url);
	const app = readFileSync(new URL('src/ui/app.js', root), 'utf8');
	const html = readFileSync(new URL('index.html', root), 'utf8');
	const css = readFileSync(new URL('css/app.css', root), 'utf8');

	// The handle was a local in `saveFile` and went out of scope with it, so
	// every Save for the rest of the session opened the chooser again -- which
	// is what made saving feel like exporting.
	assert(/state\.fileHandle/.test(app), 'the file is not remembered');
	// The *button* opens the Save dialog now -- what to write, in which
	// format, and which of it -- but the **keyboard** still saves. ⌘S writes
	// to the file this model came from with nothing in between: pressing a key
	// called Save should save, and the dialog is for choosing, not for
	// repeating yesterday's choice.
	assert(/\$\('#save'\)\.addEventListener\('click', \(\) => openSave\(\)\)/.test(app),
		'the Save button does not open the dialog');
	assert(/if \(e\.shiftKey\) saveFile\('json'\);\n\t\t\telse saveToFile\(\);/.test(app),
		'⌘S no longer writes straight to the file');
	const saveTo = /async function saveToFile\(\) \{([\s\S]*?)\n\}/.exec(app)?.[1];
	assert(saveTo, 'there is no write-to-the-file-we-have path');
	assert(/createWritable\(\)/.test(saveTo), 'it does not write');
	assert(/await saveFile\('json'\)/.test(saveTo),
		'with no file, and after a failed write, it has to fall back to asking');

	// Saving with the results is a different file *about* the model, not the
	// model, so it must not become the file Save writes to.
	assert(/if \(as !== 'data'\) noteSaved\(handle\)/.test(app),
		'a results archive would become the model’s file');

	// Two questions the button now answers: will it ask, and is there anything
	// to write. Neither was answerable before -- the label never changed and
	// nothing showed unsaved work at all.
	const render = /function renderSaveButton\(\) \{([\s\S]*?)\n\}/.exec(app)?.[1];
	assert(render, 'the button is never redrawn');
	assert(/state\.savedRev !== state\.rev/.test(render), 'unsaved work is not detected');
	assert(/named \? 'Save' : 'Save/.test(render),
		'the ellipsis does not follow whether it will ask');
	assert(/is-unsaved/.test(render) && /#save\.is-unsaved::after/.test(css),
		'there is no mark for unsaved work');
	// And redrawn wherever either answer can change.
	assert(/updateDirtyBadge\(\);\n\t\/\/[^\n]*\n\trenderSaveButton\(\);/.test(app),
		'an edit does not update the button');

	// Opening a model is not the file the last one was in, and is not unsaved
	// work either: it is the model in the file it came from.
	assert(/state\.fileHandle = null;[\s\S]{0,400}?state\.savedRev = state\.rev;/.test(app),
		'opening a model leaves the old file, or claims unsaved work on arrival');

	// The shortcut every editor has, and the modifier that means "somewhere
	// else". Taken before the general modifier gate, which lets shift through.
	const keys = /if \(\(e\.metaKey \|\| e\.ctrlKey\) && !e\.altKey && \(e\.key === 's'[\s\S]{0,260}?\n\t\t\}/.exec(app)?.[0];
	assert(keys, 'there is no save shortcut');
	assert(/e\.preventDefault\(\)/.test(keys), 'the browser’s own Save page would still open');
	assert(/e\.shiftKey\) saveFile\('json'\)/.test(keys), '⇧⌘S does not ask where');
	assert(/else saveToFile\(\)/.test(keys), '⌘S does not write');

	// The button's markup is the state before any of it has happened.
	assert(/id="save"[^>]*>Save…<\/button>/.test(html.replace(/\s+/g, ' ')),
		'the button does not start out saying it will ask');
});

test('what is wrong now, and what was wrong when it last ran, are different questions', async () => {
	const { readFileSync } = await import('node:fs');
	const app = readFileSync(new URL('../src/ui/app.js', import.meta.url), 'utf8');

	// A run's failure is about the model as it was. Deleting the block the
	// message names is the obvious way to answer one -- and the strip went on
	// carrying `Func: has no body yet` over a model with no Func in it, with
	// nothing to click and no way to dismiss it.
	const changed = /function modelChanged\(opts = \{\}\) \{([\s\S]*?)\n\}/.exec(app)?.[1];
	assert(changed, 'there is no one place an edit passes through');
	assert(/state\.runProblem = null;/.test(changed),
		'an edit leaves the last run’s failure on screen');
	// Only a real edit: moving a block is not a reason to forget why the run
	// failed, and it does not move the revision either.
	assert(/if \(!opts\.layoutOnly\) \{[\s\S]*?state\.runProblem = null;[\s\S]*?\n\t\}/.test(changed),
		'a layout-only change clears it too');

	// And a dialog that refuses to open says so. `showError` puts the fault in
	// the strip, which is right -- but where the strip already carries the same
	// one it puts it nowhere, so the button appeared to do nothing at all.
	for (const fn of ['openProbabilistic', 'openLocalSensitivity']) {
		const at = app.indexOf(`function ${fn}() {`);
		assert(at >= 0, `${fn} is gone`);
		const body = app.slice(at, app.indexOf('\n}', at));
		assert(/needs a model that builds/.test(body), `${fn} refuses silently`);
	}
});

test('the sensitivity table says what it was fitted to, and can be asked at the peak', async () => {
	const { readFileSync } = await import('node:fs');
	const root = new URL('..', import.meta.url);
	const dialog = readFileSync(new URL('src/ui/sensdialog.js', root), 'utf8');
	const worker = readFileSync(new URL('src/worker/sim-worker.js', root), 'utf8');
	const app = readFileSync(new URL('src/ui/app.js', root), 'utf8');
	const css = readFileSync(new URL('css/app.css', root), 'utf8');

	// Three translations where there was a tick box, each named for what it
	// does rather than for the acronym it produces.
	const list = /const TRANSLATIONS = \[([\s\S]*?)\n\];/.exec(dialog)?.[1] ?? '';
	for (const k of ['none', 'rank', 'log']) {
		assert(list.includes(`'${k}'`), `${k} is not offered`);
	}
	assert(!/Use ranks/.test(dialog), 'the tick box is still there');
	// And the choice reaches the worker, which takes only what it knows.
	assert(/onAsk\?\.\(\{ index: view\.index, at: atPeak \? 'peak' : view\.at, translate/.test(dialog),
		'the dialog does not send the translation');
	assert(/TRANSLATIONS\.has\(msg\.translate\) \? msg\.translate : 'none'/.test(worker),
		'the worker takes any translation it is handed');

	// "Wherever it peaks" is resolved where the matrix is, and the dialog keeps
	// asking for the peak rather than pinning the index it came back with --
	// so changing the output finds the new output's peak.
	assert(/function peakTime\(values, times, iterations, mask\)/.test(worker),
		'there is no peak time');
	assert(/msg\.at === 'peak'/.test(worker), 'the worker cannot be asked for it');
	assert(/let atPeak = false;/.test(dialog) && /atPeak = pick\.value === 'peak';/.test(dialog),
		'the dialog forgets that the peak was asked for');
	// It is the mean over realisations, not the largest single realisation.
	const peak = /function peakTime[\s\S]*?\n\}/.exec(worker)?.[0] ?? '';
	assert(/sum \+= v;/.test(peak) && /const mean = sum \/ n;/.test(peak),
		`the peak is not of the mean: ${peak.slice(0, 200)}`);
	assert(/if \(mask && !mask\[i\]\) continue;/.test(peak),
		'screened realisations count toward the peak');

	// The coefficient in units, beside the standardized one.
	assert(/coef\(m\.b\?\.\[i\]\)/.test(dialog), 'the unstandardized coefficient is not shown');
	assert(/b: rows\.map\(\(row\) => reg\.b\[row\.k\]\)/.test(worker), 'the worker does not send it');
	// Drawn as a number and not as a bar: it is in units, and a bar against a
	// scale of one would say nothing about any of them.
	assert(/function coef\(v\)/.test(dialog), 'there is no formatter for it');
	assert(!/bar\(m\.b/.test(dialog), 'the coefficient in units is drawn as a bar');

	// R² on its own line. In the row beside the control the sentence wrapped
	// inside a third of the dialog and left the rest of the row empty.
	assert(/className: `sens-r2\$\{m\.ok \? '' : ' is-bad'\}`/.test(dialog),
		'the R² line is not its own paragraph');
	const r2 = /\n\.sens-r2 \{([^}]*)\}/.exec(css)?.[1] ?? '';
	assert(/margin: 2px 0 0/.test(r2) && !/margin-left/.test(r2),
		`the R² line is still inline: ${r2}`);

	// And the translation is passed all the way from the button.
	assert(/function openSensitivity\(at = null, index = null, translate = 'none'\)/.test(app),
		'app.js still speaks of ranks');
});

test('the Chart and the Table say what produced them, and the Chart has a second picture', async () => {
	const { readFileSync } = await import('node:fs');
	const root = new URL('..', import.meta.url);
	const app = readFileSync(new URL('src/ui/app.js', root), 'utf8');
	const html = readFileSync(new URL('index.html', root), 'utf8');
	const css = readFileSync(new URL('css/app.css', root), 'utf8');
	const worker = readFileSync(new URL('src/worker/sim-worker.js', root), 'utf8');
	const view = readFileSync(new URL('src/ui/histview.js', root), 'utf8');

	// --- what ran -----------------------------------------------------------
	//
	// A chart of five curves looks like a chart of five medians from across a
	// desk. Both views say which, in the same words.
	const kind = /function renderRunKind\(\) \{([\s\S]*?)\n\}/.exec(app)?.[1];
	assert(kind, 'nothing says what produced the view');
	for (const phrase of ['One deterministic run', 'realisations', 'Realisation ']) {
		assert(kind.includes(phrase), `the run kind never says ${phrase}`);
	}
	// The fourth state is deliberately silent here. pendingResults() fills the
	// body of both views with it, with the reason and the button; this line
	// repeating the bare fact put it above the only thing that could act on it.
	assert(!/Nothing has run yet/.test(kind),
		'the run kind repeats what the body already says');
	assert(/for \(const id of \['#chart-what', '#table-what'\]\)/.test(kind),
		'the two views do not say the same thing');
	assert(/id="chart-what"/.test(html) && /id="table-what"/.test(html), 'neither line exists');
	// And a model that could be run probabilistically says so where the reader
	// is looking, since that is the run nobody knows is there.
	assert(/ed\.hasDistributions\(state\.raw\)/.test(kind),
		'a model with distributions is not told it could be sampled');

	// The table gained a line above it, so its body is its own element --
	// `drawTable` used to empty the whole panel on every redraw.
	assert(/const wrap = \$\('#table-body'\);/.test(app), 'the table still empties its panel');
	assert(/id="table-body"/.test(html), 'the table has no body of its own');

	// --- the second picture -------------------------------------------------
	assert(/state\.chartMode/.test(app) && /id="chart-mode"/.test(html),
		'there is no mode control');
	// Only where there are realisations to take a distribution of.
	const showing = /function showingDistribution\(\) \{([\s\S]*?)\n\}/.exec(app)?.[1] ?? '';
	assert(/state\.chartMode === 'dist' && !!currentProb\(\)/.test(showing),
		`the mode does not require a sample: ${showing}`);
	// Whether the chart element is on screen stays one decision in one place.
	const chart = /function renderChart\(\) \{([\s\S]*?)\n\}/.exec(app)?.[1] ?? '';
	assert(!/\$\('#chart'\)\.hidden = false/.test(chart),
		'renderChart shows the chart itself again');
	assert(/showingSample\(\)/.test(/function renderStaleness\(\)[\s\S]*?\n\}/.exec(app)?.[0] ?? ''),
		'the staleness rule does not know about the pictures that replace the curves');

	// The rule the user asked for: after a probabilistic run, a selection that
	// is all time-invariant opens as a distribution -- a band over a quantity
	// that does not vary is a flat line saying only that it is flat.
	//
	// Decided in `renderResults`, not when the run lands: pressing
	// Probabilistic… on a model that has never been run takes its selection
	// from the ordinary run that follows, so at the moment the sample arrives
	// there is nothing selected to decide about.
	const render = /function renderResults\(\) \{([\s\S]*?)\n\}/.exec(app)?.[1] ?? '';
	assert(/if \(allConstant\(\)\) state\.chartMode = 'dist';/.test(render),
		'a run of nothing but parameters still opens as curves');
	assert(/state\.probModeFor !== prob\.runId/.test(render),
		'the picture is chosen again on every redraw, so choosing the other one does not stick');
	const accept = /function acceptProbabilistic\(payload, runId\) \{([\s\S]*?)\n\}/.exec(app)?.[1] ?? '';
	assert(/state\.hist = null;/.test(accept), 'the last run’s histograms survive the next run');
	// A parameter says it outright -- the worker knows, because its value is
	// its slot -- and anything else is read off its own curve.
	const allc = /function allConstant\(\) \{([\s\S]*?)\n\}/.exec(app)?.[1] ?? '';
	assert(/outs\[i\]\?\.constant != null/.test(allc), `a parameter is not recognised: ${allc}`);
	assert(/Math\.abs\(v\[j\] - v\[0\]\)/.test(allc),
		'a quantity that is flat without being a parameter is not recognised');
	// Read off the run's own median, which is in hand: the deterministic
	// column is fetched from the worker when something asks for it, and at the
	// moment this is decided it is still a placeholder.
	assert(/prob\.bands\?\.\[k\]\?\.q\?\.\[mid\]/.test(allc),
		'flatness is read from a column that has not arrived yet');
	assert(/constant: results\.constantOf\(o\)/.test(worker), 'the worker does not send it');

	// And a probabilistic run on a model that has never been run: it used to
	// read `state.results.outputs` of null and throw, taking the bands, the
	// statistics and the picker down with it.
	assert(/if \(!state\.results\) \{\n\t\trenderChart\(\);/.test(app),
		'renderResults still assumes there are results');
	assert(/const outs = state\.results\?\.outputs \?\? \[\];/.test(app),
		'pickDefaultSeries still assumes there are results');
	// One deterministic run is started when there is none *or* when the one on
	// screen is of an older model — a band belongs under its own line or under
	// none, so a sample landing on a stale run would otherwise finish and show
	// nothing at all. Which is what an import does: it moves the revision.
	assert(/if \(!state\.running && \(!state\.results \|\| state\.results\.rev !== state\.rev\)\) \{[\s\S]{0,400}?runSimulation\(\{ manual: true \}\);/
		.test(accept), 'a probabilistic run with nothing current behind it draws nothing');

	// The answer is keyed on what it answers, so switching back to a picture
	// already drawn costs nothing and a stale one is never shown.
	const ask = /function askHistograms\(\) \{([\s\S]*?)\n\}/.exec(app)?.[1] ?? '';
	assert(/const key = `\$\{prob\.runId\}\|\$\{at\}\|/.test(ask), `no key on the answer: ${ask}`);
	assert(/if \(state\.hist\?\.key === key\) return;/.test(ask), 'it asks again for what it has');
	assert(/type: 'prob-hist'/.test(worker), 'the worker cannot be asked');

	// Small multiples, capped, and the cap is said rather than silently
	// dropping series the reader ticked.
	assert(/export const MOST_PANELS/.test(view), 'there is no cap');
	assert(/more \? ` \$\{more\.toLocaleString\(\)\} more series are selected/.test(view),
		'series past the cap vanish silently');
	assert(/\.hist-grid \{[^}]*repeat\(auto-fill/.test(css), 'the panels are not a grid');
});

test('every reply about the sample survives a later run', async () => {
	const { messageIsCurrent } = await import('../src/ui/app.js');
	const { readFileSync } = await import('node:fs');
	const app = readFileSync(new URL('../src/ui/app.js', import.meta.url), 'utf8');
	const worker = readFileSync(new URL('../src/worker/sim-worker.js', import.meta.url), 'utf8');

	// A question about the probabilistic run is answered under the *sample's*
	// id, and by the time it comes back `state.runId` has usually moved on --
	// a deterministic run, an auto-run, anything. A reply not on the list is
	// dropped with nothing said, and the panel that asked waits for ever.
	// That is how `prob-hist` was found, after `sensitivity` before it.
	const list = /const PROB_REPLIES = new Set\(\[([\s\S]*?)\]\);/.exec(app)?.[1] ?? '';
	assert(list, 'the replies about the sample are not named in one place');

	// Everything the worker answers under `lastProb`'s id has to be there.
	// Found from the worker itself rather than from a list kept by hand here,
	// so a message added there and not to the set fails this.
	// A branch that *asks about* an existing sample is one that checks the id
	// it was given against the one held -- as opposed to `probabilistic`,
	// which creates it.
	const asked = new Set();
	for (const m of worker.matchAll(/if \(msg\.type === '([\w-]+)'\) \{([\s\S]*?)\n\t\}/g)) {
		if (/lastProb\.id !== msg\.id/.test(m[2])) asked.add(m[1]);
	}
	assert(asked.size >= 4, `only found ${[...asked].join(', ')}`);
	for (const type of asked) {
		assert(list.includes(`'${type}'`),
			`${type} is answered under the sample's id and is not on the list — `
			+ 'its reply is dropped whenever anything has run since');
		assert(messageIsCurrent({ type, id: 1 }, 99), `${type} is dropped at runId 99`);
	}

	// And an ordinary reply is still judged by the run it belongs to.
	assert(messageIsCurrent({ type: 'done', id: 7 }, 7));
	assert(!messageIsCurrent({ type: 'done', id: 7 }, 8),
		'a reply from a run that has been superseded is still accepted');
});

test('a settings window stays where it is put, and can be moved and sized', async () => {
	const { readFileSync } = await import('node:fs');
	const root = new URL('..', import.meta.url);
	const modal = readFileSync(new URL('src/ui/modal.js', root), 'utf8');
	const css = readFileSync(new URL('css/app.css', root), 'utf8');

	// A `<dialog>` is centred by the browser and *re-*centred whenever its
	// contents change -- so a validation line appearing under a field moved
	// the field being typed into, by half a line in each direction. Pinned to
	// where it opened, it grows downwards like anything else.
	assert(/function pin\(dialog\)/.test(modal), 'the dialog is still centred by the browser');
	assert(/dialog\.showModal\(\);\n\t\/\/[\s\S]{0,300}?\tpin\(dialog\);/.test(modal),
		'it is pinned before the browser has laid it out, which measures nothing');
	assert(/\.modal\[style\*="top"\] \{ position: fixed; \}/.test(css),
		'nothing takes the pinned coordinates');

	// And the rebuild does not let it collapse and grow back between one
	// keystroke and the next.
	const refresh = /const refresh = \(\) => \{([\s\S]*?)\n\t\};/.exec(modal)?.[1] ?? '';
	assert(/body\.style\.minHeight = `\$\{Math\.round\(was\)\}px`;/.test(refresh),
		'the body is not held at the height it had across a rebuild');
	assert(/requestAnimationFrame\(\(\) => \{ body\.style\.minHeight = ''; \}\)/.test(refresh),
		'the floor is never released, so the window can only ever grow');

	// Moved by the header, which is the one part of a dialog that is not a
	// control -- and not by the close button inside it.
	assert(/function draggable\(dialog, handle\)/.test(modal), 'it cannot be moved');
	const drag = /function draggable[\s\S]*?\n\}/.exec(modal)?.[0] ?? '';
	assert(/ev\.target\.closest\('button, input, select, textarea, a'\)/.test(drag),
		'a press on a control in the header drags the window');
	assert(/setPointerCapture/.test(drag), 'the drag is lost the moment the pointer leaves');
	assert(/function within\(x, y, dialog\)/.test(modal),
		'a window can be dragged somewhere it cannot be dragged back from');

	// Sized by a grip, because the browser's own `resize` needs an overflow
	// the dialog cannot have -- it clips its rounded corners.
	assert(/function resizable\(dialog, grip, body\)/.test(modal), 'it cannot be sized');
	const size = /function resizable[\s\S]*?\n\}/.exec(modal)?.[0] ?? '';
	assert(/Math\.max\(320,/.test(size) && /Math\.max\(120,/.test(size),
		'it can be sized down to nothing');
	assert(/window\.innerWidth - r\.left/.test(size) && /window\.innerHeight - r\.top/.test(size),
		'it can be sized past the window, leaving no corner to pull back');
	assert(/\.modal-grip \{/.test(css), 'the grip is invisible');
	assert(/\.modal-head \{ cursor: grab; \}/.test(css), 'the header does not say it is a handle');
});

test('a scatter pairs the realisations, and its line is fitted to what is drawn', async () => {
	const S = await import('../src/domain/sensitivity.js');
	const { readFileSync } = await import('node:fs');
	const root = new URL('..', import.meta.url);
	const worker = readFileSync(new URL('src/worker/sim-worker.js', root), 'utf8');
	const view = readFileSync(new URL('src/ui/scatterview.js', root), 'utf8');
	const app = readFileSync(new URL('src/ui/app.js', root), 'utf8');

	// --- the fit -----------------------------------------------------------
	const n = 240;
	const x = new Float64Array(n);
	const y = new Float64Array(n);
	for (let i = 0; i < n; i++) { x[i] = 1 + i * 0.05; y[i] = 3 + 2 * x[i]; }
	const exact = S.lineFit(x, y);
	assert(exact.ok, 'a straight line was not fitted');
	close(exact.a, 3, 1e-9);
	close(exact.b, 2, 1e-9);
	close(exact.r2, 1, 1e-12);
	assert(exact.n === n && exact.dropped === 0);

	// A power law is a curve on the values and a line in the logarithms, which
	// is the whole reason the axis choice decides the fit.
	for (let i = 0; i < n; i++) y[i] = 5 * x[i] ** 3;
	const straight = S.lineFit(x, y);
	const logged = S.lineFit(x, y, { translate: 'log' });
	assert(straight.r2 < 0.95, `a cubic fitted straight: R² ${straight.r2}`);
	close(logged.r2, 1, 1e-12);
	close(logged.b, 3, 1e-9);
	close(Math.exp(logged.a), 5, 1e-9);

	// A logarithm needs a positive number; those pairs are dropped and counted.
	const withZero = Float64Array.from(x);
	withZero[0] = 0;
	withZero[1] = -1;
	assert(S.lineFit(withZero, y, { translate: 'log' }).dropped === 2);
	assert(S.lineFit(withZero, y).dropped === 0);

	// An input that never varied, and an output that never did.
	const flat = new Float64Array(n).fill(2);
	assert(!S.lineFit(flat, y).ok && !S.lineFit(x, flat).ok, 'a line through nothing');
	// And too few points to fit one.
	assert(!S.lineFit(x.subarray(0, 2), y.subarray(0, 2)).ok);

	// The equation says which fit it is, because `y = a·x^b` and `y = a + b·x`
	// are different claims.
	assert(/y = .*·x\^/.test(view.match(/\? `y = [^`]*`/)?.[0] ?? ''), 'no power-law form');
	assert(/y = \$\{fmtStat\(fit\.a\)\}/.test(view), 'no straight-line form');

	// --- the pairing -------------------------------------------------------
	//
	// Every other question about the sample takes the column sorted, because a
	// distribution is a shape and the order is not part of it. A scatter is the
	// opposite: sorting either column destroys the thing being looked at.
	const points = /if \(msg\.type === 'prob-points'\) \{([\s\S]*?)\n\t\}/.exec(worker)?.[1] ?? '';
	assert(points, 'the worker cannot be asked for the realisations');
	assert(!/sortedColumn/.test(points), 'a scatter would be drawn from sorted columns');
	assert(/if \(mask && !mask\[i\]\) continue;/.test(points),
		'screened realisations are plotted');
	// One list of rows for every column, so a point never pairs one
	// realisation's x with another's y.
	assert(/const rows = \[\];/.test(points) && /rows\[j\] \* times \+ at/.test(points),
		'the columns are not taken over the same realisations');

	// The reply carries the sample's id, so it has to be on the list that
	// survives a later run.
	assert(/'prob-points'/.test(/const PROB_REPLIES = new Set\(\[([\s\S]*?)\]\);/.exec(app)?.[1] ?? ''),
		'the scatter’s answer is dropped whenever anything has run since');

	// The x axis is held by label: a re-run renumbers the outputs, and an index
	// would quietly become a different series.
	assert(/state\.scatterX = ev\.currentTarget\.value \|\| null;/.test(app), 'no x picker');
	const xi = /function scatterXIndex\(\) \{([\s\S]*?)\n\}/.exec(app)?.[1] ?? '';
	assert(/o\.label === state\.scatterX/.test(xi), `the x axis is held by index: ${xi}`);
});

test('the reader chooses what the band’s line is, and the table can list the realisations', async () => {
	const { readFileSync } = await import('node:fs');
	const root = new URL('..', import.meta.url);
	const app = readFileSync(new URL('src/ui/app.js', root), 'utf8');
	const html = readFileSync(new URL('index.html', root), 'utf8');
	const worker = readFileSync(new URL('src/worker/sim-worker.js', root), 'utf8');

	// --- what the lines are ------------------------------------------------
	//
	// The median with its percentile bands is the assessment's own picture and
	// stays the default. The mean answers a different question and for a
	// skewed output the two are far apart, so all three are offered -- as tick
	// boxes rather than a list of one, because they are not alternatives: how
	// far apart the two summaries are, and where the model's own values fall
	// among the realisations, are questions about two lines at once.
	for (const id of ['chart-lines', 'chart-spread']) {
		assert(new RegExp(`id="${id}"`).test(html), `${id} is not there`);
	}
	for (const line of ['median', 'mean', 'single']) {
		assert(new RegExp(`data-line="${line}"`).test(html), `the ${line} line has no box`);
	}
	assert(/chartLines: \{ median: true, mean: false, single: false \},/.test(app)
		&& /chartSpread: 'bands',/.test(app), 'the defaults moved');
	// Never all off: a chart with no line is not a picture of anything, and a
	// click that silently came back would be worse than a box that is fixed.
	assert(/return on\.length \? on : \[CHART_LINES\[0\]\];/.test(app),
		'every line can be turned off at once');
	assert(/box\.disabled = box\.checked && on\.length === 1;/.test(app),
		'the last line on can be turned off');
	// Colour is which output a line is of; the pattern is which line of it. So
	// the three share the output's slot and are told apart by their dash --
	// three colours for one series would read as three series.
	assert(/slot: pos/.test(app) && /set: many \? line\.set : undefined/.test(app),
		'the three lines of one output do not share its colour');
	assert(/export function styleOf\(s, si\)/.test(readFileSync(new URL('src/ui/chart.js', root), 'utf8')),
		'the chart cannot be told which style a series wears');
	// An interval is drawn about the line it belongs to, and the two lines do
	// not share one: `sd/√n` is the error of a *mean*, and drawn about a median
	// it would be an interval around a number it is not the spread of.
	const build = /const series = state\.selected\.flatMap\(\(i, pos\) => \{([\s\S]*?)\n\t\}\);/.exec(app)?.[1] ?? '';
	assert(build, 'the chart’s series builder moved');
	assert(/lo\[j\] = mean\[j\] - half;/.test(build),
		'the interval is not drawn about the mean it belongs to');
	assert(/1\.959964 \* sd\[j\]\) \/ Math\.sqrt/.test(build),
		'the standard error is not the deviation over the root of the count');
	// And with the median chosen it is the median's own pair, off the sorted
	// realisations, not the mean's borrowed.
	assert(/if \(kind === 'median'\)[\s\S]*?const m = med;/.test(build)
		&& /const med = band\.med &&/.test(build),
		'the median is drawn with the mean’s interval behind it');
	assert(/lo: m\.errLo, hi: m\.errHi/.test(build) && /lo: m\.bodyLo, hi: m\.bodyHi/.test(build),
		'the median’s two spreads are not both drawn');
	assert(/med: medianSpread\(v, times, result\.iterations, 1\.959964, mask\)/.test(worker),
		'the band does not carry the median’s spread');
	// And the deviation is sent with the band, over the same realisations the
	// mean was taken over.
	assert(/function sdOf\(values, times, iterations, mean, mask\)/.test(worker),
		'the worker does not send the spread');
	assert(/sd: sdOf\(v, times, result\.iterations, mean, mask\)/.test(worker),
		'the band does not carry it');

	// The percentile bands belong to the *sample*, not to any line through it,
	// so they are painted once however many lines are up -- twice would be the
	// same fill at twice the opacity.
	assert(/if \(!first\) return null;/.test(build), 'the percentile bands are painted per line');

	// --- Run once ----------------------------------------------------------
	//
	// Pressing it with a sample's picture up means "show me one run", and the
	// sample is kept rather than thrown away: a thousand integrations is not a
	// thing to discard because somebody wanted to see one.
	const run = /function runSimulation\(opts = \{\}\) \{([\s\S]*?)\n\}/.exec(app)?.[1] ?? '';
	assert(/if \(opts\.manual && showingSample\(\)\) \{[\s\S]{0,200}?state\.chartMode = 'time';/.test(run),
		'Run once leaves one of the sample’s pictures up');
	// Turned on, not switched to: the lines can be up together, and clearing
	// the reader's other two to show this one answers a question nobody asked.
	assert(/state\.chartLines = \{ \.\.\.state\.chartLines, single: true \};/.test(run),
		'Run once does not draw its own run');
	assert(!/state\.prob = null/.test(run), 'Run once throws the sample away');

	// --- coming back to the curves ------------------------------------------
	//
	// The chart's container is `display: none` while another picture is up, so
	// the canvas was last painted against a box of nothing and comes back as a
	// handful of enormous pixels. The observer answers a *change* of size and
	// the element is the size it was before, so nothing tells it to paint.
	assert(/requestAnimationFrame\(\(\) => \{ if \(!\$\('#chart'\)\.hidden\) chart\?\.draw\(\); \}\)/.test(app),
		'the chart is not repainted when it comes back');

	// --- the table at one time ----------------------------------------------
	assert(/id="table-mode"/.test(html) && /tableMode: 'time',/.test(app),
		'the table has no second reading');
	const sample = /function drawSampleTable\(wrap, outs\) \{([\s\S]*?)\n\}/.exec(app)?.[1] ?? '';
	assert(sample, 'there is no table of the realisations');
	assert(/stat\('mean'/.test(sample) && /stat\('median'/.test(sample)
		&& /stat\('5%'/.test(sample) && /stat\('95%'/.test(sample),
	'the summary above the rows is missing');
	// It rides on the same unsorted, paired columns the scatter asks for --
	// there is one question and one answer, not two of each.
	assert(/askSampleColumns\(\);/.test(sample), 'it fetches nothing');
	assert(/type: 'prob-points'/.test(/function askSampleColumns\(\) \{([\s\S]*?)\n\}/.exec(app)?.[1] ?? ''),
		'the table asks a question of its own');
});

test('a model that has never run is a model owing a run', async () => {
	const { readFileSync } = await import('node:fs');
	const app = readFileSync(new URL('../src/ui/app.js', import.meta.url), 'utf8');

	// `dirty` means "there is a run owing", and nothing owes one more than a
	// model that has never had one. `setModel` cleared the results and left
	// the flag alone, so a freshly opened model read as up to date: no dot on
	// Run, and switching auto-run on did nothing at all until something else
	// was edited -- which on a model nobody had touched yet was for ever.
	const set = /function setModel\(raw, source\) \{([\s\S]*?)\n\}/.exec(app)?.[1] ?? '';
	assert(set, 'setModel is gone');
	assert(/state\.results = null;/.test(set), 'opening a model keeps the last one’s results');
	assert(/state\.dirty = true;/.test(set), 'a model with no results reads as up to date');

	// And switching auto-run on starts one, because that is what switching it
	// on means: keep this up to date, of which the first instalment is now.
	const auto = /\$\('#autorun'\)\.addEventListener\('change', \(e\) => \{([\s\S]*?)\n\t\}\);/.exec(app)?.[1] ?? '';
	assert(auto, 'the auto-run switch is gone');
	assert(/state\.dirty \|\| !state\.results/.test(auto),
		'switching auto-run on does nothing on a model that has never run');
	// Not as a manual run: that is the Run button, which takes the tab off a
	// sample's picture, and ticking auto-run is not asking for that.
	assert(/runSimulation\(\);/.test(auto) && !/runSimulation\(\{ manual: true \}\)/.test(auto),
		'auto-run switches the chart away from the sample');
});

test('the median’s spread is read off the realisations, not borrowed from the mean', async () => {
	const { medianSpread } = await import('../src/sim/probabilistic.js');

	// One time, a hundred realisations holding 0..99, so every rank is its own
	// value and the arithmetic is visible.
	const n = 100;
	const flat = Float64Array.from({ length: n }, (_, i) => i);
	const m = medianSpread(flat, 1, n);

	// The distribution-free interval for a median: ranks (n-1)/2 ∓ z√n/2, which
	// here is 49.5 ∓ 9.7998, rounded *outwards* so the coverage is at least the
	// 95% asked for rather than a shade under it.
	assert(m.errLo[0] === 40, 'the lower rank is not ceil((n-1)/2 - z√n/2)');
	assert(m.errHi[0] === 59, 'the upper rank is not floor((n-1)/2 + z√n/2)');
	// And the body: the ranks at 15.87% and 84.13%, the median ± one standard
	// deviation if the sample were normal.
	assert(m.bodyLo[0] === 16, 'the 16% rank moved');
	assert(m.bodyHi[0] === 83, 'the 84% rank moved');

	// It is a *standard error*, so it narrows as the root of the count. Four
	// times the realisations, half the interval.
	const wide = medianSpread(Float64Array.from({ length: 400 }, (_, i) => i / 4), 1, 400);
	const one = m.errHi[0] - m.errLo[0];
	const four = wide.errHi[0] - wide.errLo[0];
	assert(Math.abs(four / one - 0.5) < 0.06, `four times the sample did not halve it: ${four / one}`);

	// On a symmetric sample it agrees with the textbook value for one -- the
	// median of a normal sample is known 1.2533 times less well than its mean,
	// so the half-width is 1.96 · 1.2533 · σ/√n. A fixed generator, because a
	// test that fails one morning in fifty is worse than no test.
	let seed = 20260918;
	const rand = () => {
		seed = (seed * 1103515245 + 12345) & 0x7fffffff;
		return (seed + 0.5) / 0x80000000;
	};
	const N = 4000;
	const normal = new Float64Array(N);
	for (let i = 0; i < N; i++) {
		// Box–Muller, one of the pair.
		normal[i] = Math.sqrt(-2 * Math.log(rand())) * Math.cos(2 * Math.PI * rand());
	}
	const g = medianSpread(normal, 1, N);
	const want = 1.959964 * 1.2533 * (1 / Math.sqrt(N));
	const got = (g.errHi[0] - g.errLo[0]) / 2;
	assert(Math.abs(got / want - 1) < 0.2,
		`the half-width is ${got.toFixed(5)}, the asymptotic one ${want.toFixed(5)}`);
	// The mean's standard error is the *narrower* of the two, which is the
	// whole reason both are offered rather than one being called "the" error.
	assert(want > 1.959964 / Math.sqrt(N), 'a median is not known less well than a mean');

	// On a skewed sample it comes back lopsided, which is the reason for reading
	// it off the realisations rather than computing a half-width: a log-normal
	// output has far more room above its median than below, and ± the same
	// number either side would say otherwise.
	//
	// The *body* is where that shows. The error interval is only a couple of
	// per cent of the sample wide, so the quantile function across it is nearly
	// a straight line and its lopsidedness is small -- small enough that on any
	// one draw the noise on 62 spacings either side of the middle is larger, so
	// there is nothing here to assert about it.
	const skew = Float64Array.from(normal, (v) => Math.exp(3 * v));
	const k = medianSpread(skew, 1, N);
	const mid = Float64Array.from(skew).sort()[N >> 1];
	assert(k.bodyHi[0] - mid > 3 * (mid - k.bodyLo[0]),
		'a log-normal sample came back symmetric about its median');
	// And it is still an interval about the median, either way up.
	assert(k.errLo[0] <= mid && mid <= k.errHi[0], 'the interval does not contain the median');

	// Nothing finite, nothing to say -- not a zero, which would be drawn.
	const gone = medianSpread(Float64Array.from([NaN, NaN]), 1, 2);
	assert(Number.isNaN(gone.errLo[0]) && Number.isNaN(gone.bodyHi[0]),
		'an empty column came back as a number');
});

test('a sample can be thrown away without touching the model', async () => {
	const { readFileSync } = await import('node:fs');
	const root = new URL('..', import.meta.url);
	const app = readFileSync(new URL('src/ui/app.js', root), 'utf8');
	const html = readFileSync(new URL('index.html', root), 'utf8');
	const worker = readFileSync(new URL('src/worker/sim-worker.js', root), 'utf8');
	const dialog = readFileSync(new URL('src/ui/probdialog.js', root), 'utf8');

	// A sample is the one expensive thing the tool holds -- a thousand
	// realisations of every kept series, in the page as bands and in the worker
	// as the matrix they came from. It goes out of date on its own at the next
	// edit, but until then there was no way to say "I am done with that" short
	// of editing the model to make it stale.
	const drop = /function discardProb\(\) \{([\s\S]*?)\n\}/.exec(app)?.[1] ?? '';
	assert(drop, 'there is no way to discard a sample');
	// Everything derived from it goes with it: a histogram of nothing is not a
	// picture of anything, and a sensitivity is of the realisations it read.
	for (const gone of ['state.prob = null;', 'state.hist = null;', 'state.points = null;',
		'state.sensFor = null;', 'state.tornado = null;']) {
		assert(drop.includes(gone), `discarding a sample leaves ${gone.split(' ')[0]} behind`);
	}
	// Including the two pictures that exist only for a sample.
	assert(/state\.chartMode !== 'time'\) state\.chartMode = 'time';/.test(drop),
		'a histogram of a discarded sample stays up');
	// And the realisations themselves, which is the memory this is about: the
	// page holds bands, the worker holds the matrix every other question about
	// the sample is answered from.
	assert(/postMessage\(\{ type: 'prob-forget' \}\)/.test(drop), 'the worker keeps the realisations');
	assert(/if \(msg\.type === 'prob-forget'\) \{\n\t\tlastProb = null;/.test(worker),
		'the worker does not let go of them');
	// The model is not touched -- this is about what has been computed, not
	// about what the model says. It is *read*, for the default the lines go
	// back to, and that is all.
	assert(!/modelChanged|state\.rev|state\.raw\w*\s*=[^=]/.test(drop),
		'discarding a sample edits the model');
	assert(/state\.chartLines = \{ median: true, mean: !!state\.raw\?\.simulation\?\.show_mean/.test(drop),
		'the lines do not go back to this model’s default');

	// Offered where a reader is when they decide: beside the line that says
	// the sample is there, on both tabs, and in the dialog that makes one.
	for (const id of ['chart-discard', 'table-discard']) {
		assert(new RegExp(`id="${id}"`).test(html), `${id} is not there`);
	}
	assert(/for \(const id of \['#chart-discard', '#table-discard'\]\) \{\n\t\t\$\(id\)\?\.addEventListener\('click', \(\) => discardProb\(\)\);/.test(app),
		'the discard buttons are not wired');
	assert(/b\.hidden = !prob;/.test(app), 'the discard button shows with no sample to discard');
	assert(/onDiscard: currentProb\(\) \? \(\) => discardProb\(\) : null,/.test(app),
		'the probabilistic dialog cannot discard, or offers to with nothing held');
	assert(/if \(onDiscard\) \{/.test(dialog) && /'Discard sample'/.test(dialog),
		'the dialog has no discard button');
});

test('the product is named in one spelling, and storage keys are not part of it', async () => {
	const { readFileSync } = await import('node:fs');
	const root = new URL('..', import.meta.url);
	const read = (f) => readFileSync(new URL(f, root), 'utf8');
	const NAME = 'Kompartment';

	// Everywhere the product names itself to a reader: the tab, the header, the
	// three documents, the icon, the file pickers, the run log, and the `source`
	// attribute a results archive carries. A rename that reaches some of these
	// and not the rest leaves a tool that disagrees with itself about what it
	// is called, which is the failure this pins.
	const html = read('index.html');
	assert(html.includes(`<title>${NAME}</title>`), 'the browser tab has another name');
	assert(html.includes(`<b id="title">${NAME}</b>`), 'the header has another name');
	assert(read('icon.svg').includes(`<title>${NAME}</title>`), 'the icon has another name');
	assert(JSON.parse(read('package.json')).name === NAME.toLowerCase(), 'the package has another name');
	assert(read('README.md').startsWith(`# ${NAME}\n`), 'the repo front page has another name');
	assert(read('GUIDE.md').startsWith(`# ${NAME} — guide\n`), 'the guide has another name');
	assert(read('INTERNALS.md').includes(`\n${NAME} covers the part of`), 'How it works has another name');
	const app = read('src/ui/app.js');
	assert(app.includes(`document.title = \`\${name} — ${NAME}\`;`), 'a model’s tab has another name');
	assert((app.match(new RegExp(`description: '${NAME} model`, 'g')) ?? []).length === 4,
		'the file pickers do not all offer the same product');
	assert(read('src/domain/runlog.js').includes(`${NAME} run log`), 'the run log has another name');
	assert(read('src/io/resultfile.js').includes(`source: '${NAME}',`), 'a results archive has another name');

	// And nowhere else. The one exception is deliberate, below.
	for (const f of ['index.html', 'icon.svg', 'README.md', 'GUIDE.md', 'INTERNALS.md',
		'serve.py', 'package.json', 'css/app.css', 'src/ui/app.js', 'src/domain/runlog.js',
		'src/io/resultfile.js']) {
		assert(!/boxflow/i.test(read(f)), `${f} still carries the old name`);
	}

	// **Storage keys do not follow the product's name.** A key is where a
	// reader's work is, and renaming it to match a title discards that work in
	// every browser holding any -- silently, because the new name simply finds
	// nothing. The draft's key is two products old and the clipboard's is one;
	// both stay until what is *under* them changes, and then the version at the
	// end is what moves.
	assert(read('src/ui/autosave.js').includes("const KEY = 'ecolego.draft.v1';"),
		'the draft key was renamed with the product — every unsaved draft is gone');
	assert(read('src/ui/clipboard.js').includes("const KEY = 'boxflow.clipboard.v1';"),
		'the clipboard key was renamed with the product');
	assert(read('src/ui/help.js').includes("const WIDTH_KEY = 'boxflow.help.width';"),
		'the help width key was renamed with the product');
});

test('a sample of a model that reports the solver’s own points is run on the grid', async () => {
	const { runProbabilistic } = await import('../src/sim/probabilistic.js');
	const { readFileSync } = await import('node:fs');
	const runner = readFileSync(new URL('../src/sim/runner.js', import.meta.url), 'utf8');

	// *The solver's own points* is a per-run answer: each integration reports
	// at the steps it took, and a thousand realisations take a thousand
	// different sets of them. There is then no shared time to read a
	// percentile down, so a sample is always reported on the model's grid --
	// and the solver is asked for exactly those times, out of its own
	// interpolant, rather than the grid being read off whatever steps happened
	// to land near it.
	assert(/const steps = project\.solverPoints && !opts\.onGrid/.test(runner),
		'a run cannot be asked for the grid');

	const model = (spacing) => ({
		name: 'decay',
		simulation: {
			start_time: 0, end_time: 100, output_points: 9, spacing,
			solver: 'ndf', rtol: 1e-10, abstol: 1e-14, time_unit: 'year',
		},
		parameters: [{
			name: 'k', default: 0.05, unit: '1/year',
			entries: [{ index: {}, pdf: { kind: 'unif', params: { min: 0.01, max: 0.2 } } }],
		}],
		compartments: [{ name: 'A', initial: '1', unit: 'Bq', dydt: '-k*A' }],
	});

	// `A` is exactly `exp(-k t)`, so every realisation has a right answer to be
	// checked against. Read off the nearest step instead, the rows carry a
	// state from a later time than the one they are labelled with -- which was
	// 2% here, six orders of magnitude worse than the solver's own error, and
	// a different amount in every realisation because every realisation steps
	// differently.
	for (const spacing of ['solver', 'both', 'log']) {
		const p = runProbabilistic(model(spacing), { iterations: 4 });
		const w = p.outputs.findIndex((o) => /^A/.test(o.label));
		const v = p.values[w];
		const T = p.t.length;
		let worst = 0;
		for (let j = 0; j < T; j++) {
			for (let i = 0; i < 4; i++) {
				const exact = Math.exp(-p.samples[0][i] * p.t[j]);
				if (exact < 1e-6) continue; // nothing left to be relatively wrong about
				worst = Math.max(worst, Math.abs(v[i * T + j] - exact) / exact);
			}
		}
		assert(worst < 1e-6,
			`${spacing}: the realisations are ${worst.toExponential(1)} off their own answer`);
		assert(T === 9, `${spacing}: the sample is not on the model’s grid (${T} times)`);
	}
});

test('a histogram takes the number of bins and the spacing it is asked for', async () => {
	const { histogram, HIST_BINS } = await import('../src/domain/distribution.js');
	const sorted = (v) => Float64Array.from(v).sort();

	// Ten decades, positive: `auto` bins it in the logarithm, because on an
	// even spacing it is one tall bin and a tail nobody can see.
	const wide = sorted(Array.from({ length: 400 }, (_, i) => 10 ** (-5 + (10 * i) / 399)));
	assert(histogram(wide).log, 'a sample spanning ten decades was binned evenly');
	assert(!histogram(wide, null, 'linear').log, 'linear was asked for and not given');
	assert(histogram(wide, null, 'log').log, 'log was asked for and not given');

	// One decade: `auto` leaves it even, and `log` is still the reader's to ask
	// for -- the judgement is a default, not a rule.
	const narrow = sorted(Array.from({ length: 400 }, (_, i) => 1 + i / 400));
	assert(!histogram(narrow).log, 'a narrow sample was binned logarithmically');
	assert(histogram(narrow, null, 'log').log, 'log was refused on a positive sample');

	// The count, and its limits. Below the floor and above the ceiling are the
	// rule and the ceiling, not a throw: this comes from a box somebody typed
	// in, and the box says its own limits.
	assert(histogram(wide, 42).edges.length === 43, 'the bin count was ignored');
	assert(histogram(wide, 2).edges.length === 3, 'the smallest histogram was refused');
	assert(histogram(wide, 1e9).edges.length === HIST_BINS.max + 1, 'the ceiling was ignored');
	assert(histogram(wide, 0).edges.length === histogram(wide).edges.length,
		'a count below the floor did not fall back to the rule');
	// And the counts still add up to the sample, whatever it was binned into.
	for (const bins of [2, 7, 42, 200]) {
		const h = histogram(wide, bins, 'log');
		let n = 0;
		for (const c of h.counts) n += c;
		assert(n === wide.length, `${bins} bins hold ${n} of ${wide.length} realisations`);
	}

	// A sample reaching zero has no logarithm to bin by. That is refused out
	// loud rather than drawn as something else, because a reader who asked for
	// log and got linear would read the picture as the one they asked for.
	const zero = sorted([0, 1, 2, 3, 4, 5]);
	const got = histogram(zero, 5, 'log');
	assert(!got.log && got.refused, 'a log histogram was drawn of a sample containing zero');
	assert(!histogram(zero, 5, 'linear').refused, 'linear cannot be refused');
});

test('the Table can be any of the runs a sample holds, and the whole matrix of one', async () => {
	const { readFileSync } = await import('node:fs');
	const root = new URL('..', import.meta.url);
	const app = readFileSync(new URL('src/ui/app.js', root), 'utf8');
	const html = readFileSync(new URL('index.html', root), 'utf8');
	const worker = readFileSync(new URL('src/worker/sim-worker.js', root), 'utf8');

	// A column of numbers cannot say which run it is by looking, and after a
	// thousand realisations there are several honest answers. So the Table
	// says which, and lets the reader choose.
	assert(/id="table-series"/.test(html) && /id="table-real"/.test(html),
		'the Table cannot be asked which run its rows are');
	for (const k of ['median', 'mean', 'realisation', 'run', 'raw']) {
		assert(new RegExp(`\\['${k}',`).test(app), `the Table cannot show ${k}`);
	}
	// The median and the mean are already on the page, in the bands. Only a
	// single realisation and the whole matrix need the worker, which is where
	// the realisations are.
	assert(/if \(which === 'mean'\) return prob\.bands\[k\]\.mean;/.test(app),
		'the mean over time is fetched when the page already has it');
	assert(/askProbMatrices\(want, String\(state\.tableReal\)\)/.test(app),
		'one realisation cannot be read out of the sample');
	assert(/askProbMatrices\(\[k\], 'all'\)/.test(app), 'the whole matrix cannot be read');
	assert(/want === 'mean'/.test(worker) && /timeMajor\(result\.values\[k\]/.test(worker),
		'the worker cannot answer either');

	// The matrix is time down and realisation across, so a second series would
	// want a second table rather than more columns.
	assert(/TABLE_SERIES\.filter\(\(\[k\]\) => \(k === 'raw' \? one : true\)\)/.test(app),
		'the whole matrix is offered for more than one series at a time');
	// And both directions are capped on screen: a thousand realisations over
	// four hundred times is four hundred thousand cells.
	assert(/const TABLE_COLS = \d+;/.test(app), 'the matrix draws every realisation it has');
	assert(/state\.tableRawCols \?\? TABLE_COLS/.test(app), 'the column cap cannot be lifted');

	// The rows come from whichever run they are of: a sample is on the model's
	// grid and the run under it may be on the solver's own steps.
	assert(/const times = which === 'run' \? r\.t : \(prob\?\.t \?\? r\.t\);/.test(app),
		'the Table labels the sample’s rows with the run’s times');

	// What was read back is dropped with the sample it was read from.
	const drop = /function discardProb\(\) \{([\s\S]*?)\n\}/.exec(app)?.[1] ?? '';
	for (const k of ['tableCols', 'tableRaw', 'tableRawCols']) {
		assert(drop.includes(`state.${k} = null;`), `discarding a sample keeps state.${k}`);
	}
});

test('a truncation can be written as a pair of percentiles', async () => {
	const P = await import('../src/domain/pdf.js');
	const S = await import('../src/domain/sample.js');

	// The same cut, said the other way round. A data set that fixes the same
	// tail fraction for a thousand element-specific log-normals quotes `p5`
	// and `p95`: the *values* differ in every one of them and the rule does
	// not, so writing the values would be writing the rule out a thousand
	// times and getting it wrong once.
	const spec = P.parsePDF('logn(gm=20,gsd=7,pmin=0.05,pmax=0.95)', 'Logn4');
	assert(spec.pmin === 0.05 && spec.pmax === 0.95, 'the percentiles were not read');
	assert(P.formatPDF(spec) === 'logn(gm=20,gsd=7,pmin=0.05,pmax=0.95)', P.formatPDF(spec));

	// It is the *probability* the sampler reads between, which is what makes
	// this form cheaper than the value form: no CDF has to be evaluated to
	// find where to start. So the draw at u=0 is exactly the untruncated 5th
	// percentile and the draw at u=1 exactly the 95th.
	const bare = P.parsePDF('logn(gm=20,gsd=7)', 'Logn4');
	const near = (a, b) => Math.abs(a - b) <= Math.abs(b) * 1e-9;
	assert(near(S.valueAtProbability(spec, 0), P.quantile(bare, 0.05)),
		'the bottom of the range is not the 5th percentile');
	assert(near(S.valueAtProbability(spec, 1), P.quantile(bare, 0.95)),
		'the top of the range is not the 95th percentile');
	assert(near(S.valueAtProbability(spec, 0.5), P.quantile(bare, 0.5)),
		'the middle moved');

	// The drawing is cut too: a curve drawn over ground it has been truncated
	// off is a curve of a different distribution.
	const span = P.supportOf(spec);
	assert(near(span[0], P.quantile(bare, 0.05)) && near(span[1], P.quantile(bare, 0.95)),
		`the support is ${span.join('..')}`);
	assert(/≥ p5 and ≤ p95/.test(P.describePDF(spec)), P.describePDF(spec));

	// Both forms together mean the intersection: truncating twice is not an
	// error and neither is saying the same cut both ways.
	const both = P.parsePDF('norm(mean=0,sd=1,trmin=-1,trmax=1,pmin=0.5,pmax=0.99)', 'norm');
	assert(S.valueAtProbability(both, 0) >= 0, 'the percentile floor was ignored');
	assert(S.valueAtProbability(both, 1) <= 1, 'the value ceiling was ignored');

	// And it is a probability, which the editor has to be told when it is not.
	const silly = P.parsePDF('logn(gm=20,gsd=7,pmin=5,pmax=95)', 'Logn4');
	assert(P.pdfProblems(silly).some((m) => /between 0 and 1/.test(m)),
		'a percentile of 5 was accepted as a probability');
	const backwards = P.parsePDF('logn(gm=20,gsd=7,pmin=0.9,pmax=0.1)', 'Logn4');
	assert(P.pdfProblems(backwards).some((m) => /inside out/.test(m)),
		'an inverted pair of percentiles was accepted');
});

test('inputs in one group share one underlying sample', async () => {
	const { runProbabilistic } = await import('../src/sim/probabilistic.js');

	// A group is one uncertainty seen in several places — one element's
	// concentration ratio quoted for four ecosystems — so its members are not
	// two draws that happen to agree, they are one draw used twice. The whole
	// implementation is which stream the uniforms come from.
	const pdf = (kind, params, group) => ({
		kind, params, values: null, trmin: null, trmax: null,
		pmin: null, pmax: null, group, inorder: true, pos: 0,
	});
	const model = (group) => ({
		name: 'grouped',
		simulation: {
			start_time: 0, end_time: 10, output_points: 3, spacing: 'linear',
			solver: 'ndf', time_unit: 'year',
		},
		parameters: [
			{ name: 'a', default: 1, entries: [{ index: {}, pdf: pdf('unif', { min: 0, max: 1 }, group) }] },
			{ name: 'b', default: 1, entries: [{ index: {}, pdf: pdf('unif', { min: 0, max: 1 }, group) }] },
			{ name: 'c', default: 1, entries: [{ index: {}, pdf: pdf('unif', { min: 0, max: 1 }, null) }] },
			{ name: 'd', default: 1, entries: [{ index: {}, pdf: pdf('norm', { mean: 10, sd: 2 }, group) }] },
		],
		compartments: [{ name: 'A', initial: 'a+b+c+d', unit: 'Bq' }],
	});
	const run = (group) => {
		const p = runProbabilistic(model(group), { iterations: 200 });
		const col = (name) => Array.from(p.samples[p.plan.findIndex((e) => e.name === name)]);
		return { col, stats: p.stats };
	};
	const r = (x, y) => {
		const n = x.length;
		const mx = x.reduce((s, v) => s + v, 0) / n;
		const my = y.reduce((s, v) => s + v, 0) / n;
		let sx = 0; let sy = 0; let sxy = 0;
		for (let i = 0; i < n; i++) {
			sx += (x[i] - mx) ** 2; sy += (y[i] - my) ** 2; sxy += (x[i] - mx) * (y[i] - my);
		}
		return sxy / Math.sqrt(sx * sy);
	};

	const on = run('G1');
	// Same shape, same group: the identical number every realisation.
	assert(on.col('a').every((v, i) => v === on.col('b')[i]),
		'two members of a group drew different numbers');
	// A different shape in the same group shares the *rank*, not the number —
	// which is what full correlation means when the curves differ.
	assert(r(on.col('a'), on.col('d')) > 0.9, `a and d are ${r(on.col('a'), on.col('d'))}`);
	assert(!on.col('a').every((v, i) => v === on.col('d')[i]), 'a normal drew a uniform’s value');
	// And an input outside the group is untouched.
	assert(Math.abs(r(on.col('a'), on.col('c'))) < 0.2, `a and c are ${r(on.col('a'), on.col('c'))}`);
	assert(on.stats.groups.length === 1 && on.stats.groups[0].members.join() === 'a,b,d',
		JSON.stringify(on.stats.groups));

	// With no group nothing is correlated, which is the same run otherwise.
	const off = run(null);
	assert(!off.col('a').every((v, i) => v === off.col('b')[i]), 'ungrouped inputs moved together');
	assert(off.stats.groups.length === 0, 'a group was reported where none was named');
});

test('a model’s data goes out and comes back as a spreadsheet and as HDF5', async () => {
	const DF = await import('../src/io/datafile.js');
	const DT = await import('../src/domain/datatable.js');
	const { readFileSync } = await import('node:fs');
	const root = new URL('..', import.meta.url);

	const load = (name) => {
		const raw = ed.migrateKeys(JSON.parse(readFileSync(new URL(`examples/${name}.json`, root), 'utf8')));
		ed.materialiseShorthand(raw);
		return raw;
	};
	// Compared on what a row *says*, not on object identity: a spec that came
	// from a file written before `group` existed has no such key, and one
	// parsed back has it as null, which is the same distribution.
	const key = (r) => `${r.id}@${r.time ?? ''}`;
	const shape = (s) => (s ? [s.kind, JSON.stringify(s.params), s.trmin, s.trmax,
		s.pmin, s.pmax, s.group ?? null].join('|') : '-');

	for (const name of ['lookup-driver', 'biosphere', 'waste-packages', 'landscape']) {
		const raw = load(name);
		const rows = DT.collect(raw);
		assert(rows.length, `${name} has no data rows`);

		for (const [what, got] of [
			['xlsx', (await DF.readDataWorkbook(await DF.writeDataWorkbook(rows, { name: 'd' }))).rows],
			['h5', (await DF.readDataHDF5(DF.writeDataHDF5(rows, { root: name }))).rows],
		]) {
			const back = new Map(got.map((r) => [key(r), r]));
			assert(got.length === rows.length,
				`${name} as ${what}: ${got.length} rows came back from ${rows.length}`);
			for (const r of rows) {
				const o = back.get(key(r));
				assert(o, `${name} as ${what}: ${key(r)} did not come back`);
				assert(String(o.value) === String(r.value),
					`${name} as ${what}: ${key(r)} is ${o.value}, was ${r.value}`);
				assert(shape(o.pdf) === shape(r.pdf),
					`${name} as ${what}: ${key(r)} — ${shape(o.pdf)} was ${shape(r.pdf)}`);
				assert((o.unit ?? '') === (r.unit ?? ''), `${name} as ${what}: ${key(r)} lost its unit`);
			}
		}
	}

	// --- the id, and reading it back --------------------------------------
	//
	// Nothing in `CR.food.herbiv.Ac` says where the name stops and the index
	// begins. The model does: the longest prefix that is a block is the block.
	const raw = load('biosphere');
	for (const r of DT.collect(raw)) {
		const hit = DT.resolve(raw, r.id);
		assert(hit && hit.block === r.block, `${r.id} resolved to ${hit?.name ?? 'nothing'}`);
	}
	assert(DT.resolve(raw, 'leachRate.I-129')?.index.Radionuclides === 'I-129',
		'an index segment was read as part of the name');
	// `_` is the block's own value rather than an index of that name.
	const own = DT.resolve(raw, 'leachRate._');
	assert(own && Object.keys(own.index).length === 0, 'an underscore was read as an index');
	assert(DT.resolve(raw, 'nothing.of.the.sort') === null, 'an unknown id resolved to something');
});

test('a data file read onto a model says what it did and what it could not', async () => {
	const DF = await import('../src/io/datafile.js');
	const DT = await import('../src/domain/datatable.js');

	const rows = [
		{ id: 'k', unit: '1/year', time: null, value: 0.5, pdf: null },
		{ id: 'table', unit: 'm3/year', time: 0, value: 1 },
		{ id: 'table', unit: 'm3/year', time: 10, value: 2 },
		{ id: 'nowhere.at.all', unit: '', time: null, value: 3, pdf: null },
	];
	const model = {
		name: 'small',
		simulation: { start_time: 0, end_time: 10, output_points: 3, spacing: 'linear', time_unit: 'year' },
		parameters: [{ name: 'k', value: '1', unit: '1/year' }],
		lookups: [{ name: 'table', points: [[0, 99]], interpolation: 'linear', unit: 'm3/year' }],
	};

	// Update-only: what matched landed, what did not is *reported* rather than
	// invented. An import that quietly does four rows of five is worse than
	// one that refuses, because the four are indistinguishable afterwards.
	const a = structuredClone(model);
	const rep = DT.apply(a, rows);
	assert(rep.values === 1 && rep.tables === 1, JSON.stringify(rep));
	assert(rep.created === 0, 'update-only created a block');
	assert(rep.unmatched.length === 1 && /nowhere\.at\.all/.test(rep.unmatched[0]),
		JSON.stringify(rep.unmatched));
	assert(a.parameters[0].value === '0.5', `k is ${a.parameters[0].value}`);
	assert(JSON.stringify(a.lookups[0].points) === '[[0,1],[10,2]]',
		JSON.stringify(a.lookups[0].points));
	assert(/Read 1 value, 1 lookup table\./.test(DT.describe(rep)), DT.describe(rep));

	// Creating: with no block to ask, the whole path is the name — the last
	// segment is the block and the rest are sub-systems.
	const b = structuredClone(model);
	const made = DT.apply(b, rows, { create: true });
	assert(made.created === 1 && made.unmatched.length === 0, JSON.stringify(made));
	const born = b.parameters.find((p) => p.name === 'all');
	assert(born && born.system === 'nowhere.at', JSON.stringify(born));

	// Two rows at one time is a mistake in the file, not a table with a step.
	const c = structuredClone(model);
	const clash = DT.apply(c, [
		{ id: 'table', time: 0, value: 1 }, { id: 'table', time: 0, value: 2 },
	]);
	assert(clash.problems.some((m) => /both at time 0/.test(m)), JSON.stringify(clash.problems));

	// And the columns a spreadsheet uses mean what the shape says they mean:
	// Min and Max are a uniform's own ends and a normal's scissors.
	const at = (row) => (name) => row[name];
	const u = DF.pdfFromColumns(at({ Type: 'unif', Min: 1, Max: 3 }));
	assert(u.params.min === 1 && u.params.max === 3 && u.trmin === null,
		'a uniform’s ends were read as a truncation');
	const n = DF.pdfFromColumns(at({ Type: 'norm', Mean: 5, Std: 1, Min: 0, Max: 9 }));
	assert(n.params.mean === 5 && n.trmin === 0 && n.trmax === 9,
		'a normal’s truncation was read as its ends');
	const g = DF.pdfFromColumns(at({ Type: 'logn', GM: 2, GSD: 3, Pmin: 0.05, Pmax: 0.95, Group: 'G1' }));
	assert(g.pmin === 0.05 && g.pmax === 0.95 && g.group === 'G1', JSON.stringify(g));
	assert(DF.pdfFromColumns(at({ Type: 'wobble' }))?.bad, 'an unknown curve was accepted');
	// A triangular's most likely value is the `Value` column where `Mean` is
	// empty: the number the model runs at *is* the mode, and a second column
	// saying it again is a second place to get it wrong.
	const t2 = DF.pdfFromColumns(at({ Type: 'triang', Min: 62, Max: 1911, Value: 455 }));
	assert(t2.params.mode === 455, JSON.stringify(t2.params));

	// --- a table whose points carry their own spreads ----------------------
	//
	// One row per point in the spreadsheet, and in HDF5 a *list* of specs on
	// the dataset — one per value, in the order the values are in.
	const table = [
		{ id: 'SRF', unit: 'unitless', time: 0, value: 455,
			pdf: DF.pdfFromColumns(at({ Type: 'triang', Min: 62, Max: 1911, Value: 455, Group: 'S10' })) },
		{ id: 'SRF', unit: 'unitless', time: 8700, value: 17,
			pdf: DF.pdfFromColumns(at({ Type: 'triang', Min: 1, Max: 23, Value: 17, Group: 'S10' })) },
	];
	for (const [what, got] of [
		['xlsx', (await DF.readDataWorkbook(await DF.writeDataWorkbook(table, { name: 'd' }))).rows],
		['h5', (await DF.readDataHDF5(DF.writeDataHDF5(table, { root: 'm' }))).rows],
	]) {
		assert(got.length === 2, `${what}: ${got.length} points came back`);
		assert(got[0].pdf?.params.min === 62 && got[1].pdf?.params.min === 1,
			`${what}: the two points share one spread`);
		assert(got[0].pdf?.group === 'S10', `${what}: the group was lost`);
		assert(got[0].time === 0 && got[1].time === 8700, `${what}: the times moved`);
	}
	// The HDF5 form is a list rather than an object, which is how a reader
	// tells "one spread per point" from "one spread".
	assert(DF.pdfListFromJSON('[{"type":"unif","a":1,"b":2}]')?.[0]?.params.min === 1,
		'a list of specs did not read');
	assert(DF.pdfFromJSON('[{"type":"unif","a":1,"b":2}]') === null,
		'a list was read as if it were one spec');

	// --- a value that is not a number --------------------------------------
	//
	// `SRF.speciation.Ac` is `GROUP1`: which speciation class an element is
	// in. Dropping it for not parsing would lose seventeen rows of a hundred
	// and seventy silently, so it is carried; writing it into a parameter is
	// what is refused, and said.
	const words = [{ id: 'speciation.Ac', unit: '', time: null, value: 'GROUP1', pdf: null }];
	const backX = (await DF.readDataWorkbook(await DF.writeDataWorkbook(words, { name: 'd' }))).rows;
	assert(backX[0].value === 'GROUP1', `xlsx made it ${backX[0].value}`);
	const backH = (await DF.readDataHDF5(DF.writeDataHDF5(words, { root: 'm' }))).rows;
	assert(backH[0].value === 'GROUP1', `h5 made it ${backH[0].value}`);
	const refused = DT.apply({ name: 'x', parameters: [] }, words, { create: true });
	assert(refused.created === 0 && refused.problems.some((m) => /not a number/.test(m)),
		JSON.stringify(refused.problems));

	// --- a name a model cannot hold ---------------------------------------
	//
	// `1BMA` is a real repository and not a legal identifier. Creating gives
	// it one, says so once rather than per row, and `resolve` tries it — so
	// importing the same file again finds what the last import made.
	assert(DT.legalName('1BMA') === '_1BMA', DT.legalName('1BMA'));
	assert(DT.legalName('SRF') === 'SRF', 'a legal name was changed');
	const odd = [{ id: '1BMA.SRF', unit: '', time: null, value: 2, pdf: null }];
	const built = { name: 'x' };
	const madeIt = DT.apply(built, odd, { create: true });
	assert(madeIt.created === 1 && madeIt.renamed.get('1BMA') === '_1BMA',
		JSON.stringify([...madeIt.renamed]));
	assert(DT.resolve(built, '1BMA.SRF')?.name === '_1BMA.SRF',
		'the file’s own id no longer finds what it made');
});

test('HDF5 written the other way round reads here too', async () => {
	const { readHDF5 } = await import('../src/io/hdf5read.js');
	const DF = await import('../src/io/datafile.js');
	const { readFileSync } = await import('node:fs');

	// ./fixtures/v1-symbol-table.h5 is the dialect a data file actually
	// arrives in: **version 1 object headers**, where a group is a symbol
	// table -- a version 1 B-tree of names beside a local heap holding them --
	// rather than the version 2 compact links ../src/io/hdf5.js writes. Both
	// are HDF5 and the library reads both; a reader that only understood the
	// one this tool writes would open nothing anybody sent it.
	//
	// At least one object in it carries a long enough attribute to need a
	// continuation block, which is the case that cost four hundred of a real
	// file's nine hundred datasets: a version 1 continuation does not end the
	// chunk it sits in, and stopping at the first one loses every message
	// after it — including, for some objects, the datatype or the layout.
	const bytes = new Uint8Array(readFileSync(new URL('fixtures/v1-symbol-table.h5', import.meta.url)));
	assert(bytes[8] === 0, `the fixture is superblock version ${bytes[8]}, not the old one`);
	const { datasets, problems } = await readHDF5(bytes);
	assert(!problems.length, problems.join(' | '));
	const by = new Map(datasets.map((d) => [d.path, d]));
	assert(datasets.length === 4, `${datasets.length} datasets: ${[...by.keys()].join(' ')}`);

	const one = by.get('/demo/Atmosphere/height/L1');
	assert(one && one.values[0] === 10 && one.attrs.unit === 'm', JSON.stringify(one?.attrs));
	const table = by.get('/demo/lobj/area/aqu');
	assert(table && table.values.length === 3 && table.values[0] === 9.74e6, 'the table did not read');
	assert(table.attrs.lookup_table, 'the lookup flag did not read');
	assert(Array.from(table.attrs.index).join() === '0,500,1000', String(table.attrs.index));
	assert(/^PSAR SFR/.test(String(one.attrs.reference)), 'the long attribute did not read');

	// And the whole way through to rows, which is what the import reads.
	const { rows } = await DF.readDataHDF5(bytes);
	assert(rows.length === 6, `${rows.length} rows`);
	const ids = rows.map((r) => r.id);
	assert(ids.includes('Atmosphere.height.L1') && ids.includes('CR.food.herbiv.Ac'),
		ids.join(' '));
	// The three points of the table are three rows sharing an id.
	const pts = rows.filter((r) => r.id === 'lobj.area.aqu');
	assert(pts.length === 3 && pts[0].time === 0 && pts[2].time === 1000, JSON.stringify(pts));
	// A percentile truncation, and a group, both survive the trip.
	const ac = rows.find((r) => r.id === 'CR.food.herbiv.Ac');
	assert(ac.pdf.kind === 'Logn4' && ac.pdf.pmin === 0.05 && ac.pdf.pmax === 0.95,
		JSON.stringify(ac.pdf));
	const ag = rows.find((r) => r.id === 'CR.food.herbiv.Ag');
	assert(ag.pdf.kind === 'norm' && ag.pdf.trmin === 0 && ag.pdf.group === 'G1',
		JSON.stringify(ag.pdf));

	// A file that is not one says so rather than coming back empty.
	let said = '';
	try { await readHDF5(new Uint8Array([1, 2, 3, 4, 5, 6, 7, 8, 9])); } catch (e) { said = e.message; }
	assert(/not an HDF5 file/.test(said), said);
});

test('a point of a lookup table can carry its own distribution', async () => {
	const { runProbabilistic, samplingPlan } = await import('../src/sim/probabilistic.js');
	const { run } = await import('../src/sim/runner.js');
	const { Project } = await import('../src/domain/project.js');

	// A table is a curve, not a number, and a data set that knows how
	// uncertain a release fraction is knows it at the years it was measured:
	// `SRF` is triangular on 62..1911 at year 0 and on 1..23 at year 8700.
	// Those are two spreads of one quantity, so the spread belongs where the
	// number is — the third element of a point.
	const tri = (min, max, mode, group) => ({
		kind: 'triang', params: { min, max, mode }, values: null,
		trmin: null, trmax: null, pmin: null, pmax: null, group, inorder: true, pos: 0,
	});
	const model = (group) => ({
		name: 'srf',
		simulation: {
			start_time: 0, end_time: 10000, output_points: 5, spacing: 'linear',
			solver: 'ndf', time_unit: 'year',
		},
		lookups: [{
			name: 'SRF', unit: 'unitless', interpolation: 'linear',
			points: [[0, 455, tri(62, 1911, 455, group)], [8700, 17, tri(1, 23, 17, group)]],
		}],
		parameters: [{ name: 'k', default: 1, unit: '1/year' }],
		compartments: [{ name: 'A', initial: '1', unit: 'Bq', dydt: '-k*A/SRF' }],
		expressions: [{ name: 'peek', equation: 'SRF', unit: 'unitless' }],
	});

	// Each point is an input of its own, named by the time it sits at: a table
	// has one per point and `SRF` alone would name several at once.
	const plan = samplingPlan(new Project(structuredClone(model(null))));
	assert(plan.map((e) => e.name).join(' ') === 'SRF@0 SRF@8700',
		plan.map((e) => e.name).join(' '));

	// The deterministic run is untouched: a distributed point starts at the
	// value the model holds.
	const det = run(new Project(structuredClone(model(null))));
	const out = det.outputs().find((o) => /peek/.test(o.label));
	const curve = Array.from(det.series(out));
	assert(Math.abs(curve[0] - 455) < 1e-9 && Math.abs(curve[4] - 17) < 1e-9, curve.join(' '));

	const stats = (group) => {
		const p = runProbabilistic(model(group), { iterations: 500 });
		const w = p.outputs.findIndex((o) => /peek/.test(o.label));
		const v = p.values[w];
		const T = p.t.length;
		const at = (j) => Array.from({ length: 500 }, (_, i) => v[i * T + j]);
		const mean = (a) => a.reduce((x, y) => x + y, 0) / a.length;
		return { p, at, mean };
	};

	// Each point varies over its *own* curve, and a triangular's mean is
	// (min + max + mode)/3 — 809.3 at year 0 and 13.67 at the end.
	const free = stats(null);
	assert(Math.abs(free.mean(free.at(0)) - (62 + 1911 + 455) / 3) < 40,
		`year 0 averages ${free.mean(free.at(0))}`);
	assert(Math.abs(free.mean(free.at(4)) - (1 + 23 + 17) / 3) < 1,
		`the end averages ${free.mean(free.at(4))}`);
	assert(Math.min(...free.at(0)) >= 62 && Math.max(...free.at(0)) <= 1911,
		'a realisation left the first point’s own range');
	assert(Math.min(...free.at(4)) >= 1 && Math.max(...free.at(4)) <= 23,
		'a realisation left the last point’s own range');

	const r = (x, y) => {
		const n = x.length;
		const mx = x.reduce((s, v2) => s + v2, 0) / n;
		const my = y.reduce((s, v2) => s + v2, 0) / n;
		let sx = 0; let sy = 0; let sxy = 0;
		for (let i = 0; i < n; i++) {
			sx += (x[i] - mx) ** 2; sy += (y[i] - my) ** 2; sxy += (x[i] - mx) * (y[i] - my);
		}
		return sxy / Math.sqrt(sx * sy);
	};
	// Two points of one table are independent unless the file says otherwise,
	// and a group is how it says otherwise — which is exactly how a release
	// fraction that scales as a whole is written.
	const a = Array.from(free.p.samples[0]);
	const b = Array.from(free.p.samples[1]);
	assert(Math.abs(r(a, b)) < 0.2, `ungrouped points correlate at ${r(a, b)}`);
	const tied = stats('G');
	assert(r(Array.from(tied.p.samples[0]), Array.from(tied.p.samples[1])) > 0.9,
		'a group did not tie the two points together');

	// A model whose *only* uncertainty is in a table still gets offered a
	// probabilistic run: `hasDistributions` is what puts the button there, and
	// it used to look at parameters and events alone.
	assert(ed.hasDistributions(model('G')), 'a table’s spreads do not count as dice');
	assert(!ed.hasDistributions({ lookups: [{ name: 'T', points: [[0, 1], [1, 2]] }] }),
		'an ordinary table was taken for a distribution');

	// And the machinery: a slot in P, and the table rebuilt from it.
	const { readFileSync } = await import('node:fs');
	const builder = readFileSync(new URL('../src/sim/builder.js', import.meta.url), 'utf8');
	assert(/const refreshTables = \(\) => \{/.test(builder), 'the tables are never rebuilt');
	assert(/refreshTables\(\);\n\t\tctx\.t = t;/.test(builder),
		'the rebuild does not happen before the invariants are worked out');
	assert(/lookupPoints: pointLayout\.map/.test(builder), 'the layout does not carry the points');
	const sample = readFileSync(new URL('../src/domain/sample.js', import.meta.url), 'utf8');
	assert(/for \(const pt of layout\.lookupPoints \?\? \[\]\)/.test(sample),
		'the sampler does not walk them');
	// A table whose points are distributed is never shared between index
	// slots: two slots reading one entry would be one draw shown twice.
	assert(/let table = mine \? undefined : cache\.get\(points\);/.test(builder),
		'a distributed table can come out of the shared cache');
});

test('raw sample data from a file drives a run, value for value', async () => {
	const DF = await import('../src/io/datafile.js');
	const DT = await import('../src/domain/datatable.js');
	const { runProbabilistic, samplingPlan } = await import('../src/sim/probabilistic.js');
	const { run } = await import('../src/sim/runner.js');
	const { Project } = await import('../src/domain/project.js');
	const { readFileSync } = await import('node:fs');

	// Some data is not quoted as a curve at all: a near-field release rate is
	// the output of a thousand runs of another model, and what the next model
	// wants is those thousand curves, not a shape fitted to them.
	//
	// ./fixtures/chunked-samples.h5 is both forms, in the layout such a file
	// actually arrives in — **chunked, shuffled and deflated**, which is what
	// h5py writes the moment anything is compressed. A reader without that
	// opens none of it.
	const bytes = new Uint8Array(readFileSync(new URL('fixtures/chunked-samples.h5', import.meta.url)));
	const { rows, problems } = await DF.readDataHDF5(bytes);
	assert(!problems.length, problems.join(' | '));
	assert(rows.length === 4, `${rows.length} rows: ${rows.map((r) => r.id).join(' ')}`);

	// A column: `include_deterministic` means the first value is the one the
	// model runs at and the rest are the realisations.
	const one = rows.find((r) => r.id === 'inventory');
	assert(one.value === 100, `the deterministic value is ${one.value}`);
	assert(Array.from(one.pdf.values).join() === '1,2,3,4', Array.from(one.pdf.values).join());
	// In order, not drawn from: these values *are* the sample, and shuffling
	// them would break the pairing with everything else out of the same run.
	assert(one.pdf.kind === 'pg' && one.pdf.inorder === true, JSON.stringify(one.pdf.kind));

	// A matrix: every column is one realisation's whole curve, so a row of it
	// is that point's sample. With no deterministic column the middle of the
	// sample stands in.
	const table = rows.filter((r) => r.id === 'release');
	assert(table.length === 3 && table.map((r) => r.time).join() === '0,10,20',
		table.map((r) => r.time).join());
	assert(Array.from(table[1].pdf.values).join() === '10,20,30,40',
		Array.from(table[1].pdf.values).join());
	assert(table[1].value === 25, `the stand-in is ${table[1].value}`);

	// --- and it runs -------------------------------------------------------
	const model = {
		name: 'raw',
		simulation: {
			start_time: 0, end_time: 20, output_points: 3, spacing: 'linear',
			solver: 'ndf', time_unit: 'year',
		},
		parameters: [{ name: 'I0', value: '1', unit: 'Bq' }],
		lookups: [{ name: 'release', unit: 'Bq/year', interpolation: 'linear', points: [[0, 0]] }],
		compartments: [{ name: 'A', initial: 'I0', unit: 'Bq', dydt: 'release' }],
		expressions: [{ name: 'peek', equation: 'release', unit: 'Bq/year' }],
	};
	const rep = DT.apply(model, rows.map((r) => (r.id === 'inventory' ? { ...r, id: 'I0' } : r)));
	assert(rep.samples === 4 && rep.sampleValues === 16, JSON.stringify(rep));

	// Every point of the table is an input of its own, and so is the value.
	const plan = samplingPlan(new Project(structuredClone(model)));
	assert(plan.map((e) => e.name).sort().join(' ') === 'I0 release@0 release@10 release@20',
		plan.map((e) => e.name).join(' '));

	// The deterministic run is the deterministic value and the stand-in curve.
	const det = run(new Project(structuredClone(model)));
	const peek = det.outputs().find((o) => /peek/.test(o.label));
	assert(Math.abs(det.series(peek)[1] - 25) < 1e-9, `the middle point is ${det.series(peek)[1]}`);
	assert(Math.abs(det.series(det.outputs().find((o) => /^A/.test(o.label)))[0] - 100) < 1e-9,
		'the deterministic value was not the first of the column');

	// And realisation `i` is column `i` — of the table *and* of the value, at
	// every time, because a list is read at the realisation's number rather
	// than drawn. That is what keeps a curve whole across its points.
	const p = runProbabilistic(model, { iterations: 4 });
	const w = p.outputs.findIndex((o) => /peek/.test(o.label));
	const T = p.t.length;
	const v = p.values[w];
	for (let i = 0; i < 4; i++) {
		assert(Math.abs(v[i * T + 0] - (i + 1)) < 1e-5, `realisation ${i} at t=0 is ${v[i * T]}`);
		assert(Math.abs(v[i * T + 1] - 10 * (i + 1)) < 1e-4,
			`realisation ${i} at t=10 is ${v[i * T + 1]}`);
		assert(Math.abs(v[i * T + 2] - 100 * (i + 1)) < 1e-3,
			`realisation ${i} at t=20 is ${v[i * T + 2]}`);
	}

	// A sample enters the model as a plain list: it is read as a view into the
	// one array the file was read into, and `JSON.stringify` of a typed array
	// is an object with numbered keys rather than a list — which would save a
	// model nothing could open.
	const stored = model.lookups[0].points[1][2];
	assert(Array.isArray(stored.values), `the sample was stored as ${stored.values?.constructor?.name}`);
	assert(JSON.parse(JSON.stringify(model)).lookups[0].points[1][2].values.length === 4,
		'the sample does not survive being saved');
});

test('everything this tool writes is in one room, and everything a file holds is in another', async () => {
	const { readFileSync } = await import('node:fs');
	const root = new URL('..', import.meta.url);
	const app = readFileSync(new URL('src/ui/app.js', root), 'utf8');
	const html = readFileSync(new URL('index.html', root), 'utf8');
	const { KINDS } = await import('../src/ui/savedialog.js');
	const { matching, pickerState } = await import('../src/ui/pick.js');

	// --- what can be written ----------------------------------------------
	//
	// There were six ways to save and they were in four places: a button, a
	// caret menu beside it, the Table's right-click menu and the canvas's.
	// Each knew about some of the formats and none of them let you say which
	// series.
	const keys = KINDS.map((k) => k.key).join(' ');
	assert(keys === 'model archive results realisations data log', keys);
	for (const k of KINDS) {
		assert(k.formats.length, `${k.key} offers no format`);
		assert(k.blurb, `${k.key} does not say what it is`);
	}
	// Everything but a whole model is a list of named things, and each of
	// those offers the list.
	for (const k of KINDS) {
		if (k.key === 'model' || k.key === 'archive' || k.key === 'log') continue;
		assert(k.picks, `${k.key} cannot be narrowed`);
	}
	assert(!/id="save-as"/.test(html), 'the old caret menu is still in the markup');
	assert(/\$\('#save'\)\.addEventListener\('click', \(\) => openSave\(\)\)/.test(app),
		'the Save button does not open the dialog');

	// --- the picker --------------------------------------------------------
	//
	// One question asked once: which of these several hundred named things.
	const items = [
		{ key: 'a', name: 'Dose', kind: 'expression', unit: 'Sv/year', count: 4, system: '' },
		{ key: 'b', name: 'Lake', kind: 'compartment', unit: 'Bq', count: 4, system: '' },
		{ key: 'c', name: 'Near.Buffer', kind: 'compartment', unit: 'Bq', count: 1, system: 'Near' },
	];
	const ui = pickerState();
	assert(matching(items, ui).length === 3, 'an empty search hides something');
	assert(matching(items, { ...ui, query: 'lake' }).map((i) => i.key).join() === 'b',
		'the search does not match a name');
	assert(matching(items, { ...ui, query: 'sv/year' }).map((i) => i.key).join() === 'a',
		'the search does not match a unit');
	assert(matching(items, { ...ui, kind: 'compartment' }).map((i) => i.key).join() === 'b,c',
		'the kind filter does not filter');
	assert(matching(items, { ...ui, system: 'Near' }).map((i) => i.key).join() === 'c',
		'the sub-system filter does not filter');
	// Both at once, which is what makes a long list reachable.
	assert(matching(items, { query: 'b', kind: 'compartment', system: 'Near' })
		.map((i) => i.key).join() === 'c', 'the filters do not compose');

	// --- what a file holds -------------------------------------------------
	//
	// Read first, asked second: a `.zip` from this tool is a model *and* a
	// run, and a `.h5` is a table of values or a thousand realisations of
	// somebody else's near-field.
	assert(/\$\('#import'\)\.addEventListener\('click', \(\) => pickFile\(chooseImport\)\)/.test(app),
		'the Import button does not go through the chooser');
	const survey = /async function chooseImport\(file\) \{([\s\S]*?)\n\}/.exec(app)?.[1] ?? '';
	assert(survey, 'there is no survey');
	for (const what of ["key: 'data'", "key: 'model'", "key: 'results'"]) {
		assert(survey.includes(what), `the survey never offers ${what}`);
	}
	// A row that cannot be acted on stays and says why, rather than going
	// missing: "why is this greyed out" is the question a disabled control
	// always asks and almost never answers.
	assert(/why: dataset \? null/.test(survey), 'a file with no run in it says nothing about it');
	assert(/openImportChooser\(\{ name, holds/.test(survey), 'the survey is never shown');
});

test('the block importer reads only fields it is actually given', async () => {
	const { readFileSync } = await import('node:fs');
	const src = readFileSync(new URL('../src/ui/importblocks.js', import.meta.url), 'utf8');

	// A sweep that renamed the *block kind* `source` to `inflow` took this
	// dialog's `ui.source` with it — the model being read from — and left six
	// reads of `ui.inflow`, which nothing ever sets. Every block import threw
	// `Cannot read properties of undefined` before the dialog could draw, and
	// nothing caught it because the fields come from `...opts` and no test
	// opened the dialog.
	//
	// So: every field read off `ui` has to be one the literal sets or one the
	// caller is documented to pass. A rename that misses half of a pair now
	// fails here instead of in front of somebody.
	const literal = /\n\tui = \{([\s\S]*?)\n\t\};/.exec(src)?.[1] ?? '';
	assert(literal, 'the ui literal moved');
	const set = new Set([...literal.matchAll(/^\t\t(\w+):/gm)].map((m) => m[1]));
	// `...opts` is what the caller fills in; the doc comment is the contract.
	assert(/\.\.\.opts,/.test(literal), 'the options are no longer spread in');
	for (const m of src.matchAll(/@param \{[^}]*\} \[?opts\.(\w+)/g)) set.add(m[1]);
	// Set on `ui` after it is built counts too.
	for (const m of src.matchAll(/\bui\.(\w+)\s*=[^=]/g)) set.add(m[1]);

	const read = new Set([...src.matchAll(/\bui\??\.(\w+)/g)].map((m) => m[1]));
	const missing = [...read].filter((k) => !set.has(k));
	assert(!missing.length, `ui.${missing.join(', ui.')} is read and never set`);
	assert(read.has('source') && set.has('source'),
		'the model being read from is no longer called `source`');
	assert(!/ui\.inflow/.test(src), 'the mis-renamed field is back');
});

test('three ways downhill, all of them bounded', async () => {
	const O = await import('../src/domain/optimise.js');

	// Rosenbrock: the standard cruelty. A curved valley whose floor is almost
	// flat, minimum at (1, 1). Every method here has to find it, and how many
	// evaluations each takes is the thing that decides which to offer for what.
	const rosen = (x) => 100 * (x[1] - x[0] * x[0]) ** 2 + (1 - x[0]) ** 2;
	const parts = (x) => [10 * (x[1] - x[0] * x[0]), 1 - x[0]];
	const box = { lower: [-5, -5], upper: [5, 5] };
	const near = (out, why) => {
		assert(out.x, `${why}: nothing came back`);
		assert(Math.abs(out.x[0] - 1) < 1e-3 && Math.abs(out.x[1] - 1) < 1e-3,
			`${why}: (${out.x.map((v) => v.toFixed(4))}) after ${out.evals}`);
	};
	near(O.nelderMead(rosen, [-1.2, 1], { ...box, maxEvals: 2000 }), 'Nelder–Mead');
	near(O.levenbergMarquardt(parts, [-1.2, 1], { ...box, maxEvals: 2000 }), 'Levenberg–Marquardt');
	near(O.differentialEvolution(rosen, { ...box, maxEvals: 9000, seed: 7 }), 'differential evolution');

	// Levenberg–Marquardt uses the structure the other two throw away, so on a
	// least-squares problem it should be much the cheapest.
	const lm = O.levenbergMarquardt(parts, [-1.2, 1], { ...box, maxEvals: 2000 });
	const nm = O.nelderMead(rosen, [-1.2, 1], { ...box, maxEvals: 2000 });
	assert(lm.evals < nm.evals, `LM took ${lm.evals}, Nelder–Mead ${nm.evals}`);

	// The bounds are bounds: an optimum outside the box comes back on its wall
	// rather than beyond it, which is what makes a bound a statement about
	// what is physical rather than a hint.
	const far = O.nelderMead((x) => (x[0] - 10) ** 2, [0], {
		lower: [0], upper: [3], maxEvals: 200,
	});
	assert(far.x[0] === 3, `it left the box at ${far.x[0]}`);
	const deep = O.differentialEvolution((x) => (x[0] - 10) ** 2, {
		lower: [0], upper: [3], maxEvals: 400, seed: 3,
	});
	assert(deep.x[0] <= 3 + 1e-12, `it left the box at ${deep.x[0]}`);

	// Stopping is answered, not ignored: every evaluation is a whole run of a
	// model and a reader who presses Stop means it.
	let n = 0;
	const stop = { aborted: false };
	const out = O.nelderMead((x) => { if (++n > 5) stop.aborted = true; return rosen(x); },
		[-1.2, 1], { ...box, maxEvals: 1000, signal: stop });
	assert(out.reason === 'stopped' && out.evals <= 7, `${out.reason} after ${out.evals}`);
	// And the budget is a budget.
	const capped = O.nelderMead(rosen, [-1.2, 1], { ...box, maxEvals: 12 });
	assert(capped.reason === 'budget' && capped.evals <= 12, JSON.stringify(capped.reason));

	// --- how a residual is measured ---------------------------------------
	//
	// The three scales are three different questions, and the log one is why:
	// being out by a factor of two is the same error at 1e−9 as at 1e3, and
	// neither of the other two says so.
	const one = (got, want, scale) => O.objectiveOf([got], [{ value: want, scale }]).residuals[0];
	assert(one(2, 1, 'absolute') === 1 && one(200, 100, 'absolute') === 100,
		'absolute is not the difference');
	assert(one(2, 1, 'relative') === 1 && one(200, 100, 'relative') === 1,
		'relative does not divide by the target');
	assert(Math.abs(one(2, 1, 'log') - one(200, 100, 'log')) < 1e-12,
		'a factor of two is not the same error at both ends');
	// A reading the model never produced is a big miss rather than a NaN that
	// makes every comparison false and the search wander.
	assert(Number.isFinite(O.objectiveOf([NaN], [{ value: 1, scale: 'relative' }]).objective),
		'a missing reading poisons the objective');
	// Weights are weights.
	const w = O.objectiveOf([2, 2], [{ value: 1, scale: 'absolute', weight: 4 },
		{ value: 1, scale: 'absolute', weight: 1 }]);
	assert(Math.abs(w.objective - 5) < 1e-12, `weighted objective is ${w.objective}`);
});

test('an optimisation solves for a model’s own parameters and leaves the model alone', async () => {
	const { calibrate, variablesOf, readingOf } = await import('../src/sim/calibrate.js');
	const { run } = await import('../src/sim/runner.js');
	const { Project } = await import('../src/domain/project.js');

	// `A` decays at `k` from `A0`, so two readings determine both — and the
	// answer is known, which is what makes this a test rather than a demo.
	const model = () => ({
		name: 'cal',
		simulation: {
			start_time: 0, end_time: 100, output_points: 101, spacing: 'linear',
			solver: 'ndf', rtol: 1e-8, abstol: 1e-12, time_unit: 'year',
		},
		parameters: [
			{ name: 'k', value: '0.05', unit: '1/year' },
			{ name: 'A0', value: '1', unit: 'Bq' },
		],
		compartments: [{ name: 'A', initial: 'A0', unit: 'Bq', dydt: '-k*A' }],
	});
	assert(variablesOf(model()).map((v) => v.key).join() === 'k,A0',
		variablesOf(model()).map((v) => v.key).join());

	const truth = { k: 0.03, A0: 5 };
	const targets = [20, 80].map((time) => ({
		output: 'A', when: 'at', time, scale: 'log', weight: 1,
		value: truth.A0 * Math.exp(-truth.k * time),
	}));
	const variables = [
		{ key: 'k', lower: 1e-3, upper: 1, space: 'log' },
		{ key: 'A0', lower: 0.1, upper: 100, space: 'log' },
	];

	for (const method of ['nelder', 'lm', 'de']) {
		const raw = model();
		const out = calibrate(raw, {
			targets, variables, method, maxEvals: method === 'de' ? 2000 : 400,
		});
		assert(out.ok && out.matched, `${method}: ${JSON.stringify(out.targets)}`);
		const got = Object.fromEntries(out.values.map((v) => [v.key, v.value]));
		assert(Math.abs(got.k - truth.k) < 1e-4, `${method}: k came out ${got.k}`);
		assert(Math.abs(got.A0 - truth.A0) < 1e-3, `${method}: A0 came out ${got.A0}`);
		// The model is a question being asked, not a thing being edited: an
		// optimisation that left the parameters where it last tried them would
		// hand back a model nobody asked for.
		assert(raw.parameters[0].value === '0.05' && raw.parameters[1].value === '1',
			`${method} edited the model: ${JSON.stringify(raw.parameters)}`);
	}

	// A target the model cannot reach comes back honestly: the value sits on
	// the bound the search ran into, and `matched` is false even though
	// numbers came back.
	//
	// On the *log* scale, which is the one that still has a gradient when the
	// target is a million times away: a relative residual of an unreachable
	// target is −1 everywhere, and a search cannot be blamed for not moving
	// on a floor that is flat.
	const stuck = calibrate(model(), {
		targets: [{ output: 'A', when: 'end', value: 1e6, scale: 'log' }],
		variables: [{ key: 'A0', lower: 0.1, upper: 10, space: 'log' }],
		method: 'nelder', maxEvals: 200,
	});
	assert(stuck.ok && !stuck.matched, 'an unreachable target reported as matched');
	assert(stuck.values[0].pinned === 'upper', JSON.stringify(stuck.values[0]));

	// Where a target is read is the reader's choice, and `peak` is the one a
	// dose is argued about.
	const results = run(new Project(model()));
	const first = readingOf(results, { output: 'A', when: 'at', time: 0 });
	assert(Math.abs(first - 1) < 1e-9, `at t=0 it is ${first}`);
	assert(Math.abs(readingOf(results, { output: 'A', when: 'peak' }) - 1) < 1e-9,
		'the peak of a decay is not its start');
	assert(readingOf(results, { output: 'A', when: 'end' }) < 0.01, 'the end is not the end');

	// Nothing to aim at, or nothing to move, is refused in words.
	for (const [opts, why] of [
		[{ targets: [], variables }, /endpoint/i],
		[{ targets, variables: [] }, /vary/i],
		[{ targets, variables: [{ key: 'k', lower: 1, upper: 0.1 }] }, /no range/i],
		[{ targets, variables: [{ key: 'k', lower: -1, upper: 1, space: 'log' }] }, /above zero/i],
		[{ targets, variables: [{ key: 'nope', lower: 0, upper: 1 }] }, /not a parameter/i],
	]) {
		let said = '';
		try { calibrate(model(), { ...opts, method: 'nelder' }); } catch (e) { said = e.message; }
		assert(why.test(said), `expected ${why}, got '${said}'`);
	}
});

test('an optimised answer can be tried without being taken', async () => {
	const { readFileSync } = await import('node:fs');
	const app = readFileSync(new URL('../src/ui/app.js', import.meta.url), 'utf8');

	// Two buttons because they are two things. *Run at these values* runs
	// against a copy and edits nothing; *Update the parameters* is the edit,
	// written as one step so one undo takes the whole answer back.
	const fn = /function runAtValues\(values, \{ keep \}\) \{([\s\S]*?)\n\}/.exec(app)?.[1] ?? '';
	assert(fn, 'there is no way to use an answer');
	assert(/runSimulation\(\{ manual: true, substitute: state\.preview \}\)/.test(fn),
		'a preview does not run against a substitute');
	assert(/putValues\(state\.raw, named\)[\s\S]*?modelChanged\(/.test(fn),
		'taking the values is not one edit of the model');
	// The preview must not touch the model at all.
	const preview = fn.slice(0, fn.indexOf('state.preview = null'));
	assert(!/putValues\(state\.raw/.test(preview), 'the preview edits the model');

	// And the run built from a substitute is built from a *copy*.
	assert(/const copy = structuredClone\(state\.raw\); putValues\(copy, opts\.substitute\)/.test(app),
		'a substituted run is not made against a copy');
	// A preview that read as an ordinary run would be the worst of both, so
	// the corner of the Chart says which it is.
	assert(/at \$\{state\.preview\.length\} optimised value/.test(app),
		'the chart does not say a preview is one');
	assert(/if \(!opts\.substitute\) state\.preview = null;/.test(app),
		'an ordinary run does not clear the preview');

	// The replies carry their own counter, not the run's — the trap that
	// leaves a dialog waiting for ever.
	assert(/const OWN_ID_REPLIES = new Set\(\['optimise', 'optimise-progress', 'variables'\]\)/.test(app),
		'the optimiser’s replies are dropped by messageIsCurrent');

	// **The model it optimises is the model that is open**, built now.
	// `state.project` is set by `runSimulation` and is null until something
	// has run — and an optimisation is exactly what somebody reaches for
	// *before* running anything, so reading it threw on the first click. It
	// is also the only way an edit made since the last run is the one that
	// gets optimised.
	const open = /async function openOptimise\(\) \{([\s\S]*?)\n\}/.exec(app)?.[1] ?? '';
	assert(open, 'the optimiser cannot be opened');
	assert(!/state\.project/.test(open), 'opening the optimiser reads state.project');
	const ask = /function askVariables\(\) \{([\s\S]*?)\n\}/.exec(app)?.[1] ?? '';
	assert(!/state\.project/.test(ask), 'asking for the variables reads state.project');
	assert(/function projectNow\(\) \{\n\treturn new Project\(structuredClone\(state\.raw\)\)\.toJSON\(\);/
		.test(app), 'the model is not built from what is open');
	// And a model with nothing to aim at says so rather than opening an empty
	// dialog or throwing.
	assert(/This model reports nothing to aim at/.test(open), 'a model with no outputs throws');
	assert(/This model has no parameters to vary/.test(open), 'a model with no parameters throws');

	// --- asking again ------------------------------------------------------
	//
	// A setup is something somebody argues with: widen a bound, add an
	// endpoint, try the global method because the local one sat down on a
	// wall. With the Optimise button gone the moment an answer arrived, every
	// one of those meant closing the dialog and building the whole thing
	// again.
	const dlg = readFileSync(new URL('../src/ui/optdialog.js', import.meta.url), 'utf8');
	const footer = /\/\/ ------------------------------------------------------ the buttons([\s\S]*?)\n\t\t\tbody\.append\(foot\);/.exec(dlg)?.[1] ?? '';
	assert(footer, 'the footer moved');
	assert(/state\.result \? 'Optimise again' : 'Optimise'/.test(footer),
		'there is no way to ask again');
	// It is inside the not-running branch and outside the has-an-answer one,
	// so it is there whether or not something came back.
	const running = footer.indexOf('if (state.running)');
	const answer = footer.indexOf("if (state.result?.ok)");
	const again = footer.indexOf("'Optimise again' : 'Optimise'");
	assert(running >= 0 && answer > running && again > answer,
		'the Optimise button is inside the branch that has an answer');

	// An answer is an answer to the setup it was asked of. Change a bound and
	// it is still a real answer -- those values solved *that* problem -- but
	// not this one, and the dialog has to say which.
	assert(/state\.ranWith = JSON\.stringify\(snapshot\(\)\);/.test(dlg),
		'nothing remembers what the answer was an answer to');
	assert(/const stale = !!state\.result && state\.ranWith !== JSON\.stringify\(snapshot\(\)\);/.test(dlg),
		'a changed setup does not make the answer stale');
	assert(/The setup has changed since that answer/.test(dlg), 'the footer does not say so');
	assert(/This answer is to the setup as it was/.test(dlg), 'the answer does not say so');
	// And which button is the obvious one follows: use it while it fits, ask
	// again once it does not.
	assert(/className: stale \? 'ghost' : 'primary'/.test(dlg),
		'updating stays the primary action after the setup moved');
	assert(/className: state\.result\?\.ok && !stale \? 'ghost' : 'primary'/.test(dlg),
		'asking again does not become the primary action once the answer is stale');

	// --- the two tables are one grid ---------------------------------------
	//
	// They are read one under the other, so a column that means the same
	// thing has to be in the same place. With `auto` each table sized its own
	// columns and one long cell in the second -- a parameter sitting on its
	// bound, spelled out -- moved every column under the first by two hundred
	// pixels.
	const css = readFileSync(new URL('../css/app.css', import.meta.url), 'utf8');
	// Anchored to the start of a line: `.opt-result.is-stale .opt-table {`
	// also ends in `.opt-table {` and is not the rule meant here.
	const table = /^\.opt-table \{([^}]*)\}/m.exec(css)?.[1] ?? '';
	assert(/table-layout: fixed/.test(table), 'the result tables size themselves');
	assert(/\.opt-table th:not\(:first-child\), \.opt-table td:not\(:first-child\) \{[^}]*width: [\d.]+em/
		.test(css), 'the number columns have no shared width');
	// And numbers line up by their last digit, or a column of them cannot be
	// compared down, which is the only reason to put them in one.
	assert(/\.opt-table th:not\(:first-child\), \.opt-table td:not\(:first-child\) \{[^}]*text-align: right/
		.test(css), 'the numbers are not right-aligned');
	// The bound is a mark in the cell and a sentence in the warning above it,
	// not a sentence in the cell.
	assert(!/on its \$\{v\.pinned\} bound\)/.test(dlg), 'the bound is spelled out in the cell');
	assert(/className: 'opt-bound'/.test(dlg), 'a pinned value carries no mark');
});

test('a block that looks like a compartment and is not says so', async () => {
	const { readFileSync } = await import('node:fs');
	const graph = readFileSync(new URL('../src/ui/graph.js', import.meta.url), 'utf8');
	const { KIND_ICON, markPath } = await import('../src/ui/icons.js');
	const ed2 = await import('../src/domain/edit.js');

	const set = /const GLYPH_KINDS = new Set\(\[([\s\S]*?)\]\);/.exec(graph)?.[1] ?? '';
	assert(set, 'the glyph list moved');
	const glyphs = new Set([...set.matchAll(/'([a-z_0-9]+)'/g)].map((m) => m[1]));

	// **Every kind in the list has to have a mark.** Putting one in without
	// one draws nothing at all and says nothing about it -- which is what a
	// trigger did, silently, until the canvas was looked at.
	for (const kind of glyphs) {
		assert(markPath(kind), `${kind} is on the glyph list and has no mark`);
	}

	// The rounded box is the crowded one: five kinds wear it, and on the
	// canvas they carry a name and a dimension line and nothing else, so what
	// tells them apart is the fill colour and only that.
	const rounded = ['compartment', 'expression', 'index_reduction', 'block_reduction', 'function'];
	for (const kind of rounded) {
		assert(ed2.defaultShapeFor(kind) === 'rounded', `${kind} is no longer a rounded box`);
	}
	// The four that are not compartments say so...
	for (const kind of rounded.slice(1)) {
		assert(glyphs.has(kind), `${kind} looks like a compartment and does not say otherwise`);
	}
	// ...and the compartment stays bare, which is the rule rather than an
	// oversight: the shape's plain reading is "a compartment", so a glyph
	// means "this looks like one and is not". Marking all five would leave
	// the mark saying nothing.
	assert(!glyphs.has('compartment'), 'every rounded box is marked, so the mark says nothing');
	assert(!glyphs.has('parameter') && !glyphs.has('lookup'),
		'a kind with a shape of its own, or its own curve, is marked as well');

	// A trigger and an event share the diamond, and a trigger now has a mark
	// even though the diamond is too short to wear one on the canvas — the
	// tree and the menus draw it at a size where it reads.
	assert(KIND_ICON.trigger?.mark && markPath('trigger'), 'a trigger has no mark anywhere');
	assert(KIND_ICON.trigger.mark !== KIND_ICON.event.mark,
		'a trigger and an event wear the same mark');
	assert(/The diamond is left out on purpose/.test(graph),
		'the diamond is missing from the list with no reason given');
});

test('ticking a parameter does not throw the list back to the top', async () => {
	const { readFileSync } = await import('node:fs');
	const src = readFileSync(new URL('../src/ui/localsensdialog.js', import.meta.url), 'utf8');
	const css = readFileSync(new URL('../css/app.css', import.meta.url), 'utf8');

	// `.prob-list` is a scroller, so rebuilding the dialog around it sends it
	// back to the top: on a search that found the parameter forty rows down,
	// every tick meant finding it again. Only what a tick actually changes is
	// rewritten -- the count, which boxes may still be ticked, the limit note
	// and whether there is anything to run.
	assert(/\.prob-list \{[^}]*overflow-y: auto/.test(css), '.prob-list no longer scrolls');
	const handler = /box\.addEventListener\('change', \(\) => \{([\s\S]*?)\n\t\t\t\t\}\);/.exec(src)?.[1] ?? '';
	assert(handler, 'the tick handler moved');
	assert(!/modal\.refresh\(\)/.test(handler), 'ticking still rebuilds the dialog');
	assert(/retally\(\)/.test(handler), 'ticking updates nothing');

	const retally = /function retally\(\) \{([\s\S]*?)\n\t\t\t\}/.exec(src)?.[1] ?? '';
	assert(retally, 'there is no tally to update');
	for (const [what, re] of [
		['the count', /count\.textContent/],
		['the cost', /cost\.textContent/],
		['the other boxes', /b2\.box\.disabled/],
		['the limit note', /full\.hidden/],
		['the Run button', /go\.disabled/],
	]) {
		assert(re.test(retally), `a tick does not update ${what}`);
	}

	// The endpoint picker had this right already, and is the other place a
	// tick must not rebuild.
	const eps = readFileSync(new URL('../src/ui/endpoints.js', import.meta.url), 'utf8');
	const epHandler = /box\.addEventListener\('change', \(\) => \{([\s\S]*?)\n\t\t\t\t\}\);/.exec(eps)?.[1] ?? '';
	assert(epHandler && !/modal\.refresh\(\)/.test(epHandler) && /retally\(\)/.test(epHandler),
		'the endpoint picker rebuilds on a tick');
});

test('a long generated function runs in parts and gives the same numbers', async () => {
	const { tapePrelude } = await import('../src/parser/compile.js');
	// V8 will not optimise a function of more than 60 KB of bytecode, so
	// buildFunction cuts a long body into parts (see splitBody in
	// compile.js). This body has the shapes the generators write: the tape
	// line, conditionals through a top-level `let`, a flux `const` read on
	// the next lines, loops with block-scoped locals, and a return at the end.
	const lines = [tapePrelude()];
	for (let k = 0; k < 900; k++) {
		lines.push(`\t// block ${k}`);
		// A local read twenty blocks after it is made: no cut may fall
		// between the two.
		if (k === 400) lines.push('\tconst early = y[0] * 2;');
		if (k === 420) lines.push('\tout[0] += early;');
		lines.push(`\tT[${k}] = y[${k % 7}] * P[${k % 3}] + ${k};`);
		lines.push(`\tlet v${k};`);
		lines.push(`\tif (T[${k}] > ${k + 1.5}) { v${k} = T[${k}] / 3; } else { v${k} = -T[${k}]; }`);
		lines.push(`\tconst f${k} = v${k} * y[${(k + 1) % 7}];`);
		lines.push(`\tout[${k % 7}] -= f${k};`);
		lines.push(`\tout[${(k + 3) % 7}] += f${k};`);
		lines.push(`\tfor (let n0 = 0; n0 < 3; n0++) {`);
		lines.push(`\t\tconst s = T[${k}] * n0;`);
		lines.push(`\t\tX[${k} * 3 + n0] = s + y[n0];`);
		lines.push('\t}');
	}
	lines.push('\treturn out;');
	const body = lines.join('\n');
	const params = ['y', 'out', 'P', 'X'];
	const split = buildFunction(params, body, 'dydt');
	assert(split.parts > 5, `a ${body.length}-character body was not cut (${split.parts} part)`);
	assert(split.source === `"use strict";\n${body}`, 'the source is no longer the whole body');
	// eslint-disable-next-line no-new-func
	const whole = new Function('F', 'ctx', ...params, `"use strict";\n${body}`);
	const y = Float64Array.from([1.5, -2, 3.25, 0.5, 7, -1, 2]);
	const P = Float64Array.from([0.3, 2, -1.1]);
	const run1 = (fn) => {
		const ctx = {};
		const out = new Float64Array(7);
		const X = new Float64Array(2700);
		const r = fn({}, ctx, y, out, P, X);
		return { r, out, X, T: ctx.__tape };
	};
	const a = run1(split);
	const b = run1(whole);
	assert(a.r === a.out, 'the parts do not return what the last one returns');
	assert(a.out.every((v, i) => Object.is(v, b.out[i])), 'the parts change out');
	assert(a.X.every((v, i) => Object.is(v, b.X[i])), 'the parts change X');
	assert(a.T.length === b.T.length && a.T.every((v, i) => Object.is(v, b.T[i])), 'the parts change the tape');

	// What the scan does not understand is compiled whole, as before.
	const filler = Array.from({ length: 2000 }, (_, k) => `\tX[${k}] = y[0] + ${k};`).join('\n');
	for (const [what, text] of [
		['a string', `${filler}\n\tX[0] = F.named("a").fn(ctx);\n${filler}`],
		['a return before the end', `${filler}\n\tif (y[0] > 0) { return X; }\n${filler}`],
		['an arrow function', `${filler}\n\tX[1] = [1, 2].map((q) => q)[0];\n${filler}`],
	]) {
		assert(buildFunction(['y', 'X'], text).parts === 1, `a body with ${what} was cut`);
	}
	assert(buildFunction(['y', 'X'], '\tX[0] = y[0];').parts === 1, 'a short body was cut');
});

test('the LU that keeps its pivots solves what the searching one does', async () => {
	// ../src/ode/core/refactor.js chooses pivots once and replays them, checking each one;
	// sparseIterationMatrix uses it where it costs no more than Gilbert-Peierls.
	const { RefactorLU } = await import('../src/ode/core/refactor.js');
	const { sparseIterationMatrix } = await import('../src/ode/core/sparse.js');
	const { readFileSync: read } = await import('node:fs');
	const project = new Project(JSON.parse(read(new URL('../examples/farfield.json', import.meta.url), 'utf8')));
	const sys = buildSystem(project);
	const { pattern } = sys.jacobian;
	const { n, colPtr, rowIdx } = pattern;
	const J = Float64Array.from(sys.jacobian.evaluate(0, sys.initialState()));
	// ||(I - hJ) x - b|| / (||I - hJ|| ||x|| + ||b||), infinity norms.
	const backward = (h, x, b) => {
		const r = Float64Array.from(x, (v, i) => v - b[i]);
		const rowSum = new Float64Array(n).fill(1);
		for (let j = 0; j < n; j++) {
			for (let p = colPtr[j]; p < colPtr[j + 1]; p++) {
				r[rowIdx[p]] -= h * J[p] * x[j];
				rowSum[rowIdx[p]] += Math.abs(h * J[p]);
			}
		}
		const inf = (v) => v.reduce((m, e) => Math.max(m, Math.abs(e)), 0);
		return inf(r) / (inf(rowSum) * inf(x) + inf(b));
	};
	const b = Float64Array.from({ length: n }, (_, i) => Math.sin(i + 1));
	const lu = new RefactorLU(pattern);
	for (const h of [1e-3, 1, 1e3, 1e6, 1e9]) {
		assert(lu.factor(h, J), `I - ${h}J of the farfield model was declined`);
		const e = backward(h, lu.solve(b), b);
		assert(e < 1e-14, `I - ${h}J solves with backward error ${e}`);
	}
	const W = sparseIterationMatrix(n, pattern, J);
	assert(W?.lu === 'refactor', `sparseIterationMatrix gave the farfield model ${W?.lu}`);
	W.form(1e3, J);
	assert(backward(1e3, W.solve(b), b) < 1e-14, 'through sparseIterationMatrix it solves worse');

	// With h = -1 the matrix is I + J: a full 3 x 3 whose first kept pivot
	// collapses is chosen again; a zero matrix and a NaN are declined.
	const full = { n: 3, nnz: 9, colPtr: Int32Array.from([0, 3, 6, 9]), rowIdx: Int32Array.from([0, 1, 2, 0, 1, 2, 0, 1, 2]) };
	const ofMatrix = (A) => Float64Array.from(A, (v, k) => v - (k % 4 === 0 ? 1 : 0));	// column-major, minus I
	const small = new RefactorLU(full);
	const A = [4, 1, 0, 1, 5, 1, 0, 1, 6];
	assert(small.factor(-1, ofMatrix(A)), 'a well-conditioned 3 x 3 was declined');
	const collapsed = A.slice();
	collapsed[small.pc[0] * 3 + small.pr[0]] = 1e-9;
	const before = small.repivots;
	assert(small.factor(-1, ofMatrix(collapsed)), 'the matrix with a collapsed pivot was declined');
	assert(small.repivots === before + 1, 'a collapsed kept pivot was used rather than chosen again');
	const x = small.solve(Float64Array.from([1, 2, 3]));
	const res = [0, 1, 2].map((i) => Math.abs(collapsed[i] * x[0] + collapsed[3 + i] * x[1] + collapsed[6 + i] * x[2] - (i + 1)));
	assert(Math.max(...res) < 1e-14, `after choosing again the residual is ${Math.max(...res)}`);
	assert(!small.factor(-1, ofMatrix([0, 0, 0, 0, 0, 0, 0, 0, 0])), 'a zero matrix was factorised');
	assert(!small.factor(-1, ofMatrix([NaN, 1, 0, 1, 5, 1, 0, 1, 6])), 'a matrix with a NaN was factorised');

	// A matrix it declines goes to Gilbert-Peierls, whose singular message is
	// the one the reader gets: I - 1*I is zero.
	const m = 30;
	const diag = { n: m, nnz: m, colPtr: Int32Array.from({ length: m + 1 }, (_, k) => k), rowIdx: Int32Array.from({ length: m }, (_, k) => k) };
	const D = sparseIterationMatrix(m, diag, new Float64Array(m).fill(0.5));
	let said = '';
	try { D.form(2, new Float64Array(m).fill(0.5)); } catch (e) { said = e.message; }
	assert(/singular at column/.test(said), `a singular matrix said ${JSON.stringify(said)}`);
});

